// بيانات السور
Object.assign(quranData, {
    2: { // سورة البقرة
        name: "البقرة",
        basmalaTafsir: `ابتدأت السورة باسم الله تعالى، لتكرر الاستعانة به، وليتعلم المسلم كي يبتدئ جميع أعماله بهذا الاسم المبارك، وليتركز هذا الاسم الكريم في الأذهان، فإن للتكرار أثرا بالغا.`,
        verses: [
            { text: "الٓمٓ", tafsir: `أي من جنس هذه الحروف المقطعة : « أ » ، « ل » ، « م » .` },
            { text: "ذَٰلِكَ ٱلْكِتَٰبُ لَا رَيْبَ فِيهِ هُدًى لِّلْمُتَّقِينَ", tafsir: `والإشارة بالبعيد ، للإشارة إلى كون القرآن سامي المقام ، عالي المنزلة ( لا رَيْبَ فِيهِ ) أي ليس محلّا للريب ، وإن ارتاب فيه الكفار ، كما أن النهار لا ريب فيه ، وإن ارتاب فيه السوفسطائيون ، و ( لا رَيْبَ فِيهِ ) صفة للكتاب ( هُدىً لِلْمُتَّقِينَ ) صفة بعد صفة ، أي أن هذا القرآن هداية لمن اتقى ، وخاف من التردي ، فإنه هو الذي يهتدي بالقرآن ، وإن كان القرآن صالحا ، لأن يهدي الكل.` },
            { text: "ٱلَّذِينَ يُؤْمِنُونَ بِٱلْغَيْبِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقْنَٰهُمْ يُنفِقُونَ", tafsir: `صفة للمتقين ، والمراد بالإيمان الاعتقاد به ، والغيب هو الذي غاب عن الحواس الظاهرة ، أي ما وراء الطبيعة ، فالروح غيب ، وأحوال القبر غيب ، والله سبحانه غيب ، وهكذا ( وَيُقِيمُونَ الصَّلاةَ ) إقامة الصلاة ، الإتيان بها دائما على الوجه المأمور بها ، ولذا تدل على معنى أرفع ، من معنى « صل » ( وَمِمَّا رَزَقْناهُمْ يُنْفِقُونَ ) والرزق أعم من المأكول ، والملبوس ، والمسكون ، والعلم والصحة ، وغيرها ، وإنفاق كل شيء بحسبه.` },
            { text: "وَٱلَّذِينَ يُؤْمِنُونَ بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ وَبِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ", tafsir: `من الوحي والقرآن ( وَما أُنْزِلَ مِنْ قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ (4) أُولئِكَ عَلى هُدىً مِنْ رَبِّهِمْ وَأُولئِكَ هُمُ الْمُفْلِحُونَ (5) إِنَّ الَّذِينَ كَفَرُوا سَواءٌ عَلَيْهِمْ أَ أَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ (6) قَبْلِكَ ) فإن من شرائط الإيمان ، الإيمان بكل الأنبياء عليهم‌السلام ( لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ) (1) ( وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ) واليقين بالآخرة هو الاعتقاد بها ، والعمل بمقتضاها ، وبعض هذه الأمور ، وإن كانت داخلة في « الإيمان بالغيب » ، لكنها ذكرت لزيادة الاهتمام بها ، وذكر الخاص بعد العام.` },
            { text: "أُو۟لَٰٓئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ", tafsir: `أي على بصيرة ، وهذه البصيرة أتت إليهم من ناحية الله سبحانه ( وَأُولئِكَ هُمُ الْمُفْلِحُونَ ) الناجحون ، فهم في الدنيا على بصيرة ، وفي الآخرة في زمرة الناجين ، ثم أن القرآن لما ذكر المؤمنين ، ثنّاهم بذكر الكافرين ، ثم ثلّثهم بذكر المنافقين ، فإن كل دعوة ، لا بد وأن ينقسم الناس أمامها إلى ثلاثة أقسام : مؤمن بها وكافر بها ، ومذبذب بين ذلك يجامل الطرفين.` },
            { text: "إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ", tafsir: `والكفر هو الستر ، كأن الكافر يستر الحقيقة ، ولا يبديها ( سَواءٌ عَلَيْهِمْ أَ أَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ ) والمراد ب « الذين كفروا » هنا هم المعاندون منهم ، لأنهم المصداق الأجلى للكافر ، وإلا فالذين آمنوا بالرسول صلى‌الله‌عليه‌وآله‌وسلم من الناس كانوا كفارا ثم ( 1) البقرة : 286. خَتَمَ اللهُ عَلى قُلُوبِهِمْ وَعَلى سَمْعِهِمْ وَعَلى أَبْصارِهِمْ غِشاوَةٌ وَلَهُمْ عَذابٌ عَظِيمٌ (7) آمنوا ، ومن المعلوم أن المعاند يتساوى في حقه الإنذار وعدمه ، نعم يجب إنذاره إتماما للحجة ، وهذا تسلية للنبي صلى‌الله‌عليه‌وآله‌وسلم ، حتى لا تذهب نفسه عليهم حسرات.` },
            { text: "خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ وَعَلَىٰٓ أَبْصَٰرِهِمْ غِشَٰوَةٌ وَلَهُمْ عَذَابٌ عَظِيمٌ", tafsir: `طبعها بالكفر ، أي جعلها بحيث يصعب إيمانها ، لأنها اعتادت الكفر ، وعدم الاستماع إلى الحق ، وإنما ختم الله ، لأنها لم تقبل الهداية ، كمن يطرد ولده عن داره بعد ما أرشده مرات ، فلم يفد فيه النصح ، كما قال تعالى ( طَبَعَ اللهُ عَلَيْها بِكُفْرِهِمْ ) (1) أي بسبب كفرهم ، وإنما فسرنا « الختم » ب « يصعب » لبداهة أن الإنسان ولو كان معاندا ، لا يخرج عن قابلية القبول والاهتداء ( وَعَلى سَمْعِهِمْ ) بمعنى إنهم لا يستفيدون من السمع ، كالأصم ، لأن في سمعهم خلل ( وَعَلى أَبْصارِهِمْ غِشاوَةٌ ) تشبيه للغشاوة المعنوية بالغشاوة الظاهرية ، فكما أن من على بصره غشاوة ، لا يرى المحسوسات ، كذلك من يعاند يكون على بصره مثل الغشاوة ، وهو تنزيل لفاقد الوصف منزلة فاقد الأصل ، كما تقول لمن لا ينتفع بالعلم ، هو جدار ( وَلَهُمْ عَذابٌ عَظِيمٌ ) في الدنيا والآخرة ، فإن من ينحرف عن قوانين الله تعالى ، يكون ( لَهُ مَعِيشَةً ضَنْكاً وَنَحْشُرُهُ يَوْمَ الْقِيامَةِ أَعْمى ) (2) . ( 1) النساء : 156. ( 2) طه : 125. وَمِنَ النَّاسِ مَنْ يَقُولُ آمَنَّا بِاللهِ وَبِالْيَوْمِ الْآخِرِ وَما هُمْ بِمُؤْمِنِينَ (8) يُخادِعُونَ اللهَ وَالَّذِينَ آمَنُوا وَما يَخْدَعُونَ إِلاَّ أَنْفُسَهُمْ وَما يَشْعُرُونَ (9) فِي قُلُوبِهِمْ مَرَضٌ فَزادَهُمُ اللهُ مَرَضاً` },
            { text: "وَمِنَ ٱلنَّاسِ مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلْيَوْمِ ٱلْـَٔاخِرِ وَمَا هُم بِمُؤْمِنِينَ", tafsir: `المنافقون ، وهم القسم الثالث ، فهو ( مَنْ يَقُولُ آمَنَّا بِاللهِ وَبِالْيَوْمِ الْآخِرِ ) قولا باللفظ فقط ( وَما هُمْ بِمُؤْمِنِينَ ) حقيقة ، فلا يعملون أعمال المؤمنين ، وإن كانت قلوبهم أيضا متيقنة بحقائق الإيمان.` },
            { text: "يُخَٰدِعُونَ ٱللَّهَ وَٱلَّذِينَ ءَامَنُوا۟ وَمَا يَخْدَعُونَ إِلَّآ أَنفُسَهُمْ وَمَا يَشْعُرُونَ", tafsir: `أي يفعلون مع الله تعالى ، فعل المخادع ، الذي يريد الخديعة ، فيظهر ما لا يريده ، ويريد ما لا يظهره ( وَالَّذِينَ آمَنُوا ) فيرونهم خلاف ما يضمرونه ، لكن عملهم هذا ليس خدعة حقيقية لله وللمؤمنين ، فإنهما يعلمان نواياهم ، فلا ينخدعان بهم ، بل ( وَما يَخْدَعُونَ إِلَّا أَنْفُسَهُمْ ) إذ يجري عليهم أحكام المؤمنين ظاهرا ، ولا يشتركون معهم في أسرارهم ، كما لا يشتركون معهم في آخرتهم ، فهم مخدوعون من حيث ظنوا أنهم خادعين ( وَما يَشْعُرُونَ ) بأنهم خدعوا أنفسهم ، لا أنهم خدعوا الله والمؤمنين ، إذ لو شعروا بأنهم يخدعون أنفسهم ، لم يقدموا على ما ظنوه خدعة لغيرهم ، والحال أنها خدعة لهم حقيقة وواقعا.` },
            { text: "فِى قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ ٱللَّهُ مَرَضًا وَلَهُمْ عَذَابٌ أَلِيمٌۢ بِمَا كَانُوا۟ يَكْذِبُونَ", tafsir: `فإن قلب المنافق ملتو ، ونفسه معوجة ، لا تريد الاستقامة ( فَزادَهُمُ اللهُ مَرَضاً ) إذ نزول الآيات ، ونصب الرسول ، وَلَهُمْ عَذابٌ أَلِيمٌ بِما كانُوا يَكْذِبُونَ (10) وَإِذا قِيلَ لَهُمْ لا تُفْسِدُوا فِي الْأَرْضِ قالُوا إِنَّما نَحْنُ مُصْلِحُونَ (11) أَلا إِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلكِنْ لا يَشْعُرُونَ (12) وَإِذا قِيلَ لَهُمْ أوجب أن يزيدوا في التوائهم ، لئلا يسلط النور عليهم ، فيعرفوا ( وَلَهُمْ عَذابٌ أَلِيمٌ ) أي مؤلم ( بِما كانُوا يَكْذِبُونَ ) أي بسبب كذبهم ، بمخالفة ظاهرهم لباطنهم ، فإنه نوع من الكذب ، وإن كان كلامهم مطابقا للواقع ، لكنهم حيث أخبروا عن إيمانهم ـ ولم يكونوا مؤمنين ـ كان ذلك كذبا.` },
            { text: "وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ قَالُوٓا۟ إِنَّمَا نَحْنُ مُصْلِحُونَ", tafsir: `أي للمنافقين ( لا تُفْسِدُوا فِي الْأَرْضِ ) فإن النفاق يلازم الإفساد ، إذ يعمل المنافق ضد الدعوة ، ويؤلب عليها ، وهو إفساد حينما تريد الدعوة الإصلاح والتقدم ( قالُوا إِنَّما نَحْنُ مُصْلِحُونَ ) فإنهم يظنون أن الدعوة إفساد ، وأنهم بوقوفهم ضدها يصلحون في الأرض.` },
            { text: "أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ", tafsir: `لأنهم بوقوفهم النفاقي ضد الإسلام ، يكونون مفسدين إفسادا بالغا أكثر من إفساد الكفار ، ولذا قال تعالى في آية أخرى ( هُمُ الْعَدُوُّ ) (1) على نحو الحصر ( وَلكِنْ لا يَشْعُرُونَ ) بذلك ، بل يحسبون أنهم يحسنون صنعا.` },
            { text: "وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ كَمَآ ءَامَنَ ٱلنَّاسُ قَالُوٓا۟ أَنُؤْمِنُ كَمَآ ءَامَنَ ٱلسُّفَهَآءُ أَلَآ إِنَّهُمْ هُمُ ٱلسُّفَهَآءُ وَلَٰكِن لَّا يَعْلَمُونَ", tafsir: `أي للمنافقين ، والقائل هم جماعة من المؤمنين ( 1) المنافقون : 5. آمِنُوا كَما آمَنَ النَّاسُ قالُوا أَ نُؤْمِنُ كَما آمَنَ السُّفَهاءُ أَلا إِنَّهُمْ هُمُ السُّفَهاءُ وَلكِنْ لا يَعْلَمُونَ (13) وَإِذا لَقُوا الَّذِينَ آمَنُوا قالُوا آمَنَّا وَإِذا خَلَوْا إِلى شَياطِينِهِمْ قالُوا إِنَّا مَعَكُمْ إِنَّما نَحْنُ مُسْتَهْزِؤُنَ (14) اللهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ الذين لا يخافونهم ( آمِنُوا كَما آمَنَ النَّاسُ ) إيمانا لا يشوبه نفاق ( قالُوا أَ نُؤْمِنُ كَما آمَنَ السُّفَهاءُ ) يعنون بالسفهاء المؤمنين الحقيقيين ( أَلا إِنَّهُمْ هُمُ السُّفَهاءُ ) وأية سفاهة أعظم من كون الإنسان حائد عن طريق الحق مع كونه متصفا بصفة النفاق الرذيلة ( وَلكِنْ لا يَعْلَمُونَ ) إنهم هم السفهاء ، لأنهم يظنون أن طريقتهم النفاقية ، أصلح الطرق.` },
            { text: "وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَوْا۟ إِلَىٰ شَيَٰطِينِهِمْ قَالُوٓا۟ إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِءُونَ", tafsir: `من « لقى » أي التقى المنافقون ب ( الَّذِينَ آمَنُوا قالُوا ) لهم ( آمَنَّا وَإِذا خَلَوْا إِلى شَياطِينِهِمْ ) أي أشباههم من المنافقين ( قالُوا ) لهم ( إِنَّا مَعَكُمْ ) يريدون بذلك إرضاء الجانبين ( إِنَّما نَحْنُ مُسْتَهْزِؤُنَ ) بالمؤمنين ، في إظهار الإيمان لهم ، وهذا هو دليل نفاقهم ، وإلّا لو كان الأمر بالعكس ، بأن أظهروا الكفر تقية لم يزيدوا على إظهاره.` },
            { text: "ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ", tafsir: `أي يفعل لهم فعل المستهزئ ، فيجري عليهم في الدنيا أحكام الإيمان ، وفي الآخرة يجازيهم بجزاء الكفار ، وفي بعض الأحاديث إنه يستهزئ بهم في الآخرة في النار ( وَيَمُدُّهُمْ ) إمداد الله سبحانه وتعالى ، بعدم الضرب على أيديهم كما يقال : الملك يمد فِي طُغْيانِهِمْ يَعْمَهُونَ (15) أُولئِكَ الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى فَما رَبِحَتْ تِجارَتُهُمْ وَما كانُوا مُهْتَدِينَ (16) مَثَلُهُمْ كَمَثَلِ الَّذِي اسْتَوْقَدَ ناراً فَلَمَّا أَضاءَتْ ما حَوْلَهُ ذَهَبَ اللهُ بِنُورِهِمْ قطّاع الطريق حيث لا يستأصلهم ( فِي طُغْيانِهِمْ يَعْمَهُونَ ) الطغيان تجاوز الحد ، والعمه التحير ، فإن المنافق ، كالشخص المتحير ، وإنما يمدهم الله سبحانه ، لأن الدنيا دار اختبار وامتحان ، فلا جبر ولا إلجاء.` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ فَمَا رَبِحَت تِّجَٰرَتُهُمْ وَمَا كَانُوا۟ مُهْتَدِينَ", tafsir: `المنافقون ( الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى ) فكأنهم أعطوا الهداية ، وأخذوا مكانها الضلالة ، أو كأنهم أعطوا أنفسهم بدل الضلالة ، بينما كان الذي ينبغي أن يعطوا أنفسهم بدل الهداية ، كما قال الشاعر : أنفاس عمرك أثمان الجنان فلا تشري بها لهبا في الحشر تشتعل ( فَما رَبِحَتْ تِجارَتُهُمْ ) المعنوية ، بل خسروا رأس المال الذي هو أنفسهم ( وَما كانُوا مُهْتَدِينَ ) في هذه التجارة والاشتراء.` },
            { text: "مَثَلُهُمْ كَمَثَلِ ٱلَّذِى ٱسْتَوْقَدَ نَارًا فَلَمَّآ أَضَآءَتْ مَا حَوْلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِى ظُلُمَٰتٍ لَّا يُبْصِرُونَ", tafsir: `أي مثل هؤلاء المنافقين ( كَمَثَلِ الَّذِي اسْتَوْقَدَ ناراً ) استوقد بمعنى أوقد ، أو بمعنى طلب الوقود الذي هو الحطب ونحوه ، والمعنى أشعل نارا ليستضيء ويدفأ بها ( فَلَمَّا أَضاءَتْ ) النار ( ما حَوْلَهُ ) وانتفع بها ( ذَهَبَ اللهُ بِنُورِهِمْ ) بأن أرسل ريحا فأطفأها وَتَرَكَهُمْ فِي ظُلُماتٍ لا يُبْصِرُونَ صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لا يَرْجِعُونَ (18) أَوْ كَصَيِّبٍ مِنَ السَّماءِ فِيهِ ظُلُماتٌ ( وَتَرَكَهُمْ فِي ظُلُماتٍ لا يُبْصِرُونَ ) ما حولهم وإنما كان هذا مثلا لهم ، لأن المنافق بإيمانه الظاهري ، يعبّد لنفسه سبيل الحياة ، وينور في طريقه ، فإن الإيمان نور ، وسبب لهداية الإنسان إلى الحق والعدل والخير ، فإذا قبض الله أرواحهم تركهم ، كسائر الكفار في نار وعذاب ، حين يقبض الله أرواح المؤمنين ، إلى نور أوسع ورحمة أكبر ، فهؤلاء المنافقون :` },
            { text: "صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَرْجِعُونَ", tafsir: `جمع أصم ، لأنهم لا ينتفعون بالحق ، فهم والأصم سواء ( بُكْمٌ ) جمع أبكم ، وهو الأخرس ، لأنهم لا يقولون الحق فهم والأبكم سواء ( عُمْيٌ ) جمع أعمى ، لأنهم لا يبصرون الحق ، فهم والأعمى سواء ( فَهُمْ لا يَرْجِعُونَ ) عن غيهم وضلالهم ، و « ف » ، للإشارة إلى أنهم حيث صموا وأبكموا وعملوا لم يرج فيهم الخير ، فإنه ( وَلا يَسْمَعُ الصُّمُّ الدُّعاءَ ) (1) .` },
            { text: "أَوْ كَصَيِّبٍ مِّنَ ٱلسَّمَآءِ فِيهِ ظُلُمَٰتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَٰبِعَهُمْ فِىٓ ءَاذَانِهِم مِّنَ ٱلصَّوَٰعِقِ حَذَرَ ٱلْمَوْتِ وَٱللَّهُ مُحِيطٌۢ بِٱلْكَٰفِرِينَ", tafsir: `مثال آخر لحال المنافقين ، والفرق بين المثالين ، إن المثال الأول ، كان مثالا للمنافق نفسه ، وهذا المثال مثال الحق الذي يغمر المنافق ، لكنه لا ينتفع به والصيب هو المطر ، فالحق الذي يغمر هؤلاء كمطر ينزل من السماء ( فِيهِ ظُلُماتٌ ) ظلمة السحاب وظلمة المطر ، لأنه يحول بين الضياء وبين الأرض ، وظلمة ( 1) الأنبياء : 46. وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصابِعَهُمْ فِي آذانِهِمْ مِنَ الصَّواعِقِ حَذَرَ الْمَوْتِ وَاللهُ مُحِيطٌ بِالْكافِرِينَ (19) يَكادُ الْبَرْقُ يَخْطَفُ أَبْصارَهُمْ كُلَّما أَضاءَ لَهُمْ مَشَوْا فِيهِ وَإِذا أَظْلَمَ عَلَيْهِمْ قامُوا وَلَوْ شاءَ اللهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصارِهِمْ إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (20) سحاب فوق سحاب ( وَرَعْدٌ وَبَرْقٌ ) من الأمور المخوفة ( يَجْعَلُونَ ) أي من ابتلى بهذا الصيب ( أَصابِعَهُمْ فِي آذانِهِمْ مِنَ ) خشية ( الصَّواعِقِ ) فإن الصاعقة إذا نزلت ، قرعت الأسماع بصوتها الشديد ( حَذَرَ الْمَوْتِ ) فإن الصوت الشديد يوجب انخلاع القلب ، فيموت الشخص ، لكن هؤلاء المنافقين الذين هم كفار في الباطن لا يظنون أنهم يتمكنون الفرار من بأس الله تعالى ( وَاللهُ مُحِيطٌ بِالْكافِرِينَ ) إحاطة علم وقدرة.` },
            { text: "يَكَادُ ٱلْبَرْقُ يَخْطَفُ أَبْصَٰرَهُمْ كُلَّمَآ أَضَآءَ لَهُم مَّشَوْا۟ فِيهِ وَإِذَآ أَظْلَمَ عَلَيْهِمْ قَامُوا۟ وَلَوْ شَآءَ ٱللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَٰرِهِمْ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `اللامع في السحاب ( يَخْطَفُ أَبْصارَهُمْ ) أي أبصار من ابتلى بالصيب ، وخطف البصر كناية عن عماه ( كُلَّما أَضاءَ لَهُمْ ) بأن أبرق ، ورأوا طريقهم ( مَشَوْا فِيهِ ) أي في البرق ـ بمعنى استفادتهم من نوره فيمشون ( وَإِذا أَظْلَمَ عَلَيْهِمْ ) بأن لم يبرق ( قامُوا ) في أماكنهم ـ أي وقفوا ـ ( وَلَوْ شاءَ اللهُ لَذَهَبَ بِسَمْعِهِمْ ) بسبب صاعقة قوية فتصمهم ( وَأَبْصارِهِمْ ) بسبب برق قوي ، إذ النور إذا قوي أوجب ذهاب البصر ( إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فلا يمنعه أن يحتمي الإنسان بإصبعه ، أو بغمض بصره عن أن يذهب بسمعه يا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ (21) أو بصره ، وهذا توضيح المثال بتطبيقه على المورد أن « الصيب » هو الحق النازل على الرسول صلى‌الله‌عليه‌وآله‌وسلم و « البرق » هو تقدم المسلمين ، وما يسبب لهم إنارة الطريق ، و « الرعد والصاعقة » إيعادات الرسل ، والأهوال المكتنفة بالدعوة ، والمنافقون كمن ابتلى بهذا الصيب في الصحراء ، فالحق كالمطر فيه الحياة ، لكن فيه ظلمات غلبة الكفار ، وذهاب الأنفس والأموال والثمرات ، وفيه برق ينير طريق الحياة السعيدة ، وفيه رعد وصاعقة مواعيد الرسول ، وفضيحة المنافقين ، وهؤلاء المنافقون تكاد سرعة تقدم المسلمين ، تعميهم ، فإن العين إذا نظرت إلى ما لا يسرها اضطربت ودمعت ، كلما أضاء لهم ، بأن غلبوا في الحرب ، وحصلوا على الغنائم ، اتبعوا الرسول ، وإذا أظلم عليهم ، بأن غلب عليهم الكفار ، وقفوا وقاموا في مكانهم ، لا يعلمون ولا يتقدمون وهم يخافون من الفضيحة ، إن نزلت آية في شأن المنافقين ، فيجعلون أصابعهم في آذانهم ، حتى لا يسمعونها ، أو يتغافلون عنها ، كي لا يرى أثر الانهزام في وجوههم ، فإن الإنسان المجرم إذا سمع ما يمس إجرامه ظهرت الصفرة وآثار الانهزام على وجهه ، لكن الله قادر على إماتتهم ، كما هو قادر على فضحهم والذهاب بسمعهم وبصرهم ، فليسوا هم في راحة من نفاقهم ـ كما زعموا ـ بل هم في أشد ابتلاء ومحنة.` },
            { text: "يَٰٓأَيُّهَا ٱلنَّاسُ ٱعْبُدُوا۟ رَبَّكُمُ ٱلَّذِى خَلَقَكُمْ وَٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", tafsir: `خلق ( الَّذِينَ مِنْ قَبْلِكُمْ ) وكان السبب في الخلق ( لَعَلَّكُمْ تَتَّقُونَ ) أي خلقكم للتقوى الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِراشاً وَالسَّماءَ بِناءً وَأَنْزَلَ مِنَ السَّماءِ ماءً فَأَخْرَجَ بِهِ مِنَ الثَّمَراتِ رِزْقاً لَكُمْ فَلا تَجْعَلُوا لِلَّهِ أَنْداداً وَأَنْتُمْ تَعْلَمُونَ (22) وَإِنْ كُنْتُمْ فِي رَيْبٍ مِمَّا نَزَّلْنا عَلى عَبْدِنا فَأْتُوا بِسُورَةٍ مِنْ مِثْلِهِ وَادْعُوا شُهَداءَكُمْ والعبادة ، كما قال تعالى ( وَما خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ ) (1) .` },
            { text: "ٱلَّذِى جَعَلَ لَكُمُ ٱلْأَرْضَ فِرَٰشًا وَٱلسَّمَآءَ بِنَآءً وَأَنزَلَ مِنَ ٱلسَّمَآءِ مَآءً فَأَخْرَجَ بِهِۦ مِنَ ٱلثَّمَرَٰتِ رِزْقًا لَّكُمْ فَلَا تَجْعَلُوا۟ لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", tafsir: `كالفراش الذي يكون راحة للبدن وزينة وجمالا ( وَالسَّماءَ بِناءً ) أي مبنيا ، وهذا يلائم كون السماء طبقة تحطم القذائف إلى الأرض ، فإن البناء ليس المراد منه أن يكون المبنى من جسم كثيف ( وَأَنْزَلَ مِنَ السَّماءِ ماءً ) والمراد من السماء هنا جهة العلو ، أو المراد من تلك الناحية ( فَأَخْرَجَ بِهِ ) أي بسبب الماء ( مِنَ الثَّمَراتِ رِزْقاً لَكُمْ ) فإذا كان الخلق وسائر النعم من الله سبحانه ( فَلا تَجْعَلُوا لِلَّهِ أَنْداداً ) شركاء من الأصنام أو غيرها ( وَأَنْتُمْ تَعْلَمُونَ ) أنها باطلة ، وأنه ليس لله شريك.` },
            { text: "وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `محمد بن عبد الله صلى‌الله‌عليه‌وآله‌وسلم ، وتزعمون أنه ليس من الله سبحانه ( فَأْتُوا بِسُورَةٍ ) واحدة ( مِنْ مِثْلِهِ ) أي من مثل هذا المنزل ، ولو كان قصر سورة نحو ( قُلْ هُوَ اللهُ أَحَدٌ ) (2) أو ( إِنَّا أَعْطَيْناكَ ) (3) ( وَادْعُوا شُهَداءَكُمْ ) ، الذين يشهدون ( 1) الذاريات : 57. ( 2) الإخلاص : 2. ( 3) الكوثر : 2. مِنْ دُونِ اللهِ إِنْ كُنْتُمْ صادِقِينَ (23) فَإِنْ لَمْ تَفْعَلُوا وَلَنْ تَفْعَلُوا فَاتَّقُوا النَّارَ الَّتِي وَقُودُهَا النَّاسُ وَالْحِجارَةُ أُعِدَّتْ لِلْكافِرِينَ (24) وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا معكم ، أن محمدا صلى‌الله‌عليه‌وآله‌وسلم ليس بنبي ( مِنْ دُونِ اللهِ ) أي كائن ما كان غير الله سبحانه ، كما يقال ما دون الله مخلوق ( إِنْ كُنْتُمْ صادِقِينَ ) في ريبكم وزعمكم ، أن محمدا ليس بنبي ، وأن القرآن ليس منزلا من عند الله تعالى ، إذ لو لم يكن محمد صلى‌الله‌عليه‌وآله‌وسلم نبيا ، لكان إنسانا عاديا ، فيمكن الإتيان بمثل كلامه.` },
            { text: "فَإِن لَّمْ تَفْعَلُوا۟ وَلَن تَفْعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِى وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ أُعِدَّتْ لِلْكَٰفِرِينَ", tafsir: `ولم تأتوا بسورة من مثل هذا القرآن ( وَلَنْ تَفْعَلُوا ) هذا إخبار بأنهم لن يفعلوا ذلك أبدا ، إذ القرآن معجز ، فلا يمكن الإتيان بمثله ( فَاتَّقُوا ) عاقبة تكذيبكم ، لرسول الله ، ولكتاب الله ، التي هي ( النَّارَ الَّتِي وَقُودُهَا ) أي حطبها ، وما يسبب إيقادها ( النَّاسُ وَالْحِجارَةُ ) جمع حجر ولعل المراد بها أصنامهم ، كما قال تعالى ( إِنَّكُمْ وَما تَعْبُدُونَ مِنْ دُونِ اللهِ حَصَبُ جَهَنَّمَ ) (1) وتخصيص الحجارة بالذكر للتهويل ، إذ الحجارة لا تفنى ، فتكون النار دائمة ( أُعِدَّتْ ) هذه النار ( لِلْكافِرِينَ ) هذه عاقبة من يكذب.` },
            { text: "وَبَشِّرِ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمْ جَنَّٰتٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ كُلَّمَا رُزِقُوا۟ مِنْهَا مِن ثَمَرَةٍ رِّزْقًا قَالُوا۟ هَٰذَا ٱلَّذِى رُزِقْنَا مِن قَبْلُ وَأُتُوا۟ بِهِۦ مُتَشَٰبِهًا وَلَهُمْ فِيهَآ أَزْوَٰجٌ مُّطَهَّرَةٌ وَهُمْ فِيهَا خَٰلِدُونَ", tafsir: `يا رسول الله ( الَّذِينَ آمَنُوا ) بقلوبهم وألسنتهم ( وَعَمِلُوا ( 1) الأنبياء : 99. الصَّالِحاتِ أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ كُلَّما رُزِقُوا مِنْها مِنْ ثَمَرَةٍ رِزْقاً قالُوا هذَا الَّذِي رُزِقْنا مِنْ قَبْلُ وَأُتُوا بِهِ مُتَشابِهاً وَلَهُمْ فِيها أَزْواجٌ مُطَهَّرَةٌ وَهُمْ فِيها خالِدُونَ (25) الصَّالِحاتِ ) بجوارحهم ( أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) الجنة باعتبار كونها بستانا ذات أشجار ونخيل ، تكون أرضها « من تحتها » فالأنهار جارية من تحت الجنة على أرضها ( كُلَّما رُزِقُوا ) أي رزق المؤمنون ( مِنْها ) أي من الجنات ( مِنْ ثَمَرَةٍ رِزْقاً ) بأن أتى لهم بفاكهة وثمرة ( قالُوا هذَا الَّذِي رُزِقْنا مِنْ قَبْلُ ) فإنهم يألفون تلك الثمار لما رأوا منها في الدنيا ، وليسوا كأصحاب الجحيم الذين لا يألفون طعامهم الذي من ضريع ، ولا شرابهم الذي من حميم ( وَأُتُوا بِهِ ) أي بذلك الرزق ( مُتَشابِهاً ) يشبه بعضه بعضا في الجودة والجدة ، لا كأثمار الدنيا ، بعضها ناضج ، وبعضها غير ناضج ، وبعضها جيد ، وبعضها رديء ( وَلَهُمْ فِيها ) أي في الجنات ( أَزْواجٌ مُطَهَّرَةٌ ) من القذارات الخلقية ، كالأوساخ والدماء ، والقذارات الخلقية ، كالسب والشتم والحسد ، ونحوها ( وَهُمْ فِيها ) أي في تلك الجنات ( خالِدُونَ ) أبدا لا يموتون ، ولا يتحولون عنها ، وحيث قسم الله الناس إلى أقسام ثلاثة ، مؤمن ومنافق وكافر ، ومثل للمنافق ، ثم أمر الناس عامة بالعبادة ، ودعاهم إلى حضيرة الإيمان ، وذكر لهم فوائده ، واحتج على من أنكر الرسالة ، أجاب عن سؤال سأله الكفار ومن إليهم تعنتا ، إِنَّ اللهَ لا يَسْتَحْيِي أَنْ يَضْرِبَ مَثَلاً ما بَعُوضَةً فَما فَوْقَها فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ ما ذا أَرادَ اللهُ بِهذا مَثَلاً يُضِلُّ بِهِ كَثِيراً وَيَهْدِي بِهِ كَثِيراً وَما يُضِلُّ بِهِ وهو : أن الله لما ذا يضرب المثل ، كما مثل للمنافق هنا ، ومثل في سور أخرى بالعنكبوت ونحوها ؟ فإن المثال أوقع في النفوس ، وموجب لتقريب المطلب إلى الأذهان.` },
            { text: "إِنَّ ٱللَّهَ لَا يَسْتَحْىِۦٓ أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا فَأَمَّا ٱلَّذِينَ ءَامَنُوا۟ فَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَأَمَّا ٱلَّذِينَ كَفَرُوا۟ فَيَقُولُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلًا يُضِلُّ بِهِۦ كَثِيرًا وَيَهْدِى بِهِۦ كَثِيرًا وَمَا يُضِلُّ بِهِۦٓ إِلَّا ٱلْفَٰسِقِينَ", tafsir: `فإن الحياء من الأشياء القبيحة ، أو نحوها ، وليس في تمثيل الله الكبير بالأشياء الصغيرة الحقيرة ، في النظر حياء ، أي مثل كان ، وهذا معنى قوله « ما » أي شيئا من الأشياء ، ( بَعُوضَةً ) وهي البقة ( فَما فَوْقَها ) ولعل ذكر البعوضة هنا لأنها أصغر حيوان متعارف يراه كل أحد ( فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ ) أي المثل ( الْحَقُّ مِنْ رَبِّهِمْ ) وأتى به لغرض التوضيح والتبيين ( وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ ) معترضين ( ما ذا أَرادَ اللهُ بِهذا مَثَلاً ) ومثلا تمييز في معنى « بهذا المثل » ولماذا يأتي الله بهذا المثل ـ غير المناسب لجلال الله ـ ف ( يُضِلُّ بِهِ كَثِيراً وَيَهْدِي بِهِ كَثِيراً ) ويوجب انقسام الناس ، ومن المحتمل أن يكون « يضل .. . » جوابا عن اعتراضهم ، أي أن المقصود من المثل الإضلال والهداية ، لكنه ينافي السياق ، فإن المقصود بالمثل ليس ذلك ، وإنما التوضيح والتقريب ( وَما يُضِلُّ بِهِ ) أي بالمثل إِلاَّ الْفاسِقِينَ (26) الَّذِينَ يَنْقُضُونَ عَهْدَ اللهِ مِنْ بَعْدِ مِيثاقِهِ وَيَقْطَعُونَ ما أَمَرَ اللهُ بِهِ أَنْ يُوصَلَ وَيُفْسِدُونَ فِي الْأَرْضِ أُولئِكَ هُمُ الْخاسِرُونَ (27) كَيْفَ تَكْفُرُونَ بِاللهِ وَكُنْتُمْ أَمْواتاً فَأَحْياكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ (28) ( إِلَّا الْفاسِقِينَ ) الذين فسقوا أي خرجوا عن طاعة ربهم ومقتضى عقولهم ، ثم بين الفاسقين بإبراز سماتهم بقوله :` },
            { text: "ٱلَّذِينَ يَنقُضُونَ عَهْدَ ٱللَّهِ مِنۢ بَعْدِ مِيثَٰقِهِۦ وَيَقْطَعُونَ مَآ أَمَرَ ٱللَّهُ بِهِۦٓ أَن يُوصَلَ وَيُفْسِدُونَ فِى ٱلْأَرْضِ أُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ", tafsir: `الميثاق ما وقع التوثيق به ، وميثاق الله هو ما أخذ عليهم في الكتب السالفة من الإيمان ، أو هو ما أودع فيهم من الفطرة بعرفان الحق ( وَيَقْطَعُونَ ما أَمَرَ اللهُ بِهِ أَنْ يُوصَلَ ) من صلة الأرحام ، أو صلة الرسول والمؤمنين ( وَيُفْسِدُونَ فِي الْأَرْضِ ) بالكفر والنفاق وإتيان المحرمات ( أُولئِكَ هُمُ الْخاسِرُونَ ) الذين خسروا أعمارهم ، فذهبت دنياهم ضنكا وآخرتهم عذابا ونارا. [29] ثم عاد سبحانه إلى حال الكافر ، ووجه الخطاب إليه مستدلا على بطلان كفره بقوله : ( كَيْفَ تَكْفُرُونَ بِاللهِ وَكُنْتُمْ أَمْواتاً ) لا روح فيكم ، فإن أصل الإنسان التراب ، ثم يكون نباتا ، ثم يكون حيوانا وما أشبه ، فيأكله الإنسان ، فيتولد منه المني ، ثم يصير إنسانا ، ثم يموت ويرجع ترابا ، ثم يعاد يوم القيامة إنسانا ( فَأَحْياكُمْ ) نباتا أو حيوانا أو إنسانا ( ثُمَّ يُمِيتُكُمْ ) وقت موتكم ( ثُمَّ يُحْيِيكُمْ ) يوم القيامة ( ثُمَ ) بعد الحياة الثانية ( إِلَيْهِ تُرْجَعُونَ ) لتساقون إلى المحاكمة الكبرى ، وكون هُوَ الَّذِي خَلَقَ لَكُمْ ما فِي الْأَرْضِ جَمِيعاً ثُمَّ اسْتَوى إِلَى السَّماءِ فَسَوَّاهُنَّ سَبْعَ سَماواتٍ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ (29) وَإِذْ قالَ رَبُّكَ لِلْمَلائِكَةِ الرجوع إليه ، مع إن الإنسان في جميع الأحوال ، بدءا وختاما ، تحت سلطة الله وقدرته وعلمه ، باعتبار محاسبته تعالى للإنسان.` },
            { text: "كَيْفَ تَكْفُرُونَ بِٱللَّهِ وَكُنتُمْ أَمْوَٰتًا فَأَحْيَٰكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ", tafsir: `يرجى تزويدنا بنص الآية وتفسيرها لإضافتها.` },
            { text: "هُوَ ٱلَّذِى خَلَقَ لَكُم مَّا فِى ٱلْأَرْضِ جَمِيعًا ثُمَّ ٱسْتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبْعَ سَمَٰوَٰتٍ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `لمنفعتكم ( ما فِي الْأَرْضِ جَمِيعاً ) فمن خلقها غيره ، وكون الخلق للإنسان ، لا يدل على تحليل كل شيء ، بل كل شيء بحسبه ، فالأسماك المحرمة ، والحيوانات المفترسة لتمتع السمع والبصر ، لا للأكل ونحوه وهكذا ( ثُمَّ اسْتَوى ) أي توجه بالخلق والأمر ( إِلَى السَّماءِ فَسَوَّاهُنَّ سَبْعَ سَماواتٍ ) مدارات للنجوم السيارة ، فإن السماء في اللغة بمعنى المدار ـ هذا إذا قلنا بالنظر الفعلي حول السماوات ـ ويؤيده حديث عن الإمام الرضا عليه‌السلام ـ كما في « الهيئة والإسلام » (1) ـ ( وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ ) فلا يغيب عنه شيء ، فمن كفر كان الله مطلعا عليه لا يفوته ذلك ، ولا يخفى أن خلق الأرض كان أولا ، ثم خلق السماء ، ثم دحو الأرض ، كما قال ( وَالْأَرْضَ بَعْدَ ذلِكَ دَحاها ) (2) . [31] وحيث ذكر سبحانه قصة خلق السماء والأرض ، وثم البناء ، توجه الحديث إلى من استخلف فيها ( وَ ) اذكر ( إِذْ قالَ رَبُّكَ لِلْمَلائِكَةِ ) الذين هم مخلوقين في الملإ الأعلى لا يرون بالعين إلّا لمن شاء الله ( 1) للعلامة الشهرستاني. ( 2) النازعات : 31. إِنِّي جاعِلٌ فِي الْأَرْضِ خَلِيفَةً قالُوا أَ تَجْعَلُ فِيها مَنْ يُفْسِدُ فِيها وَيَسْفِكُ الدِّماءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قالَ إِنِّي أَعْلَمُ ما لا تَعْلَمُونَ (30) ( إِنِّي جاعِلٌ فِي الْأَرْضِ خَلِيفَةً ) يخلفني في الأمر والنهي والإرشاد ، وهذا الحوار إنما كان لأجل إظهار كوامن ، وبيان حقائق ( قالُوا أَ تَجْعَلُ فِيها ) أي في الأرض ( مَنْ يُفْسِدُ فِيها وَيَسْفِكُ الدِّماءَ ) وهذا استفهام حقيقي ، يريدون بذلك استيضاح السبب ، ولعلهم إنما علموا بذلك ، لما كانوا يدرون من كدرة الأرض وثقلها الموجبة للفساد والتكدر ، أو لما رأوا من فعل بني الجان سابقا ( وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ ) ففينا الكفاية ، وليس هذا تزكية ، بل كقول العبد المطيع لمولاه : إني أقوم بخدمتك فلما ذا تأتي بغيري الذي لا يقوم بالواجب ، ومعنى التسبيح التنزيه ، وكان المراد من التسبيح بحمده ، التنزيه المقترن بالحمد ، مقابل التنزيه غير المقترن به ، كتنزيه الجوهرة الثمينة عن النقائص ، لكن التنزيه فيها لا يقترن بالحمد ، إذ ليس ذلك باختيارها بخلافه تعالى المقترن أفعاله وأعماله بالإرادة ( وَنُقَدِّسُ لَكَ ) أي أن تقديسنا وتنزيهنا لأجلك لا يشوبه رياء وسمعة ( قالَ ) الله تعالى في جواب الملائكة السائلين عن السبب ( إِنِّي أَعْلَمُ ما لا تَعْلَمُونَ ) فإن في استخلاف البشر ، مصالح أهم من الفساد الواقع منهم ، كما أن استخلافهم أهم من استخلافكم فإن منهم من الأخيار والصالحين من لا يلحقه الملك المقرب ، بالإضافة إلى أنه خلق يظهر من عظمة الصانع نوعا جديدا. [32] وإذا أراد الله تعالى إعلام الملائكة ببعض مزايا البشر ، وإنه من جنس وَعَلَّمَ آدَمَ الْأَسْماءَ كُلَّها ثُمَّ عَرَضَهُمْ عَلَى الْمَلائِكَةِ فَقالَ أَنْبِئُونِي بِأَسْماءِ هؤُلاءِ إِنْ كُنْتُمْ صادِقِينَ (31) قالُوا سُبْحانَكَ لا عِلْمَ لَنا إِلاَّ ما أرفع منهم ، علّم آدم عليه‌السلام ، علوما يتمكن هو من فهمها وهضمها ، بينما لا يقدر الملائكة على ذلك ، ثم قال تعالى للملائكة : هل تتحملون مثل ذلك ؟ فأبدوا عجزهم ، وإذا رأوا من آدم التحمل والقدرة ، اعترفوا بالتفوق ، وإنه أحق بالخلافة ، وتوضيح ذلك بمثال أنه إذا كان لإنسان خادم لا يقدر فطرة على بناء دار جميلة ، ثم أراد استخدام مهندس ، فقال الخادم : لماذا تستخدم غيري وأنا حاضر ؟ يقول له السيد : إني أعلم ما لا تعلم ، ثم يستخدم المهندس ، ويبين له ما يريده من الدار ، فيقدر المهندس من بنائها ، بينما لا يقدر الخادم على النزول عند رغبة السيد ، وهناك يعترف بالعجز ، وأن السيد كان عارفا حيث تركه إلى غيره ( وَعَلَّمَ ) الله تعالى ( آدَمَ ) عليه‌السلام ( الْأَسْماءَ كُلَّها ) أسماء الأشياء وعلائمها ، وذلك يستلزم تعليم المسميات والمعلومات ، فإذا علمت أحدا اسم زيد وعمرو وبكر ، كان اللازم تعريفهم له أيضا ، ولذا قال ( ثُمَّ عَرَضَهُمْ عَلَى الْمَلائِكَةِ ) بإتيان ضمير « هم » تغليبا للعقلاء على غيرهم ، والعرض على الملائكة ( فَقالَ أَنْبِئُونِي بِأَسْماءِ هؤُلاءِ إِنْ كُنْتُمْ صادِقِينَ ) صدقا خبريا يطابق كلامكم الواقع في أنكم كافين في الاستخلاف ، ولعل تعليم آدم كان بالإلهام ، وخلق العلم فيه ، مما هو قابل له ، دون الملائكة ، فإنهم لم يكونوا قابلين لهذا العلم والإلهام ، فلا يقال لماذا لم يعلّم الله تعالى الملائكة.` },
            { text: "وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌ فِى ٱلْأَرْضِ خَلِيفَةً قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ", tafsir: `يرجى تزويدنا بنص الآية وتفسيرها لإضافتها.` },
            { text: "وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `يرجى تزويدنا بنص الآية وتفسيرها لإضافتها.` },
            { text: "قَالُوا۟ سُبْحَٰنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُ", tafsir: `أنت منزه عن القبيح والعبث ( لا عِلْمَ لَنا إِلَّا ما عَلَّمْتَنا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ (32) قالَ يا آدَمُ أَنْبِئْهُمْ بِأَسْمائِهِمْ فَلَمَّا أَنْبَأَهُمْ بِأَسْمائِهِمْ قالَ أَ لَمْ أَقُلْ لَكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّماواتِ وَالْأَرْضِ وَأَعْلَمُ ما تُبْدُونَ وَما كُنْتُمْ تَكْتُمُونَ (33) وَإِذْ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ عَلَّمْتَنا ) فليس لنا هذا العلم الذي لآدم مما هو قابل له ، ولسنا قابلين له ( إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ ) والحكيم هو الذي يفعل الأشياء عن حكمة ، بمعنى وضع الأشياء في مواضعها اللائقة بها.` },
            { text: "قَالَ يَٰٓـَٔادَمُ أَنۢبِئْهُم بِأَسْمَآئِهِمْ فَلَمَّآ أَنۢبَأَهُم بِأَسْمَآئِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّىٓ أَعْلَمُ غَيْبَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ", tafsir: `أي بأسماء ما عرضهم على الملائكة ( فَلَمَّا أَنْبَأَهُمْ بِأَسْمائِهِمْ ) وعرفت الملائكة كون قابلية آدم فوق قابليتهم ( قالَ ) الله تعالى لهم ( أَ لَمْ أَقُلْ لَكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّماواتِ وَالْأَرْضِ ) ما غاب عن إدراككم ( وَأَعْلَمُ ما تُبْدُونَ ) أي تظهرون ( وَما كُنْتُمْ تَكْتُمُونَ ) من حسد بعضكم ـ وهو الشيطان ـ لآدم عليه‌السلام : ثم أن مقتضى اللطف العام والرحمة الواسعة أن يخلق الله تعالى أنواع المخلوقات الممكنة ، التي لا يمنع عن خلقها مانع ، ولذا خلق الملائكة دون البشر ، وخلق بعض كل من الصنفين أرفع من البعض الأخر ، فلا مجال للتساؤل ، فلما ذا لم يجعل الله تعالى هذه القابلية البشرية في الملائكة ؟ وثم خلق آدم عليه‌السلام ، وانتهى كل شيء.` },
            { text: "وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ", tafsir: `أذكر ( إِذْ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ ) إما بأن يكون هو قبلتهم ويكون السجود لله سبحانه ، وإما أن يكون السجود لآدم ، ولا دليل عقلي على إنه لا يجوز لغير الله تعالى ، نعم ورد الشرع بذلك بالنسبة فَسَجَدُوا إِلاَّ إِبْلِيسَ أَبى وَاسْتَكْبَرَ وَكانَ مِنَ الْكافِرِينَ (34) وَقُلْنا يا آدَمُ اسْكُنْ أَنْتَ وَزَوْجُكَ الْجَنَّةَ وَكُلا مِنْها رَغَداً حَيْثُ شِئْتُما وَلا تَقْرَبا هذِهِ الشَّجَرَةَ فَتَكُونا مِنَ الظَّالِمِينَ (35) إلى المسلمين ( فَسَجَدُوا إِلَّا إِبْلِيسَ ) هو الشيطان ( أَبى وَاسْتَكْبَرَ ) أي امتنع وأنف ( وَكانَ مِنَ الْكافِرِينَ ) التفات ، كما نقول نحن « كان أبو جهل كافرا » وليس حكاية ، عطفا على « أبى » حتى يستلزم كونه كافرا من قبل ذلك.` },
            { text: "وَقُلْنَا يَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ", tafsir: `حواء عليها‌السلام ، قال لهما ذلك ، بعد ما خلق حواء أيضا ، خلقا كخلق آدم ابتداء من غير أب وأم ( الْجَنَّةَ ) الجنة هو البستان ، وقد كانت لله تعالى جنة أسكنها آدم وحواء ( وَكُلا مِنْها رَغَداً ) أكلا واسعا ، بلا زحمة وتكلف ( حَيْثُ شِئْتُما ) من أطراف الجنة ( وَلا تَقْرَبا هذِهِ الشَّجَرَةَ ) فقد نهوا عن شجرة واحدة ، اختبارا وامتحانا ، وكانت الشجرة على قول جمع « الحنطة » وقد كان النهي إرشاديا ، كنهي الطبيب مريضه أن لا يأكل ما يضره ، وقد كانت فائدة عدم أكلهما لها أنهما يبقيان في الجنة ، كما قال سبحانه ( إِنَّ لَكَ أَلَّا تَجُوعَ فِيها وَلا تَعْرى * وَأَنَّكَ لا تَظْمَؤُا فِيها وَلا تَضْحى ) (1) ( فَتَكُونا مِنَ الظَّالِمِينَ ) فإن الإنسان إذا حرم نفسه من الخير ، كان ظالما لها ، إذ الظلم بمعنى وضع الشيء في غير موضعه ، كما إن العدل معناه وضع الشيء موضعه. ( 1) طه : 119 و 120. فَأَزَلَّهُمَا الشَّيْطانُ عَنْها فَأَخْرَجَهُما مِمَّا كانا فِيهِ وَقُلْنَا اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتاعٌ إِلى حِينٍ (36) فَتَلَقَّى آدَمُ مِنْ رَبِّهِ كَلِماتٍ فَتابَ عَلَيْهِ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ (37) قُلْنَا اهْبِطُوا مِنْها جَمِيعاً فَإِمَّا` },
            { text: "فَأَزَلَّهُمَا ٱلشَّيْطَٰنُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ وَقُلْنَا ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ", tafsir: `أي حمل الشيطان آدم وحواء على الزلة عن الجنة ، بسبب إنه حملهما على الأكل من الشجرة ( فَأَخْرَجَهُما مِمَّا كانا فِيهِ ) من النعيم ( وَقُلْنَا اهْبِطُوا ) الخطاب لآدم وحواء والشيطان ، والهبوط إما حقيقي ، إن كان محل أعلى إلى أسفل ، أو رتبي ( بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ) فإن الشيطان عدوهما ، وهما عدوان له ( وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ ) محل القرار ( وَمَتاعٌ ) أي استمتاع ( إِلى حِينٍ ) إلى حين انقضاء الدنيا ، أو موت كل أحد ، وإذ ارتكب آدم خلاف الأولى بأكل الشجرة ، وأهبطه الله تعالى من الجنة تداركته الرحمة.` },
            { text: "فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٍ فَتَابَ عَلَيْهِ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ", tafsir: `أي أخذ ( آدَمُ مِنْ رَبِّهِ كَلِماتٍ ) تسبب التوبة والرجوع عن الزلة ، وكان ذلك بتعليم الله تعالى له أن يجري تلك الكلمات على لسانه ، فأجراها ( فَتابَ ) الله ( عَلَيْهِ ) أي على آدم ( إِنَّهُ هُوَ التَّوَّابُ ) أي كثير القبول للتوبة ( الرَّحِيمُ ) بعباده.` },
            { text: "قُلْنَا ٱهْبِطُوا۟ مِنْهَا جَمِيعًا فَإِمَّا يَأْتِيَنَّكُم مِّنِّى هُدًى فَمَن تَبِعَ هُدَاىَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `إنما كرر الأمر بالهبوط توطئة لموضوع آخر ، وهو أمر الهداية ، بعد ذكر المقر والمتاع ، كما يقال : قلت له اذهب تربح ، قلت له اذهب تسلم ( فَإِمَّا ) أصله « إن » الشرطية ، و « ما » يَأْتِيَنَّكُمْ مِنِّي هُدىً فَمَنْ تَبِعَ هُدايَ فَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (38) وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآياتِنا أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (39) الزائدة ، دخلت عليها لتصحيح نون التأكيد ، يعني فإن ( يَأْتِيَنَّكُمْ ) أيها البشر الذي في صلب آدم ( مِنِّي هُدىً ) يهديكم إلى الحق ( فَمَنْ تَبِعَ هُدايَ فَلا خَوْفٌ عَلَيْهِمْ ) في الدنيا ولا في الآخرة ( وَلا هُمْ يَحْزَنُونَ ) إذ الخوف الكامل ، إنما يكون من أمر مكروه ، ولا يعوض ، وكذلك الحزن ومصائب المؤمنين تعوّض ، فلا خوف كامل منها ، والفرق بين الخوف والحزن : أن الأول لأمر مترقب ، والثاني لأمر حادث ـ غالبا ـ ولا مانع من الخطاب إلى المعدوم إذا كان المقصود منه الوصول إليه بعد وجوده ، هذا مع الغض عن عالم الذر ، كما لا مانع من الجمع بين « إن » و « نون التوكيد » إذ المعنى إن أتاكم إتيانا قطعيا مقابل الإتيان المظنون.` },
            { text: "وَٱلَّذِينَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔايَٰتِنَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `فلم يؤمنوا بعد أن تمت عليهم الحجة ، ولعل هذا سر قوله « كذبوا » بعد « كفروا » إذ الكفر لا يلازم التكذيب ، إذا كان عن قصور ( أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) أبدا ولا يخفى أن المقصر المعاند خالد أبدا أما غيره فيمتحن هناك. [41] ولما أتم القرآن الكريم قصة « آدم » واستخلافه في الأرض ، وجه الكلام إلى « بني إسرائيل » الذين هم نموذج للجنس البشري ، وقد أتتهم يا بَنِي إِسْرائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا بِعَهْدِي أُوفِ بِعَهْدِكُمْ وَإِيَّايَ فَارْهَبُونِ (40) وَآمِنُوا بِما أَنْزَلْتُ مُصَدِّقاً لِما مَعَكُمْ الأنبياء عليهم‌السلام « هدى » وأنعم عليهم الله تعالى ، فكفروا بالنعم ، وقتلوا الأنبياء ، ليكون فذلكة لقصة آدم ، ودرسا لأمة محمد صلى‌الله‌عليه‌وآله‌وسلم ( يا بَنِي إِسْرائِيلَ ) هم اليهود ، وإسرائيل اسم يعقوب النبي عليه‌السلام ، نسبوا إلى أبيهم الأعلى ، كما نسب البشر إلى أبيهم الأعلى ، في قوله ( يا بَنِي آدَمَ ) (1) ( اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ ) وحيث لم يذكر المتعلق أفاد العموم ، فيشمل كل نعمة مادية أو معنوية ( وَأَوْفُوا بِعَهْدِي ) وحيث لم يذكر المتعلق أفاد كل عهد عهده ، سواء كان ذلك وقت أخذ موسى عليه‌السلام عنهم العهد بالإيمان بالرسول صلى‌الله‌عليه‌وآله‌وسلم ، أم كان وقت أخذ الله عنهم العهد في عالم الذر ، ثم أودع فيهم الفطرة دليلا عليه ( أُوفِ بِعَهْدِكُمْ ) بإعطائكم الدنيا والآخرة ، فإن الله سبحانه ضمن لمن وفي بعهده ، أن يعمر دنياه وآخرته ( وَإِيَّايَ فَارْهَبُونِ ) الرهبة هي الخوف ، يعني يجب أن يكون الخوف من الله ، لا من الناس.` },
            { text: "يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا۟ بِعَهْدِىٓ أُوفِ بِعَهْدِكُمْ وَإِيَّٰىَ فَٱرْهَبُونِ", tafsir: `يرجى تزويدنا بنص الآية وتفسيرها لإضافتها.` },
            { text: "وَءَامِنُوا۟ بِمَآ أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوٓا۟ أَوَّلَ كَافِرٍۭ بِهِۦ وَلَا تَشْتَرُوا۟ بِـَٔايَٰتِى ثَمَنًا قَلِيلًا وَإِيَّٰىَ فَٱتَّقُونِ", tafsir: `من القرآن ( مُصَدِّقاً لِما مَعَكُمْ ) من التوراة ، فإن التوراة الأصلية ، كانت مصدقة ، حتى في زمان النبي صلى‌الله‌عليه‌وآله‌وسلم إلا ما نسخ منها ، والنسخ ليس إبطالا لها ، كما أن نسخ بعض الأحكام في ( 1) الأعراف : 28. وَلا تَكُونُوا أَوَّلَ كافِرٍ بِهِ وَلا تَشْتَرُوا بِآياتِي ثَمَناً قَلِيلاً وَإِيَّايَ فَاتَّقُونِ (41) وَلا تَلْبِسُوا الْحَقَّ بِالْباطِلِ وَتَكْتُمُوا الْحَقَّ وَأَنْتُمْ تَعْلَمُونَ (42) القرآن ـ على القول به ـ ليس إبطالا له ( وَلا تَكُونُوا أَوَّلَ كافِرٍ بِهِ ) أي أول من يكفر بما أنزلت ، وإنما كانوا أول كافر ، لأنهم بسبب علمهم كانوا مرجعا للجهال ، فيكون كفر الجهال بمرتبة ثانية ( وَلا تَشْتَرُوا بِآياتِي ثَمَناً قَلِيلاً ) أي بمقابل آياتي ، بأن تعطوا الآيات ـ بمعنى عدم الإيمان بها ـ في مقابل ثمن قليل ، هو رئاسة الدنيا وكونها قليلا لانقطاعها ( وَإِيَّايَ فَاتَّقُونِ ) فالتقوى يجب أن تكون منه تعالى ، لا أن يكون الاتقاء من غيره ، لأن الله بيده النفع والضر دون غيره ، كما قال تعالى ( قُلْ كُلٌّ مِنْ عِنْدِ اللهِ ) (1) .` },
            { text: "وَلَا تَلْبِسُوا۟ ٱلْحَقَّ بِٱلْبَٰطِلِ وَتَكْتُمُوا۟ ٱلْحَقَّ وَأَنتُمْ تَعْلَمُونَ", tafsir: `اللبس هو التعمية ، أي لا تخلطوا الحق بالباطل ، فتأخذوا ببعض التوراة الذي هو في نفعكم ، وتتركوا بعضها الذي يضركم وهو بعض الأحكام التي تركوها ، ومنها التبشير بمحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَ ) لا ( تَكْتُمُوا الْحَقَ ) الذي هو أوصاف النبي صلى‌الله‌عليه‌وآله‌وسلم وبعض الأحكام الأخر ، كما قال سبحانه ( قُلْ فَأْتُوا بِالتَّوْراةِ فَاتْلُوها إِنْ كُنْتُمْ صادِقِينَ ) (2) ( وَأَنْتُمْ تَعْلَمُونَ ) بصنعكم وأنه تلبيس المحق بالباطل ، وكتمان الحق. ( 1) النساء : 79. ( 2) آل عمران : 94. وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ (43) أَ تَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنْسَوْنَ أَنْفُسَكُمْ وَأَنْتُمْ تَتْلُونَ الْكِتابَ أَ فَلا تَعْقِلُونَ (44) وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ وَإِنَّها` },
            { text: "وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱرْكَعُوا۟ مَعَ ٱلرَّٰكِعِينَ", tafsir: `كما يأمر الإسلام ( وَارْكَعُوا مَعَ الرَّاكِعِينَ ) الذين هم المسلمون.` },
            { text: "أَتَأْمُرُونَ ٱلنَّاسَ بِٱلْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ ٱلْكِتَٰبَ أَفَلَا تَعْقِلُونَ", tafsir: `استفهام إنكاري ، أي لم تأمرون الناس بالأعمال الخيرية ( وَتَنْسَوْنَ أَنْفُسَكُمْ ) فلا تعملون بها والنسيان كفاية عن عدم العمل لشبهه به في النتيجة ، كما قال سبحانه ( نَسُوا اللهَ فَنَسِيَهُمْ ) (1) فقد كان اليهود يخالفون أحكام التوراة ، ويرتشون ويفسدون ويكذبون ( وَأَنْتُمْ تَتْلُونَ الْكِتابَ ) جملة حالية ، أي والحال أنتم تقرءون كتاب الله ، فاللازم أن تكونوا أول العاملين به ( أَ فَلا تَعْقِلُونَ ) أي ألا تعلمون أن ما تأتون به قبيح ؟.` },
            { text: "وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلْخَٰشِعِينَ", tafsir: `في رجوعكم عن دينكم وإلغائكم لرؤسائكم ـ بما يجر ذلك عليكم من سلب بعض دنياكم ـ ( بِالصَّبْرِ ) فإنكم إذا صبرتم على ما تكرهون من اتباع النبي صلى‌الله‌عليه‌وآله‌وسلم عاد ذلك عليكم بخير مما أنتم فيه ( وَالصَّلاةِ ) فإن الصلاة توجب تهدئة النفس ، واطمئنان الخاطر ( أَلا بِذِكْرِ اللهِ تَطْمَئِنُّ الْقُلُوبُ ) (2) ( وَإِنَّها ) أي الاستعانة بالصبر والصلاة ( 1) التوبة : 67. ( 2) الرعد : 29. لَكَبِيرَةٌ إِلاَّ عَلَى الْخاشِعِينَ (45) الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ راجِعُونَ (46) يا بَنِي إِسْرائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ (47) ( لَكَبِيرَةٌ إِلَّا عَلَى الْخاشِعِينَ ) فإن الصبر ليس أمرا هينا ، والصلاة الكاملة ليست عملا سهلا ، وإنما قيدنا الصلاة بالكاملة ، لأنها هي التي يستعان بها ، أو أن المراد الصلوات اليومية ، وهي صعبة جدا إلا على الذين يخشون الله سبحانه. [47] ثم فسر الخاشعين بأنهم ( الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا رَبِّهِمْ ) الظن إما بمعنى اليقين ، وإما بمعنى الرجحان ، ولعل السر في هذا التعبير دون اليقين ، للإشارة إلى أدنى مراتب الرجحان يوجب الخشوع ، فإن من يظن أنه يلاقي الملك لبعثه ذلك على التهيئة ، فكيف بمن يظن أنه يلاقي مالك الملوك ، وملاقاة الله كناية عن الحضور للمحاسبة ، وإلا فالله سبحانه ليس أدنى إلى الناس في القيامة منه إليهم في الدنيا ( وَأَنَّهُمْ إِلَيْهِ راجِعُونَ ) والرجوع إليه معنوي كما تقدم.` },
            { text: "ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَٰجِعُونَ", tafsir: `يرجى تزويدنا بنص الآية وتفسيرها لإضافتها.` },
            { text: "يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ", tafsir: `تكرار للتركيز والإلفات ، فإن الإنسان ربما كان غافلا حين التذكير الأول ، فيذكر ثانيا وثالثا ، بالإضافة إلى أن النفس ، إذا كررت عليها الموعظة ، رسخت فيها ( وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ ) التفضيل على عالم زمانهم لا على كل العوالم ، فإن الظاهر من هكذا تفضيلات هو الاختصاص ، فلو قيل أن « الدولة الفلانية أقوى الدول » لم يفهم منه إلا وَاتَّقُوا يَوْماً لا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئاً وَلا يُقْبَلُ مِنْها شَفاعَةٌ وَلا يُؤْخَذُ مِنْها عَدْلٌ وَلا هُمْ يُنْصَرُونَ (48) وَإِذْ نَجَّيْناكُمْ مِنْ آلِ فِرْعَوْنَ الإقوائية من الدول المعاصرة لها ، لأكل دولة أتت أو تأتي ، ثم أن تفضيلهم على العالمين إنما كان لأجل إيمانهم بموسى عليه‌السلام ، بينما كان العالم بين كافر به عنادا ، كفرعون ومن تبعه ، أو جهلا كمن كان في البلاد البعيدة التي لم تبلغهم دعوة موسى فكانوا قاصرين.` },
            { text: "وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا شَفَٰعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ", tafsir: `أي لا تغني ، فلا تدفع نفس عن نفس مكروها ، وإنما الأمر كله لله ، حتى أن الشفاعة تكون بإذنه ، والمراد بذلك اليوم ـ القيامة ـ ومعنى التقوى منه الاستعداد له ( وَلا يُقْبَلُ مِنْها ) أي من النفس ( شَفاعَةٌ ) إلا إذا أذن الله للشفيع ( وَلا يُؤْخَذُ مِنْها ) أي من النفس ( عَدْلٌ ) أي فدية ، وإنما سميت الفدية عدلا ، لأنها تعادل المفدى ( وَلا هُمْ يُنْصَرُونَ ) فإن طريق الخلاص في الدنيا إحدى هذه الأربعة ، وليست شيء منها في الآخرة ، إلا إذا أذن الله في الشفاعة ، وعدم الاستثناء من « شفاعة » لأجل أن المراد منها الشفاعات الارتجالية ، كما هو المعتاد في الدنيا.` },
            { text: "وَإِذْ نَجَّيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُذَبِّحُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ", tafsir: `اذكروا يا بني إسرائيل نعمة أنعمناها عليكم ( إِذْ نَجَّيْناكُمْ مِنْ آلِ فِرْعَوْنَ ) ومن المتعارف ، أن ينسب الشيء المرتبط ببعض الأمة إلى جميعها ، إذ يجمعهم العطف والهدى والانتصار ، فيقال بنو تميم قتلوا فلانا ، وإنما قتله بعضهم ، أو عشيرة فلان شجعان ، وإنما جماعة منهم كذلك ، ولذا قال سبحانه « نجيناكم » وقد كانت التنجية بالنسبة إلى يَسُومُونَكُمْ سُوءَ الْعَذابِ يُذَبِّحُونَ أَبْناءَكُمْ وَيَسْتَحْيُونَ نِساءَكُمْ وَفِي ذلِكُمْ بَلاءٌ مِنْ رَبِّكُمْ عَظِيمٌ (49) وَإِذْ فَرَقْنا بِكُمُ الْبَحْرَ أسلافهم ، والمراد بآل الرجل قومه وخواصه وإن لم تكن بينهم قرابة ، كما يقال « آل الله » لأهل البيت عليهم‌السلام ( يَسُومُونَكُمْ سُوءَ الْعَذابِ ) وسامه خسفا عذابا بمعنى ألقاه فيه ، ثم فسر سوء العذاب بقوله ( يُذَبِّحُونَ أَبْناءَكُمْ ) التذبيح هو التكثير في الذبح ( وَيَسْتَحْيُونَ نِساءَكُمْ ) أي يدعونهن أحياء ، فإن فرعون ملك القبط ، لما علم من الكهان ، أنه يولد في بني إسرائيل ـ الذين كانوا طائفة خاصة من آل يعقوب عليهم‌السلام ـ أمر بذبح الأولاد وإبقاء النساء للاسترقاق والنكاح ( وَفِي ذلِكُمْ ) « كم » خطاب فقط ، و « ذا » إشارة ، فإذا كان طرف الخطاب واحد يقال « ذلك » وإذا كان اثنين يقال « ذلكما » وإذا كانوا جماعة يقال « ذلكم » و « ذا » هنا اسم إشارة إلى سوء العذاب ( بَلاءٌ مِنْ رَبِّكُمْ عَظِيمٌ ) أنها كانت بالنسبة إلى الله تعالى ، لأنه لم يحل بين فرعون ، وبين هذا العمل ، كما يقال ، إن الأب أفسد ولده إذا لم يحل بينه وبين عمله الفاسد ، وعدم حيلولة الله تعالى ، لأجل الامتحان والاختبار ـ كما تقدم ـ والإنجاء ، إنما كان بإهلاك فرعون وقومه.` },
            { text: "وَإِذْ فَرَقْنَا بِكُمُ ٱلْبَحْرَ فَأَنجَيْنَٰكُمْ وَأَغْرَقْنَآ ءَالَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ فَرَقْنا بِكُمُ الْبَحْرَ ) أي جعلنا فواصل في البحر ، حتى صارت بين الماء شوارع ، وكان عملنا هذا بسببكم ولأجلكم ، والمراد بالبحر ـ البحر الأحمر في مصر ـ وقد كان طول فَأَنْجَيْناكُمْ وَأَغْرَقْنا آلَ فِرْعَوْنَ وَأَنْتُمْ تَنْظُرُونَ (50) وَإِذْ واعَدْنا مُوسى أَرْبَعِينَ لَيْلَةً ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ الشوارع التي أسفرت عنها الماء ما يقرب من أربعة فراسخ ، فإن موسى عليه‌السلام وبني إسرائيل فروا من فرعون فوصلوا إلى البحر وعقبهم فرعون وقومه ، فأمر الله موسى عليه‌السلام أن يضرب بعصاه البحر ، فضرب فانحسر الماء عن الشوارع حتى عبر بنوا إسرائيل ، وأتبعهم فرعون وجنوده ولما توسطوا الماء ، وخرج موسى عليه‌السلام وقومه ، رجع الماء إلى حالته الأولية ، فأغرق فرعون وقومه ( فَأَنْجَيْناكُمْ ) من عدوكم ( وَأَغْرَقْنا آلَ فِرْعَوْنَ ) مع فرعون ، ولم يذكر تغليبا للآل عليه ( وَأَنْتُمْ تَنْظُرُونَ ) كيف أغرقناهم لأجلكم ، ولا يخفى أن الإعجاز هين بالنسبة إلى الله سبحانه ، فتأويل بعض الناس للمعاجز انهزام مادي غربي.` },
            { text: "وَإِذْ وَٰعَدْنَا مُوسَىٰٓ أَرْبَعِينَ لَيْلَةً ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ واعَدْنا مُوسى أَرْبَعِينَ لَيْلَةً ) واعد بمعنى وعد ، وإن موسى عليه‌السلام قبل ، ولذا جيء بصيغة المفاعلة ، ولا ينافي كون الوعد هنا أربعين ليلة ، وفي آية أخرى ثلاثين ، فإن هذه الآية بالنسبة إلى الوعدين ، وفي الآية الأخرى بالنسبة إلى الوعد الأول ، فقد كان الله سبحانه وعد موسى أولا ثلاثين ، ثم مدده وأضاف عشرا ، والوعد كان لإعطاء الثروة التي فيها أحكام الله ، وتنظيم أمور بني إسرائيل الذي هو نعمة عظيمة ( ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ ) ، أي من بعد موسى عليه‌السلام أي وقت ذهابه إلى الطور للوعد ، فإنهم بعد ما ذهب موسى عليه‌السلام ، لميقات ربه صنعوا عجلا من ذهب ، وجعلوه إلها لهم وسجدوا له ، فقابلوا نعم الله عليهم بالكفران ، وعبادة العجل. وَأَنْتُمْ ظالِمُونَ (51) ثُمَّ عَفَوْنا عَنْكُمْ مِنْ بَعْدِ ذلِكَ لَعَلَّكُمْ تَشْكُرُونَ (52) وَإِذْ آتَيْنا مُوسَى الْكِتابَ وَالْفُرْقانَ لَعَلَّكُمْ تَهْتَدُونَ (53) وَإِذْ قالَ مُوسى لِقَوْمِهِ يا قَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنْفُسَكُمْ بِاتِّخاذِكُمُ الْعِجْلَ فَتُوبُوا إِلى بارِئِكُمْ فَاقْتُلُوا أَنْفُسَكُمْ ذلِكُمْ ( وَأَنْتُمْ ظالِمُونَ ) جملة حالية ، والمراد ظلمهم بأنفسهم.` },
            { text: "ثُمَّ عَفَوْنَا عَنكُم مِّنۢ بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ", tafsir: `عبادتكم للعجل ( مِنْ بَعْدِ ذلِكَ ) الاتخاذ ( لَعَلَّكُمْ تَشْكُرُونَ ) نعمنا عليكم ، فتعملوا بأوامرنا.` },
            { text: "وَإِذْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَٱلْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ آتَيْنا مُوسَى ) نبيكم ( الْكِتابَ ) وهو التوراة ( وَالْفُرْقانَ ) أي الفارق بين الحق والباطل ، فهو أهم من الكتاب ( لَعَلَّكُمْ تَهْتَدُونَ ) ولعل ليس ترجيا من الله سبحانه بل بمعنى عاقبة الترجي.` },
            { text: "وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦ يَٰقَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِٱتِّخَاذِكُمُ ٱلْعِجْلَ فَتُوبُوٓا۟ إِلَىٰ بَارِئِكُمْ فَٱقْتُلُوٓا۟ أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ قالَ مُوسى لِقَوْمِهِ ) الذين عبدوا العجل وقت ذهاب موسى إلى الطور لتلقي التوراة والأوامر من الله سبحانه ( يا قَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنْفُسَكُمْ بِاتِّخاذِكُمُ الْعِجْلَ ) إلها فإن اتخاذه موجب للغضب والذلة في الحياة الدنيا والآخرة ( فَتُوبُوا ) توبة ( إِلى بارِئِكُمْ ) الذي برءكم وخلقكم وهو إلهكم ( فَاقْتُلُوا أَنْفُسَكُمْ ) بأن يقتل من لم يعبد العجل من عبده ولو كان قريبا له ، فإنه كفارة للقاتل حيث سكت ولم يتكلم ، وللمقتول حيث عبد العجل ( ذلِكُمْ ) القتل خَيْرٌ لَكُمْ عِنْدَ بارِئِكُمْ فَتابَ عَلَيْكُمْ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ (54) وَإِذْ قُلْتُمْ يا مُوسى لَنْ نُؤْمِنَ لَكَ حَتَّى نَرَى اللهَ جَهْرَةً فَأَخَذَتْكُمُ الصَّاعِقَةُ وَأَنْتُمْ تَنْظُرُونَ (55) ثُمَّ بَعَثْناكُمْ ( خَيْرٌ لَكُمْ ) إذ الألم القليل خير من عذاب النار الدائم ( عِنْدَ بارِئِكُمْ ) متعلق بخير ، أي إن هذا العمل خير عند الله تعالى ، وفي حكمه وإرادته ، وذلك مقابل الخير عند الناس الذي هو بالبقاء والعيش في الدنيا ( فَتابَ عَلَيْكُمْ ) بعد ما سمعتم الأمر بأن تبتم ، وقتل بعضكم بعضا ، ومعنى تاب عليكم ، قبل توبتكم ( إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ ) بكم ، فلم يغضب حتى لا يقبل توبتكم أبدا.` },
            { text: "وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى ٱللَّهَ جَهْرَةً فَأَخَذَتْكُمُ ٱلصَّٰعِقَةُ وَأَنتُمْ تَنظُرُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ قُلْتُمْ يا مُوسى لَنْ نُؤْمِنَ لَكَ ) بأن لنا إلها خلقنا وبيده أمورنا ، أو لن نؤمن لك بأنك نبي مبعوث من قبل الله سبحانه ( حَتَّى نَرَى اللهَ جَهْرَةً ) أي علانية وعيانا ، فيخبرنا بذلك ، وذلك أن موسى عليه‌السلام اختار من قومه سبعين رجلا يحضرون معه إلى الميقات ، لما طلبت بنو إسرائيل منه ذلك ، ولما جاءوا طلبوا رؤية الله تعالى ( فَأَخَذَتْكُمُ الصَّاعِقَةُ ) وهي نار تنزل من السماء ، أو مادة مذابة من المعدن ونحوه ، فتصيب الإنسان فتقتله ، فإنهم لما طلبوا رؤية الله سبحانه ، نزلت صاعقة من السماء فقتلتهم جميعا ( وَأَنْتُمْ تَنْظُرُونَ ) حال نزولها ، وسبب موتكم ، فكان ذلك دليلا لكم على ذنبكم وخطإكم ولم يكن موتا لم يعرف سببه حتى تقولوا إنه أمر طبيعي.` },
            { text: "ثُمَّ بَعَثْنَٰكُم مِّنۢ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ", tafsir: `أي أحييناكم لما طلب موسى عليه‌السلام ذلك لئلا يقول مِنْ بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ (56) وَظَلَّلْنا عَلَيْكُمُ الْغَمامَ وَأَنْزَلْنا عَلَيْكُمُ الْمَنَّ وَالسَّلْوى كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ وَما ظَلَمُونا وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ (57) وَإِذْ قُلْنَا ادْخُلُوا هذِهِ الْقَرْيَةَ فَكُلُوا مِنْها حَيْثُ شِئْتُمْ الباقي من بني إسرائيل ، إنه عليه‌السلام قتلهم في الطور ( مِنْ بَعْدِ مَوْتِكُمْ ) بسبب الصاعقة ( لَعَلَّكُمْ تَشْكُرُونَ ) نعمنا عليكم.` },
            { text: "وَظَلَّلْنَا عَلَيْكُمُ ٱلْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ", tafsir: `اذكروا يا بني إسرائيل ، إذ كنتم في « التيه » حين أمرتم بحرب العمالقة فعصيتم فبقيتم في الصحراء مدة مديدة ، وكنتم تتأذون من حر الشمس ، ولم يكن لكم مأكل ف ( ظَلَّلْنا عَلَيْكُمُ الْغَمامَ ) بأن جعلناه سترة لكم تقيكم حر الشمس وبرد القمر ( وَأَنْزَلْنا عَلَيْكُمُ الْمَنَّ وَالسَّلْوى ) المن شيء يشبه « الترنجبين » مادة حلوة ، كانت تقع على أشجارهم فيأكلوها والسلوى طير السماني ، وإنزال السماني ، إما بكون هذا الطير ، كان كثيرا في التيه ، فكانوا يصطادونه ، أو بأنه كان ينزل عليهم الطير المشوي ، وقلنا لكم ( كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ ) طيب مذاقا ، وحقيقة لكونه حلالا ، لكنهم كفروا بعد كل هذه النعم ( وَما ظَلَمُونا ) بكفرانهم ، فإنهم لن يضروا الله شيئا ( وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ ) لأنهم أورثوا لأنفسهم ذلة في الدنيا وعذابا في الآخرة.` },
            { text: "وَإِذْ قُلْنَا ٱدْخُلُوا۟ هَٰذِهِ ٱلْقَرْيَةَ فَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا وَقُولُوا۟ حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَٰيَٰكُمْ وَسَنَزِيدُ ٱلْمُحْسِنِينَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ قُلْنَا ) لكم بعد أن خرجتم عن التيه ( ادْخُلُوا هذِهِ الْقَرْيَةَ ) بيت المقدس ، أو « أريحا » وهي بلدة قريبة من بيت المقدس ( فَكُلُوا مِنْها حَيْثُ شِئْتُمْ ) من الأماكن أو المآكل رَغَداً وَادْخُلُوا الْبابَ سُجَّداً وَقُولُوا حِطَّةٌ نَغْفِرْ لَكُمْ خَطاياكُمْ وَسَنَزِيدُ الْمُحْسِنِينَ (58) فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلاً غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَنْزَلْنا عَلَى الَّذِينَ ظَلَمُوا رِجْزاً مِنَ السَّماءِ بِما كانُوا يَفْسُقُونَ (59) وَإِذِ اسْتَسْقى مُوسى لِقَوْمِهِ ( رَغَداً ) واسعا ( وَادْخُلُوا الْبابَ ) أي باب القرية ( سُجَّداً ) جمع ساجد ، أي في حال كونكم ساجدين ( وَقُولُوا حِطَّةٌ ) أي سجودنا لله حطة لذنوبنا ، ومحو لسيئاتنا ، فإن فعلتم ذلك ( نَغْفِرْ لَكُمْ خَطاياكُمْ ) السالفة ( وَسَنَزِيدُ الْمُحْسِنِينَ ) منكم من خير الدنيا وخير الآخرة على ما يستحقون ، كما قال سبحانه ( لِيُوَفِّيَهُمْ أُجُورَهُمْ وَيَزِيدَهُمْ مِنْ فَضْلِهِ ) (1) .` },
            { text: "فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى ٱلَّذِينَ ظَلَمُوا۟ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَفْسُقُونَ", tafsir: `فقالوا « حنطة حمراء خير لنا » عوض « حطة » كما إنهم دخلوا بأستاهم عوض أن يدخلوا سجدا ( فَأَنْزَلْنا عَلَى الَّذِينَ ظَلَمُوا ) فيما فعلوا ( رِجْزاً مِنَ السَّماءِ ) الرجز العذاب ( بِما كانُوا يَفْسُقُونَ ) أي بسبب عصيانهم.` },
            { text: "وَإِذِ ٱسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِۦ فَقُلْنَا ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنفَجَرَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ كُلُوا۟ وَٱشْرَبُوا۟ مِن رِّزْقِ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ", tafsir: `اذكروا يا بني إسرائيل ( إِذِ اسْتَسْقى مُوسى لِقَوْمِهِ ) أي سأل موسى عليه‌السلام من الله تعالى أن يسقيهم ، وذلك حين كانوا في التيه ، ( 1) فاطر : 31. فَقُلْنَا اضْرِبْ بِعَصاكَ الْحَجَرَ فَانْفَجَرَتْ مِنْهُ اثْنَتا عَشْرَةَ عَيْناً قَدْ عَلِمَ كُلُّ أُناسٍ مَشْرَبَهُمْ كُلُوا وَاشْرَبُوا مِنْ رِزْقِ اللهِ وَلا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ (60) وَإِذْ قُلْتُمْ يا مُوسى لَنْ نَصْبِرَ عَلى طَعامٍ واحِدٍ فَادْعُ لَنا رَبَّكَ يُخْرِجْ لَنا مِمَّا تُنْبِتُ الْأَرْضُ مِنْ بَقْلِها وَقِثَّائِها وَفُومِها وَعَدَسِها وَبَصَلِها ولم يكن لهم ماء فظمئوا ( فَقُلْنَا اضْرِبْ بِعَصاكَ الْحَجَرَ ) وعصاه هي التي صارت ثعبانا ، والحجر ، إما كان حجرا خاصا ، أو مطلق الحجر ( فَانْفَجَرَتْ مِنْهُ اثْنَتا عَشْرَةَ عَيْناً ) بعدد أسباط بني إسرائيل ، فإنهم كانوا اثنتي عشرة قبيلة ، فكانت تجري لكل قبيلة عين ( قَدْ عَلِمَ كُلُّ أُناسٍ ) أي كل قبيلة ( مَشْرَبَهُمْ ) أي موضع شربهم ( كُلُوا وَاشْرَبُوا مِنْ رِزْقِ اللهِ ) أكلهم المن والسلوى ، وشربهم ماء العين المنفجر ( وَلا تَعْثَوْا فِي الْأَرْضِ ) الفساد ( مُفْسِدِينَ ) حالة مؤكدة.` },
            { text: "وَإِذْ قُلْتُمْ يَٰمُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَٰحِدٍ فَٱدْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنۢبِتُ ٱلْأَرْضُ مِنۢ بَقْلِهَا وَقِثَّآئِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا قَالَ أَتَسْتَبْدِلُونَ ٱلَّذِى هُوَ أَدْنَىٰ بِٱلَّذِى هُوَ خَيْرٌ ٱهْبِطُوا۟ مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ ٱلذِّلَّةُ وَٱلْمَسْكَنَةُ وَبَآءُو بِغَضَبٍ مِّنَ ٱللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا۟ يَكْفُرُونَ بِـَٔايَٰتِ ٱللَّهِ وَيَقْتُلُونَ ٱلنَّبِيِّـۧنَ بِغَيْرِ ٱلْحَقِّ ذَٰلِكَ بِمَا عَصَوا۟ وَّكَانُوا۟ يَعْتَدُونَ", tafsir: `حين كنتم في التيه ، وينزل عليكم المن والسلوى ( لَنْ نَصْبِرَ عَلى طَعامٍ واحِدٍ ) أي قسم واحد من الطعام ، ولو كان ذي لونين ، فالمراد بالوحدة التكرر في كل يوم ( فَادْعُ ) أي فاسأل ( لَنا ) أي لأجلنا ( رَبَّكَ يُخْرِجْ لَنا مِمَّا تُنْبِتُ الْأَرْضُ ) أي من نباتها ( مِنْ بَقْلِها ) البقل أنواع الخضر ( وَقِثَّائِها ) الخيار ( وَفُومِها ) الحنطة ( وَعَدَسِها وَبَصَلِها ) حتى نتقوت بها ونأكلها عوض قالَ أَ تَسْتَبْدِلُونَ الَّذِي هُوَ أَدْنى بِالَّذِي هُوَ خَيْرٌ اهْبِطُوا مِصْراً فَإِنَّ لَكُمْ ما سَأَلْتُمْ وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَباؤُ بِغَضَبٍ مِنَ اللهِ ذلِكَ بِأَنَّهُمْ كانُوا يَكْفُرُونَ بِآياتِ اللهِ المن والسلوى ( قالَ ) لهم موسى عليه‌السلام ( أَ تَسْتَبْدِلُونَ الَّذِي هُوَ أَدْنى بِالَّذِي هُوَ خَيْرٌ ) أي تتركون ما هو الأفضل مما اختاره الله لكم ، إلى ما هو الأدون مما ترغبون إليه ، وكونها أفضل وأدون ، أما باعتبار السهولة والصعوبة ، أو باعتبار الطعم واللذة ، أو باعتبار التقوية والتغذية ، وعلى أي حال ، دعا موسى واستجاب الله دعاءه ، وقال لهم ( اهْبِطُوا مِصْراً ) من الأمصار ( فَإِنَّ لَكُمْ ) في المصر ( ما سَأَلْتُمْ ) من الأطعمة ( وَ ) لكن اليهود بسبب تمردهم وعصيانهم ولجاجتهم المستمرة ( ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ ) فهم أذلاء في الأرض لا حكومة لهم مستقلة ولا عزة لهم عند الناس ( وَالْمَسْكَنَةُ ) فإنهم مع ثروتهم أحيانا لا يفارقون المسكنة ، حيث إنهم دائمو التشكّي لمخافتهم من الفقر ، وهذه الآية من معاجز القرآن الكثيرة ، فإن اليهود لم تقم لهم حكومة من تاريخ القرآن إلى هذا اليوم ، إلا بحبل من الناس ، واتصال بالحكومات القوية ( وَباؤُ بِغَضَبٍ مِنَ اللهِ ) باء أي رجع ، والمراد أنهم بعملهم السيئ غضب الله عليهم ( ذلِكَ ) المذكور من ضرب الذلة والمسكنة ، والرجوع بالغضب بسبب أنهم ( كانُوا يَكْفُرُونَ بِآياتِ اللهِ ) المنزلة على موسى عليه‌السلام حيث لم يكونوا يطيعون وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِّ ذلِكَ بِما عَصَوْا وَكانُوا يَعْتَدُونَ (61) إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هادُوا وَالنَّصارى وَالصَّابِئِينَ مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صالِحاً فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (62) وَإِذْ أَخَذْنا مِيثاقَكُمْ ( وَيَقْتُلُونَ النَّبِيِّينَ ) فإن الأنبياء تواترت إليهم لكثرة لجاجتهم ، فكانوا يقتلونهم ، وقوله تعالى ( بِغَيْرِ الْحَقِ ) قيد توضيحي ، إذ لا يكون قتل النبي حقا أبدا ، وذلك بخلاف ما لو قيل يقتل البشر بغير الحق ( ذلِكَ ) المذكور من كفرانهم وقتلهم الأنبياء ( بِما عَصَوْا ) أي بسبب عصيانهم للأوامر العقلية والشرعية ( وَكانُوا يَعْتَدُونَ ) فإن عصيانهم واعتداءهم صار سببا للقتل والكفر ، وهما سببا ضرب الذلة والمسكنة والغضب.` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَادُوا۟ وَٱلنَّصَٰرَىٰ وَٱلصَّٰبِـِٔينَ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَعَمِلَ صَٰلِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `من المسلمين ( وَالَّذِينَ هادُوا ) أي صاروا يهودا باليهودية ( وَالنَّصارى ) المؤمنين بعيسى عليه‌السلام ( وَالصَّابِئِينَ ) وفيهم غموض وخلاف ، وربما قيل أنهم عبدة النجوم ( مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ ) حقيقة ( وَعَمِلَ صالِحاً ) مما أمر به الله سبحانه ( فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ ) لا في الدنيا ولا في الآخرة ـ كما تقدم ـ ( وَلا هُمْ يَحْزَنُونَ ) فلا ييأس أحد من روح الله ما دام في الدنيا ، وإنما قيدنا « من آمن » ب « حقيقة » لئلا ينافي ما في صدر الآية ( إِنَّ الَّذِينَ آمَنُوا ) .` },
            { text: "وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَكُمْ ) العهد الشديد ، وقد وَرَفَعْنا فَوْقَكُمُ الطُّورَ خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ وَاذْكُرُوا ما فِيهِ لَعَلَّكُمْ تَتَّقُونَ (63) ثُمَّ تَوَلَّيْتُمْ مِنْ بَعْدِ ذلِكَ فَلَوْ لا فَضْلُ اللهِ عَلَيْكُمْ وَرَحْمَتُهُ لَكُنْتُمْ مِنَ الْخاسِرِينَ (64) وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنْكُمْ فِي السَّبْتِ تقدم مكان أخذ العهد ( وَرَفَعْنا فَوْقَكُمُ الطُّورَ ) وذلك أن موسى عليه‌السلام لما جاءهم بالتوراة لم يقبلوها ، فقطع جبرائيل عليه‌السلام قطعة من جبل طور ورفعها فوق رؤوسهم مهددا ، إنهم إن لم يقبلوا التوراة قذفها على رؤوسهم ، فقبلوا قبول التوراة مجبرين ، وقلنا لكم ( خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ ) أي بجد ويقين وشدة لا تحيدوا عنه ( وَاذْكُرُوا ) أي احفظوا واعملوا ب ( ما فِيهِ ) أي في « ما آتيناكم » وهو التوراة ( لَعَلَّكُمْ تَتَّقُونَ ) أي كي تخافون ، فإن العامل بأوامر الله سبحانه يكون خائفا متقيا.` },
            { text: "ثُمَّ تَوَلَّيْتُم مِّنۢ بَعْدِ ذَٰلِكَ فَلَوْلَا فَضْلُ ٱللَّهِ عَلَيْكُمْ وَرَحْمَتُهُۥ لَكُنتُم مِّنَ ٱلْخَٰسِرِينَ", tafsir: `أي أعرضتم أيها اليهود ( مِنْ بَعْدِ ذلِكَ ) الميثاق الأكيد ، فلم تعملوا بما في التوراة ، ولم تتمثلوا أوامرنا ( فَلَوْ لا فَضْلُ اللهِ عَلَيْكُمْ ) حيث تفضل عليكم بالتوبة ( وَرَحْمَتُهُ ) بأن رحمكم فلم يؤاخذكم بسيئات عملكم ( لَكُنْتُمْ مِنَ الْخاسِرِينَ ) في الدنيا والآخرة ، فإن من ينسلخ عنه الإيمان يكون من أخسر الناس.` },
            { text: "وَلَقَدْ عَلِمْتُمُ ٱلَّذِينَ ٱعْتَدَوْا۟ مِنكُمْ فِى ٱلسَّبْتِ فَقُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ", tafsir: `أي عرفتم أيها اليهود ( الَّذِينَ اعْتَدَوْا مِنْكُمْ فِي السَّبْتِ ) أي جاوزوا حدود الله فيه ، وذلك أنهم حرم عليهم اصطياد السمك في السبت فكانت الأسماك تأتي وتتجمع في هذا اليوم فَقُلْنا لَهُمْ كُونُوا قِرَدَةً خاسِئِينَ (65) فَجَعَلْناها نَكالاً لِما بَيْنَ يَدَيْها وَما خَلْفَها وَمَوْعِظَةً لِلْمُتَّقِينَ (66) وَإِذْ قالَ مُوسى لشعورها بأمنها في هذا اليوم ، فكان اليهود يحتالون لأخذها بإيصال الماء إلى أحواضهم ، فلما تأتي إليها الأسماك يوم السبت سدوا طريقها ، ثم يصطادونها يوم الأحد ، وكان هذا خرقا لحرمات الله ( فَقُلْنا لَهُمْ ) أي للمعتدين ( كُونُوا قِرَدَةً خاسِئِينَ ) أي مبعدين عن الخير دنيا وآخرة ، فإنكم أيها اليهود الذين شاهدتم هذا المسخ بالنسبة إلى المعتدي منكم كيف تعملون خلاف أوامر الله سبحانه.` },
            { text: "فَجَعَلْنَٰهَا نَكَٰلًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ", tafsir: `أي جعلنا المسخة التي مسخوا بها ، والعقوبة التي عوقبوا فيها ( نَكالاً ) أي عبرة ( لِما بَيْنَ يَدَيْها ) أي من كان في زمانهم من سائر اليهود والأمم ( وَما خَلْفَها ) الذين يأتون من بعدهم مما يسمعون بأخبارهم ، أو يكون معنى « نكالا » « عقوبة » فالمعنى جعلنا المسخة عقوبة للمعاصي التي ارتكبوها مما كانت بين يدي المسخة ، وهو « الاعتداء » وما خلف المسخة من سائر المعاصي التي كانوا يرتكبونها بعد اعتدائهم في السبت ( وَ ) جعلناها ( مَوْعِظَةً لِلْمُتَّقِينَ ) لئلا يرتكبوا خلاف أمر الله سبحانه.` },
            { text: "وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِۦٓ إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا۟ بَقَرَةً قَالُوٓا۟ أَتَتَّخِذُنَا هُزُوًا قَالَ أَعُوذُ بِٱللَّهِ أَنْ أَكُونَ مِنَ ٱلْجَٰهِلِينَ", tafsir: `اذكروا أيها اليهود قصة البقرة ، وهي أنهم وجدوا قتيلا لم يعرفوا قاتله ، فرجعوا إلى موسى عليه‌السلام ، فأمرهم الله تعالى ، أن يذبحوا بقرة ، ثم يضربوا القتيل بها ليحيي القتيل ويخبرهم بالقاتل ، وكان هذا اختبارا لإيمانهم ، حيث أن كون ضرب ميت بميت موجبا للحياة مما لا يصدقه ضعفاء الإيمان ، ولهذا جعلوا يسألون أسئلة تافهة من موسى عليه‌السلام حول البقرة ( إِذْ قالَ مُوسى لِقَوْمِهِ إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً قالُوا أَ تَتَّخِذُنا هُزُواً قالَ أَعُوذُ بِاللهِ أَنْ أَكُونَ مِنَ الْجاهِلِينَ (67) قالُوا ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما هِيَ قالَ إِنَّهُ يَقُولُ إِنَّها بَقَرَةٌ لا فارِضٌ وَلا بِكْرٌ عَوانٌ بَيْنَ ذلِكَ فَافْعَلُوا ما تُؤْمَرُونَ (68) قالُوا ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما لَوْنُها قالَ إِنَّهُ يَقُولُ إِنَّها لِقَوْمِهِ ) بني إسرائيل ( إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً ) لإحياء القتيل ( قالُوا أَ تَتَّخِذُنا هُزُواً ) أي أ تسخر منا وتتخذنا سخرية ، فما الربط بين القتيل ، وبين ذبح البقرة ، أو كيف تكون البقرة الميتة سببا لإحياء القتيل ( قالَ ) موسى عليه‌السلام ( أَعُوذُ بِاللهِ أَنْ أَكُونَ مِنَ الْجاهِلِينَ ) الذين يستهزئون بالناس ، فإن السخرية من شأن الجهال والسفهاء.` },
            { text: "قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌۢ بَيْنَ ذَٰلِكَ فَٱفْعَلُوا۟ مَا تُؤْمَرُونَ", tafsir: `أي اطلب من أجلنا ( رَبَّكَ يُبَيِّنْ لَنا ما هِيَ ) أي ما هي البقرة ، من حيث سنها وعمرها ( قالَ ) موسى عليه‌السلام ( إِنَّهُ ) تعالى ( يَقُولُ إِنَّها ) أي البقرة يلزم أن تكون ( بَقَرَةٌ لا فارِضٌ وَلا بِكْرٌ ) الفارض الكبيرة الهرمة والبكر الصغيرة ( عَوانٌ ) أي وسط العمر ( بَيْنَ ذلِكَ ) أي المذكور بين الصغير والكبير ( فَافْعَلُوا ما تُؤْمَرُونَ ) من ذبح هكذا بقرة.` },
            { text: "قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَآءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ ٱلنَّٰظِرِينَ", tafsir: `أي اسأل من ربك لأجلنا ( يُبَيِّنْ لَنا ما لَوْنُها ) أي ما لون البقرة التي أمرنا بذبحها ( قالَ ) موسى عليه‌السلام ( إِنَّهُ ) تعالى ( يَقُولُ إِنَّها بَقَرَةٌ صَفْراءُ فاقِعٌ لَوْنُها تَسُرُّ النَّاظِرِينَ (69) قالُوا ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما هِيَ إِنَّ الْبَقَرَ تَشابَهَ عَلَيْنا وَإِنَّا إِنْ شاءَ اللهُ لَمُهْتَدُونَ (70) قالَ إِنَّهُ يَقُولُ إِنَّها بَقَرَةٌ لا ذَلُولٌ تُثِيرُ الْأَرْضَ وَلا تَسْقِي الْحَرْثَ بَقَرَةٌ صَفْراءُ ) اللون ( فاقِعٌ لَوْنُها ) أي حسنة الصفرة لا تضرب إلى السواد لشدتها ، ولا إلى البياض لقلتها ( تَسُرُّ النَّاظِرِينَ ) إليها إي تعجب الناظرين وتفرحهم بسبب حسن لونها. [71] ولما بين سبحانه سن البقرة ، ولونها سألوا عن صفتها ( قالُوا ) يا موسى ( ادْعُ لَنا رَبَّكَ يُبَيِّنْ لَنا ما هِيَ ) البقرة ، أ تكون من العوامل ، أو من السوائم التي لا تعمل ، ف ( إِنَّ الْبَقَرَ ) الذي أمرتنا بذبحه ( تَشابَهَ ) أي اشتبه ( عَلَيْنا ) وإنه كيف ينبغي أن يكون ( وَإِنَّا إِنْ شاءَ اللهُ لَمُهْتَدُونَ ) إلى صفة البقرة بتعريف الله سبحانه لنا كيف يجب أن يكون ، وفي الحديث عن النبي صلى‌الله‌عليه‌وآله‌وسلم : إنهم لما شددوا على أنفسهم ، شدد الله عليهم ، ولو لم يستثنوا ما بينت لهم إلى آخر الأبد (1) .` },
            { text: "قَالُوا۟ ٱدْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِىَ إِنَّ ٱلْبَقَرَ تَشَٰبَهَ عَلَيْنَا وَإِنَّآ إِن شَآءَ ٱللَّهُ لَمُهْتَدُونَ", tafsir: `يرجى تزويدنا بنص الآية وتفسيرها لإضافتها.` },
            { text: "قَالَ إِنَّهُۥ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ ٱلْأَرْضَ وَلَا تَسْقِى ٱلْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا قَالُوا۟ ٱلْـَٰٔنَ جِئْتَ بِٱلْحَقِّ فَذَبَحُوهَا وَمَا كَادُوا۟ يَفْعَلُونَ", tafsir: `موسى عليه‌السلام ( إِنَّهُ ) سبحانه ( يَقُولُ إِنَّها ) أي البقرة التي أمرتم بذبحها ( بَقَرَةٌ لا ذَلُولٌ ) يذلها العمل ( تُثِيرُ الْأَرْضَ ) أي تعمل وتكرب لإثارة الأرض ( وَلا تَسْقِي الْحَرْثَ ) الحرث الزرع ، فلا ( 1) مستدرك الوسائل : ج 16 ص 54 ، باب حكم الحلف على ترك الطيبات. مُسَلَّمَةٌ لا شِيَةَ فِيها قالُوا الْآنَ جِئْتَ بِالْحَقِّ فَذَبَحُوها وَما كادُوا يَفْعَلُونَ (71) وَإِذْ قَتَلْتُمْ نَفْساً فَادَّارَأْتُمْ فِيها وَاللهُ مُخْرِجٌ ما كُنْتُمْ تَكْتُمُونَ (72) فَقُلْنا اضْرِبُوهُ بِبَعْضِها كَذلِكَ يُحْيِ اللهُ الْمَوْتى وَيُرِيكُمْ آياتِهِ تسقيه بالناعور ، والدلاء ، والمعنى أن لا تكون عاملة ( مُسَلَّمَةٌ ) أي سالمة لا نقص فيها فهي بريئة من العيوب ( لا شِيَةَ ) من الوشي بمعنى اللون ( فِيها ) أي لا لون فيها يخالف لونها ، وهذا ليس تأكيد لما سبق ، إذ كونها صفراء ، لا تدل على عدم الوشي فيها ( قالُوا ) لموسى عليه‌السلام ( الْآنَ ) وبعد هذه التوضيحات لصفات البقرة ( جِئْتَ بِالْحَقِ ) الواضح ، أو بما هو حق الكلام مقابل الإجمال الذي قاله عليه‌السلام سابقا بقوله ( إِنَّ اللهَ يَأْمُرُكُمْ أَنْ تَذْبَحُوا بَقَرَةً )( فَذَبَحُوها ) أي ذبح اليهود تلك البقرة المأمور بذبحها ( وَما كادُوا يَفْعَلُونَ ) أي كاد ، أن لا يذبحوا تلك البقرة لغلاء ثمنها ، فإنها انحصرت في بقرة واحدة ، لم يعطها صاحبها إلا بثمن فاحش.` },
            { text: "وَإِذْ قَتَلْتُمْ نَفْسًا فَٱدَّٰرَْٰٔتُمْ فِيهَا وَٱللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ قَتَلْتُمْ نَفْساً فَادَّارَأْتُمْ فِيها ) ادارأتم بمعنى اختلفتم ، وأصله تدارأتم ( وَاللهُ مُخْرِجٌ ما كُنْتُمْ تَكْتُمُونَ ) من أمر القاتل ، وإنه من القاتل ، ولماذا قتل.` },
            { text: "فَقُلْنَا ٱضْرِبُوهُ بِبَعْضِهَا كَذَٰلِكَ يُحْىِ ٱللَّهُ ٱلْمَوْتَىٰ وَيُرِيكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ", tafsir: `أي اضربوا القتيل ( بِبَعْضِها ) أي ببعض البقرة المذبوحة التي أمروا بذبحها ( كَذلِكَ ) أي مثل هذا الإحياء ( يُحْيِ اللهُ الْمَوْتى ) في يوم القيامة ، فإن القتيل لما ضرب بالبقرة قام حيا وأوداجه تشخب دما ، وأخبر بسبب قتله ، وبالذي قتله ( وَيُرِيكُمْ آياتِهِ ) في لَعَلَّكُمْ تَعْقِلُونَ (73) ثُمَّ قَسَتْ قُلُوبُكُمْ مِنْ بَعْدِ ذلِكَ فَهِيَ كَالْحِجارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ الْحِجارَةِ لَما يَتَفَجَّرُ مِنْهُ الْأَنْهارُ وَإِنَّ مِنْها لَما يَشَّقَّقُ فَيَخْرُجُ مِنْهُ الْماءُ وَإِنَّ مِنْها لَما يَهْبِطُ مِنْ خَشْيَةِ اللهِ الكون وفي أنفسكم ، أو بمعنى يريكم معجزاته ( لَعَلَّكُمْ تَعْقِلُونَ ) أي كي تستعملوا عقولكم ، ولعل وجه تأخير آية « وإذ قتلتم » على الآيات السالفة ، مع إن النظم يقتضي تقديمها ، أن السياق لبيان لجاجة اليهود ، وعدم إطاعتهم الأوامر ، فكان المقتضى تقديم ما يدل على ذلك.` },
            { text: "ثُمَّ قَسَتْ قُلُوبُكُم مِّنۢ بَعْدِ ذَٰلِكَ فَهِىَ كَٱلْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً وَإِنَّ مِنَ ٱلْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ ٱلْأَنْهَٰرُ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ ٱلْمَآءُ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ", tafsir: `من بعد ما رأيتم هذه الآيات أيها اليهود ( قَسَتْ قُلُوبُكُمْ ) أي غلظت ( مِنْ بَعْدِ ذلِكَ ) المذكور من آيات الله تعالى ، أو من بعد ذبح البقرة ، وما رأيتم من إحياء الله الميت ( فَهِيَ كَالْحِجارَةِ ) في القسوة للمعقول بالمحسوس ( أَوْ أَشَدُّ قَسْوَةً ) وبين سبب أشديتها قسوة ، بقوله ( وَإِنَّ مِنَ الْحِجارَةِ لَما ) اللام للتأكيد ، و « ما » موصولة ، أي الحجر الذي ( يَتَفَجَّرُ مِنْهُ الْأَنْهارُ ) فيكون مبعثا للخير نافعا ، بخلاف قلوبكم التي لا يأتي منها إلا الشر ( وَإِنَّ مِنْها لَما يَشَّقَّقُ ) أصله تشقق ( فَيَخْرُجُ مِنْهُ الْماءُ ) فيكون عينا ، وإن لم يجر ، وبهذا يفترق عن السابق ، وهو ما يتفجر منه الأنهار ( وَإِنَّ مِنْها ) أي من الحجارة ( لَما يَهْبِطُ ) أي ينزل من الجبل ويسقط ( مِنْ خَشْيَةِ اللهِ ) فإن كل حجارة تسقط ، لا بد وأن تكون سقطتها بإذن الله ، ومن خشيته خشية واقعية وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (74) أَ فَتَطْمَعُونَ أَنْ يُؤْمِنُوا لَكُمْ وَقَدْ كانَ فَرِيقٌ مِنْهُمْ يَسْمَعُونَ كَلامَ اللهِ ثُمَّ يُحَرِّفُونَهُ مِنْ بَعْدِ ما عَقَلُوهُ وَهُمْ يَعْلَمُونَ (75) وَإِذا لَقُوا أو تشبيه ، كالذي يخشى كثيرا فيسقط على وجهه ، وقلوبكم أيها اليهود أقسى من تلك الحجارة ، إذ لا تخشى من الله سبحانه ، ولا تتواضع لعظمته ( وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ ) أيها اليهود ، فيجازيكم بسيئات أعمالكم.` },
            { text: "أَفَتَطْمَعُونَ أَن يُؤْمِنُوا۟ لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَٰمَ ٱللَّهِ ثُمَّ يُحَرِّفُونَهُۥ مِنۢ بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ", tafsir: `أيها المسلمون ( أَنْ يُؤْمِنُوا ) أي يؤمن اليهود ( لَكُمْ ) أي لنفعكم ، إذ كل من آمن يكون في نفع المؤمنين السابقين ، أو بمعنى الإيمان بمبادئكم ، وهذا استفهام إنكاري ، أي لن يؤمن هؤلاء اليهود بالإسلام ( وَقَدْ كانَ فَرِيقٌ مِنْهُمْ ) أي من هؤلاء ، وهم أسلافهم ، وإنما صحت النسبة إليهم ، لأن الأمة الواحدة ، والقبيلة الواحدة ، تكون متشابهة الأعمال والأفعال والأقوال ( يَسْمَعُونَ كَلامَ اللهِ ) الذي يتلوه الأنبياء عليهم ( ثُمَّ يُحَرِّفُونَهُ ) بالزيادة والنقصان لفظا أو معنى ، كما هو المتعارف عند من يريد نقل كلام لا يرضيه ، فإنه إما أن ينقص فيه أو يزيد ـ لو وجد إلى ذلك سبيل ـ وإما أن يفسره بغير ما أراد المتكلم ( مِنْ بَعْدِ ما عَقَلُوهُ ) وفهموه ( وَهُمْ يَعْلَمُونَ ) فكيف يؤمن هؤلاء الذين كانوا يعملون بكلام الله بعد تعقل هذا العمل.` },
            { text: "وَإِذَا لَقُوا۟ ٱلَّذِينَ ءَامَنُوا۟ قَالُوٓا۟ ءَامَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوٓا۟ أَتُحَدِّثُونَهُم بِمَا فَتَحَ ٱللَّهُ عَلَيْكُمْ لِيُحَآجُّوكُم بِهِۦ عِندَ رَبِّكُمْ أَفَلَا تَعْقِلُونَ", tafsir: `من الملاقاة ، أي لقي اليهود وكانت هذه خصلة بعضهم نسبت إلى الجميع ، كما هو المتعارف من نسبة ما يقوم به البعض إلى الَّذِينَ آمَنُوا قالُوا آمَنَّا وَإِذا خَلا بَعْضُهُمْ إِلى بَعْضٍ قالُوا أَ تُحَدِّثُونَهُمْ بِما فَتَحَ اللهُ عَلَيْكُمْ لِيُحَاجُّوكُمْ بِهِ عِنْدَ رَبِّكُمْ أَ فَلا تَعْقِلُونَ (76) أَ وَلا يَعْلَمُونَ أَنَّ اللهَ يَعْلَمُ ما يُسِرُّونَ وَما يُعْلِنُونَ (77) الجميع ( الَّذِينَ آمَنُوا قالُوا آمَنَّا ) بأن محمدا صلى‌الله‌عليه‌وآله‌وسلم هذا موجود في كتبنا بوصفه وحليته ، ولم يقصدوا الإيمان الحقيقي كسائر المسلمين ، ولا الإيمان الظاهري كالمنافقين ، وإنما أريد الإيمان بمعناه اللغوي ، وهذا ذم لهم ، حيث إنهم اتصفوا بصفات المنافقين ( وَإِذا خَلا بَعْضُهُمْ إِلى بَعْضٍ ) وجمع هؤلاء اليهود وغيرهم من سائر اليهود ، مجلس خال من المؤمنين ( قالُوا ) أي قال من لم يكن يظهر الإيمان لمن أظهره ( أَ تُحَدِّثُونَهُمْ ) أي لماذا تحدثون المسلمين ( بِما فَتَحَ اللهُ عَلَيْكُمْ ) أي بما عرفكم الله في كتابكم ، بأن محمدا صلى‌الله‌عليه‌وآله‌وسلم حق ، يقال فتح عليه باب العلم إذا أرشده إليه وعلمه به ( لِيُحَاجُّوكُمْ بِهِ عِنْدَ رَبِّكُمْ ) أي إذا أظهرتم أنتم أيها اليهود للمسلمين ، أن في كتابكم صفات محمد صلى‌الله‌عليه‌وآله‌وسلم حاجوكم يوم القيامة عند الله فيقول المسلمون لليهود المظهرين أنتم ذكرتم أن في كتابكم صفات النبي ، فلم لم تؤمنوا به ( أَ فَلا تَعْقِلُونَ ) أيها اليهود المظهرون للمسلمين ، أن إظهاركم سبب لغلبة المسلمين عليكم في الحجة عند الله.` },
            { text: "أَوَلَا يَعْلَمُونَ أَنَّ ٱللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ", tafsir: `يعني اليهود المنافقون ( أَنَّ اللهَ يَعْلَمُ ما يُسِرُّونَ ) يسر بعضهم إلى بعض ( وَما يُعْلِنُونَ ) وما الفائدة في أن لا يظهروا صفات وَمِنْهُمْ أُمِّيُّونَ لا يَعْلَمُونَ الْكِتابَ إِلاَّ أَمانِيَّ وَإِنْ هُمْ إِلاَّ يَظُنُّونَ (78) فَوَيْلٌ لِلَّذِينَ يَكْتُبُونَ الْكِتابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هذا مِنْ عِنْدِ اللهِ لِيَشْتَرُوا بِهِ ثَمَناً قَلِيلاً فَوَيْلٌ لَهُمْ مِمَّا كَتَبَتْ أَيْدِيهِمْ النبي ، فإن الله يعلم أنهم يعلمون صفاته ، ولا يؤمنون به عنادا.` },
            { text: "وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ ٱلْكِتَٰبَ إِلَّآ أَمَانِىَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ", tafsir: `أي من اليهود ( أُمِّيُّونَ ) منسوب إلى الأم ، بمعنى من لا يقرأ ولا يكتب كأنه نشأ تحت تربية أمه ، لا تحت تربية المعلم ( لا يَعْلَمُونَ الْكِتابَ إِلَّا أَمانِيَ ) الأماني جمع أمنية ، كالأغاني جمع أغنية ، والأماني الأحاديث المختلفة ، أي أنهم لا يعرفون ما في التوراة من صفات النبي صلى‌الله‌عليه‌وآله‌وسلم وغيرها ، وإنما هم جهلاء ، يأخذون أمور الكتاب عن علمائهم محرفة مختلفة ، فلا يميزون بين الحق والباطل ( وَإِنْ هُمْ ) أي ما هم ( إِلَّا يَظُنُّونَ ) بصحة ما يسمعون ، ولا يتيقنون لأنهم لم يطالعوا الكتاب بأنفسهم ، حتى يعرفون ما فيه.` },
            { text: "فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ", tafsir: `أي لعلمائهم الذين ( يَكْتُبُونَ الْكِتابَ ) أي التوراة ( بِأَيْدِيهِمْ ) كناية عن أنها غير منزلة ، وإنما مكتوبة مبعثها الأيدي لا الوحي والإلهام ( ثُمَّ يَقُولُونَ هذا ) المكتوب ( مِنْ عِنْدِ اللهِ ) وإنه منزل منه ( لِيَشْتَرُوا بِهِ ) أي بما يكتبونه ( ثَمَناً قَلِيلاً ) لأنهم لو كانوا يظهرون ما في التوراة حقيقة رجع مقلدوهم إلى النبي صلى‌الله‌عليه‌وآله‌وسلم ، فلم يكونوا يبذلون لهم الأموال والاحترام ( فَوَيْلٌ لَهُمْ ) أي للذين يكتبون الكتاب بأيديهم ( مِمَّا كَتَبَتْ أَيْدِيهِمْ ) فإنه يوجب عذابا ، لأنه تحريف وَوَيْلٌ لَهُمْ مِمَّا يَكْسِبُونَ (79) وَقالُوا لَنْ تَمَسَّنَا النَّارُ إِلاَّ أَيَّاماً مَعْدُودَةً قُلْ أَتَّخَذْتُمْ عِنْدَ اللهِ عَهْداً فَلَنْ يُخْلِفَ اللهُ عَهْدَهُ أَمْ تَقُولُونَ عَلَى اللهِ ما لا تَعْلَمُونَ (80) بَلى مَنْ كَسَبَ سَيِّئَةً وَأَحاطَتْ بِهِ خَطِيئَتُهُ فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (81) لكلام الله تعالى ( وَوَيْلٌ لَهُمْ مِمَّا يَكْسِبُونَ ) من الأموال إزاء تحريفاتهم ، فإن ثمن الحرام حرام آخر ، وذلك موجب للعذاب فإنه أكل للأموال بالباطل ، والويل أصله الهلاك والعذاب ، ثم استعمل في كل واقع في الهلكة.` },
            { text: "وَقَالُوا۟ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامًا مَّعْدُودَةً قُلْ أَتَّخَذْتُمْ عِندَ ٱللَّهِ عَهْدًا فَلَن يُخْلِفَ ٱللَّهُ عَهْدَهُۥٓ أَمْ تَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `أي قال قسم من اليهود ( لَنْ تَمَسَّنَا النَّارُ إِلَّا أَيَّاماً مَعْدُودَةً ) فلن نعذب في جهنم إلا سبعة أيام أو ما أشبه ، على تقدير كفرنا وعصياننا ، فلما ذا نترك رئاسة الدنيا خوفا من عذاب قليل ( قُلْ ) يا رسول الله لهم ( أَتَّخَذْتُمْ ) أي هل اتخذتم ( عِنْدَ اللهِ عَهْداً ) بذلك ( فَلَنْ يُخْلِفَ اللهُ عَهْدَهُ أَمْ تَقُولُونَ عَلَى اللهِ ) كذبا وزورا ( ما لا تَعْلَمُونَ ) ومن أدراكم أن العذاب أيام معدودة.` },
            { text: "بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَٰطَتْ بِهِۦ خَطِيٓـَٔتُهُۥ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `ليس الأمر كما قالوا ولكن ( مَنْ كَسَبَ سَيِّئَةً وَ ) لم ينقلع عنها بل ( أَحاطَتْ بِهِ خَطِيئَتُهُ ) كالإنسان الذي يقع في دخان حيث يحيط به الدخان ، حتى لا يتنفس ولا يبصر ولا يسمع إلا في الدخان ، وكذلك المشرك المنحرف في الخطيئة ( فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) إلى الأبد. وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ أُولئِكَ أَصْحابُ الْجَنَّةِ هُمْ فِيها خالِدُونَ (82) وَإِذْ أَخَذْنا مِيثاقَ بَنِي إِسْرائِيلَ لا تَعْبُدُونَ إِلاَّ اللهَ وَبِالْوالِدَيْنِ إِحْساناً وَذِي الْقُرْبى وَالْيَتامى وَالْمَساكِينِ وَقُولُوا لِلنَّاسِ حُسْناً وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ ثُمَّ تَوَلَّيْتُمْ إِلاَّ قَلِيلاً مِنْكُمْ وَأَنْتُمْ مُعْرِضُونَ (83)` },
            { text: "وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `بقلوبهم وألسنتهم ( وَعَمِلُوا الصَّالِحاتِ ) التي أمر بها الإسلام ( أُولئِكَ أَصْحابُ الْجَنَّةِ هُمْ فِيها خالِدُونَ ) بها لا انقطاع لها ولا زوال.` },
            { text: "وَإِذْ أَخَذْنَا مِيثَٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَ بَنِي إِسْرائِيلَ ) عهدهم الأكيد على لسان أنبيائهم ، بأن ( لا تَعْبُدُونَ إِلَّا اللهَ ) وحده ( وَ ) بأن أحسنوا ( بِالْوالِدَيْنِ إِحْساناً ) ولا تسيئوا إليهما ( وَ ) أحسنوا إلى ( ذِي الْقُرْبى ) أقربائهم ( وَالْيَتامى ) الذين مات والدهم ( وَالْمَساكِينِ ) الفقراء ( وَقُولُوا لِلنَّاسِ حُسْناً ) وذلك يشمل جميع أنواع الأمر بالمعروف والنهي عن المنكر ، والإرشاد ورد الاعتداء بالحسن ( وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ ) وهما في سائر الأمم ، لم يكونا بهذا الشكل الموجود فعلا في هذه الأمة ( ثُمَّ تَوَلَّيْتُمْ ) أعرضتم ( إِلَّا قَلِيلاً مِنْكُمْ ) الذين عملوا بأوامرنا ( وَأَنْتُمْ مُعْرِضُونَ ) تأكيدا لقوله « توليتم » . وَإِذْ أَخَذْنا مِيثاقَكُمْ لا تَسْفِكُونَ دِماءَكُمْ وَلا تُخْرِجُونَ أَنْفُسَكُمْ مِنْ دِيارِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنْتُمْ تَشْهَدُونَ (84) ثُمَّ أَنْتُمْ هؤُلاءِ تَقْتُلُونَ أَنْفُسَكُمْ وَتُخْرِجُونَ فَرِيقاً مِنْكُمْ مِنْ دِيارِهِمْ تَظاهَرُونَ عَلَيْهِمْ بِالْإِثْمِ وَالْعُدْوانِ وَإِنْ يَأْتُوكُمْ أُسارى تُفادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْراجُهُمْ` },
            { text: "وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ لَا تَسْفِكُونَ دِمَآءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَٰرِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَكُمْ ) عهدكم الأكيد على لسان الأنبياء ( لا تَسْفِكُونَ دِماءَكُمْ ) أي لا يسفك بعضكم دماء بعض ( وَلا تُخْرِجُونَ أَنْفُسَكُمْ مِنْ دِيارِكُمْ ) أي لا يخرج بعضكم بعضا من الديار ، بأن يسفرهم ويبعدهم ( ثُمَّ أَقْرَرْتُمْ ) بذلك الميثاق ، بأن أعطيتمونا العهود بذلك ( وَأَنْتُمْ تَشْهَدُونَ ) أيها اليهود ، بوقوع هذا الميثاق بيننا.` },
            { text: "ثُمَّ أَنتُمْ هَٰٓؤُلَآءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَٰرِهِمْ تَظَٰهَرُونَ عَلَيْهِم بِٱلْإِثْمِ وَٱلْعُدْوَٰنِ وَإِن يَأْتُوكُمْ أُسَٰرَىٰ تُفَٰدُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ أَفَتُؤْمِنُونَ بِبَعْضِ ٱلْكِتَٰبِ وَتَكْفُرُونَ بِبَعْضٍ فَمَا جَزَآءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْىٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيَوْمَ ٱلْقِيَٰمَةِ يُرَدُّونَ إِلَىٰٓ أَشَدِّ ٱلْعَذَابِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ", tafsir: `بعد ذلك الميثاق ( أَنْتُمْ هؤُلاءِ ) الذين ( تَقْتُلُونَ أَنْفُسَكُمْ وَتُخْرِجُونَ فَرِيقاً مِنْكُمْ مِنْ دِيارِهِمْ ) مخالفة لأوامرنا ( تَظاهَرُونَ ) أنتم أي يتعاون بعضكم مع بعض في إخراجكم لهم تظاهرا ( عَلَيْهِمْ بِالْإِثْمِ وَالْعُدْوانِ ) لا إخراجا بالحق ( وَ ) الحال ( إِنْ يَأْتُوكُمْ أُسارى تُفادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْراجُهُمْ ) أي كيف يخرج بعضكم بعضا ، ويقتل بعضكم بعضا ، مع أنكم إذا وجدتم بعضكم أسيرا في أيدي غيرهم ، تعطون الفدية لخلاصهم ، فإن كان بينكم عداء ، فما هذه الفدية ، وإن كان بينكم وداد فما هذا القتل والإخراج. روي عن ابن عباس : أن قريظة والنضير ، كانا أخوين ، كالأوس والخزرج ، فافترقوا فكانت أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتابِ وَتَكْفُرُونَ بِبَعْضٍ فَما جَزاءُ مَنْ يَفْعَلُ ذلِكَ مِنْكُمْ إِلاَّ خِزْيٌ فِي الْحَياةِ الدُّنْيا وَيَوْمَ الْقِيامَةِ يُرَدُّونَ إِلى أَشَدِّ الْعَذابِ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (85) أُولئِكَ الَّذِينَ اشْتَرَوُا الْحَياةَ الدُّنْيا بِالْآخِرَةِ فَلا النضير مع الخزرج ، وكانت قريظة مع الأوس ، فإذا اقتتلوا عاونت كل فرقة حلفاءها ، فإذا وضعت الحرب أوزارها فدوا أسراها تصديقا لما في التوراة (1) ، وروي عن آخر أن اليهود كانوا إذا استضعفوا جماعة آخرين أخرجوهم من ديارهم ( أَ فَتُؤْمِنُونَ ) أيها اليهود ( بِبَعْضِ الْكِتابِ ) أي التوراة القائل بوجوب إعطاء الفدية لأسراكم ( وَتَكْفُرُونَ بِبَعْضٍ ) القائل بحرمة القتل والإخراج والتظاهر بالإثم والعدوان ( فَما جَزاءُ مَنْ يَفْعَلُ ذلِكَ مِنْكُمْ ) احكموا أنتم بأنفسكم ( إِلَّا خِزْيٌ فِي الْحَياةِ الدُّنْيا ) بالتفرقة والضعف والمهانة عند سائر الأمم ( وَيَوْمَ الْقِيامَةِ يُرَدُّونَ إِلى أَشَدِّ الْعَذابِ ) بمخالفتهم أوامر الله سبحانه ( وَمَا اللهُ ) أي ليس الله ( بِغافِلٍ عَمَّا تَعْمَلُونَ ) فإنه يعلم أعمالكم ، فيجازيكم عليها.` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلْحَيَوٰةَ ٱلدُّنْيَا بِٱلْـَٔاخِرَةِ فَلَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنصَرُونَ", tafsir: `اليهود الذين خالفوا الأوامر بتلك الأفعال ( الَّذِينَ اشْتَرَوُا الْحَياةَ الدُّنْيا بِالْآخِرَةِ ) فباعوا الآخرة ، وأخذوا الدنيا بدلها ( فَلا ( 1) راجع بحار الأنوار : ج 20 ص 166. يُخَفَّفُ عَنْهُمُ الْعَذابُ وَلا هُمْ يُنْصَرُونَ (86) وَلَقَدْ آتَيْنا مُوسَى الْكِتابَ وَقَفَّيْنا مِنْ بَعْدِهِ بِالرُّسُلِ وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ وَأَيَّدْناهُ بِرُوحِ الْقُدُسِ أَ فَكُلَّما جاءَكُمْ رَسُولٌ بِما لا تَهْوى أَنْفُسُكُمُ اسْتَكْبَرْتُمْ فَفَرِيقاً كَذَّبْتُمْ وَفَرِيقاً تَقْتُلُونَ (87) وَقالُوا قُلُوبُنا غُلْفٌ يُخَفَّفُ عَنْهُمُ الْعَذابُ ) يوم القيامة ( وَلا هُمْ يُنْصَرُونَ ) هناك.` },
            { text: "وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ", tafsir: `أعطينا التوراة إياه ( وَقَفَّيْنا ) أي أردفنا وأتبعنا بعضهم خلف بعض ( مِنْ بَعْدِهِ ) أي بعد موسى ( بِالرُّسُلِ ) رسول يتبع رسولا ( وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ ) جمع بينة ، أي الدلالة الواضحة ، وهي المعجزات التي أعطيت لعيسى عليه‌السلام من إبراء الأكمه والأبرص ، وإحياء الموتى ( وَأَيَّدْناهُ بِرُوحِ الْقُدُسِ ) التأييد التقوية ، وروح القدس ، إما جبرئيل عليه‌السلام ، أو روح قوية من الله سبحانه فيه تقوية على التبليغ والإرشاد مع كثرة أعدائه ( أَ فَكُلَّما جاءَكُمْ ) أيها اليهود ( رَسُولٌ بِما لا تَهْوى أَنْفُسُكُمُ ) ولا يمثل إليه من الأحكام ( اسْتَكْبَرْتُمْ ) وتكبرتم عن قبول أحكام الله سبحانه ( فَفَرِيقاً كَذَّبْتُمْ ) كعيسى ومحمد صلوات الله عليهما ( وَفَرِيقاً تَقْتُلُونَ ) كزكريا ويحيى عليها‌السلام ؟ وهذا استفهام إنكاري عليهم.` },
            { text: "وَقَالُوا۟ قُلُوبُنَا غُلْفٌۢ بَل لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ", tafsir: `أي قالت اليهود للنبي صلى‌الله‌عليه‌وآله‌وسلم ( قُلُوبُنا غُلْفٌ ) جمع أغلف ، بمعنى إنها في غطاء وغلاف عن هدايتكم ، فلا تصل الهداية إليها ، بَلْ لَعَنَهُمُ اللهُ بِكُفْرِهِمْ فَقَلِيلاً ما يُؤْمِنُونَ (88) وَلَمَّا جاءَهُمْ كِتابٌ مِنْ عِنْدِ اللهِ مُصَدِّقٌ لِما مَعَهُمْ وَكانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جاءَهُمْ ما عَرَفُوا كَفَرُوا بِهِ كما في آية أخرى ( وَقالُوا قُلُوبُنا فِي أَكِنَّةٍ ) (1) ( بَلْ ) ليس كذلك ، وإنما ( لَعَنَهُمُ اللهُ ) وأبعدهم عن الخير بسبب كفرهم فإنهم لما كفروا ولم يمتثلوا أوامر الله ، أبعدهم الله عن الخير ، كمن لا يسمع شخصا أمره فيتركه ولا يعتني به ( فَقَلِيلاً ما يُؤْمِنُونَ ) لما ران على قلوبهم ، وأظلمت نفوسهم بالكفر.` },
            { text: "وَلَمَّا جَآءَهُمْ كِتَٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَٰفِرِينَ", tafsir: `أي اليهود ( كِتابٌ مِنْ عِنْدِ اللهِ ) هو القرآن ( مُصَدِّقٌ لِما مَعَهُمْ ) أي الكتاب الذي مع اليهود ، وهو التوراة ، فإن القرآن يصدق التوراة الحقيقي المنزل على موسى عليه‌السلام ( إِنَّا أَنْزَلْنَا التَّوْراةَ فِيها هُدىً وَنُورٌ ) (2) ( وَكانُوا ) أي اليهود ( مِنْ قَبْلُ ) أي قبل أن يأتي الرسول صلى‌الله‌عليه‌وآله‌وسلم أو ينزل القرآن ( يَسْتَفْتِحُونَ ) أي يطلبون الفتح من الله ( عَلَى الَّذِينَ كَفَرُوا ) فإنهم كانوا يدعون الله ، أن يبعث الرسول ، حتى يكونوا أرجح كفة من الكفار ( فَلَمَّا جاءَهُمْ ما عَرَفُوا ) أي الرسول صلى‌الله‌عليه‌وآله‌وسلم الذي عرفوه بصفاته ومزاياه ( كَفَرُوا بِهِ ) وأخذوا يحاربوه ، بل فوق ذلك أنهم كانوا يرجحون الكافرين على ( 1) فصلت : 6. ( 2) المائدة : 45. فَلَعْنَةُ اللهِ عَلَى الْكافِرِينَ (89) بِئْسَمَا اشْتَرَوْا بِهِ أَنْفُسَهُمْ أَنْ يَكْفُرُوا بِما أَنْزَلَ اللهُ بَغْياً أَنْ يُنَزِّلَ اللهُ مِنْ فَضْلِهِ عَلى مَنْ يَشاءُ مِنْ عِبادِهِ الرسول والمؤمنين قائلين ( هؤُلاءِ أَهْدى مِنَ الَّذِينَ آمَنُوا سَبِيلاً ) (1) ( فَلَعْنَةُ اللهِ عَلَى ) اليهود ( الْكافِرِينَ ) بمحمد صلى‌الله‌عليه‌وآله‌وسلم وبالقرآن ، وهم يعرفون ذلك.` },
            { text: "بِئْسَمَا ٱشْتَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ أَن يَكْفُرُوا۟ بِمَآ أَنزَلَ ٱللَّهُ بَغْيًا أَن يُنَزِّلَ ٱللَّهُ مِن فَضْلِهِۦ عَلَىٰ مَن يَشَآءُ مِنْ عِبَادِهِۦ فَبَآءُو بِغَضَبٍ عَلَىٰ غَضَبٍ وَلِلْكَٰفِرِينَ عَذَابٌ مُّهِينٌ", tafsir: `أي بئس الشيء الذي باع اليهود بذلك أنفسهم ، فأعطوا أنفسهم للعذاب الأبدي ، واشتروا الكفر ( أَنْ يَكْفُرُوا بِما أَنْزَلَ اللهُ ) بدل « ما » أي بئس الكفر الذي أخذوه مقابل أنفسهم ، وذلك تشبيه ، فكأن الكفر والإسلام ، سلعتان فمن أختار أحدهما باع نفسه بذلك الشيء ، إذ يصرف نفسه في سبيل ذلك ، فإذا باع نفسه مقابل الإسلام كان نعم ما اشترى به نفسه ، وإذا باع نفسه مقابل الكفر كان بئسما اشترى به نفسه ، واشترى هنا بمعنى البيع ، كما قال ( وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ ابْتِغاءَ مَرْضاتِ اللهِ ) (2) ( بَغْياً ) أي حسدا ، وهو علة لاشترائهم السيئ ، أي كان سبب شرائهم الكفر الحسد ، الذي كان فيهم لمحمد صلى‌الله‌عليه‌وآله‌وسلم ، حيث أنه من ولد إسماعيل ، لا من ولد جدهم إسحاق عليهما‌السلام ( أَنْ يُنَزِّلَ اللهُ ) الدين ( مِنْ فَضْلِهِ عَلى مَنْ يَشاءُ مِنْ عِبادِهِ ) وأن ينزل ، متعلق ب « بغيا » أي أن الحسد من جهة نزول القرآن ( 1) النساء : 52. ( 2) البقرة : 208. فَباؤُ بِغَضَبٍ عَلى غَضَبٍ وَلِلْكافِرِينَ عَذابٌ مُهِينٌ (90) وَإِذا قِيلَ لَهُمْ آمِنُوا بِما أَنْزَلَ اللهُ قالُوا نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا وَيَكْفُرُونَ بِما وَراءَهُ وَهُوَ الْحَقُّ مُصَدِّقاً لِما مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنْبِياءَ اللهِ مِنْ قَبْلُ إِنْ كُنْتُمْ مُؤْمِنِينَ (91) على محمد صلى‌الله‌عليه‌وآله‌وسلم دون غيره ( فَباؤُ ) أي رجع اليهود ( بِغَضَبٍ عَلى غَضَبٍ ) فإنهم كانوا مغضوب عليهم من جهة تعدياتهم في زمان موسى وعيسى ، وسائر الأنبياء عليهم‌السلام ، فغضب الله عليهم مرة أخرى من جهة كفرهم بمحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَلِلْكافِرِينَ ) الذين من أظهر مصاديقهم اليهود ( عَذابٌ مُهِينٌ ) وهو العذاب الذي يذل صاحبه ويهينه.` },
            { text: "وَإِذَا قِيلَ لَهُمْ ءَامِنُوا۟ بِمَآ أَنزَلَ ٱللَّهُ قَالُوا۟ نُؤْمِنُ بِمَآ أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَآءَهُۥ وَهُوَ ٱلْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ قُلْ فَلِمَ تَقْتُلُونَ أَنۢبِيَآءَ ٱللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `أي لليهود ( آمِنُوا بِما أَنْزَلَ اللهُ ) على محمد صلى‌الله‌عليه‌وآله‌وسلم ( قالُوا نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) من التوراة ( وَيَكْفُرُونَ بِما وَراءَهُ ) أي وراء ما نزل عليه من كتاب عيسى عليه‌السلام ومحمد صلى‌الله‌عليه‌وآله‌وسلم ( وَهُوَ ) أي ما وراء كتابهم ( الْحَقُّ مُصَدِّقاً لِما مَعَهُمْ ) والجملة حالية ( قُلْ ) إنكم تكذبون في قولكم ( نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) فإنكم لستم بمؤمنين ، حتى بالتوراة وإلا ( فَلِمَ تَقْتُلُونَ أَنْبِياءَ اللهِ مِنْ قَبْلُ ) في السابق ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) بالتوراة ، فإن كتابكم حرم قتل الأنبياء ، فأنتم لستم بمؤمنين ، لا بكتابكم ، ولا بما بعد كتابكم من الإنجيل والقرآن. وَلَقَدْ جاءَكُمْ مُوسى بِالْبَيِّناتِ ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِنْ بَعْدِهِ وَأَنْتُمْ ظالِمُونَ (92) وَإِذْ أَخَذْنا مِيثاقَكُمْ وَرَفَعْنا فَوْقَكُمُ الطُّورَ خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ وَاسْمَعُوا قالُوا سَمِعْنا وَعَصَيْنا وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَما يَأْمُرُكُمْ بِهِ إِيمانُكُمْ` },
            { text: "وَلَقَدْ جَآءَكُم مُّوسَىٰ بِٱلْبَيِّنَٰتِ ثُمَّ ٱتَّخَذْتُمُ ٱلْعِجْلَ مِنۢ بَعْدِهِۦ وَأَنتُمْ ظَٰلِمُونَ", tafsir: `كيف تقولون ( نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) وعملكم ، يدل على خلاف ذلك ، ف ( لَقَدْ جاءَكُمْ مُوسى بِالْبَيِّناتِ ) أي بالحجج الواضحة ( ثُمَّ اتَّخَذْتُمُ الْعِجْلَ ) إلها لكم ( مِنْ بَعْدِهِ ) أي بعد رواحة إلى الطور ( وَ ) الحال ( أَنْتُمْ ظالِمُونَ ) لأنفسكم في عبادة العجل ، فلو كنتم مؤمنين بما نزل عليكم ، لم تتخذوا العجل إلها ؟.` },
            { text: "وَإِذْ أَخَذْنَا مِيثَٰقَكُمْ وَرَفَعْنَا فَوْقَكُمُ ٱلطُّورَ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱسْمَعُوا۟ قَالُوا۟ سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا۟ فِى قُلُوبِهِمُ ٱلْعِجْلَ بِكُفْرِهِمْ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِۦٓ إِيمَٰنُكُمْ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `اذكروا يا بني إسرائيل ( إِذْ أَخَذْنا مِيثاقَكُمْ ) عهدكم الشديد ، بالعمل بالتوراة ( وَرَفَعْنا فَوْقَكُمُ الطُّورَ ) أي قطعة من جبل الطور ـ كما تقدم ـ وقلنا لكم ( خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ ) أي بشدة ، بمعنى العمل ، بكل ما في الكتاب عملا مستمرا قويا ( وَاسْمَعُوا ) أوامر الله سبحانه ( قالُوا سَمِعْنا وَعَصَيْنا ) حكاية حالهم ، ويحتمل أنهم قالوه بلفظهم استهزاء ( وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ ) فكما أن من شرب الماء يدخل الماء في جوفه ، كذلك اليهود ، دخل العجل ـ أي حبه ـ في قلوبهم بسبب كفرهم بالله سبحانه ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لهم ( بِئْسَما يَأْمُرُكُمْ بِهِ إِيمانُكُمْ ) الذي قلتم ( نُؤْمِنُ بِما أُنْزِلَ عَلَيْنا ) فإن الإيمان الذي يأمر باتباع العجل ، ليس إيمانا ، وإنما هو كفر. إِنْ كُنْتُمْ مُؤْمِنِينَ (93) قُلْ إِنْ كانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِنْدَ اللهِ خالِصَةً مِنْ دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِنْ كُنْتُمْ صادِقِينَ (94) وَلَنْ يَتَمَنَّوْهُ أَبَداً بِما قَدَّمَتْ أَيْدِيهِمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ (95) ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) وهذا استهزاء لهم ، ثم إنه إنما كرر « رفع الطور » للدلالة ، على أنهم عكسوا الميثاق الذي أخذ منهم ، حال الرفع ، بل اتخذوا العجل إلها.` },
            { text: "قُلْ إِن كَانَتْ لَكُمُ ٱلدَّارُ ٱلْـَٔاخِرَةُ عِندَ ٱللَّهِ خَالِصَةً مِّن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `يا رسول الله لهؤلاء اليهود ، الذين يقولون أن الآخرة هي لهم وحدهم لا يشركون فيها غيرهم من النصارى والمسلمين وغيرهما ( إِنْ كانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِنْدَ اللهِ خالِصَةً مِنْ دُونِ النَّاسِ ) عند الله صفة للدار الآخرة ، أي الدار التي هي عند الله ، ومن دون الناس صفة لخالصته ، أو لقوله « لكم » ( فَتَمَنَّوُا الْمَوْتَ ) لأن من يدري أن مصيره الجنة ، لا بد وأن يتمنى الموت ، حتى يخلص من آلام الدنيا وأتعابها ( إِنْ كُنْتُمْ صادِقِينَ ) في مقالكم وكنتم تعتقدون ما تقولونه بألسنتكم. [96] ثم أخبر سبحانه بأنهم ليسوا صادقين ( وَ ) الدليل على ذلك أنهم ( لَنْ يَتَمَنَّوْهُ ) أي الموت ( أَبَداً ) في حين من الأحيان بسبب ما ( قَدَّمَتْ أَيْدِيهِمْ ) من المعاصي والمنكرات والكفر ، وإنما نسب التقديم إلى اليد لأنها الآلة الظاهرة في تقديم الأشياء المحسوسة غالبا ( وَاللهُ عَلِيمٌ بِالظَّالِمِينَ ) فلا يغترون بمقالهم ، أن لهم الآخرة ، وأنهم أحباء الله دون سواهم. وَلَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلى حَياةٍ وَمِنَ الَّذِينَ أَشْرَكُوا يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَما هُوَ بِمُزَحْزِحِهِ مِنَ الْعَذابِ أَنْ يُعَمَّرَ وَاللهُ بَصِيرٌ بِما يَعْمَلُونَ (96) قُلْ مَنْ كانَ عَدُوًّا` },
            { text: "وَلَن يَتَمَنَّوْهُ أَبَدًۢا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ", tafsir: `(قُلْ) يا رسول الله لهؤلاء اليهود، الذين يقولون أن الآخرة هي لهم وحدهم لا يشركون فيها غيرهم من النصارى والمسلمين وغيرهما (إِنْ كانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِنْدَ اللهِ خالِصَةً مِنْ دُونِ النَّاسِ) عند الله صفة للدار الآخرة، أي الدار التي هي عند الله، ومن دون الناس صفة لخالصته، أو لقوله «لكم» (فَتَمَنَّوُا الْمَوْتَ) لأن من يدري أن مصيره الجنة، لا بد وأن يتمنى الموت، حتى يخلص من آلام الدنيا وأتعابها (إِنْ كُنْتُمْ صادِقِينَ) في مقالكم وكنتم تعتقدون ما تقولونه بألسنتكم.` },
            { text: "وَلَتَجِدَنَّهُمْ أَحْرَصَ ٱلنَّاسِ عَلَىٰ حَيَوٰةٍ وَمِنَ ٱلَّذِينَ أَشْرَكُوا۟ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِۦ مِنَ ٱلْعَذَابِ أَن يُعَمَّرَ وَٱللَّهُ بَصِيرٌۢ بِمَا يَعْمَلُونَ", tafsir: `كيف يتمنون الموت ، والحال أنك يا رسول الله ( لَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلى حَياةٍ ) فإنهم أشد حرصا من سائر الناس على البقاء في الدنيا ، لأنهم يعلمون أن آخرتهم إلى النار والعذاب ( وَ ) حتى أنهم أحرص ( مِنَ الَّذِينَ أَشْرَكُوا ) إذ المشرك ، يزعم أنه لا شيء وراءه ، فيكون حريصا على البقاء لئلا يفنى ، وهؤلاء حيث يعلمون العقاب ، فهم أحرص من المشركين ( يَوَدُّ ) أي يحب ( أَحَدُهُمْ ) أي كل واحد منهم ( لَوْ يُعَمَّرُ ) ويطول عمره ( أَلْفَ سَنَةٍ ) حتى لا يذوق العذاب عاجلا ( وَ ) الحال ( ما هُوَ ) أي ليس التعمير ألف سنة ( بِمُزَحْزِحِهِ مِنَ الْعَذابِ ) زحزحه أي نحاه ، وقوله ( أَنْ يُعَمَّرَ ) بدل « هو » أي ما التعمير بمزحزحه من العذاب ، فما الفائدة في البقاء ألف سنة لمن عاقبته النار ( وَاللهُ بَصِيرٌ بِما يَعْمَلُونَ ) من الكفر والسيئات ، فيجازيهم عليها يوم القيامة بالنار والعذاب.` },
            { text: "قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُۥ نَزَّلَهُۥ عَلَىٰ قَلْبِكَ بِإِذْنِ ٱللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ", tafsir: `يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لليهود الذين جاءوك وقالوا لك لو أن الملك الذي يأتيك ميكائيل لآمنّا بك فإنه ملك الرحمة يأتي بالسرور والرخاء وهو صديقنا وجبرائيل ملك العذاب ينزل بالقتل والشدة والحرب وهو عدونا فإن كان ينزل عليك جبرائيل لا نؤمن بك ( مَنْ كانَ عَدُوًّا لِجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلى قَلْبِكَ بِإِذْنِ اللهِ مُصَدِّقاً لِما بَيْنَ يَدَيْهِ وَهُدىً وَبُشْرى لِلْمُؤْمِنِينَ (97) مَنْ كانَ عَدُوًّا لِلَّهِ وَمَلائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكالَ فَإِنَّ اللهَ عَدُوٌّ لِلْكافِرِينَ (98) وَلَقَدْ أَنْزَلْنا إِلَيْكَ آياتٍ بَيِّناتٍ وَما يَكْفُرُ بِها إِلاَّ الْفاسِقُونَ (99) لِجِبْرِيلَ فَإِنَّهُ ) ليس سببا فيما يعمل حتى تتخذونه عدوا بل إنه ( نَزَّلَهُ ) أي القرآن ( عَلى قَلْبِكَ بِإِذْنِ اللهِ ) لا من عند نفسه ( مُصَدِّقاً لِما بَيْنَ يَدَيْهِ ) أي للكتاب الذي قبله وهو التوراة ( وَهُدىً وَبُشْرى لِلْمُؤْمِنِينَ ) فأي ذنب لجبريل عليه‌السلام حتى تتخذونه عدوا ولا تؤمنون بالكتاب الذي يأتي به.` },
            { text: "مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَٰٓئِكَتِهِۦ وَرُسُلِهِۦ وَجِبْرِيلَ وَمِيكَىٰلَ فَإِنَّ ٱللَّهَ عَدُوٌّ لِّلْكَٰفِرِينَ", tafsir: `أي يفعل فعل المعادي من الإتيان بما يكرهه سبحانه ( وَمَلائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكالَ ) وإنما خصهما بالذكر لأنهما موضع البحث مع اليهود ( فَإِنَّ اللهَ عَدُوٌّ لِلْكافِرِينَ ) إذ كل من يعادي أحد هؤلاء يكون كافرا والله عدو لمن كفر أي يفعل معه فعل المعادي من الإهانة والتعذيب والعقاب.` },
            { text: "وَلَقَدْ أَنزَلْنَآ إِلَيْكَ ءَايَٰتٍۭ بَيِّنَٰتٍ وَمَا يَكْفُرُ بِهَآ إِلَّا ٱلْفَٰسِقُونَ", tafsir: `يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( آياتٍ بَيِّناتٍ ) واضحات ( وَما يَكْفُرُ بِها إِلَّا الْفاسِقُونَ ) الفاسق هو الخارج عن طاعة الله سبحانه. أَ وَكُلَّما عاهَدُوا عَهْداً نَبَذَهُ فَرِيقٌ مِنْهُمْ بَلْ أَكْثَرُهُمْ لا يُؤْمِنُونَ (100) وَلَمَّا جاءَهُمْ رَسُولٌ مِنْ عِنْدِ اللهِ مُصَدِّقٌ لِما مَعَهُمْ نَبَذَ فَرِيقٌ مِنَ الَّذِينَ أُوتُوا الْكِتابَ كِتابَ اللهِ وَراءَ ظُهُورِهِمْ كَأَنَّهُمْ لا يَعْلَمُونَ (101) وَاتَّبَعُوا ما تَتْلُوا الشَّياطِينُ عَلى مُلْكِ سُلَيْمانَ` },
            { text: "أَوَكُلَّمَا عَٰهَدُوا۟ عَهْدًا نَّبَذَهُۥ فَرِيقٌ مِّنْهُم بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ", tafsir: `أي اليهود ( عَهْداً نَبَذَهُ ) أي نقضه ( فَرِيقٌ مِنْهُمْ ) أي جماعة ( بَلْ أَكْثَرُهُمْ لا يُؤْمِنُونَ ) وهذا إنكار عليهم في نقضهم عهود الأنبياء السابقين بإطاعتهم ونقضهم عهود رسول الله صلى‌الله‌عليه‌وآله‌وسلم في قصة نضير وقريضة والمراد بالإيمان : إما الإيمان بالعهود وإما الإيمان بالله ورسله وإما الإيمان بالرسول صلى‌الله‌عليه‌وآله‌وسلم ، وإنما قال أكثرهم لأن بعضهم آمن كعبد الله بن سلام.` },
            { text: "وَلَمَّا جَآءَهُمْ رَسُولٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ كِتَٰبَ ٱللَّهِ وَرَآءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ", tafsir: `أي اليهود ( رَسُولٌ مِنْ عِنْدِ اللهِ ) كعيسى عليه‌السلام ومحمد صلى‌الله‌عليه‌وآله‌وسلم ( مُصَدِّقٌ لِما مَعَهُمْ ) من التوراة ( نَبَذَ فَرِيقٌ ) أي جماعة ( مِنَ الَّذِينَ أُوتُوا الْكِتابَ ) من اليهود الذين آتاهم الله التوراة ( كِتابَ اللهِ وَراءَ ظُهُورِهِمْ ) وتركوا أوامره باتباع الأنبياء عليهم‌السلام من بعد موسى عليه‌السلام ( كَأَنَّهُمْ لا يَعْلَمُونَ ) أي من أحكام التوراة الإيمان بالأنبياء واتباع الرسل.` },
            { text: "وَٱتَّبَعُوا۟ مَا تَتْلُوا۟ ٱلشَّيَٰطِينُ عَلَىٰ مُلْكِ سُلَيْمَٰنَ وَمَا كَفَرَ سُلَيْمَٰنُ وَلَٰكِنَّ ٱلشَّيَٰطِينَ كَفَرُوا۟ يُعَلِّمُونَ ٱلنَّاسَ ٱلسِّحْرَ وَمَآ أُنزِلَ عَلَى ٱلْمَلَكَيْنِ بِبَابِلَ هَٰرُوتَ وَمَٰرُوتَ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَآ إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِۦ بَيْنَ ٱلْمَرْءِ وَزَوْجِهِۦ وَمَا هُم بِضَآرِّينَ بِهِۦ مِنْ أَحَدٍ إِلَّا بِإِذْنِ ٱللَّهِ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ وَلَقَدْ عَلِمُوا۟ لَمَنِ ٱشْتَرَىٰهُ مَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ وَلَبِئْسَ مَا شَرَوْا۟ بِهِۦٓ أَنفُسَهُمْ لَوْ كَانُوا۟ يَعْلَمُونَ", tafsir: `عوض الكتاب ـ السحر ـ فنبذوا الكتاب وراء ظهورهم وراحوا يتعلقون ب ( ما تَتْلُوا ) وتقر ( الشَّياطِينُ ) والسحرة ( عَلى مُلْكِ سُلَيْمانَ ) بن داود عليهم‌السلام حيث أن الشياطين على لسان السحرة على وَما كَفَرَ سُلَيْمانُ وَلكِنَّ الشَّياطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ زمان سليمان كانوا يتلون السحر للناس و « على » بمعنى « في » كما قال ابن مالك « على للاستعلاء ومعنى في وعن » أي أن اليهود أخذوا يتعلقون بالسحر الذي كان في زمان سليمان يريدون بذلك جلب الأموال والتقرب إلى الناس وكانوا يقولون أن سليمان عليه‌السلام إنما أوتي الملك العظيم بسبب أنه كان يعمل بالسحر فرد الله عليهم بقوله ( وَما كَفَرَ سُلَيْمانُ ) فإن السحر موجب للكفر ولا يخفى أن الكفر على نوعين : كفر في العقيدة وكفر في العمل ، فالكفر في العقيدة هو إنكار أصول الدين ، والكفر في العمل هو ترك واجب أو فعل ، ولذا شاع استعمال الكفر على ترك الأوامر وفعل النواهي كقوله تعالى ( وَمَنْ كَفَرَ فَإِنَّ اللهَ غَنِيٌّ عَنِ الْعالَمِينَ ) (1) في قصة الحج وقوله ( وَلَئِنْ كَفَرْتُمْ إِنَّ عَذابِي لَشَدِيدٌ ) (2) في باب الشكر و قول النبي صلى‌الله‌عليه‌وآله‌وسلم « كفر بالله العظيم من هذه الأمة عشرة » وعدّ منها النمام ونحوه وعلى أي حال فسليمان ما كان ساحرا ولم ينل ما نال بالسحر وإنما بالنبوة والموهبة الإلهية. ( وَلكِنَّ الشَّياطِينَ كَفَرُوا ) بعملهم بالسحر وتعليمهم للناس إياه والشياطين أرواح شريرة تلقي الشر في النفوس كما ثبت في العلم الحديث أيضا وغيره في باب التحضير والتنويم المغناطيسي ( يُعَلِّمُونَ النَّاسَ السِّحْرَ ) والسحر أمور غير طبيعية تأتي بعلاج خفي ومنه التصرف ( 1) آل عمران : 98. ( 2) إبراهيم : 8. وَما أُنْزِلَ عَلَى الْمَلَكَيْنِ بِبابِلَ هارُوتَ وَمارُوتَ وَما يُعَلِّمانِ مِنْ أَحَدٍ حَتَّى يَقُولا إِنَّما نَحْنُ فِتْنَةٌ فَلا تَكْفُرْ فَيَتَعَلَّمُونَ مِنْهُما ما يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ في العين وفي النفس وفي العقل فيوجب عداوة بين الناس ومرضا وما أشبه ( وَما أُنْزِلَ عَلَى الْمَلَكَيْنِ ) عطف على قوله « ما تتلوا » أي أن اليهود تركوا الكتاب واتبعوا سحر الشياطين وسحر الملكين ومن قصتهما أن بعد نوح عليه‌السلام كثرت السحرة فأنزل الله ملكين في « بابل » على نبي ذلك الزمان حتى يعلمان الناس إبطال السحر فكانا يقولان للناس « هذا السحر وهذا إبطاله » كالطبيب الذي يكتب كتاب الطب فيصف الداء وما يسببه والدواء المزيل له فيقول مثلا إن الشيء الفلاني سم ودواؤه كذا فكان الملكان يعلمان السحر وإبطاله ويحذران الناس أن يعملوا بالسحر وإنما يصران أن يبطلوا السحر فإذا تعلم منهما الناس أخذ بعضهم بالسحر كما أن الشخص يقرأ كتاب الطب فيسقي الناس السم لم يكن ذلك من ذنب المؤلف للطب وإنما هو من العامل بما يضر الناس. فقد ترك اليهود كتاب الله وأخذوا بالعلم الذي أنزل ـ أي أنزل الله ـ على الملكين الذين نزلا ( بِبابِلَ ) وهما ( هارُوتَ وَمارُوتَ ) ولا يظن أحد أنهما كيف يعلمان السحر للناس وهما ملكان من قبل الله تعالى ( وَ ) ذلك لأنه ( ما يُعَلِّمانِ مِنْ أَحَدٍ ) أي ما يعلمان أحد السحر ( حَتَّى يَقُولا ) له ( إِنَّما نَحْنُ فِتْنَةٌ ) وامتحان لك وكان تعليم للعلاج لا للإضرار ( فَلا تَكْفُرْ ) بأعمال السحر ( فَيَتَعَلَّمُونَ ) أي الناس ( مِنْهُما ) أي من الملكين ( ما يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ ) وما وَما هُمْ بِضارِّينَ بِهِ مِنْ أَحَدٍ إِلاَّ بِإِذْنِ اللهِ وَيَتَعَلَّمُونَ ما يَضُرُّهُمْ وَلا يَنْفَعُهُمْ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَراهُ ما لَهُ فِي الْآخِرَةِ مِنْ خَلاقٍ وَلَبِئْسَ ما شَرَوْا بِهِ أَنْفُسَهُمْ لَوْ كانُوا يَعْلَمُونَ (102) يوجب العداوة والبغضاء بين الزوجين مما يؤول إلى الفراق والطلاق ( وَ ) لا يتوهم أن الأمر خرج من يد الله سبحانه كلا بل إنما شاء الله أن يختبر عباده كما أنه حين يخلق العنب ويعطي القدرة للبشر فيعصره خمرا لا يخرج الأمر من يده سبحانه بل إنما ذلك للامتحان والابتلاء ولهذا قال سبحانه ( ما هُمْ ) أي الملكان ومتعلم السحر منهما ( بِضارِّينَ بِهِ ) أي بسبب السحر ( مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللهِ ) فإن شيئا لا يؤثر في شيء إطلاقا إلا بإذن الله ومعنى إذنه أنه يخلي بين المؤثر والمتأثر ولو لم يخل كان عالم الجبر وبطل الامتحان والاختبار والمراد بهذه الجملة أن شيئا لا يخرج من إرادة الله سبحانه حتى أن يتمكن من الردع لكنه لا يردع. ( وَيَتَعَلَّمُونَ ) أي يتعلم الناس من الملكين ( ما يَضُرُّهُمْ ) أي الشيء الذي يضرهم في دنياهم ودينهم ( وَلا يَنْفَعُهُمْ ) أكد بذلك ردّا لزعمهم أن السحر ينفعهم حيث يوصلهم إلى أغراضهم ( وَلَقَدْ عَلِمُوا لَمَنِ اشْتَراهُ ) أي علم المتعلمون للسحر أن من اشترى السحر وباع دينه ( ما لَهُ فِي الْآخِرَةِ مِنْ خَلاقٍ ) أي من نصيب ( وَلَبِئْسَ ما شَرَوْا بِهِ أَنْفُسَهُمْ ) فإنهم أعطوا أنفسهم للنار مقابل اشتراء السحر الذي زعموا وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِنْ عِنْدِ اللهِ خَيْرٌ لَوْ كانُوا يَعْلَمُونَ (103) يا أَيُّهَا الَّذِينَ آمَنُوا لا تَقُولُوا راعِنا وَقُولُوا انْظُرْنا وَاسْمَعُوا وَلِلْكافِرِينَ عَذابٌ أَلِيمٌ (104) إنه ينفع دنياهم ( لَوْ كانُوا يَعْلَمُونَ ) نزل العالم بالشيء منزلة الجاهل حيث لم يعمل بعلمه فإن من لا يعمل بعلمه هو والجاهل سواء.` },
            { text: "وَلَوْ أَنَّهُمْ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَمَثُوبَةٌ مِّنْ عِندِ ٱللَّهِ خَيْرٌ لَّوْ كَانُوا۟ يَعْلَمُونَ", tafsir: `أي اليهود بدل اتباع السحر ( آمَنُوا ) حقيقة ( وَاتَّقَوْا ) عن فعل المعاصي ( لَمَثُوبَةٌ ) أي ثواب ( مِنْ عِنْدِ اللهِ خَيْرٌ ) لهم في دنياهم وآخرتهم ( لَوْ كانُوا يَعْلَمُونَ ) لكنهم حيث لا يعملون بذلك فكأنهم لا يعلمونه.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تَقُولُوا۟ رَٰعِنَا وَقُولُوا۟ ٱنظُرْنَا وَٱسْمَعُوا۟ وَلِلْكَٰفِرِينَ عَذَابٌ أَلِيمٌ", tafsir: `للرسول حين كلامكم معه ( راعِنا ) فإن راعنا في اللغة العربية من المراعاة والرعاية ، ولكنها في لغة اليهود بمعنى « أسمعت لا سمعت » فهو سب ودعاء على المخاطب وقد كانت اليهود اغتنمت هذه الكلمة المتشابهة لسب النبي صلى‌الله‌عليه‌وآله‌وسلم بهذا العنوان فكانوا يأتون إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم ويقولون له « راعنا » يريدون بذلك سبه صلى‌الله‌عليه‌وآله‌وسلم فنهى الله المسلمين عن هذه اللفظة حتى لا يتمكن اليهود من التكلم بهذه الكلمة ( وَقُولُوا ) عوض ذلك ( انْظُرْنا ) أي انظر إلينا بنظرتك الرحيمة ( وَاسْمَعُوا ) أيها المؤمنون أوامرنا وأوامر الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلِلْكافِرِينَ ) من اليهود الشاتمين للنبي صلى‌الله‌عليه‌وآله‌وسلم تحت ستار لفظة « راعنا » ( عَذابٌ أَلِيمٌ ) أي مؤلم في الآخرة. ما يَوَدُّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتابِ وَلا الْمُشْرِكِينَ أَنْ يُنَزَّلَ عَلَيْكُمْ مِنْ خَيْرٍ مِنْ رَبِّكُمْ وَاللهُ يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشاءُ وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ (105) ما نَنْسَخْ مِنْ آيَةٍ أَوْ نُنْسِها نَأْتِ بِخَيْرٍ مِنْها أَوْ مِثْلِها أَ لَمْ تَعْلَمْ` },
            { text: "مَّا يَوَدُّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَٰبِ وَلَا ٱلْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ وَٱللَّهُ يَخْتَصُّ بِرَحْمَتِهِۦ مَن يَشَآءُ وَٱللَّهُ ذُو ٱلْفَضْلِ ٱلْعَظِيمِ", tafsir: `من اليهود والنصارى والمجوس ( وَلَا ) من ( الْمُشْرِكِينَ أَنْ يُنَزَّلَ عَلَيْكُمْ مِنْ خَيْرٍ مِنْ ) قبل ( رَبِّكُمْ ) سواء كان خيرا معنويا كالنبوة والإرشاد والوحي أو ماديا كالغلبة والنصر والمال ( وَاللهُ يَخْتَصُّ بِرَحْمَتِهِ مَنْ يَشاءُ ) فليس إرادة الله تبعا لإرادة الكفار والمشركين ( وَاللهُ ذُو الْفَضْلِ الْعَظِيمِ ) فليس فضله خاصا بقوم من الكفار كما كانت اليهود تزعم أن النبوة فيهم دون غيرهم.` },
            { text: "مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `بأن نرفع حكمها ونجعل مكانه حكما آخر ( أَوْ نُنْسِها ) بأن نرفع رسمها ونبلي عن القلوب حفظها ، والنسيان لا يقع بالنسبة إلى القرآن الكريم وإنما بالنسبة إلى الكتب السالفة ولذا لا يوجد كثير منها فعلا ، أما النسخ فإنه وقع بالنسبة إلى القرآن ـ على الأشهر ـ وإلى غيره ( نَأْتِ بِخَيْرٍ مِنْها أَوْ مِثْلِها ) وإنما يقع النسخ والإنساء فيما يؤتى بالمثل لأن المثل أصلح من المنسوخ والمنسي ، فمثلا إذا سقطت ورقة مالية عن الاعتبار فيأتي الحاكم بورقة أخرى مثلها في القيمة ، كما أنه قد يأخذ درهما من زيد ليعطيه بدله دينارا ( أَ لَمْ تَعْلَمْ ) أيها اليهودي أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (106) أَ لَمْ تَعْلَمْ أَنَّ اللهَ لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ وَما لَكُمْ مِنْ دُونِ اللهِ مِنْ وَلِيٍّ وَلا نَصِيرٍ (107) أَمْ تُرِيدُونَ أَنْ تَسْئَلُوا رَسُولَكُمْ كَما سُئِلَ مُوسى المنكر للنسخ ( أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فإن اليهود كانوا يلقون الشبهة بأنه كيف يمكن نسخ كتابهم بالقرآن وأنه إن كان كتابهم صالحا فلما ذا ينسخ وإن لم يكن صالحا فلما ذا أنزله الله تعالى ، وقد كان الجواب إن عدم النسخ إما لعدم مثل أو أصلح وإما لعدم قدرة الله تعالى على النسخ وكلا الأمرين مفقودان ، فالمثل والأصلح موجودان والله على كل شيء قدير.` },
            { text: "أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ", tafsir: `أيها المنكر للنسخ ( أَنَّ اللهَ لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ ) فيتصرف فيما يشاء من الأوضاع والأحكام كيف يشاء ( وَما لَكُمْ مِنْ دُونِ اللهِ ) أي غير الله ( مِنْ وَلِيٍ ) يلي أموركم ( وَلا نَصِيرٍ ) ينصركم فهو سبحانه يرى صلاحكم في النسخ والإنساء فإن المصالح تختلف حسب اختلاف الأعصار والأشخاص ، ولقد كان شأن آيات الله أن تنهض بالبشر مرتبة فمرتبة حتى وصلت النوبة لرسالة الإسلام وهذه بدلت بعض جزئياتها قبل تمامها وكمالها تحقيقا للتناسق بين الرسالة وبين العصر ، حتى إذا كملت لم يبق مبرر أو تحوير بل تبقى إلى الأبد.` },
            { text: "أَمْ تُرِيدُونَ أَن تَسْـَٔلُوا۟ رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ وَمَن يَتَبَدَّلِ ٱلْكُفْرَ بِٱلْإِيمَٰنِ فَقَدْ ضَلَّ سَوَآءَ ٱلسَّبِيلِ", tafsir: `أيها المعاصرون للرسول صلى‌الله‌عليه‌وآله‌وسلم من مسلم وكتابي ومشرك ( أَنْ تَسْئَلُوا رَسُولَكُمْ ) أسئلة تعنت ولجاجة ( كَما سُئِلَ مُوسى مِنْ قَبْلُ وَمَنْ يَتَبَدَّلِ الْكُفْرَ بِالْإِيمانِ فَقَدْ ضَلَّ سَواءَ السَّبِيلِ (108) وَدَّ كَثِيرٌ مِنْ أَهْلِ الْكِتابِ لَوْ يَرُدُّونَكُمْ مِنْ بَعْدِ إِيمانِكُمْ كُفَّاراً حَسَداً مِنْ عِنْدِ أَنْفُسِهِمْ مِنْ قَبْلُ ) حيث كانوا يقترحون عليه اقتراحات ويسألونه محالات كقولهم لن نؤمن لك حتى نرى الله جهرة ، فإن المعاصرين كانوا يسألون ما لا يعنيهم أو ما أشبه كقولهم ( أَوْ تُسْقِطَ السَّماءَ كَما زَعَمْتَ عَلَيْنا كِسَفاً ) (1) فقد زجرهم الله سبحانه لهذه الأسئلة التي لا ترتبط بمقام الرسول والرسالة من بعد ما تبين لهم الهدى ، وقوله « رسولكم » لا يختص بالمؤمنين إذ يكفي في الإضافة أدنى ملابسة ( وَمَنْ يَتَبَدَّلِ الْكُفْرَ بِالْإِيمانِ ) بأن يأخذ الكفر ويترك الإيمان الذي من مصاديقه الأسئلة التعنتية إذ إنها من سمات الكفر والانحراف ( فَقَدْ ضَلَّ سَواءَ السَّبِيلِ ) أي وسطه الموصل إلى المطلوب.` },
            { text: "وَدَّ كَثِيرٌ مِّنْ أَهْلِ ٱلْكِتَٰبِ لَوْ يَرُدُّونَكُم مِّنۢ بَعْدِ إِيمَٰنِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِم مِّنۢ بَعْدِ مَا تَبَيَّنَ لَهُمُ ٱلْحَقُّ فَٱعْفُوا۟ وَٱصْفَحُوا۟ حَتَّىٰ يَأْتِىَ ٱللَّهُ بِأَمْرِهِۦٓ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `أي أحب ( كَثِيرٌ مِنْ أَهْلِ الْكِتابِ ) اليهود والنصارى والمجوس ( لَوْ يَرُدُّونَكُمْ ) أيها المسلمون ( مِنْ بَعْدِ إِيمانِكُمْ كُفَّاراً ) فتكونون مثلهم ( حَسَداً ) لكم كيف صرتم إلى حضرة الإيمان وتقدمتم في الحياة وهذا الحب ليس من جهة أنهم متدينون فيأسفون عليكم لماذا تركتم الإيمان بل الحب ( مِنْ عِنْدِ أَنْفُسِهِمْ ) تشبيها ( 1) الإسراء : 93. مِنْ بَعْدِ ما تَبَيَّنَ لَهُمُ الْحَقُّ فَاعْفُوا وَاصْفَحُوا حَتَّى يَأْتِيَ اللهُ بِأَمْرِهِ إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (109) وَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ وَما تُقَدِّمُوا لِأَنْفُسِكُمْ مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللهِ إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ (110) وَقالُوا لَنْ يَدْخُلَ الْجَنَّةَ إِلاَّ مَنْ كانَ هُوداً أَوْ نَصارى تِلْكَ وحسب أهوائهم أي أن مبدأ الحب هوى النفس لا الدين ( مِنْ بَعْدِ ما تَبَيَّنَ لَهُمُ الْحَقُ ) فليس ذلك لجهلهم بدينكم وحقيقتكم ( فَاعْفُوا ) أيها المسلمون عنهم ( وَاصْفَحُوا ) عن أعمال الكفار ولا تقابلوا إساءتهم بالمثل ( حَتَّى يَأْتِيَ اللهُ بِأَمْرِهِ ) فيأذن لكم في المبارزة والمقاتلة والمقابلة بالمثل ( إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فيأتي يوم يجعلكم أقوياء فتتمكنوا من محاربة هؤلاء الكفار فيأذن لكم في المبارزة معهم.` },
            { text: "وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَمَا تُقَدِّمُوا۟ لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ ٱللَّهِ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `أما إذا لم يأت الله بأمره ف ( أَقِيمُوا الصَّلاةَ وَآتُوا الزَّكاةَ ) ولا تبارزوا ( وَما تُقَدِّمُوا لِأَنْفُسِكُمْ ) من إعطاء الزكاة وسائر الخيرات التي هي لأنفسكم لأنها تعود إليكم في الدنيا بالألفة وفي الآخرة بالثواب ( مِنْ خَيْرٍ تَجِدُوهُ عِنْدَ اللهِ ) يوم القيامة و ( إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ ) فلا يضيع شيء يصرف في وجهه ولا عمل يؤتى لأجله.` },
            { text: "وَقَالُوا۟ لَن يَدْخُلَ ٱلْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَٰرَىٰ تِلْكَ أَمَانِيُّهُمْ قُلْ هَاتُوا۟ بُرْهَٰنَكُمْ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `قالت اليهود : لن يدخلها إلا اليهود ، وقالت النصارى : لن يدخلها إلا النصارى ، وهود جمع هائد ، كعود جمع عائد ( تِلْكَ ) المقالة أَمانِيُّهُمْ قُلْ هاتُوا بُرْهانَكُمْ إِنْ كُنْتُمْ صادِقِينَ (111) بَلى مَنْ أَسْلَمَ وَجْهَهُ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُ أَجْرُهُ عِنْدَ رَبِّهِ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (112) وَقالَتِ الْيَهُودُ لَيْسَتِ النَّصارى عَلى شَيْءٍ وَقالَتِ النَّصارى لَيْسَتِ الْيَهُودُ عَلى شَيْءٍ وَهُمْ يَتْلُونَ الْكِتابَ ( أَمانِيُّهُمْ ) جمع أمنية أي رغبتهم الكاذبة ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لهم ( هاتُوا ) أي احضروا وجيئوا ( بُرْهانَكُمْ ) ودليلكم على ما تدّعون ( إِنْ كُنْتُمْ صادِقِينَ ) في مقالتكم.` },
            { text: "بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُۥ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُۥٓ أَجْرُهُۥ عِندَ رَبِّهِۦ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `جواب سؤال تقديره أ فليس يدخل الجنة أحد ومن هو ؟ فقيل ( مَنْ أَسْلَمَ وَجْهَهُ لِلَّهِ ) وخص الوجه لأنه أشرف الأعضاء فإذا أسلمه الشخص فقد أسلم جميع جوارحه ( وَهُوَ مُحْسِنٌ ) في عمله ( فَلَهُ أَجْرُهُ عِنْدَ رَبِّهِ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) فهو يدخل الجنة سواء كان يهوديا في زمان موسى أو نصرانيا في زمان عيسى أو مسلما في زمان محمد أو من سائر الأمم في زمان أنبيائها عليهم‌السلام . وهذا كلام معه دليله إذ معيار الدخول في الجنة الإيمان والعمل الصالح فلا يقال لمن يقول ذلك : هات برهانك.` },
            { text: "وَقَالَتِ ٱلْيَهُودُ لَيْسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَىْءٍ وَقَالَتِ ٱلنَّصَٰرَىٰ لَيْسَتِ ٱلْيَهُودُ عَلَىٰ شَىْءٍ وَهُمْ يَتْلُونَ ٱلْكِتَٰبَ كَذَٰلِكَ قَالَ ٱلَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَٱللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ ٱلْقِيَٰمَةِ فِيمَا كَانُوا۟ فِيهِ يَخْتَلِفُونَ", tafsir: `من دين وإيمان وتقوى فكل طائفة تجعل نفسها الناجية وغيرها الهالكة ( وَ ) الحال إن ( هُمْ يَتْلُونَ الْكِتابَ ) والتالي كَذلِكَ قالَ الَّذِينَ لا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ فَاللهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيامَةِ فِيما كانُوا فِيهِ يَخْتَلِفُونَ (113) وَمَنْ أَظْلَمُ مِمَّنْ مَنَعَ مَساجِدَ اللهِ أَنْ يُذْكَرَ فِيهَا اسْمُهُ وَسَعى فِي خَرابِها أُولئِكَ ما كانَ لَهُمْ أَنْ للكتاب لا يحق له أن يقول مثل هذه المقالة إذ كل منهم يعلم أن صاحبه على بعض الشيء ، فإن اليهود يعرفون أن النصارى لهم إيمان في الجملة وكذلك النصارى يعرفون أن اليهود لهم إيمان في الجملة ( كَذلِكَ ) القول ( قالَ الَّذِينَ لا يَعْلَمُونَ ) من الكفار ( مِثْلَ قَوْلِهِمْ ) وهذا تأنيب للطائفتين حيث صاروا كمن لا كتاب له وهو جاهل فإن الجاهل يمكن إن يقول ليس اليهود أو النصارى على شيء لأنه يزعم بطلان كليهما ( فَاللهُ يَحْكُمُ بَيْنَهُمْ ) جميعا ( يَوْمَ الْقِيامَةِ ) وهناك يتبين لكل طائفة إنه على شيء أم لا ( فِيما كانُوا فِيهِ يَخْتَلِفُونَ ) ولعل تخصيص الحكم بهناك لأن هناك لا تبقى شبهة في الحكم بخلاف حكمه سبحانه في الدنيا فإن من لا يؤمن بالإسلام لا يعترف بحكمه.` },
            { text: "وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَٰجِدَ ٱللَّهِ أَن يُذْكَرَ فِيهَا ٱسْمُهُۥ وَسَعَىٰ فِى خَرَابِهَآ أُو۟لَٰٓئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَآ إِلَّا خَآئِفِينَ لَهُمْ فِى ٱلدُّنْيَا خِزْىٌ وَلَهُمْ فِى ٱلْـَٔاخِرَةِ عَذَابٌ عَظِيمٌ", tafsir: `وهي عامة لكل مانع وإن كان ينطبق على أهل مكة الذين منعوا الرسول صلى‌الله‌عليه‌وآله‌وسلم عن المسجد الحرام وبخت نصّر الذي منع عن بيت المقدس ( أَنْ يُذْكَرَ فِيهَا اسْمُهُ ) أي لا أحد أظلم من هكذا شخص والحصر المستفاد من الآية إضافي وإلا فمن قتل الأنبياء أظلم ( وَسَعى فِي خَرابِها ) خرابا معنويا بمنع المصلين عنها أو خراب العمارة والبناء ( أُولئِكَ ما كانَ لَهُمْ أَنْ يَدْخُلُوها إِلاَّ خائِفِينَ لَهُمْ فِي الدُّنْيا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذابٌ عَظِيمٌ (114) وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ فَأَيْنَما تُوَلُّوا فَثَمَّ وَجْهُ اللهِ إِنَّ اللهَ واسِعٌ عَلِيمٌ (115) وَقالُوا اتَّخَذَ اللهُ وَلَداً يَدْخُلُوها إِلَّا خائِفِينَ ) من عذاب الله سبحانه ، فمن يسعى في خراب المساجد كيف يدخلها آمنا أو خائفين من المسلمين أن يعاقبوهم ( لَهُمْ فِي الدُّنْيا خِزْيٌ ) بالعقاب الإسلامي لمن فعل ذلك أو إخبار بخزي عن الله سبحانه ينزل بمن يسعى في خراب المساجد ( وَلَهُمْ فِي الْآخِرَةِ عَذابٌ عَظِيمٌ ) حيث يذوق النار مهانا ولعل هاتين الآيتين أيضا تلميح إلى فعل اليهود بمنعهم عن المساجد.` },
            { text: "وَلِلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ فَأَيْنَمَا تُوَلُّوا۟ فَثَمَّ وَجْهُ ٱللَّهِ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٌ", tafsir: `فكلتا الجهتين له سبحانه خلقها وهما ملك له وحده ( فَأَيْنَما تُوَلُّوا ) وجوهكم ( فَثَمَّ وَجْهُ اللهِ ) وجه الله جانبه أي أن الله سبحانه محيط بالعلم والقدرة على كل ناحية فإذا توجه الإنسان إلى المشرق فقد توجه إلى الله وإذا توجه إلى المغرب فقد توجه إلى الله ، وليس الله جسما حتى يكون له مكان معين يلزم التوجه إليه ( إِنَّ اللهَ واسِعٌ ) علما وقدرة لأنه محيط بجميع الجهات ( عَلِيمٌ ) بما يفعله الإنسان من التوجه إلى أية ناحية ، وربما قيل بأنها نزلت في رد اليهود الذين قالوا كيف انصرف محمد صلى‌الله‌عليه‌وآله‌وسلم عن قبلة بيت المقدس إلى الكعبة.` },
            { text: "وَقَالُوا۟ ٱتَّخَذَ ٱللَّهُ وَلَدًا سُبْحَٰنَهُۥ بَل لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ كُلٌّ لَّهُۥ قَٰنِتُونَ", tafsir: `اليهود عزير ابن الله والنصارى قالوا المسيح ابن الله والمشركون قالوا الملائكة بنات الله ( اتَّخَذَ اللهُ وَلَداً ) أما بأن أولده سُبْحانَهُ بَلْ لَهُ ما فِي السَّماواتِ وَالْأَرْضِ كُلٌّ لَهُ قانِتُونَ (116) بَدِيعُ السَّماواتِ وَالْأَرْضِ وَإِذا قَضى أَمْراً فَإِنَّما يَقُولُ لَهُ كُنْ فَيَكُونُ (117) وَقالَ الَّذِينَ لا يَعْلَمُونَ لَوْ لا يُكَلِّمُنَا اللهُ أَوْ تَأْتِينا آيَةٌ كَذلِكَ قالَ الَّذِينَ مِنْ قَبْلِهِمْ مِثْلَ كما زعم بعضهم أو أتخذ بعنوان التبني ( سُبْحانَهُ ) أي أنزهه عن ذلك تنزيها ( بَلْ لَهُ ما فِي السَّماواتِ وَالْأَرْضِ ) فكيف يكون المملوك ولدا إذ الولد ليس ملكا للوالد ، ثم إن المملوك تحت التصرف فالتبني لماذا .. . ؟ ( كُلٌ ) أي كل من السماوات والأرض ( لَهُ ) تعالى ( قانِتُونَ ) أي خاضعون ومطيعون.` },
            { text: "بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَإِذَا قَضَىٰٓ أَمْرًا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ", tafsir: `أي مبدعهما ومنشئهما وخالقهما وهذا تأكيد لما في الآية السابقة من أنه ( لَهُ ما فِي السَّماواتِ وَالْأَرْضِ ) ( وَإِذا قَضى أَمْراً ) وأراده ( فَإِنَّما يَقُولُ لَهُ ) أي لذلك الأمر المراد ( كُنْ ) أي يأمره بأن يوجد ( فَيَكُونُ ) أي فيوجد عقيب أمره فالكون بهذا النحو طوع إرادته وأمره.` },
            { text: "وَقَالَ ٱلَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا ٱللَّهُ أَوْ تَأْتِينَآ ءَايَةٌ كَذَٰلِكَ قَالَ ٱلَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ تَشَٰبَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا ٱلْـَٔايَٰتِ لِقَوْمٍ يُوقِنُونَ", tafsir: `بعد ذكر اختلاف أهل الكتاب ومنعهم وسائر المشركين عن المساجد ، وشركهم في باب التوحيد ، تعرض القرآن الحكيم حول كلامهم بالنسبة إلى الرسالة ، فقال ، و ( قالَ الَّذِينَ لا يَعْلَمُونَ ) موازين الوحي والرسالة ( لَوْ لا يُكَلِّمُنَا اللهُ ) أي هلّا يكلمنا ربنا ، بأن يأمرنا بأوامره ، بدون احتياج إلى وسيط ، أو يكلمنا بأنك نبي ( أَوْ تَأْتِينا آيَةٌ ) ومعجزة حسب اقتراحنا ( كَذلِكَ قالَ الَّذِينَ مِنْ قَبْلِهِمْ ) لأنبيائهم ( مِثْلَ قَوْلِهِمْ تَشابَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا الْآياتِ لِقَوْمٍ يُوقِنُونَ (118) إِنَّا أَرْسَلْناكَ بِالْحَقِّ بَشِيراً وَنَذِيراً وَلا تُسْئَلُ عَنْ أَصْحابِ الْجَحِيمِ (119) وَلَنْ تَرْضى عَنْكَ الْيَهُودُ وَلا النَّصا رى حَتَّى تَتَّبِعَ مِلَّتَهُمْ قَوْلِهِمْ ) لموسى عليه‌السلام أرنا الله جهرة ( تَشابَهَتْ قُلُوبُهُمْ ) في الإنكار وفي الاقتراح والتعنت ( قَدْ بَيَّنَّا الْآياتِ ) فلا حاجة إلى تكليم الله ، ولا إلى الإتيان بخوارق اقترحوها ، إذ لو كان مرادهم بيان الحق والبرهان ، فقد فعلنا ذلك ، وإن كان مرادهم غير ذلك فليس على الله إلا إتمام الحجة ( لِقَوْمٍ يُوقِنُونَ ) إنما خصهم لأنهم الذين يستفيدون منها وينتفعون بها.` },
            { text: "إِنَّآ أَرْسَلْنَٰكَ بِٱلْحَقِّ بَشِيرًا وَنَذِيرًا وَلَا تُسْـَٔلُ عَنْ أَصْحَٰبِ ٱلْجَحِيمِ", tafsir: `يا رسول الله ( بِالْحَقِ ) تأكيد للإرسال ، إذ كل إرسال الله تعالى بالحق ( بَشِيراً ) تبشر المؤمنين المطيعين ( وَنَذِيراً ) تنذر الكافرين والعاصين ، فأنت رسولنا ، وإن كانوا يشكون في رسالتك ، ويسألونك عن أشياء تافهة ( وَلا تُسْئَلُ ) أنت ( عَنْ أَصْحابِ الْجَحِيمِ ) فلست أنت مكلفا عنهم ، وإنما عليك التذكير فقط.` },
            { text: "وَلَن تَرْضَىٰ عَنكَ ٱلْيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ قُلْ إِنَّ هُدَى ٱللَّهِ هُوَ ٱلْهُدَىٰ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم بَعْدَ ٱلَّذِى جَآءَكَ مِنَ ٱلْعِلْمِ مَا لَكَ مِنَ ٱللَّهِ مِن وَلِىٍّ وَلَا نَصِيرٍ", tafsir: `حيث أن من طبيعة الحال أن كل صاحب مبدأ ليستميله الخصماء إلى ناحيتهم ، ويعدونه الرضا عنه ، إذا مال نحوهم بيّن الله تعالى لنبيه ، أن ذلك سراب خادع ويجب أن لا يغتر به الإنسان ، إذ ( لَنْ تَرْضى عَنْكَ الْيَهُودُ وَلَا النَّصارى ) إلى الأبد ( حَتَّى تَتَّبِعَ مِلَّتَهُمْ ) وتدخل في طريقتهم ، إذ كل ذي طريقة لا يرض عن شخص إلا قُلْ إِنَّ هُدَى اللهِ هُوَ الْهُدى وَلَئِنِ اتَّبَعْتَ أَهْواءَهُمْ بَعْدَ الَّذِي جاءَكَ مِنَ الْعِلْمِ ما لَكَ مِنَ اللهِ مِنْ وَلِيٍّ وَلا نَصِيرٍ (120) الَّذِينَ آتَيْناهُمُ الْكِتابَ يَتْلُونَهُ حَقَّ تِلاوَتِهِ أُولئِكَ يُؤْمِنُونَ بِهِ وَمَنْ يَكْفُرْ بِهِ فَأُولئِكَ هُمُ الْخاسِرُونَ (121) يا بَنِي إِسْرائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ بدخوله في طريقته تماما وكمالا ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِنَّ هُدَى اللهِ ) الذي هو الإسلام ( هُوَ الْهُدى ) فقط دون ما سواه من اليهودية والنصرانية ( وَلَئِنِ اتَّبَعْتَ أَهْواءَهُمْ ) إشارة إلى أن دينهم ليس إلا هوى أنفسهم ، وليس من عند الله سبحانه ( بَعْدَ الَّذِي جاءَكَ مِنَ الْعِلْمِ ) بالإسلام وشرائعه وبطلان اليهودية والنصرانية ( ما لَكَ ) أي ليس لك ( مِنَ اللهِ ) أي من طرف الله ( مِنْ وَلِيٍّ وَلا نَصِيرٍ ) أي فلا يلي الله تعالى أمورك ولا ينصرك.` },
            { text: "ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَتْلُونَهُۥ حَقَّ تِلَاوَتِهِۦٓ أُو۟لَٰٓئِكَ يُؤْمِنُونَ بِهِۦ وَمَن يَكْفُرْ بِهِۦ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ", tafsir: `التوراة والإنجيل الموصوفين بكذبهم ( يَتْلُونَهُ حَقَّ تِلاوَتِهِ ) بالعمل بما في الكتاب ( أُولئِكَ يُؤْمِنُونَ بِهِ ) أي بالنبي صلى‌الله‌عليه‌وآله‌وسلم أو بالقرآن أو بالإسلام أو بكتابهم إيمانا صحيحا ، لا كإيمان المعاندين الذين يأخذون ببعض الكتاب دون بعض ( وَمَنْ يَكْفُرْ بِهِ فَأُولئِكَ هُمُ الْخاسِرُونَ ) في الدنيا وفي الآخرة ، أما في الدنيا ، فلأن منهاج الله سبحانه هو المنهاج المسعد في الحياة ، فإذا عرض عنه الإنسان ، كانت معيشته ضنكا ، وأما في الآخرة ، فللعذاب المعد للكافرين.` },
            { text: "يَٰبَنِىٓ إِسْرَٰٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَٰلَمِينَ", tafsir: `من إرسال وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ (122) وَاتَّقُوا يَوْماً لا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئاً وَلا يُقْبَلُ مِنْها عَدْلٌ وَلا تَنْفَعُها شَفاعَةٌ وَلا هُمْ يُنْصَرُونَ (123) وَإِذِ ابْتَلى إِبْراهِيمَ رَبُّهُ بِكَلِماتٍ الرسل إليكم ، وإهلاك عدوكم ، وجعلكم ملوكا وتوسيع الدنيا لكم ( وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعالَمِينَ ) في زمانكم ، التي هي من أعظم النعم ـ وقد تقدم الكلام في مثل هذه الآية ـ.` },
            { text: "وَٱتَّقُوا۟ يَوْمًا لَّا تَجْزِى نَفْسٌ عَن نَّفْسٍ شَيْـًٔا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَٰعَةٌ وَلَا هُمْ يُنصَرُونَ", tafsir: `أي يوم القيامة ، الموصوف بأنه ( لا تَجْزِي نَفْسٌ عَنْ نَفْسٍ شَيْئاً ) هناك وإنما ترى كل نفس جزاؤها العادل ، فلا يحمل أحد وزر أحد ( وَلا يُقْبَلُ مِنْها عَدْلٌ ) أي فدية تعادله ، فيفك نفسه بالفدية والمال ( وَلا تَنْفَعُها شَفاعَةٌ ) بدون رضى الله سبحانه ( وَلا هُمْ يُنْصَرُونَ ) فلا ينصر أحد أحدا ، وقد تقدمت مثل هذه الآية ، لكن أريد الانتقال إلى موضوع آخر كرر المطلب السابق تذكيرا وتركيزا.` },
            { text: "وَإِذِ ٱبْتَلَىٰٓ إِبْرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٍ فَأَتَمَّهُنَّ قَالَ إِنِّى جَاعِلُكَ لِلنَّاسِ إِمَامًا قَالَ وَمِن ذُرِّيَّتِى قَالَ لَا يَنَالُ عَهْدِى ٱلظَّٰلِمِينَ", tafsir: `حيث تم بعض الكلام عن اليهود والنصارى والمشركين ، انتقل السياق للكلام حول إبراهيم وإسحاق ويعقوب عليهم‌السلام وبناء البيت مما يشترك فيه الجميع ، وإن تاريخهم قبل تاريخ اليهودية والنصرانية ، وقد اعتاد أن يتكلم المتكلم عن الظروف المعاصرة ، ثم ينتقل إلى التواريخ الغابرة ، واذكر يا رسول الله ( إِذِ ابْتَلى ) امتحن ( إِبْراهِيمَ ) عليه‌السلام ( رَبُّهُ ) فاعل ابتلى ، أي امتحن الله إبراهيم ( بِكَلِماتٍ ) أي بأمور ، فإن الكلمة تقال للأمر ، ولا يبعد أن يكون المراد بالكلمة نفس معناها العرفي ، فالمعنى ابتلاه بكلمات تكلم الله أو الملك معه عليه‌السلام حولها لينفذها ، ويأتي بمعناها ، ولعل الكلمات كانت حول ذبح فَأَتَمَّهُنَّ قالَ إِنِّي جاعِلُكَ لِلنَّاسِ إِماماً قالَ وَمِنْ ذُرِّيَّتِي قالَ لا يَنالُ عَهْدِي الظَّالِمِينَ (124) وَإِذْ جَعَلْنَا الْبَيْتَ مَثابَةً لِلنَّاسِ وَأَمْناً وَاتَّخِذُوا مِنْ مَقامِ إِبْراهِيمَ مُصَلًّى إسماعيل عليه‌السلام ، أو حول مجابهة نمرود الطاغي ( فَأَتَمَّهُنَ ) بأن أطاع الأمر كاملا غير منقوص ( قالَ ) الله تعالى بعد إتمام الكلمات ( إِنِّي جاعِلُكَ ) يا إبراهيم ( لِلنَّاسِ إِماماً ) والإمام هو المقتدى ، وحيث أن « الناس » كالجمع المحلى باللام أفاد العموم ، ولا منافاة بين كونه عليه‌السلام سابقا نبيا ورسولا ، ولم يكن إماما عاما ، ثم صار كذلك جزاء إتمام الكلمات ( قالَ ) إبراهيم عليه‌السلام سائلا الله تعالى ( وَمِنْ ذُرِّيَّتِي ) هل تجعل يا رب إماما ؟ وهذا طلب المتأدب يأتي به في لسان الاستفهام ( قالَ لا يَنالُ عَهْدِي ) بالإمامة ( الظَّالِمِينَ ) وهذا جواب مع زيادة ، إذ المفهوم منه ، نعم أجعل بعض ذريتك ، لكن غير الظالم منهم ، وإنما خص هذا بالذكر ، لبيان عظم مقام الإمامة.` },
            { text: "وَإِذْ جَعَلْنَا ٱلْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَٱتَّخِذُوا۟ مِن مَّقَامِ إِبْرَٰهِـۧمَ مُصَلًّى وَعَهِدْنَآ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ أَن طَهِّرَا بَيْتِىَ لِلطَّآئِفِينَ وَٱلْعَٰكِفِينَ وَٱلرُّكَّعِ ٱلسُّجُودِ", tafsir: `اذكر يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِذْ جَعَلْنَا الْبَيْتَ ) الحرام بمكة المكرمة ( مَثابَةً ) بمعنى مرجعا فإن الناس يرجعون إليه كل عام ، والرجوع بمناسبة مجموع الناس ، وإن لم يرجع إليه كل فرد ( لِلنَّاسِ وَأَمْناً ) فلا يحل القتال فيه ، وإن من التجأ إليه يكون آمنا ، فلا يجري عليه الحد ، ثم صار في الكلام التفات إلى الخطاب قائلا ( وَاتَّخِذُوا ) أيها المسلمون ( مِنْ مَقامِ إِبْراهِيمَ ) وهو الحجر الذي كان يضعه إبراهيم عليه‌السلام تحت رجله لبناء أعالي الكعبة ، الذي هو الآن بالقرب من الكعبة ( مُصَلًّى ) أي محل للصلاة ، فإنه تجب الصلاة للطواف وَعَهِدْنا إِلى إِبْراهِيمَ وَإِسْماعِيلَ أَنْ طَهِّرا بَيْتِيَ لِلطَّائِفِينَ وَالْعاكِفِينَ وَالرُّكَّعِ السُّجُودِ (125) وَإِذْ قالَ إِبْراهِيمُ رَبِّ اجْعَلْ هذا بَلَداً آمِناً وَارْزُقْ أَهْلَهُ مِنَ الثَّمَراتِ مَنْ آمَنَ مِنْهُمْ بِاللهِ وَالْيَوْمِ الْآخِرِ قالَ وَمَنْ كَفَرَ فَأُمَتِّعُهُ قَلِيلاً حول مقام إبراهيم في الحج ( وَعَهِدْنا ) أي ذكرنا ( إِلى إِبْراهِيمَ وَإِسْماعِيلَ ) عليهما‌السلام : الأب والابن ( أَنْ طَهِّرا بَيْتِيَ ) طهارة معنوية ، بعدم السماح لنصب الأصنام فيه وطهارة ظاهرية بالنظافة ( لِلطَّائِفِينَ ) أي الذين يطوفون حول البيت ( وَالْعاكِفِينَ ) الذين يعتكفون في المسجد الحرام ، وللاعتكاف مسائل وأحكام مذكورة في كتب الفقه (1) ( وَالرُّكَّعِ ) جمع راكع ( السُّجُودِ ) جمع ساجد ، أي المصلين.` },
            { text: "وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُۥ قَلِيلًا ثُمَّ أَضْطَرُّهُۥٓ إِلَىٰ عَذَابِ ٱلنَّارِ وَبِئْسَ ٱلْمَصِيرُ", tafsir: `اذكر يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِذْ قالَ إِبْراهِيمُ ) في دعائه لله تعالى ( رَبِّ اجْعَلْ هذا ) البلد وهو مكة ، التي بنى فيها البيت ( بَلَداً آمِناً ) عن الأخطار ، أو محكوما بحكم الأمن حكما شرعيا ، وإن كان السياق يؤيد الأول ( وَارْزُقْ أَهْلَهُ مِنَ الثَّمَراتِ مَنْ آمَنَ مِنْهُمْ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فإن دعاء إبراهيم عليه‌السلام كان خاصا بهم ( قالَ ) الله سبحانه في جواب إبراهيم عليه‌السلام ما يدل على استجابة دعائه مع الزيادة ، وهي ( وَمَنْ كَفَرَ ) من أهل هذا البلد ، لا نقطع عنه الثمار بل ( فَأُمَتِّعُهُ ) أي أعطيه المتاع من الحياة والرزق والأمن ، وسائر الأمور ( قَلِيلاً ) فإن ( 1) راجع موسوعة الفقه ج 77 ص 151 ، في أحكام الاعتكاف. ثُمَّ أَضْطَرُّهُ إِلى عَذابِ النَّارِ وَبِئْسَ الْمَصِيرُ (126) وَإِذْ يَرْفَعُ إِبْراهِيمُ الْقَواعِدَ مِنَ الْبَيْتِ وَإِسْماعِيلُ رَبَّنا تَقَبَّلْ مِنَّا إِنَّكَ أَنْتَ السَّمِيعُ الْعَلِيمُ (127) رَبَّنا وَاجْعَلْنا مُسْلِمَيْنِ لَكَ وَمِنْ ذُرِّيَّتِنا أُمَّةً مُسْلِمَةً لَكَ وَأَرِنا مَناسِكَنا عمر الدنيا قصير ، وأمدها قليل ( ثُمَّ أَضْطَرُّهُ ) أي أدفعه إلى النار باضطرار منه ، فما من أحد يرضى بالنار ( إِلى عَذابِ النَّارِ وَبِئْسَ الْمَصِيرُ ) أي بئس المأوى والمرجع.` },
            { text: "وَإِذْ يَرْفَعُ إِبْرَٰهِـۧمُ ٱلْقَوَاعِدَ مِنَ ٱلْبَيْتِ وَإِسْمَٰعِيلُ رَبَّنَا تَقَبَّلْ مِنَّآ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `أذكر يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( إِذْ يَرْفَعُ إِبْراهِيمُ الْقَواعِدَ مِنَ الْبَيْتِ ) أي كان يبني أساس البيت الحرام ، ويرفعه من الأرض ، ويعاونه في ذلك ( وَإِسْماعِيلُ ) ابنه ، وهما يقولان في حال البناء ( رَبَّنا تَقَبَّلْ مِنَّا ) بناء البيت ( إِنَّكَ أَنْتَ السَّمِيعُ ) دعاءنا ( الْعَلِيمُ ) بما نعمله ونقصده.` },
            { text: "رَبَّنَا وَٱجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَآ أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَآ إِنَّكَ أَنتَ ٱلتَّوَّابُ ٱلرَّحِيمُ", tafsir: `في جميع أمورنا ، والدعاء بالإسلام ، لا ينافي كونهما كذلك قبل الدعاء إذ الإسلام كسائر العقائد ، والأعمال بحاجة إلى الاستمرار ، مما لا يكون إلا بهداية الله وتوفيقه ، فكما أن الابتداء لا يكون إلا بعونه سبحانه ، كذلك الاستمرار ، كما في ( اهْدِنَا الصِّراطَ الْمُسْتَقِيمَ ) (1) ( وَ ) اجعل ( مِنْ ذُرِّيَّتِنا ) وأولادنا ( أُمَّةً مُسْلِمَةً لَكَ ) والإسلام هو تسليم الأمور إلى الله سبحانه في الاعتقاد والقول والعمل ( وَأَرِنا ) أي عرفنا ( مَناسِكَنا ) جمع منسك ، أي المواضع التي ( 1) الفاتحة : 6. وَتُبْ عَلَيْنا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ (128) رَبَّنا وَابْعَثْ فِيهِمْ رَسُولاً مِنْهُمْ يَتْلُوا عَلَيْهِمْ آياتِكَ وَيُعَلِّمُهُمُ الْكِتابَ وَالْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ (129) تتعلق النسك بها ، والنسك العبادة ، يقال رجل ناسك ، أي عابد ، وقد استجاب الله دعاءهما ، حيث أراهما جبرائيل عليه‌السلام موضع الصلاة ، والوقوف ، وغيرها ( وَتُبْ عَلَيْنا ) أي أرجع إلينا بالمغفرة والرحمة ، فإن التوبة بمعنى الرجوع ، ولذا يقال الله « التواب » أي كثير الرجوع إلى عبيده ، ومن ذلك تعرف أنه لا دلالة للآية ، على أنهما عليهما‌السلام ، كانا قد أذنبا ( إِنَّكَ أَنْتَ التَّوَّابُ ) بعبادك ( الرَّحِيمُ ) بهم.` },
            { text: "رَبَّنَا وَٱبْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُوا۟ عَلَيْهِمْ ءَايَٰتِكَ وَيُعَلِّمُهُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُزَكِّيهِمْ إِنَّكَ أَنتَ ٱلْعَزِيزُ ٱلْحَكِيمُ", tafsir: `أي في الأمة المسلمة ـ التي طلبناها منك ـ ( رَسُولاً مِنْهُمْ ) من نفس الأمة ، لا من سائر الأمم ، حتى يكون لهم الشرف بكون الرسول منهم ( يَتْلُوا عَلَيْهِمْ آياتِكَ ) دلائلك ، وبراهينك ، وأحكامك ( وَيُعَلِّمُهُمُ الْكِتابَ ) إما المراد : القرآن ، أو المراد : « كتابك » على نحو الكلي ( وَالْحِكْمَةَ ) هي وضع كل شيء موضعه والمراد بتعلمهم إياها ، تعليمهم العلوم الكونية والتشريعية ، فإن الجاهل لا يتمكن ، من وضع الأشياء مواضعها لجهله بها ( وَيُزَكِّيهِمْ ) أي يطهرهم من الأدناس والقذارات الأخلاقية والأعمالية ( إِنَّكَ أَنْتَ الْعَزِيزُ ) حقيقة ، فإن العزة لا تكون إلا بقلة الوجود ، وكثرة الاحتياج ، والله واحد لا شريك له ، وجميع الاحتياجات إليه وتخصيص العزة هنا بالذكر ، للتلميح إلى كون الاحتياج إليه ( الْحَكِيمُ ) فأفعالك صادرة عن حكمة ، وما طلباه إنما كان عين الحكمة. وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْراهِيمَ إِلاَّ مَنْ سَفِهَ نَفْسَهُ وَلَقَدِ اصْطَفَيْناهُ فِي الدُّنْيا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ (130) إِذْ قالَ لَهُ رَبُّهُ أَسْلِمْ قالَ أَسْلَمْتُ لِرَبِّ الْعالَمِينَ (131) وَوَصَّى بِها [131] هذه هي طريقة إبراهيم عليه‌السلام ( وَمَنْ يَرْغَبُ عَنْ مِلَّةِ إِبْراهِيمَ ) أي من يعرض عن هذه الطريقة في التوحيد والتسليم وسائر ما ذكر مما يدل على أنها من أفضل الطرق ( إِلَّا مَنْ سَفِهَ نَفْسَهُ ) أي لا يترك هذه الملة ، إلا من ضرب نفسه بالسفاهة والحمق ، وهل هناك طريقة أفضل من هذه الطريقة ؟ والاستفهام في قوله « من يرغب » استنكاري ( وَلَقَدِ اصْطَفَيْناهُ ) جملة حالية ، أي إنا بسبب هذه الطريقة المستقيمة ، التي كانت لإبراهيم عليه‌السلام اخترناه نبيا ( فِي الدُّنْيا وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ ) الفائزين بالدرجات الرفيعة.` },
            { text: "وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَٰهِـۧمَ إِلَّا مَن سَفِهَ نَفْسَهُۥ وَلَقَدِ ٱصْطَفَيْنَٰهُ فِى ٱلدُّنْيَا وَإِنَّهُۥ فِى ٱلْـَٔاخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ", tafsir: `(رَبَّنا وَابْعَثْ فِيهِمْ) أي في الأمة المسلمة ـ التي طلبناها منك ـ (رَسُولاً مِنْهُمْ) من نفس الأمة، لا من سائر الأمم، حتى يكون لهم الشرف بكون الرسول منهم (يَتْلُوا عَلَيْهِمْ آياتِكَ) دلائلك، وبراهينك، وأحكامك (وَيُعَلِّمُهُمُ الْكِتابَ) إما المراد: القرآن، أو المراد: «كتابك» على نحو الكلي (وَالْحِكْمَةَ) هي وضع كل شيء موضعه والمراد بتعلمهم إياها، تعليمهم العلوم الكونية والتشريعية، فإن الجاهل لا يتمكن، من وضع الأشياء مواضعها لجهله بها (وَيُزَكِّيهِمْ) أي يطهرهم من الأدناس والقذارات الأخلاقية والأعمالية (إِنَّكَ أَنْتَ الْعَزِيزُ) حقيقة، فإن العزة لا تكون إلا بقلة الوجود، وكثرة الاحتياج، والله واحد لا شريك له، وجميع الاحتياجات إليه وتخصيص العزة هنا بالذكر، للتلميح إلى كون الاحتياج إليه (الْحَكِيمُ) فأفعالك صادرة عن حكمة، وما طلباه إنما كان عين الحكمة.` },
            { text: "إِذْ قَالَ لَهُۥ رَبُّهُۥٓ أَسْلِمْ قَالَ أَسْلَمْتُ لِرَبِّ ٱلْعَٰلَمِينَ", tafsir: `هذا متعلق بقوله « اصطفيناه » أي اخترناه لما قلنا له ( أَسْلِمْ ) في جميع أمورك لله ( قالَ ) إبراهيم عليه‌السلام ( أَسْلَمْتُ لِرَبِّ الْعالَمِينَ ) وحده لا شريك له ، ومعنى أسلم استقم على الإسلام ، واثبت على التوحيد ، كقوله تعالى ( فَاعْلَمْ أَنَّهُ لا إِلهَ إِلَّا اللهُ وَاسْتَغْفِرْ ) (1) وكما يقول أحدنا لمن كان جالسا في مكان : أجلس هنا حتى الساعة العاشرة ـ مثلا ـ.` },
            { text: "وَوَصَّىٰ بِهَآ إِبْرَٰهِـۧمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ", tafsir: `أي بالملة والطريقة التي كانت لإبراهيم عليه‌السلام ( 1) محمد : 20. إِبْراهِيمُ بَنِيهِ وَيَعْقُوبُ يا بَنِيَّ إِنَّ اللهَ اصْطَفى لَكُمُ الدِّينَ فَلا تَمُوتُنَّ إِلاَّ وَأَنْتُمْ مُسْلِمُونَ (132) أَمْ كُنْتُمْ شُهَداءَ إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ إِذْ قالَ لِبَنِيهِ ما تَعْبُدُونَ مِنْ بَعْدِي ( إِبْراهِيمُ بَنِيهِ ) أولاده ، وخصهم بالذكر ، مع أن دعوة إبراهيم عليه‌السلام كانت عامة ، إشارة إلى لزوم دعوة الأهل بصورة خاصة إلى الحق ، كما قال سبحانه ( قُوا أَنْفُسَكُمْ وَأَهْلِيكُمْ ناراً ) (1) ( وَ ) وصى بها ( يَعْقُوبُ ) حفيد إبراهيم من إسحاق ، بنيه أيضا وخص يعقوب لأنه جد اليهود ، وكانت الوصية ( يا بَنِيَ ) أي يا أبنائي ، فهو جمع ابن ، وأصله بنيني ( إِنَّ اللهَ اصْطَفى ) أي اختار ( لَكُمُ الدِّينَ ) حتى تكونوا متدينين ، ومعنى اختار الله الدين لهم ، أنه سبحانه أعطاهم الدين ، وأراد ذلك منهم مقابل بعض الأمم الوحشية الذين تركوا وشأنهم ، فلم تبلغهم دعوة الأنبياء ( فَلا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ ) أي لا تتركوا الإسلام ، فيصادفكم الموت على تركه ، وإنما خص الموت ، لأنه لو كان غير مسلم قبل ذلك ، ثم أسلم ومات مسلما لم يكن عليه بأس.` },
            { text: "أَمْ كُنتُمْ شُهَدَآءَ إِذْ حَضَرَ يَعْقُوبَ ٱلْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِنۢ بَعْدِى قَالُوا۟ نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ إِلَٰهًا وَٰحِدًا وَنَحْنُ لَهُۥ مُسْلِمُونَ", tafsir: `أيها المدعون إن الأنبياء كانوا يهودا أو نصارى ، فإن اليهود كانوا يقولون أن يعقوب النبي عليه‌السلام أوصى بنيه باليهودية ، فأنكر الله تعالى عليهم ذلك بأنكم لم تكونوا حضورا ( إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ ) واقترب من الوفاة ( إِذْ قالَ لِبَنِيهِ ما تَعْبُدُونَ مِنْ بَعْدِي ) على طريقة الاستفهام التقريري ( 1) التحريم : 7. قالُوا نَعْبُدُ إِلهَكَ وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ إِلهاً واحِداً وَنَحْنُ لَهُ مُسْلِمُونَ (133) تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَها ما كَسَبَتْ وَلَكُمْ ما كَسَبْتُمْ وَلا تُسْئَلُونَ عَمَّا كانُوا يَعْمَلُونَ (134) وَقالُوا كُونُوا هُوداً أَوْ نَصارى تَهْتَدُوا قُلْ ( قالُوا نَعْبُدُ إِلهَكَ وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ ) إبراهيم جد يعقوب وإسماعيل عمه وإسحاق أبوه ، وقدم إسماعيل لأنه كان الأكبر سنا ، والأعلى منزلة ، وسمى العم أبا تغليبا ، ولأن العرب تسمي العم أبا والخالة أما ( إِلهاً واحِداً ) بغير شريك ( وَنَحْنُ لَهُ مُسْلِمُونَ ) فكان دينهم الإسلام ، والإسلام هو دين جميع الأنبياء عليهم‌السلام ، لأن معناه التسليم لله في أوامره ونواهيه ونفي الله سبحانه كون دين الأنبياء اليهودية أو النصرانية ، يراد به نفيها بالمعنى المتداول عند أهل الكتاب ، وإلا فلا يهم الاسم ، كما لا يخفى. [135] ثم بين الله حقيقة هي أن الأمة الماضية ليست تهمكم ، أيها المعاصرون للرسول صلى‌الله‌عليه‌وآله‌وسلم وإنما المهم أعمالكم ، فكيف كانت تلك الأمم ، فإنها قد ذهبت وفنت ( تِلْكَ ) أي إبراهيم وأولاده عليهم‌السلام ( أُمَّةٌ قَدْ خَلَتْ ) أي ذهبت ومضت ( لَها ما كَسَبَتْ ) فإن أعمالها ترتبط بها لا بكم ( وَلَكُمْ ما كَسَبْتُمْ ) فإن أعمالكم ترتبط بكم لا بهم ( وَلا تُسْئَلُونَ ) أنتم ( عَمَّا كانُوا يَعْمَلُونَ ) فأصلحوا أعمالكم.` },
            { text: "تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ", tafsir: `(أَمْ كُنْتُمْ شُهَداءَ) أيها المدعون إن الأنبياء كانوا يهودا أو نصارى، فإن اليهود كانوا يقولون أن يعقوب النبي عليه السلام أوصى بنيه باليهودية، فأنكر الله تعالى عليهم ذلك بأنكم لم تكونوا حضورا (إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ) واقترب من الوفاة (إِذْ قالَ لِبَنِيهِ ما تَعْبُدُونَ مِنْ بَعْدِي) على طريقة الاستفهام التقريري (قالُوا نَعْبُدُ إِلهَكَ وَإِلهَ آبائِكَ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ) إبراهيم جد يعقوب وإسماعيل عمه وإسحاق أبوه، وقدم إسماعيل لأنه كان الأكبر سنا، والأعلى منزلة، وسمى العم أبا تغليبا، ولأن العرب تسمي العم أبا والخالة أما (إِلهاً واحِداً) بغير شريك (وَنَحْنُ لَهُ مُسْلِمُونَ) فكان دينهم الإسلام، والإسلام هو دين جميع الأنبياء عليهم السلام، لأن معناه التسليم لله في أوامره ونواهيه ونفي الله سبحانه كون دين الأنبياء اليهودية أو النصرانية، يراد به نفيها بالمعنى المتداول عند أهل الكتاب، وإلا فلا يهم الاسم، كما لا يخفى.` },
            { text: "وَقَالُوا۟ كُونُوا۟ هُودًا أَوْ نَصَٰرَىٰ تَهْتَدُوا۟ قُلْ بَلْ مِلَّةَ إِبْرَٰهِـۧمَ حَنِيفًا وَمَا كَانَ مِنَ ٱلْمُشْرِكِينَ", tafsir: `أي قالت اليهود كونوا يهودا وقالت النصارى كونوا نصارى ( تَهْتَدُوا ) للحق وترشدوا ( قُلْ ) يا رسول بَلْ مِلَّةَ إِبْراهِيمَ حَنِيفاً وَما كانَ مِنَ الْمُشْرِكِينَ (135) قُولُوا آمَنَّا بِاللهِ وَما أُنْزِلَ إِلَيْنا وَما أُنْزِلَ إِلى إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطِ وَما أُوتِيَ مُوسى وَعِيسى وَما أُوتِيَ النَّبِيُّونَ مِنْ رَبِّهِمْ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ الله صلى‌الله‌عليه‌وآله‌وسلم ( بَلْ ) نتبع ( مِلَّةَ ) أي دين ( إِبْراهِيمَ ) الصافي من شوائب اليهودية والنصرانية ، وإنما هي الإسلام المصفى ، وإن كان فرق بين الإسلام وبين دين إبراهيم عليه‌السلام في بعض الخصوصيات التشريعية ، فالمراد نفي النصرانية واليهودية ( حَنِيفاً ) أي مستقيما عن الاعوجاج ( وَما كانَ ) إبراهيم ( مِنَ الْمُشْرِكِينَ ) كما أنتم أيها اليهود والنصارى مشركون ، إذ تقولون عزير ابن الله ، أو المسيح ابن الله ، وعلى هذا فالمراد بإتباع ملة إبراهيم عليه‌السلام إتباعها في التوحيد.` },
            { text: "قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ", tafsir: `أيها المسلمون ، ما يجب عليكم أن تعتقدوا به ، وما هي خلاصة الأديان السابقة واللاحقة ، التي تعين زيف العقائد النصرانية واليهودية وغيرهما ( آمَنَّا بِاللهِ وَ ) آمنا ب ( ما أُنْزِلَ إِلَيْنا ) من القرآن الحكيم ( وَما أُنْزِلَ إِلى إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطِ ) أحفاد يعقوب فإن كثيرا منهم كانوا أنبياء عليهم‌السلام نزلت عليهم الصحف ( وَ ) آمنا ب ( ما أُوتِيَ مُوسى وَعِيسى وَ ) آمنا ب ( ما أُوتِيَ النَّبِيُّونَ ) قاطبة ( مِنْ رَبِّهِمْ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ ) أي من الأنبياء عليهم‌السلام ، فإنا نعترف بالجميع ( وَنَحْنُ لَهُ ) أي لله سبحانه ( مُسْلِمُونَ ) فإن دين الأنبياء ، عليهم‌السلام كلهم يتلخص في أصول وفروع فَإِنْ آمَنُوا بِمِثْلِ ما آمَنْتُمْ بِهِ فَقَدِ اهْتَدَوْا وَإِنْ تَوَلَّوْا فَإِنَّما هُمْ فِي شِقاقٍ فَسَيَكْفِيكَهُمُ اللهُ وَهُوَ السَّمِيعُ الْعَلِيمُ (137) صِبْغَةَ اللهِ وَمَنْ أَحْسَنُ مِنَ اللهِ صِبْغَةً وَنَحْنُ لَهُ عابِدُونَ (138) وأخلاق فالأصول : التوحيد ، والعدل ، والنبوة ، والإمامة ، والمعاد ، فإن كل نبي كان يصدّق من سبقه ويبشّر بمن يلحقه ، كما إن الإمامة بمعنى الوصاية ، فإن كل نبي كان له أوصياء ، والفروع : الصلاة والصوم والزكاة وما أشبه من العبادات ، وأحكام المعاملات ـ بالمعنى الأعم ـ وكل الأديان كانت مشتركة فيها مع تفاوت يسير حسب اقتضاء الزمان والأمة ، فمثلا كان صوم الصمت في بعض الأمم وليس في الإسلام وهكذا ، والأخلاق : الصدق والأمانة ، والوفاء ، والحياء ، وما أشبه وكلها فطريات نفسيه كانت الأنبياء عليهم‌السلام تأمر بها وتنهى عن أضدادها.` },
            { text: "فَإِنْ ءَامَنُوا۟ بِمِثْلِ مَآ ءَامَنتُم بِهِۦ فَقَدِ ٱهْتَدَوا۟ وَّإِن تَوَلَّوْا۟ فَإِنَّمَا هُمْ فِى شِقَاقٍ فَسَيَكْفِيكَهُمُ ٱللَّهُ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ", tafsir: `أي آمن غير المسلمين من سائر الأديان والفرق ( بِمِثْلِ ما آمَنْتُمْ بِهِ ) أي كما تؤمنون أنتم أيها المسلمون ( فَقَدِ اهْتَدَوْا ) إلى الحق ( وَإِنْ تَوَلَّوْا ) عن مثل هذا الإيمان ، ولزموا طريقتهم المنحرفة ( فَإِنَّما هُمْ فِي شِقاقٍ ) أي في خلاف فهم في شق وأنتم في شق ( فَسَيَكْفِيكَهُمُ اللهُ ) فإن الله يكفيك يا رسول الله وينصرك عليهم ( وَهُوَ السَّمِيعُ ) كلامهم ( الْعَلِيمُ ) بأعمالكم ونواياكم. [139] اتبعوا ( صِبْغَةَ اللهِ ) واصبغوا أنفسكم بها ، وهي الإسلام ، فإن كل طريقة يتبعها الإنسان لون له ، لكنه لون غير محسوس ، تشبيها بالألوان المحسوسة ( وَمَنْ أَحْسَنُ مِنَ اللهِ صِبْغَةً ) وهذا استفهام إنكاري ، أي لا أحد أحسن من الله صبغة ودينا ( وَنَحْنُ ) المسلمون ( لَهُ عابِدُونَ ) قُلْ أَ تُحَاجُّونَنا فِي اللهِ وَهُوَ رَبُّنا وَرَبُّكُمْ وَلَنا أَعْمالُنا وَلَكُمْ أَعْمالُكُمْ وَنَحْنُ لَهُ مُخْلِصُونَ (139) أَمْ تَقُولُونَ إِنَّ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطَ كانُوا هُوداً أَوْ نَصارى لا لغيره من الشركاء الذين أنتم تعبدونها مع الله ، أو من دون الله ، وربما يقال إن وجه التسمية ب ـ « الصبغة » أن النصارى كانوا يصبغون أولادهم بماء أصفر يعمدونهم فيه ، والآية من المشابهة كقوله سبحانه ( تَعْلَمُ ما فِي نَفْسِي وَلا أَعْلَمُ ما فِي نَفْسِكَ ) (1) .` },
            { text: "صِبْغَةَ ٱللَّهِ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ صِبْغَةً وَنَحْنُ لَهُۥ عَٰبِدُونَ", tafsir: `(فَإِنْ آمَنُوا) أي آمن غير المسلمين من سائر الأديان والفرق (بِمِثْلِ ما آمَنْتُمْ بِهِ) أي كما تؤمنون أنتم أيها المسلمون (فَقَدِ اهْتَدَوْا) إلى الحق (وَإِنْ تَوَلَّوْا) عن مثل هذا الإيمان، ولزموا طريقتهم المنحرفة (فَإِنَّما هُمْ فِي شِقاقٍ) أي في خلاف فهم في شق وأنتم في شق (فَسَيَكْفِيكَهُمُ اللهُ) فإن الله يكفيك يا رسول الله وينصرك عليهم (وَهُوَ السَّمِيعُ) كلامهم (الْعَلِيمُ) بأعمالكم ونواياكم.` },
            { text: "قُلْ أَتُحَآجُّونَنَا فِى ٱللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَآ أَعْمَٰلُنَا وَلَكُمْ أَعْمَٰلُكُمْ وَنَحْنُ لَهُۥ مُخْلِصُونَ", tafsir: `يا رسول الله لهؤلاء اليهود والنصارى وغيرهم ( أَ تُحَاجُّونَنا ) أي تباحثون معنا ( فِي ) دين ( اللهِ ) وإنه لم أنسخ أديانكم ، ولم أختر من العرب رسولا ، ولم أفعل كذا وكذا ؟ ( وَهُوَ رَبُّنا وَرَبُّكُمْ ) أي أن الله ليس ربا لكم فقط حتى يكون معكم وحدكم إلى الأبد ( وَلَنا أَعْمالُنا وَلَكُمْ أَعْمالُكُمْ ) فليس عملنا غير منظور إليه عند الله ، وعملكم منظور إليه ، كما كانوا يزعمون قائلين نحن شعب الله المختار ، ونحن أبناء الله وأودائه ( وَنَحْنُ لَهُ مُخْلِصُونَ ) إذ لا نشرك به أحدا بخلافكم حيث جعلتم له شريكا.` },
            { text: "أَمْ تَقُولُونَ إِنَّ إِبْرَٰهِـۧمَ وَإِسْمَٰعِيلَ وَإِسْحَٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطَ كَانُوا۟ هُودًا أَوْ نَصَٰرَىٰ قُلْ ءَأَنتُمْ أَعْلَمُ أَمِ ٱللَّهُ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَٰدَةً عِندَهُۥ مِنَ ٱللَّهِ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ", tafsir: `تباحثون معنا في أمر الأنبياء عليهم‌السلام و ( تَقُولُونَ إِنَّ إِبْراهِيمَ وَإِسْماعِيلَ وَإِسْحاقَ وَيَعْقُوبَ وَالْأَسْباطَ ) أحفاد يعقوب الذين كانوا أنبياء عليهم‌السلام ( كانُوا هُوداً ) أي يهودا ( أَوْ نَصارى ) وهذا اشتباه منهم إذ اليهودية والنصرانية ، تولدتا بعد إبراهيم عليه‌السلام ، فكيف يكون إبراهيم ( 1) المائدة : 117. قُلْ أَ أَنْتُمْ أَعْلَمُ أَمِ اللهُ وَمَنْ أَظْلَمُ مِمَّنْ كَتَمَ شَهادَةً عِنْدَهُ مِنَ اللهِ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (140) تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَها ما كَسَبَتْ وَلَكُمْ ما كَسَبْتُمْ وَلا تُسْئَلُونَ عَمَّا كانُوا يَعْمَلُونَ (141) أحدهما ، كما قال سبحانه ( وَما أُنْزِلَتِ التَّوْراةُ وَالْإِنْجِيلُ إِلَّا مِنْ بَعْدِهِ ) (1) ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم لهؤلاء المدعين بيهودية هؤلاء الأنبياء ، أو نصرانيتهم ( أَ أَنْتُمْ أَعْلَمُ أَمِ اللهُ ) فالله سبحانه يقول لم يكونوا يهودا ولا نصارى ، وأنتم تقولون كانوا ( وَمَنْ أَظْلَمُ مِمَّنْ كَتَمَ شَهادَةً عِنْدَهُ مِنَ اللهِ ) أي لا أحد أظلم ممن يكتم الشهادة التي عنده من الله سبحانه ، فإن اليهود كانوا يكتمون ما أنزل إليهم من البينات والهدى حول الأنبياء السابقين وحول نبي الإسلام ( وَمَا اللهُ ) أي ليس الله ( بِغافِلٍ عَمَّا تَعْمَلُونَ ) فإنه يعلم أعمالكم التي منها كتمانكم للشهادة ، ثم يجازيكم عليها.` },
            { text: "تِلْكَ أُمَّةٌ قَدْ خَلَتْ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ وَلَا تُسْـَٔلُونَ عَمَّا كَانُوا۟ يَعْمَلُونَ", tafsir: `الأنبياء عليهم‌السلام وما كانوا يعملون ويتدينون لا يرتبطون بكم أيها المعاصرون للرسول ، فإنها ( أُمَّةٌ قَدْ خَلَتْ ) ومضت ( لَها ما كَسَبَتْ ) من الأعمال والأفعال ( وَلَكُمْ ما كَسَبْتُمْ ) من الخير والشر ( وَلا تُسْئَلُونَ ) أنتم ( عَمَّا كانُوا يَعْمَلُونَ ) فلم هذه المباحثة والمحاجة والمجادلة. ( 1) آل عمران : 66. تقريب القران الى الأذهان من آية ( 143) إلى ( 253) بسم الله الرّحمن الرّحيم الحمد لله رب العالمين ، والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين. سَيَقُولُ السُّفَهاءُ مِنَ النَّاسِ ما وَلاَّهُمْ عَنْ قِبْلَتِهِمُ الَّتِي كانُوا عَلَيْها قُلْ لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ يَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ (142) وَكَذلِكَ جَعَلْناكُمْ أُمَّةً وَسَطاً لِتَكُونُوا` },
            { text: "سَيَقُولُ ٱلسُّفَهَآءُ مِنَ ٱلنَّاسِ مَا وَلَّىٰهُمْ عَن قِبْلَتِهِمُ ٱلَّتِى كَانُوا۟ عَلَيْهَا قُل لِّلَّهِ ٱلْمَشْرِقُ وَٱلْمَغْرِبُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `جمع سفيه ، وهو الغر والجاهل ، وناقص العقل ( مِنَ النَّاسِ ما وَلَّاهُمْ ) أي أيّ شيء صرف المسلمون ( عَنْ قِبْلَتِهِمُ ) السابقة ( الَّتِي كانُوا عَلَيْها ) يتوجهون في صلاتهم ، وهي بيت المقدس ، فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم والمسلمون كانوا يصلون إلى بيت المقدس ، وهو قبلة اليهود ، ثم في المدينة حولت القبلة إلى الكعبة ، وكان السبب الظاهر لذلك أن اليهود عابوا النبي بأنه يصلي إلى قبلتهم ، فحوله الله عنها إلى الكعبة ، فأخذ اليهود يهرجون حول تحويل القبلة ( قُلْ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( لِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ ) فمتى شاء وجه عبيده إلى حيث يشاء ، وليست القبلة احتكارا حتى لا يمكن تحويلها ( يَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ ) وكما كان الصراط المستقيم قبلا بيت المقدس حال التوجه ، كذلك صار الصراط المستقيم ، فعلا الكعبة.` },
            { text: "وَكَذَٰلِكَ جَعَلْنَٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمْ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ", tafsir: `أي كما أن لله المشرق والمغرب ، وأنه لا مناقشة في ذلك ( جَعَلْناكُمْ ) أيها المسلمون ، وفي التأويل ، إن المراد بالخطاب الأئمة عليهم‌السلام ( أُمَّةً وَسَطاً ) متوسطا ، والإطلاق وإن كان يفيد الوسطية في كل شيء في العقيدة ، فلا جمود ولا إلجاء ، وفي المكان فهم متوسطون بين شرق الأرض وغربها ، وفي التشريع ، فليس ناقصا ولا مغاليا ، وهكذا إلا أن ظاهر قوله سبحانه بعد ذلك ( لِتَكُونُوا شُهَداءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيداً وَما جَعَلْنَا الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْها إِلاَّ لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ مِمَّنْ يَنْقَلِبُ عَلى عَقِبَيْهِ شُهَداءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيداً ) يفيد أن المراد بالتوسط الوسيطة بين الرسول وبين سائر الناس ، فالأمة تأخذ من الرسول ـ ويشهد الرسول عليهم بأنهم أخذوا منه ، حتى لا يقولوا ما عرفنا ـ وسائر الناس يأخذون من الأمة ـ وتشهد الأمة عليهم بأنهم أخذوا منها ، حتى لا يقول الناس لم نعرف ـ وهذا هو الظاهر من « لام » العلة في قوله « لتكونوا .. ويكون » ولعل ارتباط هذه الآية بما سبقها من حكم القبلة ، وما لحقها بيان أن المسلمين لهم مكان القيادة ، لأنهم الآخذون عن الرسول المبلغون للناس فالذي ينبغي أن تكون لهم سمة خاصة في شرائعهم ، حتى لا يرمون بالذيلية ، والإتباع لقبلة الآخرين ، ثم رجع السياق إلى حكم القبلة فقال سبحانه ( وَما جَعَلْنَا الْقِبْلَةَ الَّتِي كُنْتَ عَلَيْها ) وهي بيت المقدس الذي كان النبي صلى‌الله‌عليه‌وآله‌وسلم يتوجه نحوه في الصلاة ، طيلة كونه في مكة المكرمة ، ومدة بعد الهجرة ( إِلَّا لِنَعْلَمَ مَنْ يَتَّبِعُ الرَّسُولَ مِمَّنْ يَنْقَلِبُ عَلى عَقِبَيْهِ ) معنى « لنعلم » أن يتحقق علمنا في الخارج ، بأن يظهر المتبع من المخالف ، فإنه قد يقال لنعلم ، ويراد به حصول العلم للمتكلم ، وقد يقال لنعلم ، والمراد به وقوع المعلوم في الخارج ، وفي بعض التفاسير أن قوما ارتدوا على أدبارهم لما حولت القبلة (1) ، فظهر ( 1) مجمع البيان : ص 418. وَإِنْ كانَتْ لَكَبِيرَةً إِلاَّ عَلَى الَّذِينَ هَدَى اللهُ وَما كانَ اللهُ لِيُضِيعَ إِيمانَكُمْ إِنَّ اللهَ بِالنَّاسِ لَرَؤُفٌ رَحِيمٌ (143) قَدْ نَرى إنهم لم يكونوا يتبعون الرسول صلى‌الله‌عليه‌وآله‌وسلم حقيقة وإنما حسب الأهواء ، والعقب مؤخر القدم ، والمعنى التشبيه لمن يرتد كافرا ، بمن يرجع القهقرى ( وَإِنْ كانَتْ ) مفارقة القبلة الأولى إلى قبلة أخرى ( لَكَبِيرَةً ) إذ هو خرق لاعتياد قديم متركز ( إِلَّا عَلَى الَّذِينَ هَدَى اللهُ ) إياهم بأن قوى قلوبهم بالإيمان ( وَما كانَ اللهُ لِيُضِيعَ إِيمانَكُمْ ) أيها المسلمون الراسخون الذين اتبعتم النبي صلى‌الله‌عليه‌وآله‌وسلم ، وهذا تقدير لهم في ثباتهم ، ووعد لهم في الجزاء على إيمانهم الكامل ، ويحتمل أن يكون جوابا عن سؤال وقع من بعضهم ، وهو إنه كيف تكون حال صلواتهم السابقة التي صلوها إلى بيت المقدس ، وإن كان الظاهر من كلمة « إيمان » المعنى الأول ( إِنَّ اللهَ بِالنَّاسِ لَرَؤُفٌ رَحِيمٌ ) فلا يضيع أتعابهم وأعمالهم. [145] وبعد ما بين الحكم ، وأن القبلة تحولت ، بيّن الله سبحانه قصة التحويل ، فإنها كالعلة للحكم المتقدم ، والعلة دائما تأتي متأخرة في الكلام ، وإن كانت سابقة في التحقيق ، كما يقال إنه إنسان طيب لأن تربيته حسنة ( قَدْ نَرى ) « قد » هنا للتحقيق نحو ( قَدْ يَعْلَمُ اللهُ ) (1) وإن كان الغالب في « قد » الداخلة على المضارع ، أن تكون بمعنى التقليل ، ولعل سر دخولها ، إشراب الفعل معنى التقليل ، حيث لا يريد المتكلم ( 1) النور : 64. تَقَلُّبَ وَجْهِكَ فِي السَّماءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضاها فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ وَإِنَّ الَّذِينَ أُوتُوا الْكِتابَ إظهار العلم بالبت ، مثله ( وَإِنَّا أَوْ إِيَّاكُمْ لَعَلى هُدىً ) (1) ( تَقَلُّبَ وَجْهِكَ ) يا رسول الله ( فِي السَّماءِ ) أي في ناحية السماء ، فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم كان يقلب وجهه في أطراف السماء ، فينتظر الوحي حول القبلة ، وإن اليهود عيروه صلى‌الله‌عليه‌وآله‌وسلم قائلين له أنك تابع لقبلتنا فلما كان في بعض الليل خرج صلى‌الله‌عليه‌وآله‌وسلم ، يقلب وجهه في آفاق السماء ، فلما أصبح صلى الغداة ، فلما صلى من الظهر ركعتين ، جاء جبرائيل عليه‌السلام بهذه الآية ، ثم أخذ بيده فحول وجهه إلى الكعبة ، وحول من خلفه وجوههم ، حتى قام الرجال مقام النساء ، والنساء مقام الرجال ( فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضاها ) إذ الرسول كان يحب الكعبة التي هي بناء جده إبراهيم عليه‌السلام وعندها موطنه ( فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ ) الشطر الجزء ، أي حول وجهك نحو جزء من المسجد الحرام ، والمسجد لكونه محيطا بالكعبة يكون المتوجه إليه متوجها إليها إذا كان من بعيد ( وَحَيْثُ ما كُنْتُمْ ) أيها المسلمون ( فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ) وذكر « الوجه » في المقامين ، لأنه الشيء الذي يتوجه به في جسد الإنسان ( وَإِنَّ الَّذِينَ أُوتُوا الْكِتابَ ) من اليهود والنصارى الذين يستشكلون عليكم قائلين إن كانت القبلة ( 1) سبأ : 25. لَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ وَمَا اللهُ بِغافِلٍ عَمَّا يَعْمَلُونَ (144) وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتابَ بِكُلِّ آيَةٍ ما تَبِعُوا قِبْلَتَكَ وَما أَنْتَ بِتابِعٍ قِبْلَتَهُمْ وَما بَعْضُهُمْ بِتابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ اتَّبَعْتَ أَهْواءَهُمْ مِنْ بَعْدِ ما جاءَكَ مِنَ الْعِلْمِ السابقة حقا ، فهذه باطلة ، وإن كانت هذه حقا ، فتوجهكم في السابق إلى بيت المقدس باطل ( لَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِنْ رَبِّهِمْ ) أي تحويل القبلة أو هذه القبلة حق من قبل الله ، فإن الله سبحانه يعبده عباده كيف يشاء ، فمن الجائز أن يعبد الأمة بتشريع إلى مدة ، ثم يعبدهم بتشريع آخر ( وَمَا اللهُ بِغافِلٍ عَمَّا يَعْمَلُونَ ) أي يعمل أهل الكتاب من الإرجاف وبث الأباطيل حول تحويل القبلة وسائر الأمور المرتبطة بالنبي صلى‌الله‌عليه‌وآله‌وسلم .` },
            { text: "قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِى ٱلسَّمَآءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَىٰهَا فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ وَإِنَّ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ لَيَعْلَمُونَ أَنَّهُ ٱلْحَقُّ مِن رَّبِّهِمْ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا يَعْمَلُونَ", tafsir: `` },
            { text: "وَلَئِنْ أَتَيْتَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَٰبَ بِكُلِّ ءَايَةٍ مَّا تَبِعُوا۟ قِبْلَتَكَ وَمَآ أَنتَ بِتَابِعٍ قِبْلَتَهُمْ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ وَلَئِنِ ٱتَّبَعْتَ أَهْوَآءَهُم مِّنۢ بَعْدِ مَا جَآءَكَ مِنَ ٱلْعِلْمِ إِنَّكَ إِذًا لَّمِنَ ٱلظَّٰلِمِينَ", tafsir: `يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( الَّذِينَ أُوتُوا الْكِتابَ ) من اليهود والنصارى ( بِكُلِّ آيَةٍ ) من الآيات الدالة على أن قبلتك حق ( ما تَبِعُوا قِبْلَتَكَ ) لأنهم معاندون ، والمعاند لا ينفع معه الدليل ( وَما أَنْتَ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( بِتابِعٍ قِبْلَتَهُمْ ) بعد ما تعلم أن قبلتهم منسوخة ، كقوله تعالى ( لا أَعْبُدُ ما تَعْبُدُونَ* وَلا أَنْتُمْ عابِدُونَ ما أَعْبُدُ ) (1) ( وَما بَعْضُهُمْ بِتابِعٍ قِبْلَةَ بَعْضٍ ) اليهود لا يتبعون قبلة النصارى ، والنصارى لا يتبعون قبلة اليهود ( وَلَئِنِ اتَّبَعْتَ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( أَهْواءَهُمْ ) في باب القبلة وسائر التشريعات ( مِنْ بَعْدِ ما جاءَكَ مِنَ الْعِلْمِ ) بأن ( 1) الكافرون : 3 ـ 4. إِنَّكَ إِذاً لَمِنَ الظَّالِمِينَ (145) الَّذِينَ آتَيْناهُمُ الْكِتابَ يَعْرِفُونَهُ كَما يَعْرِفُونَ أَبْناءَهُمْ وَإِنَّ فَرِيقاً مِنْهُمْ لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ (146) الْحَقُّ مِنْ رَبِّكَ فَلا تَكُونَنَّ مِنَ الْمُمْتَرِينَ (147) طريقتهم باطلة ( إِنَّكَ إِذاً لَمِنَ الظَّالِمِينَ ) وهذه الجملة ، وإن كانت موجهة إلى الرسول ، لكن المقصود منها العموم ، ولا تنافي العصمة ، فإن الاشتراط يلائم المحال ، كقوله تعالى ( إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) (1) وقد تقرر في المنطق أن صدق الشرطية إنما هو بوجود العلية ونحوها ، لا بصدق الطرفين.` },
            { text: "ٱلَّذِينَ ءَاتَيْنَٰهُمُ ٱلْكِتَٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ", tafsir: `من اليهود والنصارى ( يَعْرِفُونَهُ ) أي الرسول ، أو هذا الحكم ، أعني كون تغيير القبلة بأمر الله سبحانه ، وإن كان الأول أقرب إلى سياق التشبيه ( كَما يَعْرِفُونَ أَبْناءَهُمْ وَإِنَّ فَرِيقاً مِنْهُمْ ) ممن لم يؤمن بالرسول ( لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ ) فليس عذر هؤلاء جهلهم ، حتى يرجى زواله ، وإنما العناد الذي لا علاج له.` },
            { text: "ٱلْحَقُّ مِن رَّبِّكَ فَلَا تَكُونَنَّ مِنَ ٱلْمُمْتَرِينَ", tafsir: `يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ، أي هذا هو الحق من عند الله ( فَلا تَكُونَنَّ مِنَ الْمُمْتَرِينَ ) أي الشاكين فيه ، فإن المحق إذا كثرت عليه التهجمات ورمي بأنه على غير حق ، يكاد يشك فيه ، ولذا يثبت الله الرسول صلى‌الله‌عليه‌وآله‌وسلم ، كما قال تعالى ( وَلَوْ لا أَنْ ثَبَّتْناكَ لَقَدْ كِدْتَ تَرْكَنُ إِلَيْهِمْ شَيْئاً قَلِيلاً ) (2) . ( 1) الزخرف : 82. ( 2) الإسراء : 75. وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيها فَاسْتَبِقُوا الْخَيْراتِ أَيْنَ ما تَكُونُوا يَأْتِ بِكُمُ اللهُ جَمِيعاً إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (148) وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ` },
            { text: "وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ أَيْنَ مَا تَكُونُوا۟ يَأْتِ بِكُمُ ٱللَّهُ جَمِيعًا إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `أي لكل أمة من الأمم طريقة ( هُوَ ) أي الله سبحانه ( مُوَلِّيها ) أي أمرهم بالتوجه إليها ، فلا غرابة أن يكون للمسلمين وجهة خاصة في قبلتهم ( فَاسْتَبِقُوا ) أي سارعوا إلى ( الْخَيْراتِ ) تنافسوا فيها ، فإن الله موليكم هذه الطرائق ، ولا تبقوا جامدين على طريقة منسوخة ، فإن ذلك انصراف عن الخير إلى الشر ، ومن المحتمل أن يكون « هو » راجعا إلى « كل » أي لكل فرد أو أمة ، طريقة في العمل والتفكير فذلك الشخص مولي وموجه نفسه إياها ، فليكن هم كل فريق وفرد أن يسابق غيره في الخيرات ( أَيْنَ ما تَكُونُوا ) من بقاع الأرض ( يَأْتِ بِكُمُ اللهُ جَمِيعاً ) يوم القيامة ، حتى يجازيكم على أعمالكم ( إِنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) فيتمكن من جمعكم ، ولا يفوته شيء [150] كان لتحويل القبلة نحو الكعبة أسباب وعلل ، العلة الأولى : رغبة الرسول صلى‌الله‌عليه‌وآله‌وسلم في أن تحول القبلة لما عيرته اليهود ، العلة الثانية : أن التحويل كان للحق ، وأن يكون للمسلمين ميزة خاصة يمتازون بها عن سائر الأمم ، حتى في اتجاه الصلاة ، العلة الثالثة : أن التحويل كان لقطع حجة الناس ، الذين كانوا يتعجبون من كون المسلمين ، يدعون دينا جديدا ، ومع ذلك يتوجهون إلى قبلة بني إسرائيل ، وتبعا لهذه العلل ، تكرر الأمر بالتوجه إلى المسجد الحرام ، وقال سبحانه ( وَمِنْ حَيْثُ خَرَجْتَ ) للسفر من البلاد ( فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ ) وَإِنَّهُ لَلْحَقُّ مِنْ رَبِّكَ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ (149) وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ لِئَلاَّ يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلاَّ الَّذِينَ ظَلَمُوا مِنْهُمْ فَلا تَخْشَوْهُمْ وَاخْشَوْنِي فإنه قبلة في السفر كما هو قبلة في الحضر ، وفي هذا فائدة ثانية للتكرار ( وَإِنَّهُ ) أي توجيه الوجه نحو المسجد الحرام ( لَلْحَقُ ) الذي جاء ( مِنْ رَبِّكَ وَمَا اللهُ بِغافِلٍ عَمَّا تَعْمَلُونَ ) فمن أعرض عن هذه القبلة كان جزاءه سيئا ، ومن اتبعها كان جزاءه حسنا.` },
            { text: "وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَإِنَّهُۥ لَلْحَقُّ مِن رَّبِّكَ وَمَا ٱللَّهُ بِغَٰفِلٍ عَمَّا تَعْمَلُونَ", tafsir: `` },
            { text: "وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ ٱلْمَسْجِدِ ٱلْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا۟ وُجُوهَكُمْ شَطْرَهُۥ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ فَلَا تَخْشَوْهُمْ وَٱخْشَوْنِى وَلِأُتِمَّ نِعْمَتِى عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ", tafsir: `للسفر من البلاد ( فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرامِ ) هذا للسفر ( وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ) وهذه الآية ، جمع بين الآيتين السابقتين ( وَمِنْ حَيْثُ خَرَجْتَ ) ، الآية : 150 » ( وَحَيْثُ ما كُنْتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ) ، الآية : 145 » وقد عرفت إنه كرر لفائدة العلة المذكورة في الآية ( لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ ) أي إن تحويل القبلة ، إنما هو لنقطع احتجاج الناس عليكم حيث يقولون : كيف إن المسلمين يدعون إلى دين جديد وقبلتهم هي قبلة أهل الكتاب ( إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ ) فإن هؤلاء لا ينفعهم المنطق ، فالمعاند لا تفيده الحجة ( فَلا تَخْشَوْهُمْ وَاخْشَوْنِي ) فالخشية ، إنما تكون ممن بيده النفع والضر ، وهؤلاء ليس بيدهم شيء منهما ، وإنما كل ذلك بيد الله سبحانه ، ولا يخفى أن الاستثناء منقطع كقولك : إنما فعلت الفعلة الفلانية ليعرف الناس بالأمر ، إلا من يريد وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ (150) كَما أَرْسَلْنا فِيكُمْ رَسُولاً مِنْكُمْ يَتْلُوا عَلَيْكُمْ آياتِنا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتابَ وَالْحِكْمَةَ وَيُعَلِّمُكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ (151) العناد ( وَ ) بعد ذلك فتحويل القبلة إنما كان ( لِأُتِمَّ نِعْمَتِي عَلَيْكُمْ ) بتميزكم عن أهل الكتاب وقطع تعيير اليهود ، وإرجاعكم إلى بناء جدكم إبراهيم الذي هو إحياء لذكراكم ( وَلَعَلَّكُمْ تَهْتَدُونَ ) إلى الحق اهتداء كاملا ، فإن في تشريف الإنسان بشرف سببا لتقريبه إلى الهداية الكاملة. [152] وقد أتممنا النعمة عليكم بتحويل القبلة ( كَما ) أنعمنا عليكم قبل ذلك بنعمة عظمي ف ( أَرْسَلْنا فِيكُمْ ) أيها المسلمون ( رَسُولاً مِنْكُمْ ) لا من غيركم ، فاخترتكم لأن تكون رسالتي بيد واحد منكم ( يَتْلُوا عَلَيْكُمْ آياتِنا ) وقرآننا تلاوة ( وَيُزَكِّيكُمْ ) يطهركم من أدناس الجاهلية والقذارات الخلقية ، والنجاسات البدنية ـ بإرشاده إياكم إليها ـ ( وَيُعَلِّمُكُمُ الْكِتابَ ) ومن المعلوم أن التلاوة غير التعليم ، فرب تال غير معلم ، بالإضافة إلى أن التعليم فيه معنى التركيز والتثبيت ( وَالْحِكْمَةَ ) يرشدكم بمواضع الأشياء ومواقع الخطأ والصواب ، فالحكمة ـ كما عرفت ـ وضع كل شيء موضعه ( وَيُعَلِّمُكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ ) بصورة عامة ، فيشمل القصص والتواريخ المفيدة وأحوال الأنبياء ، وأحوال المعاد مما ينفعهم في دينهم ودنياهم. فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلا تَكْفُرُونِ (152) يا أَيُّهَا الَّذِينَ آمَنُوا اسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ إِنَّ اللهَ مَعَ الصَّابِرِينَ (153) وَلا تَقُولُوا لِمَنْ يُقْتَلُ فِي سَبِيلِ اللهِ أَمْواتٌ` },
            { text: "كَمَآ أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُوا۟ عَلَيْكُمْ ءَايَٰتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ ٱلْكِتَٰبَ وَٱلْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ", tafsir: `` },
            { text: "فَٱذْكُرُونِىٓ أَذْكُرْكُمْ وَٱشْكُرُوا۟ لِى وَلَا تَكْفُرُونِ", tafsir: `أيها المسلمون بالطاعة والعبادة ، وتنفيذ الأوامر ( أَذْكُرْكُمْ ) بالنعمة والإحسان والجنان ( وَاشْكُرُوا لِي ) بإظهار النعمة والحمد عليها ( وَلا تَكْفُرُونِ ) كفرا في الاعتقاد ، أو كفرا في العمل بأن لا تعملوا بأوامري.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ", tafsir: `في أموركم التي تريدونها سواء كانت تحت اختياركم ، أم لم تكن كالصحة والغنى ( بِالصَّبْرِ ) وتحمل النفس ، فإن كثيرا من الأمور تتنجز بعد حين ، فإذا صبر الإنسان تنجزت أموره ونعم براحة البال ، واطمئنان النفس ، وإذا لم يصبر جرى القدر ، وهو مضطرب البال كئيب ( وَالصَّلاةِ ) فإن الصلاة توجب توجه الإنسان إلى الله سبحانه ، والانصراف عن الدنيا مما يشع في النفس الهدوء والسكينة ، وعدم الاهتمام بمكاره الدنيا ( إِنَّ اللهَ مَعَ الصَّابِرِينَ ) باللطف والعناية والرحمة والأجر والثواب ، وهكذا يهذب الإنسان والأمة ويرشدهم إلى مهمتهم العظيمة ، ويمرّنهم على الصبر والتحمل ، ولذا يخطوا القرآن الحكيم خطوة أخرى معهم بعد الصبر والصلاة ، قائلا : إنكم لا بد وأن تتحملوا مشاق القيادة من القتل وسائر أنواع المصائب التي تتعرض لمن أراد الإصلاح والإرشاد ، ولذا يقول سبحانه :` },
            { text: "وَلَا تَقُولُوا۟ لِمَن يُقْتَلُ فِى سَبِيلِ ٱللَّهِ أَمْوَٰتٌۢ بَلْ أَحْيَآءٌ وَلَٰكِن لَّا تَشْعُرُونَ", tafsir: `فالميت من لا تأثير له بَلْ أَحْياءٌ وَلكِنْ لا تَشْعُرُونَ (154) وَلَنَبْلُوَنَّكُمْ بِشَيْءٍ مِنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِنَ الْأَمْوالِ وَالْأَنْفُسِ وَالثَّمَراتِ وَبَشِّرِ الصَّابِرِينَ (155) الَّذِينَ إِذا أَصابَتْهُمْ مُصِيبَةٌ قالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ راجِعُونَ (156) في الحياة ولا امتداد ، وهؤلاء ليسوا كذلك ( بَلْ أَحْياءٌ ) حياة واقعية في الدنيا بتأثيراتهم وامتداداتهم ، وفي الآخرة ، لأنهم في نعيم مقيم ، ( وَلكِنْ لا تَشْعُرُونَ ) أنتم بحياتهم ، إذ الحياة في نظركم الحس والحركة ، مع إنها معنى سطحي للحياة.` },
            { text: "وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ وَبَشِّرِ ٱلصَّٰبِرِينَ", tafsir: `أي نمتحنكم أيها المسلمون ( بِشَيْءٍ مِنَ الْخَوْفِ ) وكونه شيئا ، إما باعتبار أنه لا يمتد ، وإنما الخوف في زمان يسير ، وإما باعتبار أنه لا يبلغ الخوف ـ غالبا ـ أشده ( وَالْجُوعِ ) ولم يذكر العطش لأن الماء غالبا متوفر ( وَنَقْصٍ مِنَ الْأَمْوالِ ) المبذولة في الحرب ، أو ما ينهب منها في التصادم ، أو الضيق الاقتصادي ، أو ما أشبه ( وَ ) نقص من ( الْأَنْفُسِ ) ممن يقتل في سبيل الله ( وَ ) نقص من ( الثَّمَراتِ ) بسبب النهب ، أو الحصاد قبل أوانه من أجل الأعداء ، كما وقع في قصة الخندق حيث أمر النبي صلى‌الله‌عليه‌وآله‌وسلم المسلمين أن يحصدوها ، لئلا ينتفع بها المشركون ـ كما في بعض التواريخ ـ أو بأسباب أخر ( وَبَشِّرِ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( الصَّابِرِينَ ) في هذه المكاره.` },
            { text: "ٱلَّذِينَ إِذَآ أَصَٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ", tafsir: `أي إنا مملوكون له سبحانه ( وَإِنَّا إِلَيْهِ راجِعُونَ ) فهو مرجعنا ومعه حسابنا وجزاؤنا ، وفي هذه أُولئِكَ عَلَيْهِمْ صَلَواتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُولئِكَ هُمُ الْمُهْتَدُونَ (157) إِنَّ الصَّفا وَالْمَرْوَةَ مِنْ شَعائِرِ اللهِ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ الجملة تسلية للمصاب ، إذ اعتراف الإنسان بأن كل شيء له إنما هو لله ، يهوّن ذهاب بعضها ، فإن صاحب المال أخذه ، كما أن اعتقاد الشخص ، بأن الله هو الذي يجازي يهوّن الأمر ، فإن ما فقده سوف يعوّض ولذا من كرر هذه الجملة في المصيبة عارفا معناها متوجها إلى الله سبحانه ، في التسليم والرضا ، يجد برد الاطمئنان في قلبه.` },
            { text: "أُو۟لَٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ", tafsir: `والصلوات هي العطف ، فإن صلى بمعنى عطف ، وهي من الله التوجه بالبركة والإحسان ( وَرَحْمَةٌ ) ترحم في الدنيا والآخرة ( وَأُولئِكَ هُمُ الْمُهْتَدُونَ ) الذين اهتدوا إلى واقع الأمر مما ينفع دنياهم وعقباهم ، فبذلوا ما بذلوا في سبيل الله راضين مرضين. [159] وحيث ألمع سابقا إلى الجهاد ، أتى الإلماع إلى الحج ، فإنهما صنوان في التعداد والمشقة ـ في الجملة ـ فقال سبحانه ( إِنَّ الصَّفا وَالْمَرْوَةَ ) وهما جبلان قرب المسجد الحرام ( مِنْ شَعائِرِ اللهِ ) جمع شعيرة ، وهي مشتقة من اللباس الملتصق بشعر البدن ، فكل شيء مرتبط بشيء ارتباطا وثيقا يدل عليه يكون من شعائره ، فالمراد أن هذين الجبلين من الأمور المرتبطة بالله سبحانه ، حيث جعلهما محلا لعبادته بالسعي بينهما ( فَمَنْ حَجَّ الْبَيْتَ ) أي قصد البيت الحرام ، والحج القصد ( أَوِ اعْتَمَرَ ) والعمرة هي الزيارة أخذ من العمارة ، لأن فَلا جُناحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِما وَمَنْ تَطَوَّعَ خَيْراً فَإِنَّ اللهَ شاكِرٌ عَلِيمٌ (158) إِنَّ الَّذِينَ يَكْتُمُونَ ما أَنْزَلْنا مِنَ الْبَيِّناتِ الزائر يعمر المكان بزيارته ، والحج والعمرة عملان من أعمال الحج ( فَلا جُناحَ عَلَيْهِ أَنْ يَطَّوَّفَ بِهِما ) أي يسعى بينهما ، وإنما عبر ب « لا جناح » لأن المسلمين تحرجوا من الطواف بهما ظنا منهم أنه من عمل المشركين ، حيث كان على الصفا صنم يسمى « أساف » وعلى المروة صنم يسمى « نائلة » فهو ترخيص في مقام توهم الحصر ، ومن المعلوم أن الإباحة في مقام توهم الحصر ، والنهي في مقام توهم الوجوب ، لا يدلان على مفادهما الأولية ، لأنه لإثبات أصل الطرف الآخر ، لا خصوصيته الإباحية والتمويمية ( وَمَنْ تَطَوَّعَ خَيْراً ) أي أتى بخير من الأعمال والأفعال تطوعا ، والتطوع التبرع بالشيء من الطوع بمعنى الانقياد ( فَإِنَّ اللهَ شاكِرٌ ) لعملهم ومعنى شكره تقديره وجزائه للعامل ( عَلِيمٌ ) بأعمالهم ، فلا يفوته شيء منها. [160] لعل ارتباط هذه الآية بما ورد قبلها ، أن اليهود والنصارى لم يفعلوا مثل ما فعل الرسول صلى‌الله‌عليه‌وآله‌وسلم حول الصفا والمروة ، فالرسول أبطل كل شيء حول الحج ، وأقام كل حق فيه ، فالصفا والمروة ، حيث كانا حقا أثبتهما الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وإن ظن الناس أنهما من الباطل ، لكن أهل الكتاب حشروا كل ما أتى به الرسول صلى‌الله‌عليه‌وآله‌وسلم ـ مما عرفوه حقا ـ في زمرة الباطل ، ولذا صار الكلام السابق ، فاتحة للتعريض بهم ، فهو مثل أن يقول أحد أنا اعترفت بالحق ، لكنه لم يعترف بما علم من الحق ، والله أعلم بموارده ( إِنَّ الَّذِينَ يَكْتُمُونَ ما أَنْزَلْنا مِنَ الْبَيِّناتِ ) فيخفون الأدلة وَالْهُدى مِنْ بَعْدِ ما بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتابِ أُولئِكَ يَلْعَنُهُمُ اللهُ وَيَلْعَنُهُمُ اللاَّعِنُونَ (159) إِلاَّ الَّذِينَ تابُوا وَأَصْلَحُوا وَبَيَّنُوا فَأُولئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا التَّوَّابُ الرَّحِيمُ (160) إِنَّ الَّذِينَ كَفَرُوا وَماتُوا وَهُمْ كُفَّارٌ أُولئِكَ عَلَيْهِمْ لَعْنَةُ اللهِ وَالْمَلائِكَةِ وَالنَّاسِ أَجْمَعِينَ (161) الدالة على حقية الإسلام ، مما نزلت في الكتب السالفة ( وَالْهُدى مِنْ بَعْدِ ما بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتابِ ) أي يكتمون الهدى الذي يرونه ، وإن لم يكن منزلا وبيّنا ( أُولئِكَ يَلْعَنُهُمُ اللهُ ) يبعدهم عن الخير في الدنيا وفي الآخرة ، بتضييق الأمور عليهم هنا والعذاب هناك ( وَيَلْعَنُهُمُ اللَّاعِنُونَ ) الذين يأتي منهم اللعن من الناس والملائكة والجن.` },
            { text: "إِنَّ ٱلصَّفَا وَٱلْمَرْوَةَ مِن شَعَآئِرِ ٱللَّهِ فَمَنْ حَجَّ ٱلْبَيْتَ أَوِ ٱعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلْنَا مِنَ ٱلْبَيِّنَٰتِ وَٱلْهُدَىٰ مِنۢ بَعْدِ مَا بَيَّنَّٰهُ لِلنَّاسِ فِى ٱلْكِتَٰبِ أُو۟لَٰٓئِكَ يَلْعَنُهُمُ ٱللَّهُ وَيَلْعَنُهُمُ ٱللَّٰعِنُونَ", tafsir: `` },
            { text: "إِلَّا ٱلَّذِينَ تَابُوا۟ وَأَصْلَحُوا۟ وَبَيَّنُوا۟ فَأُو۟لَٰٓئِكَ أَتُوبُ عَلَيْهِمْ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ", tafsir: `منهم واتبعوا الحق وأظهروه ( وَأَصْلَحُوا ) ما فسد من عقائدهم وأعمالهم ( وَبَيَّنُوا ) للناس ما أنزله الله من الهدى والبينات ( فَأُولئِكَ أَتُوبُ عَلَيْهِمْ ) فالتوبة معناها الرجوع ، ورجوع الله بمعنى إعادة الإحسان والرحمة عليهم بعد انقطاعها عنهم بسبب كفرهم وكتمانهم ( وَأَنَا التَّوَّابُ ) أي كثير الرجوع ، فإن العاصي إذا عصى ألف مرة ورجع ألف مرة قبلت توبته ، إذا تاب توبة نصوحا ( الرَّحِيمُ ) بالعباد.` },
            { text: "إِنَّ ٱلَّذِينَ كَفَرُوا۟ وَمَاتُوا۟ وَهُمْ كُفَّارٌ أُو۟لَٰٓئِكَ عَلَيْهِمْ لَعْنَةُ ٱللَّهِ وَٱلْمَلَٰٓئِكَةِ وَٱلنَّاسِ أَجْمَعِينَ", tafsir: `ولم يتوبوا ( وَماتُوا وَهُمْ كُفَّارٌ ) بالعقائد الصحيحة ( أُولئِكَ عَلَيْهِمْ لَعْنَةُ اللهِ وَالْمَلائِكَةِ وَالنَّاسِ أَجْمَعِينَ ) فإن الكل يلعنون الظالم ، والكافر ظالم ، فإنه وإن لم يقصده اللاعن خالِدِينَ فِيها لا يُخَفَّفُ عَنْهُمُ الْعَذابُ وَلا هُمْ يُنْظَرُونَ (162) وَإِلهُكُمْ إِلهٌ واحِدٌ لا إِلهَ إِلاَّ هُوَ الرَّحْمنُ الرَّحِيمُ (163) إِنَّ فِي خَلْقِ السَّماواتِ وَالْأَرْضِ وَاخْتِلافِ اللَّيْلِ وَالنَّهارِ وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِما يَنْفَعُ النَّاسَ وَما أَنْزَلَ اللهُ مِنَ السَّماءِ مِنْ ماءٍ فَأَحْيا بِهِ الْأَرْضَ بالذات ، لكنه داخل في عموم اللعن.` },
            { text: "خَٰلِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ ٱلْعَذَابُ وَلَا هُمْ يُنظَرُونَ", tafsir: `أي في تلك اللعنة ، إذ لعنة الدنيا تتصل بلعنة الآخرة ( لا يُخَفَّفُ عَنْهُمُ الْعَذابُ ) إذ لا أمد لعذاب الله بالنسبة إلى الكافرين ( وَلا هُمْ يُنْظَرُونَ ) فلا ينظر أحد إليهم نظرة رحمة وإحسان ، أو لا يمهلون للاعتذار ، أو لا يؤخر عنهم العذاب. [164] ولما تقدم حال الكافر صار السياق لبيان التوحيد ، والأدلة على الوحدانية ( وَإِلهُكُمْ ) أيها الناس ( إِلهٌ واحِدٌ ) لا شريك له ( لا إِلهَ إِلَّا هُوَ ) الموصوف ب ( الرَّحْمنُ الرَّحِيمُ ) لا كما يصور الإله بعض الكتب السماوية من أنه إله انتقام وغضب وعذاب.` },
            { text: "وَإِلَٰهُكُمْ إِلَٰهٌ وَٰحِدٌ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحْمَٰنُ ٱلرَّحِيمُ", tafsir: `` },
            { text: "إِنَّ فِى خَلْقِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَٰفِ ٱلَّيْلِ وَٱلنَّهَارِ وَٱلْفُلْكِ ٱلَّتِى تَجْرِى فِى ٱلْبَحْرِ بِمَا يَنفَعُ ٱلنَّاسَ وَمَآ أَنزَلَ ٱللَّهُ مِنَ ٱلسَّمَآءِ مِن مَّآءٍ فَأَحْيَا بِهِ ٱلْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَآبَّةٍ وَتَصْرِيفِ ٱلرِّيَٰحِ وَٱلسَّحَابِ ٱلْمُسَخَّرِ بَيْنَ ٱلسَّمَآءِ وَٱلْأَرْضِ لَـَٔايَٰتٍ لِّقَوْمٍ يَعْقِلُونَ", tafsir: `بهذا النظام البديع والترتيب الرائع ( وَالْأَرْضِ ) بهذا الأسلوب المنظم المتكامل ( وَ ) في ( اخْتِلافِ اللَّيْلِ وَالنَّهارِ ) يأتي أحدهما عقب الأخر خليفة ، لتنظيم الحياة على الأرض بأجمل صورة ( وَ ) في ( الْفُلْكِ ) السفينة ( الَّتِي تَجْرِي فِي الْبَحْرِ بِما يَنْفَعُ النَّاسَ ) في أسفارهم وتجارتهم ( وَ ) في ( ما أَنْزَلَ اللهُ مِنَ السَّماءِ ) جهة العلو ( مِنْ ماءٍ ) ببيان « ما » ( فَأَحْيا بِهِ الْأَرْضَ ) بَعْدَ مَوْتِها وَبَثَّ فِيها مِنْ كُلِّ دَابَّةٍ وَتَصْرِيفِ الرِّياحِ وَالسَّحابِ الْمُسَخَّرِ بَيْنَ السَّماءِ وَالْأَرْضِ لَآياتٍ لِقَوْمٍ يَعْقِلُونَ (164) وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ اللهِ أَنْداداً يُحِبُّونَهُمْ بالإنبات ( بَعْدَ مَوْتِها ) أي جمودها وركودها ( وَبَثَ ) أي نشر وفرق ( فِيها ) أي في الأرض ( مِنْ كُلِّ دَابَّةٍ ) تدب وتتحرك على وجه الأرض ، وكلمة « بث » عطف على « أحيا » أي كان المطر سببا لإحياء الأرض ، وانتشار الحيوانات فيها ، إذ لو لا المطر لم يكن للحيوان ماء ، ولا طعام فيهلك ، ولم يبق له نسل ( وَ ) في ( تَصْرِيفِ الرِّياحِ ) أي صرفها ونقلها من مكان إلى مكان لتروح وتذهب بالأمراض والعفونات ، وتنقل السحاب من هنا إلى هناك ، ولو كانت الريح راكدة لم تنفع أي شيء ( وَ ) في ( السَّحابِ الْمُسَخَّرِ بَيْنَ السَّماءِ وَالْأَرْضِ ) فإنه بما يكونه من أطنان من الماء ، يبقى معلقا بين الجهتين ، ويسير إلى كل ناحية ( لَآياتٍ ) وعلامات دالة على الله ، ووحدته وسائر صفاته ( لِقَوْمٍ يَعْقِلُونَ ) ويعملون عقولهم في استفادة النتائج من المقدمات والمسبب عن الأسباب ، وينتقلون من العلم بالمعلول إلى العلم بالعلة.` },
            { text: "وَمِنَ ٱلنَّاسِ مَن يَتَّخِذُ مِن دُونِ ٱللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ ٱللَّهِ وَٱلَّذِينَ ءَامَنُوٓا۟ أَشَدُّ حُبًّا لِّلَّهِ وَلَوْ يَرَى ٱلَّذِينَ ظَلَمُوٓا۟ إِذْ يَرَوْنَ ٱلْعَذَابَ أَنَّ ٱلْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ ٱللَّهَ شَدِيدُ ٱلْعَذَابِ", tafsir: `أي بعضهم ( مَنْ يَتَّخِذُ مِنْ دُونِ اللهِ ) أي غير الله ( أَنْداداً ) جمع ند ، بمعنى الأشباه ، والمراد بذلك آلهة يجعلها شبيهة لله في أنه يعبدها ، وهي الأوثان ( يُحِبُّونَهُمْ ) أي يحب هؤلاء الناس كَحُبِّ اللهِ وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعاً وَأَنَّ اللهَ شَدِيدُ الْعَذابِ (165) إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا وَرَأَوُا الْعَذابَ تلك الآلهة ، وإنما أتى بجمع العاقل لكونها ردفت مع الله سبحانه ، والقاعدة تغليب الرديف على رديفه كقوله تعالى ( مَنْ يَمْشِي عَلى بَطْنِهِ ) (1) وقوله ( وَارْكَعِي مَعَ الرَّاكِعِينَ ) (2) ( كَحُبِّ اللهِ ) أي كحبهم لله ، أو حبا شبيها بما يستحق الله ، وعلى الأول ، فالمراد بهم المشركون الذين يعتقدون بالله ( وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلَّهِ ) من حب هؤلاء لأوثانهم ، فالمؤمنين حيث يعرفون أن كل خير من الله يحبونه حبا بالغا ( وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعاً ) يعني لو يرون هؤلاء المشركين يوم القيامة كون القوة جميعا لرأوا مضرة فعلهم ، وسوء عاقبة شركهم ، وحذف جواب لو ، تهويلا للأمر ، كما تقول لعدوك : لو ظفرت بك ( وَأَنَّ اللهَ شَدِيدُ الْعَذابِ ) عطف على « أن القوة » . [167] إن الرؤية من الظالم للعذاب ، إنما يكون ( إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا ) من القادة ( مِنَ الَّذِينَ اتَّبَعُوا ) وهم التابعون لهم ( وَرَأَوُا ) جميعا ( الْعَذابَ ( 1) النور : 46. ( 2) آل عمران : 44. وَتَقَطَّعَتْ بِهِمُ الْأَسْبابُ (166) وَقالَ الَّذِينَ اتَّبَعُوا لَوْ أَنَّ لَنا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَما تَبَرَّؤُا مِنَّا كَذلِكَ يُرِيهِمُ اللهُ أَعْمالَهُمْ حَسَراتٍ عَلَيْهِمْ وَما هُمْ بِخارِجِينَ مِنَ النَّارِ (167) يا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلالاً طَيِّباً وَتَقَطَّعَتْ بِهِمُ ) أي فيما بينهم ( الْأَسْبابُ ) فما كان في الدنيا يسبب وصلة بعضهم لبعض من المال والرئاسة والقرابة والحلف وأشباهها ، تنقطع هناك ، فلا داعي لنصرة الرؤساء أتباعهم الذين كانوا يتبعونهم في الدنيا.` },
            { text: "إِذْ تَبَرَّأَ ٱلَّذِينَ ٱتُّبِعُوا۟ مِنَ ٱلَّذِينَ ٱتَّبَعُوا۟ وَرَأَوُا۟ ٱلْعَذَابَ وَتَقَطَّعَتْ بِهِمُ ٱلْأَسْبَابُ", tafsir: `` },
            { text: "وَقَالَ ٱلَّذِينَ ٱتَّبَعُوا۟ لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا۟ مِنَّا كَذَٰلِكَ يُرِيهِمُ ٱللَّهُ أَعْمَٰلَهُمْ حَسَرَٰتٍ عَلَيْهِمْ وَمَا هُم بِخَٰرِجِينَ مِنَ ٱلنَّارِ", tafsir: `إي التابعين لرؤسائهم ( لَوْ أَنَّ لَنا كَرَّةً ) أي يا ليت لنا عودة إلى دار الدنيا ( فَنَتَبَرَّأَ مِنْهُمْ ) أي من هؤلاء الرؤساء ( كَما تَبَرَّؤُا مِنَّا ) هنا في القيامة حال حاجتنا إلى العون ( كَذلِكَ ) أي هكذا ( يُرِيهِمُ اللهُ أَعْمالَهُمْ ) أي أعمال كل من التابعين والمتبوعين ( حَسَراتٍ عَلَيْهِمْ ) فإن صلاتهم وأعمالهم ، كلها ذهبت أدراج الرياح ، فيتحسرون لماذا لم يعملوا بأوامر الله سبحانه ( وَما هُمْ بِخارِجِينَ مِنَ النَّارِ ) فإن المشرك يبقى في النار إلى الأبد ، إن تمت عليه الحجة وعاند. [169] وإذ تم الكلام حول العقيدة ، توجه إلى الحياة التي هي مقصد الإنسان ، وإليها يرجع كثير من حركته وسكونه ( يا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ ) من نباتها وحيوانها ومائها ومعدنها ( حَلالاً طَيِّباً ) أي في حال كون المأكول حلالا طيبا ، إلا ما حرم منه ، وفي قوله « طيبا » وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ (168) إِنَّما يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشاءِ وَأَنْ تَقُولُوا عَلَى اللهِ ما لا تَعْلَمُونَ (169) وَإِذا قِيلَ لَهُمُ اتَّبِعُوا ما أَنْزَلَ اللهُ قالُوا بَلْ نَتَّبِعُ ما أَلْفَيْنا عَلَيْهِ آباءَنا أَ وَلَوْ كانَ آباؤُهُمْ لا يَعْقِلُونَ شَيْئاً وَلا يَهْتَدُونَ (170) إشارة إلى أن كل حلال طيب ، وليس فيه خبث يوجب انحراف الصحة ، أو انحراف الخلق ( وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ ) فكأن الشيطان يخطو نحو الآثام ، ومن أثم كأنه تتبع خطواته إذ مشى خلفه ( إِنَّهُ ) أي الشيطان ( لَكُمْ عَدُوٌّ مُبِينٌ ) أي عدوا ظاهرا.` },
            { text: "يَٰٓأَيُّهَا ٱلنَّاسُ كُلُوا۟ مِمَّا فِى ٱلْأَرْضِ حَلَٰلًا طَيِّبًا وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ", tafsir: `` },
            { text: "إِنَّمَا يَأْمُرُكُم بِٱلسُّوٓءِ وَٱلْفَحْشَآءِ وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `أي الأعمال السيئة ( وَالْفَحْشاءِ ) وهي الأعمال السيئة للغاية ، فهو مشتق من الفحش ، بمعنى التعدي ( وَأَنْ تَقُولُوا عَلَى اللهِ ) أي تنسبوا إلى الله ( ما لا تَعْلَمُونَ ) من العقائد والأحكام ، وعدم العلم هنا أعم من العلم بالعدم ، كما قال سبحانه ( أَمْ تُنَبِّئُونَهُ بِما لا يَعْلَمُ ) (1) .` },
            { text: "وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُوا۟ مَآ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلْ نَتَّبِعُ مَآ أَلْفَيْنَا عَلَيْهِ ءَابَآءَنَآ أَوَلَوْ كَانَ ءَابَآؤُهُمْ لَا يَعْقِلُونَ شَيْـًٔا وَلَا يَهْتَدُونَ", tafsir: `من الأحكام وسائر الوحي ( قالُوا بَلْ نَتَّبِعُ ما أَلْفَيْنا عَلَيْهِ آباءَنا ) أي وجدنا عليه آباءنا من التقاليد ، فأنكر الله ذلك عليهم بالاستفهام الإنكاري ، بقوله ( أَ وَلَوْ كانَ آباؤُهُمْ لا يَعْقِلُونَ شَيْئاً ) من أمور الدين والدنيا ( وَلا يَهْتَدُونَ ) إلى الحق فإذا ( 1) الرعد : 34. وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِما لا يَسْمَعُ إِلاَّ دُعاءً وَنِداءً صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لا يَعْقِلُونَ (171) يا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ وَاشْكُرُوا لِلَّهِ إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ (172) إِنَّما حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ ظهر لكم أن آباءكم لا يعلمون ، فكيف تتبعونهم. [172] ثم بين الله سبحانه ، أن هؤلاء الكفار لعنادهم وتعصبهم ، قد غلقت منافذ السمع والبصر عنهم ، فلا يفيد فيهم وعظ ولا تذكير ( وَمَثَلُ الَّذِينَ كَفَرُوا ) بعد ما يروا الآيات ، ويسمعوا نداءك يا رسول الله ( كَمَثَلِ الَّذِي يَنْعِقُ ) أي يرفع صوته ( بِما ) أي بالحيوان الذي ( لا يَسْمَعُ ) ولا يفهم الكلام ، وإنما يسمع ( إِلَّا دُعاءً وَنِداءً ) فالحيوان ، إذا صحت به ، لا يفهم من كلامك إلا مجرد الدعوة والنداء ، فهؤلاء الكفار كذلك ، إذ لا ينتفعون بكلامك أبدا ، فهم ( صُمٌ ) جمع أصم ( بُكْمٌ ) جمع أبكم ( عُمْيٌ ) جمع أعمى ، فإنهم ولو كانت لهم آذان وألسنة وعيون ، لكنها كالمعطلة ، لأنها لا تؤدي وظيفتها ( فَهُمْ لا يَعْقِلُونَ )` },
            { text: "وَمَثَلُ ٱلَّذِينَ كَفَرُوا۟ كَمَثَلِ ٱلَّذِى يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَآءً وَنِدَآءً صُمٌّۢ بُكْمٌ عُمْىٌ فَهُمْ لَا يَعْقِلُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَٱشْكُرُوا۟ لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ", tafsir: `تكرارا لما تقدم لإلحاق مسألتي الشكر والمحرمات به ( وَاشْكُرُوا لِلَّهِ إِنْ كُنْتُمْ إِيَّاهُ تَعْبُدُونَ ) ولا تشكروا سائر الآلهة ، كالمشركين الذين يزعمون أنهم يمطرون بالأنواء ، ويرزقون بالآلهة المزعومة.` },
            { text: "إِنَّمَا حَرَّمَ عَلَيْكُمُ ٱلْمَيْتَةَ وَٱلدَّمَ وَلَحْمَ ٱلْخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيْرِ ٱللَّهِ فَمَنِ ٱضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `وهي التي لم تذبح على النحو الشرعي وَالدَّمَ وَلَحْمَ الْخِنْزِيرِ وَما أُهِلَّ بِهِ لِغَيْرِ اللهِ فَمَنِ اضْطُرَّ غَيْرَ باغٍ وَلا عادٍ فَلا إِثْمَ عَلَيْهِ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (173) إِنَّ الَّذِينَ يَكْتُمُونَ ما أَنْزَلَ اللهُ مِنَ الْكِتابِ ( وَالدَّمَ ) وهو وإن كان مطلقا ، إلا إنه مقيد بالمسفوح لقوله سبحانه ( إِلَّا أَنْ يَكُونَ مَيْتَةً أَوْ دَماً مَسْفُوحاً ) (1) ( وَلَحْمَ الْخِنْزِيرِ ) وخص اللحم بالكلام ، وإن كانت جملته محرمة ، لأن اللحم هو المعظم المقصود في الغالب ( وَما أُهِلَّ بِهِ لِغَيْرِ اللهِ ) الإهلال في الذبيحة رفع الصوت بالتسمية ، وقد كان المشركون عند ذبحهم ، يرفعون أصواتهم بتسمية الأوثان ، فنهى الله سبحانه عن أكل ذبيحة ذكر غير اسم الله عليها ( فَمَنِ اضْطُرَّ ) بصيغة المجهول ، فإن « اضطر » متعد من باب الافتعال ، وحيث لم يكن المقصود ، سبب الاضطرار ، ذكر مجهولا ( غَيْرَ باغٍ ) أي لم يكن باغيا وطالبا للذة في أكله وشربه ( وَلا عادٍ ) أي متعد في الأكل والشرب ، عن حد الضرورة ، أو غير باغ على إمام المسلمين ، ولا عاد بالمعصية طريق المحقين ( فَلا إِثْمَ عَلَيْهِ ) في تناول هذه المحرمات ( إِنَّ اللهَ غَفُورٌ ) يستر العصيان إذا اضطر إليه ، فغفر بمعنى ستر ، وستر العصيان ، عدم المؤاخذة به ( رَحِيمٌ ) بكم ، ولذا جاز تناول المحرم في حال الاضطرار.` },
            { text: "إِنَّ ٱلَّذِينَ يَكْتُمُونَ مَآ أَنزَلَ ٱللَّهُ مِنَ ٱلْكِتَٰبِ وَيَشْتَرُونَ بِهِۦ ثَمَنًا قَلِيلًا أُو۟لَٰٓئِكَ مَا يَأْكُلُونَ فِى بُطُونِهِمْ إِلَّا ٱلنَّارَ وَلَا يُكَلِّمُهُمُ ٱللَّهُ يَوْمَ ٱلْقِيَٰمَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ", tafsir: `وهم اليهود والنصارى الذين كانوا يكتمون العقائد الحقة الموجودة في كتابهم ، وينسبون إلى ( 1) الأنعام : 146. وَيَشْتَرُونَ بِهِ ثَمَناً قَلِيلاً أُولئِكَ ما يَأْكُلُونَ فِي بُطُونِهِمْ إِلاَّ النَّارَ وَلا يُكَلِّمُهُمُ اللهُ يَوْمَ الْقِيامَةِ وَلا يُزَكِّيهِمْ وَلَهُمْ عَذابٌ أَلِيمٌ (174) أُولئِكَ الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى الكتاب أحكاما لم توجد فيه ، كما قال سبحانه ( قُلْ فَأْتُوا بِالتَّوْراةِ فَاتْلُوها إِنْ كُنْتُمْ صادِقِينَ ) (1) ولعل ارتباط هذه الآية بما قبلها من جهة الأمور التي كانوا يحرمونها ، ولم يكن في كتبهم تحريم لها ( وَيَشْتَرُونَ بِهِ ) أي بهذا الكتاب ( ثَمَناً قَلِيلاً ) من رئاسة الدنيا وأموالها ، فإنها قليل بالنسبة إلى الآخرة ( أُولئِكَ ما يَأْكُلُونَ فِي بُطُونِهِمْ ) أي لا يجرون إلى بطونهم ولعل ذكر في بطونهم للاحتراز عن الأكل في بطن الغير ، فإن العرب تقول شبع فلان في بطنه ، إذا أكله بنفسه ، وتقول شبع فلان في بطن غيره ، إذا أكله من يتعلق به ( إِلَّا النَّارَ ) فإن ما أكلوه ينقلب نارا تحرق بطونهم في جهنم ( وَلا يُكَلِّمُهُمُ اللهُ يَوْمَ الْقِيامَةِ ) فيهملهم ليذوقوا الهوان جزاء ما فعلوا ( وَلا يُزَكِّيهِمْ ) أي لا يطهرهم عن الآثام ، فإن البطن إذا مليء حراما يقسو ، فلا يهتدي حتى يتزكى الإنسان ويتطهر ( وَلَهُمْ عَذابٌ أَلِيمٌ ) مؤلم.` },
            { text: "أُو۟لَٰٓئِكَ ٱلَّذِينَ ٱشْتَرَوُا۟ ٱلضَّلَٰلَةَ بِٱلْهُدَىٰ وَٱلْعَذَابَ بِٱلْمَغْفِرَةِ فَمَآ أَصْبَرَهُمْ عَلَى ٱلنَّارِ", tafsir: `الذين يكتمون ما أنزل الله هم ( الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالْهُدى ) أي عوض الهداية ، فكأن نفس الإنسان ثمن لأحد أمرين الضلالة والهداية ، فهم أعطوا أنفسهم ، واشتروا الضلالة عوض أن ( 1) آل عمران : 94. وَالْعَذابَ بِالْمَغْفِرَةِ فَما أَصْبَرَهُمْ عَلَى النَّارِ (175) ذلِكَ بِأَنَّ اللهَ نَزَّلَ الْكِتابَ بِالْحَقِّ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِي الْكِتابِ لَفِي شِقاقٍ بَعِيدٍ (176) لَيْسَ الْبِرَّ أَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلكِنَّ الْبِرَّ مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ يشتروا الهداية ( وَ ) اشتروا ( الْعَذابَ بِالْمَغْفِرَةِ ) فعوض أن يشتروا المغفرة لأنفسهم اشتروا العذاب ( فَما أَصْبَرَهُمْ عَلَى النَّارِ ) تعجب عن صبرهم على النار التي هي عاقبة عملهم ، أي كيف أنهم يصبرون على النار حينما فعلوا ما عاقبته النار.` },
            { text: "ذَٰلِكَ بِأَنَّ ٱللَّهَ نَزَّلَ ٱلْكِتَٰبَ بِٱلْحَقِّ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِى ٱلْكِتَٰبِ لَفِى شِقَاقٍۭ بَعِيدٍ", tafsir: `العذاب ، إنما توجه إليهم بسبب أن ( اللهَ نَزَّلَ الْكِتابَ ) أي التوراة ( بِالْحَقِّ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِي الْكِتابِ ) بكتمان بعضه وإظهار بعض ( لَفِي شِقاقٍ ) وخلاف عن الحق ( بَعِيدٍ ) فهم إنما استحقوا العذاب ، لأنهم خالفوا الحق ، وكتموا ما لزم إظهاره ، ومن المحتمل أن يكون المراد بالكتاب « القرآن » أي أن عذابهم بسبب كتمانهم كون القرآن حقا واختلافهم فيه ، بأنه سحر وكهانة أو كلام بشر.` },
            { text: "لَّيْسَ ٱلْبِرَّ أَن تُوَلُّوا۟ وُجُوهَكُمْ قِبَلَ ٱلْمَشْرِقِ وَٱلْمَغْرِبِ وَلَٰكِنَّ ٱلْبِرَّ مَنْ ءَامَنَ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَٱلْمَلَٰٓئِكَةِ وَٱلْكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلْمَالَ عَلَىٰ حُبِّهِۦ ذَوِى ٱلْقُرْبَىٰ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينَ وَٱبْنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِى ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلْمُوفُونَ بِعَهْدِهِمْ إِذَا عَٰهَدُوا۟ وَٱلصَّٰبِرِينَ فِى ٱلْبَأْسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلْبَأْسِ أُو۟لَٰٓئِكَ ٱلَّذِينَ صَدَقُوا۟ وَأُو۟لَٰٓئِكَ هُمُ ٱلْمُتَّقُونَ", tafsir: `كل البر أيها اليهود المجادلون حول تحويل القبلة الصارفون أوقاتكم في هذه البحوث العقيمة ( أَنْ تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ ) فإن ذلك أمر فرعي مرتبط بتكليف الله سبحانه ، وقد كلفنا أن نصرف الوجوه إلى الكعبة ( وَلكِنَّ الْبِرَّ ) فعل ، أي ولكن ذا البر ( مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فذلك هو الأصل الذي وَالْمَلائِكَةِ وَالْكِتابِ وَالنَّبِيِّينَ وَآتَى الْمالَ عَلى حُبِّهِ ذَوِي الْقُرْبى وَالْيَتامى وَالْمَساكِينَ وَابْنَ السَّبِيلِ وَالسَّائِلِينَ وَفِي الرِّقابِ وَأَقامَ الصَّلاةَ وَآتَى الزَّكاةَ وَالْمُوفُونَ بِعَهْدِهِمْ إِذا عاهَدُوا وَالصَّابِرِينَ يتفرع عليه أحكام الصلاة وغيرها ( وَ ) آمن ب ( الْمَلائِكَةِ وَالْكِتابِ ) المنزل من عند الله على أنبيائه ( وَ ) آمن ب ( النَّبِيِّينَ ) كلهم أولهم وأوسطهم وأخرهم ( وَآتَى الْمالَ ) أي أعطاه وأنفقه ( عَلى حُبِّهِ ) أي مع أنه يحبه ، أو على حب الله تعالى ( ذَوِي الْقُرْبى ) أي قراباته وأرحامه ( وَالْيَتامى ) الذين مات أبوهم ( وَالْمَساكِينَ ) الذين لا يجدون النفقة لأنفسهم وأهليهم ( وَابْنَ السَّبِيلِ ) الذي انقطع في سفره ، فلا مال له يوصله إلى أهله ومقصده ، وسمي ابن السبيل ، لعدم معرفة أبيه وعشيرته ( وَالسَّائِلِينَ ) من الفقراء الذين يسألون الناس ( وَ ) آتى المال ( فِي ) فك ( الرِّقابِ ) أي اشتراء العبيد أو إعتاقهم ، حتى يتحرروا عن ربق العبودية ( وَأَقامَ الصَّلاةَ ) أي أداها على حدودها ( وَآتَى الزَّكاةَ ) الواجبة والمستحبة ( وَالْمُوفُونَ ) الذين يفون ( بِعَهْدِهِمْ إِذا عاهَدُوا ) سواء كان عهدا مع الله كالنذر والبيعة ، أو مع الناس كالعقود ، وهذا عطف على قوله « من آمن » ( وَالصَّابِرِينَ ) عطف على من آمن على طريق القطع بتقدير المدح ، كما قال ابن مالك : و اقطع أو اتبع أن يكن معينا بدونها أو بعضها اقطع معلنا فِي الْبَأْساءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ أُولئِكَ الَّذِينَ صَدَقُوا وَأُولئِكَ هُمُ الْمُتَّقُونَ (177) يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصاصُ فِي الْقَتْلى و ارفع أو انصب إن قطعت مضمرا مبتدءا أو ناصبا لن يظهرا فإن عادة العربي أن يتفنن بالقطع رفعا ونصبا إذا طالت الصفات تقليلا للكلل وتنشيطا للذهن بالتلون في الكلام ( فِي الْبَأْساءِ ) البؤس الفقر ( وَالضَّرَّاءِ ) والمضر الموجع والعلة وكل ضرر ( وَحِينَ الْبَأْسِ ) أي الصابرين حين القتال ( أُولئِكَ ) الموصوفون بهذه الصفات هم ( الَّذِينَ صَدَقُوا ) في نياتهم وأعمالهم ، لا من يجادل في أمر كتحويل القبلة ( وَأُولئِكَ هُمُ الْمُتَّقُونَ ) الخائفون من الله سبحانه ، وفي هذه الآية الكريمة إلماح إلى حال كثير من الناس حيث يتركون المهام ويناقشون في أمر غير مهم عنادا وعصبية. [179] وحيث ذكر سبحانه ما هو البر عقبه ببعض الأحكام التي ينبغي لأهل البر المؤمنين بالله واليوم الآخر المتصفين بتلك الصفات أن يلتزموا بها ( يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصاصُ ) ومعنى كتابته تشريعه إذ الشرائع تكتب ( فِي الْقَتْلى ) جمع قتيل ، فقد ورد أنها نزلت في حيين من العرب لأحدهما طول على الأخر ، وكانوا يتزوجون نساء بغير حلال ، وأقسموا لنقتلن بالعبد منا الحر منهم ، وبالمرأة منا الرجل منهم ، وبالرجل منا الرجلين منهم ، وجعلوا جراحاتهم على الضعف من جراح أولئك ، حتى جاء الإسلام ، وأبطل تلك الأحكام ، ف ـ الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثى بِالْأُنْثى فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ فَاتِّباعٌ بِالْمَعْرُوفِ وَأَداءٌ إِلَيْهِ بِإِحْسانٍ ذلِكَ تَخْفِيفٌ مِنْ رَبِّكُمْ وَرَحْمَةٌ فَمَنِ اعْتَدى بَعْدَ ذلِكَ فَلَهُ عَذابٌ أَلِيمٌ (178) وَلَكُمْ فِي الْقِصاصِ حَياةٌ الحر ب ـ مقابل الحر يقتل لا مقابل العبد ( وَالْعَبْدُ بِالْعَبْدِ وَالْأُنْثى ) تقتل بمقابل الأنثى لا الذكر يقتل في قبال الأنثى ( فَمَنْ عُفِيَ لَهُ مِنْ ) قبل ( أَخِيهِ شَيْءٌ ) بأن عفى الأخ الولي للمقتول عن قتل القاتل ، وبدله بالدية ، أو عفى عن بعض الدية ، وبقي بعضها الأخر فالواجب على الطرفين ، مراقبة الله في الأخذ والإعطاء ، فمن طرف الولي للمقتول ( فَاتِّباعٌ ) للقاتل ( بِالْمَعْرُوفِ ) بأن لا يشدد في طلب الدية ، ومن طرف القاتل ( وَأَداءٌ إِلَيْهِ ) أي إلى العافي ( بِإِحْسانٍ ) من غير مطل وتصعيب ( ذلِكَ ) الحكم في باب القتيل بالمماثلة ، أولا ، والتخيير بين القتل والدية والعفو ثانيا ( تَخْفِيفٌ مِنْ رَبِّكُمْ ) عليكم ( وَرَحْمَةٌ ) منه بكم ، وفي المجمع أنه كان لأهل التوراة القصاص أو العفو ، ولأهل الإنجيل العفو والدية ( فَمَنِ اعْتَدى ) عن الحكم المقرر ( بَعْدَ ذلِكَ ) الذي قررناه من الأحكام ( فَلَهُ عَذابٌ أَلِيمٌ ) مؤلم في الدنيا والآخرة.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلْقِصَاصُ فِى ٱلْقَتْلَى ٱلْحُرُّ بِٱلْحُرِّ وَٱلْعَبْدُ بِٱلْعَبْدِ وَٱلْأُنثَىٰ بِٱلْأُنثَىٰ فَمَنْ عُفِىَ لَهُۥ مِنْ أَخِيهِ شَىْءٌ فَٱتِّبَاعٌۢ بِٱلْمَعْرُوفِ وَأَدَآءٌ إِلَيْهِ بِإِحْسَٰنٍ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ فَمَنِ ٱعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُۥ عَذَابٌ أَلِيمٌ", tafsir: `` },
            { text: "وَلَكُمْ فِى ٱلْقِصَاصِ حَيَوٰةٌ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ لَعَلَّكُمْ تَتَّقُونَ", tafsir: `في باب القتل ، بأن يقتل القاتل عمدا ( حَياةٌ ) للمجموع ، لأن كل من افتكر إنه لو قتل قتل ارتدع إلا النادر ، وأيضا إن القصاص يوجب عدم تعدي أولياء المقتول على يا أُولِي الْأَلْبابِ لَعَلَّكُمْ تَتَّقُونَ (179) كُتِبَ عَلَيْكُمْ إِذا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِنْ تَرَكَ خَيْراً الْوَصِيَّةُ لِلْوالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ (180) أقرباء القاتل ، بأن يقتلوا منهم عددا كثيرا ، كما كان هو المتعارف في زمان الجاهلية ، حتى ربما فنيت القبيلة لأجل قتيل واحد ( يا أُولِي الْأَلْبابِ ) جمع لب ، بمعنى العقل ، أي يا أصحاب العقول ( لَعَلَّكُمْ تَتَّقُونَ ) القتل ، أي شرع القصاص ، حتى تتقون من القتل. [181] وحيث ألمح القرآن الحكيم إلى حكم القتل ، أشار إلى ما يرتبط به من الوصية ، فقال ( كُتِبَ عَلَيْكُمْ ) كتابة راجحة ، فإن الكتابة تشمل الواجب والمندوب ، والوصية مندوبة ، إلا إذا وجبت بالعارض ( إِذا حَضَرَ أَحَدَكُمُ الْمَوْتُ ) بأن رأى مقدماته من مرض وهرم ونحوهما ( إِنْ تَرَكَ خَيْراً ) أي مالا فإذا لم يترك الخير ، لا داعي للوصية وإن كانت مستحبة أيضا ، لكنها ليست مثل تأكيد من ترك الخير ( الْوَصِيَّةُ ) نائب فاعل « كتب » ( لِلْوالِدَيْنِ وَالْأَقْرَبِينَ ) أي الأقرباء ( بِالْمَعْرُوفِ ) بأن يوصي لوالديه وأقربائه ، ولو كانوا وراثا ، شيئا من الثلث ، وهذا يوجب نشر الألفة والمحبة أكثر فأكثر ، وإنما قيده بالمعروف ، حتى لا يوصي بما يوجب إثارة الشحناء ، كأن يترك الأقرب ، ويوصي للأبعد ، أو يفضل بعضا على بعض بما يورث البغضاء ، والمراد بالمعروف ، الذي يعرف أهل التميز ، إنه لا جور فيه ولا حيف ، وهذه الوصية تكون ( حَقًّا عَلَى الْمُتَّقِينَ ) الذين يؤثرون التقوى. فَمَنْ بَدَّلَهُ بَعْدَ ما سَمِعَهُ فَإِنَّما إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ إِنَّ اللهَ سَمِيعٌ عَلِيمٌ (181) فَمَنْ خافَ مِنْ مُوصٍ جَنَفاً أَوْ إِثْماً فَأَصْلَحَ بَيْنَهُمْ` },
            { text: "كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ ٱلْمَوْتُ إِن تَرَكَ خَيْرًا ٱلْوَصِيَّةُ لِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ", tafsir: `` },
            { text: "فَمَنۢ بَدَّلَهُۥ بَعْدَ مَا سَمِعَهُۥ فَإِنَّمَآ إِثْمُهُۥ عَلَى ٱلَّذِينَ يُبَدِّلُونَهُۥٓ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ", tafsir: `أي بدل الإيصاء وغيّره وزوّره ( بَعْدَ ما سَمِعَهُ ) أي علمه ، فالسماع يستعمل بمعنى العلم ( فَإِنَّما إِثْمُهُ ) أي إثم التبديل ( عَلَى الَّذِينَ يُبَدِّلُونَهُ ) وليس إثم على الذي يأكل المال إرثا بغير علم ، والذي يأكله زيادة على حصته ، من غير علم فإن الغالب ، أن يبدل الجيل الأول ، ويتصرف سائر الأجيال ، بلا علم منهم بالتبديل ( إِنَّ اللهَ سَمِيعٌ ) لوصاياكم وأقوالكم ( عَلِيمٌ ) بنواياكم وتبديلكم ، أو تنفيذكم للوصية ، ولعل هناك نكتة أخرى في قوله ( فَإِنَّما إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ ) هي أن كثيرا من الناس لا يوصون خوفا من أن يلحقهم إثم التبديل من بعدهم ، لأنهم بوصيتهم أعانوا من بدل ومهدوا الطريق له ، كما رأيت ذلك متعارفا في كلام كثير من الناس ، حيث يقولون من أوصى ألقى ورثته في المعصية ، فيكف بعضهم عن الوصية ، فأشار سبحانه إلى كون هذا الحكم غلطا ، فإن الموصي فعل خيرا ، وإنما المغير هو الذي يتحمل الإثم. [183] ثم استثنى سبحانه عن حرمة تبديل الوصية ، بأنه إنما يكون حراما ، إذا كان تغيرا من حق إلى باطل ، أما إذا كان من باطل إلى حق ، فلا إثم في التغيير ( فَمَنْ خافَ ) وخشي ( مِنْ مُوصٍ ) أي الذي يوصي ( جَنَفاً ) أي ميلا عن الحق إلى الباطل ، بأن أوصى أزيد مما يحق له الإيصاء به ( أَوْ إِثْماً ) بأن حرم ورثته بإيصائه ، وفي الحديث أن الإثم الخطأ عن عمد ، والجنف الخطأ لا عن عمد ( فَأَصْلَحَ بَيْنَهُمْ ) أي بين الورثة والموصي ، والموصى له ، بأن رد الزائد إلى الورثة ، وأبطل ما فَلا إِثْمَ عَلَيْهِ إِنَّ اللهَ غَفُورٌ رَحِيمٌ (182) يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيامُ كَما كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ (183) أَيَّاماً مَعْدُوداتٍ فَمَنْ كانَ مِنْكُمْ مَرِيضاً فيه الإثم ( فَلا إِثْمَ عَلَيْهِ ) أي على المبدل للوصية ( إِنَّ اللهَ غَفُورٌ رَحِيمٌ ) بمن يأثم ، فكيف بمن لا يأثم ، وقد ثبت في الشريعة إن الوصية بما زاد على الثلث لا تنفذ إلا برضى الورثة (1) . [184] ثم انتقل السياق إلى حكم آخر من أحكام الإسلام ـ لما ذكرنا من أن القرآن الحكيم ، بعد بيان أصول التوحيد ، ذكر جملة من الأحكام ـ فقال سبحانه ، ( يا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيامُ ) فإنه مفروض عليكم ، فيجب عليكم أن تصوموا ( كَما كُتِبَ عَلَى الَّذِينَ مِنْ قَبْلِكُمْ ) فلستم أنتم وحدكم أمرتم بالصيام ، بل كان الصوم شريعة في الأديان السابقة أيضا ( لَعَلَّكُمْ تَتَّقُونَ ) النار بصيامكم ، فالصائم حيث يحس بالجوع والعطش والضعف يتذكر الله سبحانه فيخبت قلبه وتضعف فيه قوى الشر ، وترق نفسه وتصفو روحه ، وكل ذلك سبب للتقوى وترك المعاصي.` },
            { text: "فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَآ إِثْمَ عَلَيْهِ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُتِبَ عَلَيْكُمُ ٱلصِّيَامُ كَمَا كُتِبَ عَلَى ٱلَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", tafsir: `` },
            { text: "أَيَّامًا مَّعْدُودَٰتٍ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ وَعَلَى ٱلَّذِينَ يُطِيقُونَهُۥ فِدْيَةٌ طَعَامُ مِسْكِينٍ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُۥ وَأَن تَصُومُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ", tafsir: `أي إن الصيام في أيام ( مَعْدُوداتٍ ) أي محصورات ، فليست أيام كثيرة لا تعد ، وإنما هي ثلاثون يوما فقط ـ وفيه تسلية للصائم ـ وليس الصيام على كل أحد ( فَمَنْ كانَ مِنْكُمْ مَرِيضاً ) مرضا ( 1) راجع موسوعة الفقه : ج 82 و 83. أَوْ عَلى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعامُ مِسْكِينٍ فَمَنْ تَطَوَّعَ خَيْراً فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ (184) يضره الصوم ( أَوْ عَلى سَفَرٍ ) فقد شبه السفر بمركوب لغلبة الركوب فيه ، وحد السفر معين في الشريعة ( فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ ) أي فليصم في أيام أخر غير شهر رمضان ، قضاء لما فاته بالمرض أو السفر ( وَعَلَى الَّذِينَ يُطِيقُونَهُ ) أي يطيقون الصيام ، بأن يكون آخر طاقاتهم وذلك موجب للعسر ، كما لا يخفى ، إذ آخر الطاقة عسر ، أو أن الذي يطيق الصوم كان في أول الشريعة مخيرا بين الصيام والإطعام ، ثم وجب الصوم وحده ، وذلك للتدرج بالأمة ( فِدْيَةٌ ) أي الواجب عليهم الفداء بدل الصوم ( طَعامُ مِسْكِينٍ ) واحد وهو مد من الطعام ( فَمَنْ تَطَوَّعَ خَيْراً ) بأن زاد على طعام المسكين ( فَهُوَ خَيْرٌ لَهُ وَأَنْ تَصُومُوا ) أيها المطيقون ، الذي يبلغ الصوم طاقتكم ( خَيْرٌ لَكُمْ ) من الإطعام ، فالإنسان إما أن يضره الصوم ضررا بالغا ، وهو الذي تقدم أن يفطر ويأتي بعدة من أيام أخر ، وإما أن يشق عليه إلى حد العسر ، وهو الذي يبلغ منتهى طاقته ، وهذا يخير بين الصيام والإطعام وإن كان الصيام خير ، وإما أن لا يشق عليه وهو الذي يجب عليه الصيام معينا مما بين في الآية التالية ( إِنْ كُنْتُمْ تَعْلَمُونَ ) لعلمتم أن الصيام خير لما فيه من الفوائد التي ليست في الإطعام ، وليس مفهومه ، إن لم تكونوا تعلمون ، فليس الصوم خير ، بل المفهوم إن لم تكونوا تعلمون ، لم تعلموا إن الصوم خير. شَهْرُ رَمَضانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ هُدىً لِلنَّاسِ وَبَيِّناتٍ مِنَ الْهُدى وَالْفُرْقانِ فَمَنْ شَهِدَ مِنْكُمُ الشَّهْرَ فَلْيَصُمْهُ وَمَنْ كانَ مَرِيضاً أَوْ عَلى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ يُرِيدُ اللهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ وَلِتُكْمِلُوا الْعِدَّةَ وَلِتُكَبِّرُوا اللهَ عَلى [186] الأيام المعدودات المفروض فيها الصيام هي ( شَهْرُ رَمَضانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ ) مما زاد في عظمته وحرمته ، إذ صار زمانا للنزول أعظم دستور للبشرية إلى الأبد في حال كون القرآن ( هُدىً لِلنَّاسِ ) يهديهم إلى الحق وإلى صراط مستقيم ( وَبَيِّناتٍ ) أي أمور واضحات ( مِنَ ) جنس ( الْهُدى ) فليس هدى غامضا يحتاج إلى إثبات ودليل ، بل واضح لائح ، ومن الهدى بيان لبينات ، إذ يمكن أن يكون شيئا بينا من حيث الشهادة ، أو المعاملة أو نحوها ( وَ ) من ( الْفُرْقانِ ) أي يفرق بين الحق والباطل والضلال والرشاد ( فَمَنْ شَهِدَ ) أي حضر ولم يغب بالسفر ( مِنْكُمُ الشَّهْرَ ) أي شهر رمضان ( فَلْيَصُمْهُ ) إيجابا ، ولما كان الحكم عاما استثنى منه بقوله ( وَمَنْ كانَ مَرِيضاً أَوْ عَلى سَفَرٍ فَعِدَّةٌ مِنْ أَيَّامٍ أُخَرَ ) وإنما كرر تمهيدا لقوله ( يُرِيدُ اللهُ بِكُمُ الْيُسْرَ وَلا يُرِيدُ بِكُمُ الْعُسْرَ ) ولذا أمركم بالإفطار في السفر والمرض ( وَ ) إنما شرع عدة من أيام أخر ( لِتُكْمِلُوا الْعِدَّةَ ) أي عدة الشهر ، فإن في صيامه فوائد لا يدركها إلا من أكملها ، فإن لم يتمكن من إكمالها في نفس شهر رمضان أكملها خارجه ( وَ ) إنما شرع الصوم ( لِتُكَبِّرُوا اللهَ عَلى ما هَداكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ (185) وَإِذا سَأَلَكَ عِبادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذا دَعانِ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ (186) ما هَداكُمْ ) أي تعظموه بسبب هدايته لكم إلى دينه وشريعته ، فالصيام سبب قرب النفس إلى الله سبحانه ، فيأتي منها التكبير عفوا ، وفي التأويل ، المراد به تكبير ليلة الفطر ( وَلَعَلَّكُمْ تَشْكُرُونَ ) فالصوم نعمة تستحق الشكر لما فيه من صلاح الدنيا والدين. [187] وحيث أن من عادة القرآن الحكيم أن يخلل الأحكام نفحة موجهة نحو الله تعالى ، ليرتبط الحكم بالخالق ، وليشع في النفس النشاط والعزيمة ، أتت أية استجابة الدعاء هنا ، بعد طول من بيان الأحكام ، ثم يأتي بعدة آيات ترتبط بالأحكام ثانية ، بالإضافة إلى أن استجابة الدعاء تناسب شهر رمضان ، فإنه شهر دعاء وضراعة ، و قد ورد أن سائلا سأل النبي صلى‌الله‌عليه‌وآله‌وسلم كيف ندعوا ، فنزلت ( وَإِذا سَأَلَكَ عِبادِي عَنِّي فَإِنِّي قَرِيبٌ ) إليهم ، قرب العلم والإحاطة والسمع والبصر ، لا قرب الزمان والمكان والجهة ، فإنه سبحانه منزه عن كل ذلك ( أُجِيبُ دَعْوَةَ الدَّاعِ ) الذي يدعوني ( إِذا دَعانِ ) ولعل في هذا القيد إفادة أن الإجابة وقت الدعوة مباشرة فإن « إذا » ظرف ، ويفيد تكرار كلمة « دعا » لتتركز في الذهن تركيزا ( فَلْيَسْتَجِيبُوا لِي ) أي يطيعوني في أوامري ونواهي ، إذ من يجيب الدعاء ، يستحق أن يستجيب له الإنسان ( وَلْيُؤْمِنُوا بِي ) إيمانا بذاتي وصفاتي ( لَعَلَّهُمْ يَرْشُدُونَ ) أي لكي يصيبوا الحق ويهتدوا إليه. أُحِلَّ لَكُمْ لَيْلَةَ الصِّيامِ الرَّفَثُ إِلى نِسائِكُمْ هُنَّ لِباسٌ لَكُمْ وَأَنْتُمْ لِباسٌ لَهُنَّ عَلِمَ اللهُ أَنَّكُمْ كُنْتُمْ تَخْتانُونَ` },
            { text: "شَهْرُ رَمَضَانَ ٱلَّذِىٓ أُنزِلَ فِيهِ ٱلْقُرْءَانُ هُدًى لِّلنَّاسِ وَبَيِّنَٰتٍ مِّنَ ٱلْهُدَىٰ وَٱلْفُرْقَانِ فَمَن شَهِدَ مِنكُمُ ٱلشَّهْرَ فَلْيَصُمْهُ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ وَلِتُكْمِلُوا۟ ٱلْعِدَّةَ وَلِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ", tafsir: `` },
            { text: "وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ", tafsir: `` },
            { text: "أُحِلَّ لَكُمْ لَيْلَةَ ٱلصِّيَامِ ٱلرَّفَثُ إِلَىٰ نِسَآئِكُمْ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ عَلِمَ ٱللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ فَٱلْـَٰٔنَ بَٰشِرُوهُنَّ وَٱبْتَغُوا۟ مَا كَتَبَ ٱللَّهُ لَكُمْ وَكُلُوا۟ وَٱشْرَبُوا۟ حَتَّىٰ يَتَبَيَّنَ لَكُمُ ٱلْخَيْطُ ٱلْأَبْيَضُ مِنَ ٱلْخَيْطِ ٱلْأَسْوَدِ مِنَ ٱلْفَجْرِ ثُمَّ أَتِمُّوا۟ ٱلصِّيَامَ إِلَى ٱلَّيْلِ وَلَا تُبَٰشِرُوهُنَّ وَأَنتُمْ عَٰكِفُونَ فِى ٱلْمَسَٰجِدِ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَقْرَبُوهَا كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ", tafsir: `الطيبات أيها الصائمون ( لَيْلَةَ الصِّيامِ ) التي تصومون غدها ( الرَّفَثُ ) أي الجماع ( إِلى نِسائِكُمْ ) وإنما عدى ب « إلى » لتعليم معنى الإفضاء ، أي الانتهاء إلى زوجاتكم بالجماع. وقد روي عن الصادق عليه‌السلام في سبب نزول هذه الآية أنه قال : كان الأكل محرما في شهر رمضان بالليل بعد النوم ، وكان النكاح حراما بالليل والنهار في شهر رمضان ، وكان رجل من أصحاب رسول الله صلى‌الله‌عليه‌وآله‌وسلم يقال له مطعم بن جبير ، أخو عبد الله بن جبير الذي كان رسول الله صلى‌الله‌عليه‌وآله‌وسلم وكله بفم الشعب يوم أحد في خمسين من الرماة ، وفارقه أصحابه وبقي في أثنى عشر رجلا ، فقتل على باب الشعب ، وكان أخوه هذا مطعم بن جبير شيخا ضعيفا ، وكان صائما فأبطأت عليه أهله بالطعام ، فنام قبل أن يفطر ، فلما انتبه قال لأهله : قد حرم عليّ الأكل في هذه الليلة ، فلما أصبح حضر حفر الخندق فأغمي عليه ، فرآه رسول الله صلى‌الله‌عليه‌وآله‌وسلم فرق له ، وكان قوم من الشباب ينكحون بالليل سرا في شهر رمضان ، فأنزل الله هذه الآية ، فأحل النكاح بالليل في شهر رمضان والأكل بعد النوم إلى طلوع الفجر (1) . ( هُنَّ لِباسٌ لَكُمْ وَأَنْتُمْ لِباسٌ لَهُنَ ) فكما أن اللباس يقي البدن وكما أنه ملاصق بالبدن ومحرم عليه ، كذلك كل من الزوجين بالنسبة إلى الآخر ( عَلِمَ اللهُ أَنَّكُمْ ) أيها الصائمون ( كُنْتُمْ تَخْتانُونَ ) من الخيانة ( 1) عوالي اللآلي : ج 2 ص 82. أَنْفُسَكُمْ فَتابَ عَلَيْكُمْ وَعَفا عَنْكُمْ فَالْآنَ بَاشِرُوهُنَّ وَابْتَغُوا ما كَتَبَ اللهُ لَكُمْ وَكُلُوا وَاشْرَبُوا حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ ثُمَّ أَتِمُّوا الصِّيامَ إِلَى اللَّيْلِ وَلا تُبَاشِرُوهُنَّ وَأَنْتُمْ عاكِفُونَ فِي الْمَساجِدِ تِلْكَ ( أَنْفُسَكُمْ ) أي كنتم تخونونها بارتكاب المعصية فكأن المرتكب لها يخونها إذ يسبب لها خسارة ، وكل خائن كذلك يسبب لمن خانه خسارة ( فَتابَ عَلَيْكُمْ ) ما كنتم تأتون به من المحرم في جماع أهليكم ليلا ( وَعَفا عَنْكُمْ ) بالنسبة إلى هذا الحكم فمن الآن ( بَاشِرُوهُنَ ) أي يجوز لكم جماعهن ليلا والأمر في مقام نفي لا يفيد إلا الجواز ( وَابْتَغُوا ما كَتَبَ اللهُ لَكُمْ ) من الأولاد واللذة المحللة الموجبة للثواب ، وهذا بالنسبة إلى نسخ الحكم بتحريم الجماع ( وَكُلُوا وَاشْرَبُوا ) أي يباح لكم الأكل والشرب من أول المغرب ( حَتَّى يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ ) بيان الخيطين أي يتضح الفجر الصادق الذي هو في وسط الظلام كخيط أبيض قرب خيط أسود ( ثُمَّ أَتِمُّوا الصِّيامَ ) بالكف عن المفطرات المذكورة في الشريعة ، من أول الفجر الصادق ( إِلَى اللَّيْلِ ) وهو المغرب الشرعي ، وهذا بالنسبة إلى نسخ الحكم بتحريم الأكل والشرب لمن نام قبل أن يفطر ( وَلا تُبَاشِرُوهُنَ ) أي لا تجامعوا النساء ( وَأَنْتُمْ عاكِفُونَ فِي الْمَساجِدِ ) ليلا أو نهارا والاعتكاف هو اللبث في المسجد بقصد العبادة ويشترط فيه الصوم ، وأقله ثلاثة أيام بتفصيل مذكور في الفقه ، ومن أحكام الاعتكاف حرمة مباشرة النساء ليلا ونهارا ( تِلْكَ ) التي ذكرنا من أحكام حُدُودُ اللهِ فَلا تَقْرَبُوها كَذلِكَ يُبَيِّنُ اللهُ آياتِهِ لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ (187) وَلا تَأْكُلُوا أَمْوالَكُمْ بَيْنَكُمْ بِالْباطِلِ وَتُدْلُوا بِها إِلَى الْحُكَّامِ لِتَأْكُلُوا فَرِيقاً الصيام (1) وغيرها ( حُدُودُ اللهِ ) التي جعلها لأفعال العباد من الفعل فلا يجوز تركه ، والترك فلا يجوز إقحامه كحدود المدينة والدار ونحوهما ( فَلا تَقْرَبُوها ) نهى عن الاقتراب ، مبالغة في النهي عن الاقتحام والمخالفة كقوله تعالى ( وَلا تَقْرَبُوا مالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ ) (2) ( كَذلِكَ ) أي مثل هذا البيان الواضح الذي بين أحكام الصيام وغيره ( يُبَيِّنُ اللهُ آياتِهِ ) دلائله وأحكامه ( لِلنَّاسِ لَعَلَّهُمْ يَتَّقُونَ ) أي لكي يتقوا معاصيه. [189] ثم انتقل السياق إلى تشريع آخر له مناسبة ما ب « الأكل » الذي دار الحديث حوله في مسألة الصيام ( وَلا تَأْكُلُوا أَمْوالَكُمْ بَيْنَكُمْ بِالْباطِلِ ) بالغصب وما أشبه ، وكان وجه ذكر كلمة « بينكم » أن الآكلين للغصب ونحوه يتآمرون بينهم في خفاء حتى يبرروا أكلهم ( وَتُدْلُوا ) الإدلاء أي الإلقاء والإفضاء أي تلقوا ( بِها ) أي بتلك الأموال ( إِلَى الْحُكَّامِ ) جمع حاكم ، بمعنى القضاة بعنوان الرشوة والهدية ليأخذوا جانبكم في أكل المال بالباطل ( لِتَأْكُلُوا ) علة لتدلوا أي علة إعطائكم الرشوة أن تأكلوا ( فَرِيقاً ) ( 1) راجع موسوعة الفقه : ج 37 ص 251. ( 2) الأنعام : 153. مِنْ أَمْوالِ النَّاسِ بِالْإِثْمِ وَأَنْتُمْ تَعْلَمُونَ (188) يَسْئَلُونَكَ عَنِ الْأَهِلَّةِ قُلْ هِيَ مَواقِيتُ لِلنَّاسِ وَالْحَجِّ أي قسما ( مِنْ أَمْوالِ النَّاسِ بِالْإِثْمِ ) بدون حق ( وَأَنْتُمْ تَعْلَمُونَ ) بأن أكلكم وإرشاءكم باطل وإثم. [190] مرت أحكام كلها تحتاج إلى التوقيت من صيام واعتكاف ومحاكمات وغيرها فناسب أن يأتي تشريع الأهلة هنا مع الغض عما تقدم من أن المقصود بيان جملة من الأحكام بعد بيان أصول التوحيد ( يَسْئَلُونَكَ ) يا رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( عَنِ الْأَهِلَّةِ ) وعن سبب اختلاف الهلال في كل شهر من الهلال إلى البدر ثم إلى الهلال حتى المحاق أو عن فائدة هذا الاختلاف ولماذا لم يكن القمر كالشمس في الانتظام ( قُلْ ) يا رسول الله في جوابهم ( هِيَ مَواقِيتُ ) جمع ميقات بمعنى الوقت والزمان ( لِلنَّاسِ ) في عباداتهم ومعاملاتهم ( وَ ) ل ( الْحَجِ ) فمن أقرض إلى شهر أو باع ليقبض الثمن ، أو يدفع الثمن بعد شهرين ، أو أراد الصيام والإفطار أو الحج في أشهره لا بد وأن يكون له معلم يستند إليه ولذلك جعل الله الأهلة ، وهذا الجواب ينطبق على السؤال بناء على الوجه الثاني في معنى « يسألونك » وأما بناء على الوجه الأول وسؤالهم كان عن سبب اختلاف الأهلة ، فإن القرآن أعرض عن جوابهم لأن عقولهم ما كانت تتحمل الجواب الفلكي ، ولذا عبر عن ذلك إلى فائدة الأهلة التي هم أحوج إليها ، كما في آية أخرى ( يَسْئَلُونَكَ ما ذا يُنْفِقُونَ قُلْ ما أَنْفَقْتُمْ مِنْ خَيْرٍ فَلِلْوالِدَيْنِ ) (1) حيث أعرض عن جواب ماهية ( 1) البقرة : 216. وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا الْبُيُوتَ مِنْ ظُهُورِها وَلكِنَّ الْبِرَّ مَنِ اتَّقى وَأْتُوا الْبُيُوتَ مِنْ أَبْوابِها وَاتَّقُوا اللهَ لَعَلَّكُمْ تُفْلِحُونَ (189) وَقاتِلُوا فِي سَبِيلِ اللهِ الَّذِينَ يُقاتِلُونَكُمْ المنفق أي محل الإنفاق لأن هذا هو الذي يترتب عليه الفائدة وهم بحاجة إليه ، وحيث ذكر الحج في الكلام انتقل السياق إلى ما كان يفعله الجاهليون من أنهم إذا أحرموا لم يدخلوا البيوت من أبوابها وإنما يدخلونها من ظهورها ، فنهى عن ذلك ، وفي هذا تلميح بأن السؤال عما لا يهمكم من الأهلة ، مثل إتيان البيوت من ظهورها وكالأكل من القفا ( وَلَيْسَ الْبِرُّ بِأَنْ تَأْتُوا ) تدخلوا ( الْبُيُوتَ مِنْ ظُهُورِها ) بأن تنقبوا البيوت وتدخلونها من النقب ( وَلكِنَّ الْبِرَّ مَنِ اتَّقى ) من الله سبحانه بإتيان أوامره واجتناب نواهيه ( وَأْتُوا الْبُيُوتَ مِنْ أَبْوابِها ) ولو في حال الإحرام ( وَاتَّقُوا اللهَ ) في أوامره ونواهيه ( لَعَلَّكُمْ تُفْلِحُونَ ) أي لكي تفلحوا بالوصول إلى السعادة الدنيوية والأخروية. [191] وهنا حكم آخر من أحكام الإسلام الكثيرة وهو القتال والجهاد ، ولقد كان بين هذا الحكم وبين « الحج » المتقدم مناسبة ، إذ المشركون قد منعوا الرسول صلى‌الله‌عليه‌وآله‌وسلم عن الحج عام الحديبية ، فكان على المسلمين أن يستعدوا للجهاد إن اقتضت الظروف ( وَقاتِلُوا ) أيها المسلمون ( فِي سَبِيلِ اللهِ ) لا لحب السيطرة والغلبة كما هو شأن ملوك الدنيا وزعمائها بل في سبيل إعلاء كلمة الله التي فيها سعادة البشر ( الَّذِينَ يُقاتِلُونَكُمْ ) وَلا تَعْتَدُوا إِنَّ اللهَ لا يُحِبُّ الْمُعْتَدِينَ (190) وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ وَلا تُقاتِلُوهُمْ لا كل آمن ، فمن ألقى سلاحه ، وسكن إلى محله ، فإن في قتاله إيجاد فوضى واضطراب لا داعي إليهما ( وَلا تَعْتَدُوا ) إذا قاتلتم من قاتلكم فإن القتال قتال دفاع ، فلا معنى للاعتداء وأنتم مرتبطون بالله الذي تقاتلون لأجله فلا يصح الاعتداء من أمثالكم ( إِنَّ اللهَ لا يُحِبُّ الْمُعْتَدِينَ ) فهو الذي يأمر بالعدل والإحسان ، فكيف يحب من اعتدى وبغى ؟.` },
            { text: "وَلَا تَأْكُلُوٓا۟ أَمْوَٰلَكُم بَيْنَكُم بِٱلْبَٰطِلِ وَتُدْلُوا۟ بِهَآ إِلَى ٱلْحُكَّامِ لِتَأْكُلُوا۟ فَرِيقًا مِّنْ أَمْوَٰلِ ٱلنَّاسِ بِٱلْإِثْمِ وَأَنتُمْ تَعْلَمُونَ", tafsir: `` },
            { text: "يَسْـَٔلُونَكَ عَنِ ٱلْأَهِلَّةِ قُلْ هِىَ مَوَٰقِيتُ لِلنَّاسِ وَٱلْحَجِّ وَلَيْسَ ٱلْبِرُّ بِأَن تَأْتُوا۟ ٱلْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلْبِرَّ مَنِ ٱتَّقَىٰ وَأْتُوا۟ ٱلْبُيُوتَ مِنْ أَبْوَٰبِهَا وَٱتَّقُوا۟ ٱللَّهَ لَعَلَّكُمْ تُفْلِحُونَ", tafsir: `` },
            { text: "وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمْ وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ", tafsir: `` },
            { text: "وَٱقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ وَٱلْفِتْنَةُ أَشَدُّ مِنَ ٱلْقَتْلِ وَلَا تُقَٰتِلُوهُمْ عِندَ ٱلْمَسْجِدِ ٱلْحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمْ فِيهِ فَإِن قَٰتَلُوكُمْ فَٱقْتُلُوهُمْ كَذَٰلِكَ جَزَآءُ ٱلْكَٰفِرِينَ", tafsir: `أي الذين يقاتلونكم ( حَيْثُ ثَقِفْتُمُوهُمْ ) أي وجدتموهم ( وَأَخْرِجُوهُمْ مِنْ حَيْثُ أَخْرَجُوكُمْ ) أي أخرجوهم من مكة كما أخرجوكم منها ، فمن قاتلكم قتلتموه ومن أخرجكم من دياركم أخرجتموه جزاء وفاقا ( وَالْفِتْنَةُ ) التي أثارها الكفار بتفتين المسلمين عن دينهم وإلقاء الارتياب والشك في قلوبهم ليجلبوهم إلى حظيرة الكفر بعد أن هداهم الله ( أَشَدُّ مِنَ الْقَتْلِ ) فالقتل يوجب ذهاب الدنيا والفتنة توجب ذهاب الدين ، فمن تقاتلونهم لا يستحقون عليكم أن يهرجوا بأن المسلمين يشهرون السلاح فإنهم يستحقون القتل لأنهم بدأوا بالقتال لأنهم فتنوا ، و روي أنها نزلت في مسلم قتل كافرا في الشهر الحرام فعابوا المؤمنين بذلك (1) ، فبين سبحانه أن الفتنة التي تصدر من الكفار أشد من القتل ( وَلا تُقاتِلُوهُمْ ) أي لا تقاتلوا ( 1) مجمع البيان : ج 2 ص 30. عِنْدَ الْمَسْجِدِ الْحَرامِ حَتَّى يُقاتِلُوكُمْ فِيهِ فَإِنْ قاتَلُوكُمْ فَاقْتُلُوهُمْ كَذلِكَ جَزاءُ الْكافِرِينَ (191) فَإِنِ انْتَهَوْا فَإِنَّ اللهَ غَفُورٌ رَحِيمٌ (192) وَقاتِلُوهُمْ حَتَّى لا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ فَإِنِ انْتَهَوْا فَلا عُدْوانَ إِلاَّ عَلَى الظَّالِمِينَ (193) الكافرين أيها المسلمون ( عِنْدَ الْمَسْجِدِ الْحَرامِ ) أي في الحرم ( حَتَّى يُقاتِلُوكُمْ فِيهِ ) ويبدءوا بالقتال ( فَإِنْ قاتَلُوكُمْ ) بدءوكم بالقتال في الحرم ( فَاقْتُلُوهُمْ ) هناك ( كَذلِكَ ) الذي مر من وجوب قتال الكفار حيث وجدوا إلى آخر ما ذكر ( جَزاءُ الْكافِرِينَ )` },
            { text: "فَإِنِ ٱنتَهَوْا۟ فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `عن الكفر بأن أسلموا ( فَإِنَّ اللهَ غَفُورٌ ) يغفر سيئاتهم حتى التي ارتكبوها قبل إسلامهم من القتال فالإسلام يجب ما قبله ( رَحِيمٌ ) بعباده المؤمنين.` },
            { text: "وَقَٰتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ ٱلدِّينُ لِلَّهِ فَإِنِ ٱنتَهَوْا۟ فَلَا عُدْوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ", tafsir: `أي الكفار الذين يقاتلوكم لا لأجل القصاص فقط بل ( حَتَّى لا تَكُونَ فِتْنَةٌ ) بأن لا يفتن المسلمون عن دينهم ( وَيَكُونَ الدِّينُ ) والطريقة ( لِلَّهِ ) فلا يبقى منهج لسواه بأن ينتصر الحق على الباطل وهذان هما الغاية من إيجاب الدفاع ( فَإِنِ انْتَهَوْا ) عن الكفر ( فَلا عُدْوانَ ) أي تعدي بالدفاع والقتال ( إِلَّا عَلَى الظَّالِمِينَ ) الباقين على كفرهم ، أي إذا انتهى المعتدون عن الفتنة والتعرض لدين الله والتعرض للمسلمين بالأذى والقتال فلا قتال معهم لأن القتال لا يكون إلا مع الظالمين ، وسمي « عدوانا » تشبيها كما قال سبحانه في الآية المقبلة : ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ ) . الشَّهْرُ الْحَرامُ بِالشَّهْرِ الْحَرامِ وَالْحُرُماتُ قِصاصٌ فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ (194) وَأَنْفِقُوا فِي سَبِيلِ اللهِ وَلا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ وَأَحْسِنُوا إِنَّ اللهَ يُحِبُّ الْمُحْسِنِينَ (195)` },
            { text: "ٱلشَّهْرُ ٱلْحَرَامُ بِٱلشَّهْرِ ٱلْحَرَامِ وَٱلْحُرُمَٰتُ قِصَاصٌ فَمَنِ ٱعْتَدَىٰ عَلَيْكُمْ فَٱعْتَدُوا۟ عَلَيْهِ بِمِثْلِ مَا ٱعْتَدَىٰ عَلَيْكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ مَعَ ٱلْمُتَّقِينَ", tafsir: `وهو ذو القعدة وذو الحجة والمحرم ورجب سميت هذه الأشهر حراما لتحريم القتال فيها ( بِالشَّهْرِ الْحَرامِ ) أي بمقابل الشهر الحرام فمن انتهك حرمة الشهر الحرام بالقتال فيه لم يحرم قتاله بل يقاتل ( وَالْحُرُماتُ قِصاصٌ ) كما أن الجروح قصاص فمن انتهك حرمة اقتص منه في نفس الشهر أو المكان الذي انتهكت حرمته ولذا يحارب المحارب في الحرم وفي الشهر الحرام ( فَمَنِ اعْتَدى عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدى عَلَيْكُمْ ) لا أزيد من ذلك وسمي اعتداء لأنه مثل الاعتداء فالتسمية إنما هي بالمجانسة ( وَاتَّقُوا اللهَ ) فلا تتجاوزوا الحدود ولا تبالغوا في القسوة والانتقام ( وَاعْلَمُوا أَنَّ اللهَ مَعَ الْمُتَّقِينَ ) فيأخذ بأيديهم في الدنيا ويسعدهم في الآخرة.` },
            { text: "وَأَنفِقُوا۟ فِى سَبِيلِ ٱللَّهِ وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ وَأَحْسِنُوٓا۟ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ", tafsir: `فإن الجهاد يحتاج إلى الإنفاق في تجهيز الجيش وهو من أعظم السبل ( وَلا تُلْقُوا بِأَيْدِيكُمْ ) أي لا تلقوا أنفسكم بأيديكم ( إِلَى التَّهْلُكَةِ ) بترك الإنفاق للجهاد حتى يتسلط عليكم العدو ( وَأَحْسِنُوا ) في إنفاقكم وجهادكم وسائر أموركم ( إِنَّ اللهَ يُحِبُّ الْمُحْسِنِينَ ) . [197] ثم يرجع السياق إلى أحكام الحج الذي ألمح إليه فيما سبق ، لأن وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ وَلا تَحْلِقُوا رُؤُسَكُمْ حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ فَمَنْ كانَ مِنْكُمْ مَرِيضاً أَوْ بِهِ أَذىً مِنْ رَأْسِهِ فَفِدْيَةٌ مِنْ صِيامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذا أَمِنْتُمْ فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ إِلَى الْحَجِّ الحج كان في مقام صلح الحديبية وحج النبي صلى‌الله‌عليه‌وآله‌وسلم ( وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ) أي ائتوا بها تماما وكاملا بإتيان مناسكهما قربة إلى الله تعالى لا لأجل رياء أو سمعة أو نحوهما ( فَإِنْ أُحْصِرْتُمْ ) بأن منعكم مانع عن الحج بعد ما أحرمتم فعليكم إذا أردتم التحلل عن الإحرام أن تقدموا أو تذبحوا ما ( اسْتَيْسَرَ ) أي ما أمكنكم ( مِنَ الْهَدْيِ ) الذي قدمتموه إلى الله ، والهدي هو البقر أو الإبل أو الغنم ( وَلا تَحْلِقُوا رُؤُسَكُمْ ) وهو كناية عن التحلل عن الأجسام أي لا تحلقوا ( حَتَّى يَبْلُغَ الْهَدْيُ مَحِلَّهُ ) الذي قرر في الشريعة من محل الحصى أو مكة أو منى كما فصل في الفقه ( فَمَنْ كانَ مِنْكُمْ مَرِيضاً ) لا يتمكن من أن لا يحلق ( أَوْ بِهِ أَذىً مِنْ رَأْسِهِ ) كأن قمل رأسه فيتأذى من هوائه فلا يتمكن من عدم الحلق فعليه إذا حلق قبل أن يبلغ الهدي محله فدية يقدمها بدل حلقه ( مِنْ صِيامٍ ) ثلاثة أيام ( أَوْ صَدَقَةٍ ) لستة مساكين ( أَوْ نُسُكٍ ) أي شاة يذبحها لأجل تعجيله في الحلق ( فَإِذا أَمِنْتُمْ ) من العدو الصاد وكذلك شفيتم من المرض وزال المانع ( فَمَنْ تَمَتَّعَ ) أي استمتع بالطيب والنساء وسائر الملذات التي يحرمها الإحرام بسبب إتيانه ( الْعُمْرَةَ ) فإن العمرة تنتهي سريعا فتحل المحرمات ( إِلَى الْحَجِ ) أي يكون تمتعه بالملذات إلى أن يحرم فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ فَمَنْ لَمْ يَجِدْ فَصِيامُ ثَلاثَةِ أَيَّامٍ فِي الْحَجِّ وَسَبْعَةٍ إِذا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كامِلَةٌ ذلِكَ لِمَنْ لَمْ يَكُنْ أَهْلُهُ حاضِرِي الْمَسْجِدِ الْحَرامِ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ شَدِيدُ الْعِقابِ (196) للحج فعليه ما ( اسْتَيْسَرَ ) أي ما تمكن عليه ( مِنَ الْهَدْيِ ) إبل أو بقر أو شاة يجب عليه ذبحها في منى أيام العيد ( فَمَنْ لَمْ يَجِدْ ) الهدي فعليه صيام ( ثَلاثَةِ أَيَّامٍ فِي ) أيام ( الْحَجَ ) من ذي الحجة ( وَسَبْعَةٍ ) أيام ( إِذا رَجَعْتُمْ ) إلى بلادكم ( تِلْكَ عَشَرَةٌ كامِلَةٌ ) تكون بدلا عن الهدي ( ذلِكَ ) التمتع الذي يكون عمرته مقدمة على حجه فرض ( لِمَنْ لَمْ يَكُنْ أَهْلُهُ حاضِرِي الْمَسْجِدِ الْحَرامِ ) من كان في أطراف الحرم من كل جانب أثني عشر ميلا أو نحوه على خلاف ، أما من كان أهله حاضري المسجد الحرام بأن كان محله عند أقل من ذلك ففرضه القرآن أو الإفراد وفي كليهما يقدم الحج على العمرة ، والفرق بينهما أن القارن يعقد إحرامه بسوق الهدي دون المفرد ( وَاتَّقُوا اللهَ ) في أحكامه أيها المسلمون ( وَاعْلَمُوا أَنَّ اللهَ شَدِيدُ الْعِقابِ ) فلا تخالفوا أوامره ونواهيه. والحج يشتمل على فرضين : ( عمرة ) هي : « الإحرام والتلبية » ، « والطواف بالبيت » ، « صلاة الطواف » ، « والسعي بين الصفا والمروة » ، « والتقصير » . و ( حج ) هو : « الإحرام » ، « والوقوف بعرفات » ، « الوقوف بالمشعر » ، « الإفاضة إلى منى » ، « رمي جمرة العقبة » ، « نحر أو ذبح » ، « حلق أو تقصير » ، طواف الحج وصلاته وسعي وتقصير وطواف النساء وصلاته « طواف النساء » ، « صلاة طواف النساء » ، « السعي بين الصفا والمروة » ، « طواف الْحَجُّ أَشْهُرٌ مَعْلُوماتٌ الزيارة » ، « صلاة طواف الزيارة » ، « المبيت بمنى ليلة الحادي عشر والثاني عشر » ، « رمي الجمار الثلاث يومي الحادي عشر والثاني عشر » ، وقد أشار الشيخ البهائي إلى هذه الأعمال في بيته المشهور أطرست للعمرة اجعل نهج أو وأرنحط رسطر مر : لحج (1)` },
            { text: "وَأَتِمُّوا۟ ٱلْحَجَّ وَٱلْعُمْرَةَ لِلَّهِ فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ وَلَا تَحْلِقُوا۟ رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ ٱلْهَدْىُ مَحِلَّهُۥ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِۦٓ أَذًى مِّن رَّأْسِهِۦ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ فَإِذَآ أَمِنتُمْ فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ فَمَن لَّمْ يَجِدْ فَصِيَامُ ثَلَٰثَةِ أَيَّامٍ فِى ٱلْحَجِّ وَسَبْعَةٍ إِذَا رَجَعْتُمْ تِلْكَ عَشَرَةٌ كَامِلَةٌ ذَٰلِكَ لِمَن لَّمْ يَكُنْ أَهْلُهُۥ حَاضِرِى ٱلْمَسْجِدِ ٱلْحَرَامِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ", tafsir: `` },
            { text: "ٱلْحَجُّ أَشْهُرٌ مَّعْلُومَٰتٌ فَمَن فَرَضَ فِيهِنَّ ٱلْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِى ٱلْحَجِّ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ يَعْلَمْهُ ٱللَّهُ وَتَزَوَّدُوا۟ فَإِنَّ خَيْرَ ٱلزَّادِ ٱلتَّقْوَىٰ وَٱتَّقُونِ يَٰٓأُو۟لِى ٱلْأَلْبَٰبِ", tafsir: `في ( أَشْهُرٌ مَعْلُوماتٌ ) أو أشهر الحج أشهر معلومات وهو شوال وذو القعدة وذو الحجة فلا يجوز تأخيره منها كما كان الجاهلون ( 1) الالف : الإحرام لعمرة التمتّع عن حجّة الإسلام. الطاء : طواف العمرة. الراء : ركعتان صلوات طواف لعمرة التمتّع. السين : السعي بين الصّفا والمروة عن عمرة التمتع. التاء : التقصير عن عمرة التمتع لحجّة الإسلام فهناك اعمال العمرة لحجّ التمتع. الألف : الإحرام لحجّ التمتّع. الواو الأول : الوقوف بعرفات في 9 من ذيحجة لحجّ التمتّع. الواو الثاني : الوقوف في مشعر الحرام ليلة العيد الى الصبح لحج التمتع. الالف : الإفاضة إلى منى يوم العيد. الراء : رمي جمرة للعقبة في يوم العيد لحج التمتّع. النون : نحر إبل أو ذبيحة لحج التمتّع. الحاء : الحلق في يوم العيد لحج التمتّع. الطاء : الطواف عن حجّة الإسلام. الراء : رمي الجمرات الثلاثة في يوم الحادي عشر من ذي حجة عن حج التمتّع. السين : السعي بين الصفا والمروة لحج التمتّع. الطاء : طواف النساء. الراء : رمي الجمرات الثلاثة في يوم الثاني عشر من ذي حجة عن حج التمتّع. الميم : المبيت في منى ثلاثة ليال عن حج التمتّع. ولا يخفى أنّ جملة ( مر لحج ) التي أتى بها البهائي ( رحمه‌الله ) تكون لتكملة الشعر فلا تدخل فيما أردناها من المناسك. فَمَن فَرَضَ فِيهِنَّ الْحَجَّ فَلاَ رَفَثَ وَلاَ فُسُوقَ وَلاَ جِدَالَ فِي الْحَجِّ وَمَا تَفْعَلُواْ مِنْ خَيْرٍ يَعْلَمْهُ اللّهُ وَتَزَوَّدُواْ فَإِنَّ خَيْرَ الزَّادِ التَّقْوَى وَاتَّقُونِ يَا أُوْلِي الأَلْبَابِ (197) لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن يفعلون حيث يؤخرون الحج ، ونزل فيهم ( إِنَّمَا النَّسِيءُ زِيادَةٌ فِي الْكُفْرِ ) (1) ( فَمَنْ فَرَضَ ) على نفسه ( فِيهِنَ ) أي في هذه الأشهر ( الْحَجُ ) فليعلم أنه لا ( رَفَثَ ) وهو الجماع ( وَلا فُسُوقَ ) وهو السباب والمفاخرة ( وَلا جِدالَ ) قول لا والله وبلى والله ( فِي الْحَجِ ) أي في حال الإحرام ( وَما تَفْعَلُوا مِنْ خَيْرٍ ) في الحج وغيره ( يَعْلَمْهُ اللهُ ) ولعل ذكره هنا لكثرة احتياج الحجاج بعضهم إلى بعض في مختلف الشؤون فأريد التنبيه بأن كل خير يصدر من الإنسان إنما هو بعلم الله سبحانه فيجازيه على ذلك ( وَتَزَوَّدُوا ) من الحج زادا للروح ( فَإِنَّ خَيْرَ الزَّادِ التَّقْوى ) وهو يحصل بكثرة هائلة في الحج حيث التجرد والكف عن الملذات ومقامات الشدائد والصعوبات ، ويحتمل أنها نزلت فيمن لم يكن يأخذ الزاد للحج بادعاء أنه ضيف الله ثم ليستعطي في الطريق فأمر بأخذ الزاد فإنه قرين بالتقوى دون الاستعطاء الذي فيه منقصة وذلة وحرمة أحيانا ( وَاتَّقُونِ ) أي خافوني في أعمالكم فلا تغفلوا ولا تتركوا واجبا ( يا أُولِي الْأَلْبابِ ) أي يا أصحاب العقول. [199] كانوا يتأثمون بالتجارة في الحج فنزلت ( لَيْسَ عَلَيْكُمْ جُناحٌ أَنْ ( 1) التوبة : 37. تَبْتَغُواْ فَضْلاً مِّن رَّبِّكُمْ فَإِذَا أَفَضْتُم مِّنْ عَرَفَاتٍ فَاذْكُرُواْ اللّهَ عِندَ الْمَشْعَرِ الْحَرَامِ وَاذْكُرُوهُ كَمَا هَدَاكُمْ وَإِن كُنتُم مِّن قَبْلِهِ لَمِنَ الضَّآلِّينَ (198) ثُمَّ أَفِيضُواْ مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُواْ اللّهَ إِنَّ اللّهَ غَفُورٌ رَّحِيمٌ (199) فَإِذَا قَضَيْتُم مَّنَاسِكَكُمْ تَبْتَغُوا فَضْلاً مِنْ رَبِّكُمْ ) بالاتجار فإنه ليس بمحرم ( فَإِذا أَفَضْتُمْ ) منها كما يندفع الماء نحو الوهاد فإن الحجاج يندفعون كالسيل ( مِنْ عَرَفاتٍ فَاذْكُرُوا اللهَ عِنْدَ الْمَشْعَرِ الْحَرامِ ) وهو الموقف الثاني ووقته بين طلوع الفجر وطلوع الشمس من يوم العيد ( وَاذْكُرُوهُ كَما هَداكُمْ ) أي بإزاء هدايته سبحانه إياكم لدينه وما يسعدكم في الدنيا والآخرة ( وَإِنْ كُنْتُمْ مِنْ قَبْلِهِ ) أي قبل الهدي ( لَمِنَ الضَّالِّينَ ) عن دينه.` },
            { text: "لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا۟ فَضْلًا مِّن رَّبِّكُمْ فَإِذَآ أَفَضْتُم مِّنْ عَرَفَٰتٍ فَٱذْكُرُوا۟ ٱللَّهَ عِندَ ٱلْمَشْعَرِ ٱلْحَرَامِ وَٱذْكُرُوهُ كَمَا هَدَىٰكُمْ وَإِن كُنتُم مِّن قَبْلِهِۦ لَمِنَ ٱلضَّآلِّينَ", tafsir: `` },
            { text: "ثُمَّ أَفِيضُوا۟ مِنْ حَيْثُ أَفَاضَ ٱلنَّاسُ وَٱسْتَغْفِرُوا۟ ٱللَّهَ إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `من المشعر إلى منى ( مِنْ حَيْثُ أَفاضَ النَّاسُ ) من قبلكم إبراهيم عليه‌السلام وذريته ( وَاسْتَغْفِرُوا اللهَ ) اطلبوا غفرانه وعفوه ( إِنَّ اللهَ غَفُورٌ رَحِيمٌ ) هكذا يقتضي نظم الآية ، لكن ورد أن قريشا لا يقفون بعرفات ولا يفيضون منه ويقولون نحن أهل حرم الله فلا نخرج منه فيقفون بالمشعر ويفيضون منه ، فأمرهم الله أن يقفوا بعرفات ويفيضوا منه كسائر الناس.` },
            { text: "فَإِذَا قَضَيْتُم مَّنَٰسِكَكُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَذِكْرِكُمْ ءَابَآءَكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا وَمَا لَهُۥ فِى ٱلْـَٔاخِرَةِ مِنْ خَلَٰقٍ", tafsir: `أي أديتم أعمالكم فالمناسك جمع منسك فَاذْكُرُواْ اللّهَ كَذِكْرِكُمْ آبَاءكُمْ أَوْ أَشَدَّ ذِكْرًا فَمِنَ النَّاسِ مَن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا وَمَا لَهُ فِي الآخِرَةِ مِنْ خَلاَقٍ (200) وِمِنْهُم مَّن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ (201) أُولَـئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُواْ وهو مصدر ميمي بمعنى العمل ( فَاذْكُرُوا اللهَ كَذِكْرِكُمْ آباءَكُمْ أَوْ أَشَدَّ ذِكْراً ) فإن أهل الجاهلية كانوا إذا فرغوا من الحج يجتمعون هناك ويعدون مفاخر آبائهم ومآثرهم ويذكرون أيامهم القديمة وأياديهم الجسيمة فأمرهم الله أن يذكروه عوض ذكرهم آبائهم ، بل يجب أن يذكروه أكثر وأحسن من ذكر آبائهم فهو المنعم الحقيقي الذي بيده كل شيء ومنه كل خير ، وهنا يكون المجال واسعا لبيان نموذجين من الناس منهم من يريد الآخرة ومنهم من يريد الدنيا ولذا قال تعالى : ( فَمِنَ النَّاسِ مَنْ يَقُولُ رَبَّنا آتِنا فِي الدُّنْيا ) أي أعطنا من نعيمها ورفاهها وسعادتها ولا يسأل نعيم الآخرة لأنه غير مؤمن بها إذ كان الحج قبل الإسلام عامّا للمعتقد والمنكر ( وَما لَهُ فِي الْآخِرَةِ مِنْ خَلاقٍ ) أي نصيب.` },
            { text: "وَمِنْهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِى ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ حَسَنَةً وَقِنَا عَذَابَ ٱلنَّارِ", tafsir: `أي من الناس ( مَنْ يَقُولُ رَبَّنا آتِنا فِي الدُّنْيا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنا ) من وقى يقي أي احفظنا من ( عَذابَ النَّارِ ) فهو يسأل نعيم الدنيا ونعيم الآخرة ويتعوذ بالله من النار.` },
            { text: "أُو۟لَٰٓئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا۟ وَٱللَّهُ سَرِيعُ ٱلْحِسَابِ", tafsir: `يسألون خير الدنيا والآخرة ( لَهُمْ نَصِيبٌ مِمَّا كَسَبُوا ) لأنهم يستحقون ثواب أعمالهم بخلاف الطائفة الأولى فإن كفرهم يمنع وَاللّهُ سَرِيعُ الْحِسَابِ (202) وَاذْكُرُواْ اللّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلاَ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلا إِثْمَ عَلَيْهِ لِمَنِ اتَّقَى وَاتَّقُواْ اللّهَ وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ (203) وَمِنَ النَّاسِ مَن يُعْجِبُكَ قَوْلُهُ فِي الْحَيَاةِ الدُّنْيَا عن ثوابهم ( وَاللهُ سَرِيعُ الْحِسابِ ) فلا يظن الإنسان أن الآخرة بعيدة فإنه لا تمر الأيام والليالي إلا والشخص دفين في التراب وإن طال عمره في الدنيا.` },
            { text: "وَٱذْكُرُوا۟ ٱللَّهَ فِىٓ أَيَّامٍ مَّعْدُودَٰتٍ فَمَن تَعَجَّلَ فِى يَوْمَيْنِ فَلَآ إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَآ إِثْمَ عَلَيْهِ لِمَنِ ٱتَّقَىٰ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ", tafsir: `أيها الحجاج ( فِي أَيَّامٍ مَعْدُوداتٍ ) وهي أيام التشريق في منى ( فَمَنْ تَعَجَّلَ ) النفر إلى مكة من منى ( فِي يَوْمَيْنِ ) بأن نفر يوم الثاني عشر ( فَلا إِثْمَ عَلَيْهِ ) فإنه يجوز النفر بعد زوال الثاني عشر ( وَمَنْ تَأَخَّرَ ) في النفر فنفر في الثالث عشر ( فَلا إِثْمَ عَلَيْهِ ) فيجوز كل من الأمرين ( لِمَنِ اتَّقى ) الصيد في إحرامه وإلا فإن صاد وجب عليه النفر الثاني فلا يجوز أن ينفر في الثاني عشر ( وَاتَّقُوا اللهَ ) فيما أمركم ونهاكم ( وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ ) الحشر هو الجمع والمعنى تجمعون إلى حكم الله وجزائه يوم القيامة. [205] ثم يلتفت السياق إلى الإنسان طالحه وصالحه ، ويبين خصائص البشر ، ليعطي درسا لمن أراد الصلاح والرشاد فيقول سبحانه : ( وَمِنَ النَّاسِ مَنْ يُعْجِبُكَ قَوْلُهُ ) للباقته وفصاحته وكلامه المعسول فتستحسن كلامه وتصغي إلى بيانه ( فِي الْحَياةِ الدُّنْيا ) أما متعلق ب « قوله » ، أي وَيُشْهِدُ اللّهَ عَلَى مَا فِي قَلْبِهِ وَهُوَ أَلَدُّ الْخِصَامِ (204) وَإِذَا تَوَلَّى سَعَى فِي الأَرْضِ لِيُفْسِدَ فِيِهَا وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ وَاللّهُ لاَ يُحِبُّ الفَسَادَ (205) وَإِذَا قِيلَ لَهُ اتَّقِ اللّهَ أَخَذَتْهُ الْعِزَّةُ بِالإِثْمِ فَحَسْبُهُ جَهَنَّمُ وَلَبِئْسَ الْمِهَادُ (206) قوله في شؤون الدنيا معجب ، أو متعلق ب « يعجبك » أي أن إعجابك إنما هو في الدنيا ، والأول أقرب ( وَيُشْهِدُ اللهَ عَلى ما فِي قَلْبِهِ ) كما هو شأن المنافقين أبدا فإنهم حيث يرون نفاقهم يظنون أن الناس مطلعون على سرائرهم فيؤكدون بأنهم مخلصون وأن ما في قلبهم يطابق ما على لسانهم ( وَهُوَ أَلَدُّ الْخِصامِ ) الألد هو شديد الخصومة والخصام جمع يعني أنه من أكبر خصمائك في الباطن.` },
            { text: "وَمِنَ ٱلنَّاسِ مَن يُعْجِبُكَ قَوْلُهُۥ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَيُشْهِدُ ٱللَّهَ عَلَىٰ مَا فِى قَلْبِهِۦ وَهُوَ أَلَدُّ ٱلْخِصَامِ", tafsir: `` },
            { text: "وَإِذَا تَوَلَّىٰ سَعَىٰ فِى ٱلْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ ٱلْحَرْثَ وَٱلنَّسْلَ وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ", tafsir: `وأدبر وذهب من عندك ( سَعى فِي الْأَرْضِ ) من هنا إلى هناك كما هو شأن المشاغب المفسد ( لِيُفْسِدَ فِيها ) بإثارة الفوضى والاضطراب ( وَيُهْلِكَ الْحَرْثَ ) أي الزراعة ( وَالنَّسْلَ ) أي الأولاد والذرية فإن إثارة الفوضى يوجب خراب الزراعات لاشتغال أهلها بالكفاح ، وفناء النسل إذ الشباب دائما يقدمون على الحرب والجلاء ( وَاللهُ لا يُحِبُّ الْفَسادَ ) .` },
            { text: "وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتْهُ ٱلْعِزَّةُ بِٱلْإِثْمِ فَحَسْبُهُۥ جَهَنَّمُ وَلَبِئْسَ ٱلْمِهَادُ", tafsir: `في عملك فلا تفسد ( أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ ) أي حملته عزة وحمية الجاهلية بأن يأثم لأنه لا يرضخ للحق ولا يعتني به ( فَحَسْبُهُ جَهَنَّمُ ) أي تمكينه جهنم جزاء له ( وَلَبِئْسَ الْمِهادُ ) أي محل القرار ، وهذه الآيات نزلت في المنافقين أو في فرد خاص منهم يسمى وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ ابْتِغاءَ مَرْضاتِ اللهِ وَاللهُ رَؤُفٌ بِالْعِبادِ (207) يا أَيُّهَا الَّذِينَ آمَنُوا ادْخُلُوا فِي السِّلْمِ كَافَّةً وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ (208) الأخنس بن شريق ، كان يظهر المحبة للنبي ويبطن الفساد والنفاق ، ولعل وجه ارتباط هذه الآيات بالحج أن الكلام انتهى هناك حول من يفتخر بالآباء اعتزازا بالنفس وهذا مثلهم في الاعتزاز والاغترار.` },
            { text: "وَمِنَ ٱلنَّاسِ مَن يَشْرِى نَفْسَهُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَٱللَّهُ رَءُوفٌۢ بِٱلْعِبَادِ", tafsir: `أي بعض الناس ( مَنْ يَشْرِي ) أي يبيع فإن كلا من البيع والشراء يجيء بمعنى الآخر ( نَفْسَهُ ابْتِغاءَ مَرْضاتِ اللهِ ) أي لأجل طلب رضاه سبحانه ( وَاللهُ رَؤُفٌ بِالْعِبادِ ) يرأف بهم فيجازيهم لعملهم الحسن ، ولعل ذكر الرأفة لأجل أن هذا البيع يحتوي على أخطاء وأضرار ، ففيه تنبيه إلى أن الله رؤف يجنب البائع الأخطار والإضرار ، وهذه الآية نزلت في الإمام أمير المؤمنين علي بن أبي طالب عليه‌السلام حين نام في فراش الرسول صلى‌الله‌عليه‌وآله‌وسلم ليلة الهجرة. [209] وحين ذكر أن من الناس من هو منافق ناسب الإرشاد العام فقال سبحانه ( يا أَيُّهَا الَّذِينَ آمَنُوا ) باللسان ( ادْخُلُوا فِي السِّلْمِ ) مع الله ورسوله في جميع أموركم ( كَافَّةً ) أي جميعا فاستسلموا للدين في جميع شؤونكم ( وَلا تَتَّبِعُوا خُطُواتِ الشَّيْطانِ ) بأن تخالفوا أمر الله سبحانه وتتبعوا أمر الشيطان وما يوحي اليه الهوى ( إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ ) أي عدو ظاهر لأنه يأمر بالمفاسد التي ترجع إلى ذهاب دينكم ودنياكم. فَإِنْ زَلَلْتُمْ مِنْ بَعْدِ ما جاءَتْكُمُ الْبَيِّناتُ فَاعْلَمُوا أَنَّ اللهَ عَزِيزٌ حَكِيمٌ (209) هَلْ يَنْظُرُونَ إِلاَّ أَنْ يَأْتِيَهُمُ اللهُ فِي ظُلَلٍ مِنَ الْغَمامِ وَالْمَلائِكَةُ وَقُضِيَ الْأَمْرُ وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ (210) سَلْ بَنِي إِسْرائِيلَ كَمْ آتَيْناهُمْ مِنْ آيَةٍ بَيِّنَةٍ` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱدْخُلُوا۟ فِى ٱلسِّلْمِ كَآفَّةً وَلَا تَتَّبِعُوا۟ خُطُوَٰتِ ٱلشَّيْطَٰنِ إِنَّهُۥ لَكُمْ عَدُوٌّ مُّبِينٌ", tafsir: `` },
            { text: "فَإِن زَلَلْتُم مِّنۢ بَعْدِ مَا جَآءَتْكُمُ ٱلْبَيِّنَٰتُ فَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ", tafsir: `تشبيه للذنب بمن يزل له قدم ( مِنْ بَعْدِ ما جاءَتْكُمُ الْبَيِّناتُ ) الأدلة الواضحة على الحق ( فَاعْلَمُوا أَنَّ اللهَ عَزِيزٌ ) فلا يمتنع عليه العذاب والعقاب بمن زل ( حَكِيمٌ ) في فعله ليعفوا عمن يشاء ويعذب من يشاء. [211] وهنا يعود السياق إلى من تأخذه العزة فيقول سبحانه ( هَلْ يَنْظُرُونَ ) النظر بمعنى الانتظار أي هل ينتظر هؤلاء المنافقون ( إِلَّا أَنْ يَأْتِيَهُمُ اللهُ ) حتى يؤمنوا ويقلعوا عن نفاقهم وكفرهم ( فِي ظُلَلٍ مِنَ الْغَمامِ ) ظلل جمع ظلة وهي ما يستظل به من الشمس وسمي السحاب ظلة لأنه يستظل به من الشمس ، والغمام هو السحاب وقد كانت اليهود تزعم أن الله ينزل في ظلل من الغمام وكذلك الملائكة معه ولذا قال : ( وَالْمَلائِكَةُ ) عطفا على « الله » ( وَقُضِيَ الْأَمْرُ ) أي يوم تغيير الكون عن وضعه لا يبقى بعد مجال للتكليف إنما هو يوم القيامة ( وَإِلَى اللهِ تُرْجَعُ الْأُمُورُ ) ويكون ذلك اليوم يوم حساب وعقاب وثواب ، لا يوم عمل وشغل ، فالآية تشير إلى أساطير أهل الكتاب متهكما ساخرا ، ثم يهدد ويوعد بأن الأمر يقضي فلا مجال بعد التكليف. [212] وحيث أشير إلى أسطورة إسرائيلية ، توجه السياق إلى تأنيب بني إسرائيل الذين كانوا يعاندون في إنكارهم للآيات ( سَلْ بَنِي إِسْرائِيلَ كَمْ آتَيْناهُمْ مِنْ آيَةٍ بَيِّنَةٍ ) أي أعطيناهم أدلة واضحة ومع ذلك عاندوا وَمَن يُبَدِّلْ نِعْمَةَ اللّهِ مِن بَعْدِ مَا جَاءتْهُ فَإِنَّ اللّهَ شَدِيدُ الْعِقَابِ (211) زُيِّنَ لِلَّذِينَ كَفَرُواْ الْحَيَاةُ الدُّنْيَا وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُواْ وَالَّذِينَ اتَّقَواْ فَوْقَهُمْ يَوْمَ الْقِيَامَةِ وَاللّهُ يَرْزُقُ مَن يَشَاء بِغَيْرِ حِسَابٍ (212) كَانَ النَّاسُ أُمَّةً وَاحِدَةً فَبَعَثَ ولم يؤمنوا ( وَمَنْ يُبَدِّلْ نِعْمَةَ اللهِ ) كفرا فلا يؤمن بآياته ( مِنْ بَعْدِ ما جاءَتْهُ فَإِنَّ اللهَ شَدِيدُ الْعِقابِ ) فليهيئ نفسه لعقابه.` },
            { text: "هَلْ يَنظُرُونَ إِلَّآ أَن يَأْتِيَهُمُ ٱللَّهُ فِى ظُلَلٍ مِّنَ ٱلْغَمَامِ وَٱلْمَلَٰٓئِكَةُ وَقُضِىَ ٱلْأَمْرُ وَإِلَى ٱللَّهِ تُرْجَعُ ٱلْأُمُورُ", tafsir: `` },
            { text: "سَلْ بَنِىٓ إِسْرَٰٓءِيلَ كَمْ ءَاتَيْنَٰهُم مِّنْ ءَايَةٍۭ بَيِّنَةٍ وَمَن يُبَدِّلْ نِعْمَةَ ٱللَّهِ مِنۢ بَعْدِ مَا جَآءَتْهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلْعِقَابِ", tafsir: `` },
            { text: "زُيِّنَ لِلَّذِينَ كَفَرُوا۟ ٱلْحَيَوٰةُ ٱلدُّنْيَا وَيَسْخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ ٱتَّقَوْا۟ فَوْقَهُمْ يَوْمَ ٱلْقِيَٰمَةِ وَٱللَّهُ يَرْزُقُ مَن يَشَآءُ بِغَيْرِ حِسَابٍ", tafsir: `أي الحياة القريبة مقابل الحياة البعيدة وهي الآخرة والتي زينها لهم هي مجموعة عوامل بعضها حق وبعضها باطل فإن الحياة التي خلقها الله جميلة تزين نفسها كما أن الشيطان والنفس والهوى تزين الحياة لتصرف الناس عن الآخرة ( وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُوا ) حيث يرونهم منصرفين عنها مقبلين إلى الآخرة ـ التي لا يعتقد هؤلاء الكفار بها ـ ( وَالَّذِينَ اتَّقَوْا ) من المؤمنين ( فَوْقَهُمْ ) أي فوق هؤلاء الكفار منزلة ومقاما ورتبة ( يَوْمَ الْقِيامَةِ ) لأنهم عملوا لها فأدركوا خيرها والكفار لم يعملوا فيبقون هناك سائلين ( وَاللهُ يَرْزُقُ مَنْ يَشاءُ بِغَيْرِ حِسابٍ ) فالرزق في الدنيا ليس بالكفر والتوجه إليها حتى يحرم أهل الآخرة منها بل الرزق يصيب الكافر والمؤمن ، فالمؤمن منعم في الدنيا وفوق الكافر في الآخرة. [214] إن كل حركة إصلاحية لا بد وأن تشق صفوف الناس المتصافقة على الفساد وهكذا كان بعث الأنبياء عليهم‌السلام فقد ( كانَ النَّاسُ أُمَّةً واحِدَةً فَبَعَثَ اللّهُ النَّبِيِّينَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ الْكِتَابَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ النَّاسِ فِيمَا اخْتَلَفُواْ فِيهِ وَمَا اخْتَلَفَ فِيهِ إِلاَّ الَّذِينَ أُوتُوهُ مِن بَعْدِ مَا جَاءتْهُمُ الْبَيِّنَاتُ بَغْيًا بَيْنَهُمْ فَهَدَى اللّهُ الَّذِينَ آمَنُواْ لِمَا اخْتَلَفُواْ فِيهِ مِنَ الْحَقِّ بِإِذْنِهِ وَاللّهُ يَهْدِي مَن يَشَاء إِلَى صِرَاطٍ مُّسْتَقِيمٍ (213) للهُ النَّبِيِّينَ مُبَشِّرِينَ ) لمن آمن وأصلح ( وَمُنْذِرِينَ ) لمن كفر أو عصى ( وَأَنْزَلَ مَعَهُمُ الْكِتابَ بِالْحَقِ ) قيد توضيحي إذ كل إنزال من الله بالحق وإنما أكد لمقابلته لسائر الكتب التي ترسلها رؤساء الحكومات إلى رعاياها فإن منها ما هو حق ومنها ما هو باطل ( لِيَحْكُمَ ) ذات الكتاب ( بَيْنَ النَّاسِ فِيمَا اخْتَلَفُوا فِيهِ ) من أمور معاملاتهم وسائر معاشراتهم والاختلاف هنا لا ينافي كون الناس أمة واحدة إذ وحدة الأمة تجتمع مع هذا النوع من الاختلاف ثم صار نفس الكتاب محلا لاختلاف الأمة فيه ، لكن هذا الاختلاف ليس عن واقع وشك ، لأن الكتاب واضح بل عن حسد وبغي وطمع ( وَمَا اخْتَلَفَ فِيهِ ) أي في الكتاب بأن فسره كل حسب نظره وهواه ( إِلَّا الَّذِينَ أُوتُوهُ ) أي الأمة التي أعطيت الكتاب ( مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّناتُ ) أي الأدلة الواضحة على معاني الكتاب ( بَغْياً بَيْنَهُمْ ) أي الاختلاف إنما نشأ من البغي والظلم والحسد الحاصل بينهم ( فَهَدَى اللهُ الَّذِينَ آمَنُوا ) حقيقة وأرادوا اتباع أحكام الله واقعا ( لِمَا اخْتَلَفُوا فِيهِ مِنَ الْحَقِ ) أي للشيء الذي اختلفت الأمة فيه ( بِإِذْنِهِ ) أي بلطفه بهم حيث هداهم ( وَاللهُ يَهْدِي مَنْ يَشاءُ إِلى صِراطٍ مُسْتَقِيمٍ ) إما أَمْ حَسِبْتُمْ أَنْ تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا مِنْ قَبْلِكُمْ مَسَّتْهُمُ الْبَأْساءُ وَالضَّرَّاءُ وَزُلْزِلُوا حَتَّى يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتى نَصْرُ اللهِ أَلا إِنَّ نَصْرَ اللهِ قَرِيبٌ (214) معناه الإيصال إلى المطلوب وهو ليس بواجب بالنسبة إلى الجميع وإما معناه إرائة الطريق ومعنى من يشاء إنه لو لم يشأ لا يهدي أحد ، إذ الهداية لا تكون إلا بإرسال الرسل ، والأول أنسب بالسياق. [215] ثم يسأل الله المؤمنين الذين وقعوا في متاعب هذا الخلاف حيث يحاربونهم الكفار لأجل أنهم اهتدوا بهدي الله ( أَمْ حَسِبْتُمْ ) أي بل حسبتم وظننتم أيها المسلمون ( أَنْ تَدْخُلُوا الْجَنَّةَ ) اعتباطا وبلا مشقة وحرج ( وَلَمَّا يَأْتِكُمْ مَثَلُ الَّذِينَ خَلَوْا ) أي مضوا ( مِنْ قَبْلِكُمْ ) أي لم يأتكم بعد امتحان مثل امتحان الأمم المؤمنة السالفة الذين ثبتوا وصبروا تجاه الأحزان والكوارث وإنما قال « مثل » لأنهم صاروا مثلا للصبر وتحمل المكاره ( مَسَّتْهُمُ ) أي لمستهم ( الْبَأْساءُ ) الفقر ( وَالضَّرَّاءُ ) المرض والحرج وأشباههما ( وَزُلْزِلُوا ) أي حركوا بأنواع المحن والبلايا ( حَتَّى ) وصل الحال إلى أن ( يَقُولَ الرَّسُولُ ) لتلك الأمم ( وَالَّذِينَ آمَنُوا مَعَهُ مَتى نَصْرُ اللهِ ) استعجالا للنصر الموعود وتمنيا للخلاص من الشدائد والمحن ، فاستدرك الأمر وأجيب سؤالهم بأنه ( أَلا إِنَّ نَصْرَ اللهِ قَرِيبٌ ) وهذا جواب طبيعي يقوله الرسول صلى‌الله‌عليه‌وآله‌وسلم والمؤمنون كلما رأوا البلاء والمحن ، وفي الآية تعبير المؤمنين وأنهم إنما يفوزون بسعادة الدنيا والآخرة بعد مثل هذه الكوارث والمتاعب. [216] ويأتي هنا دور أسئلة وجهت إلى الرسول صلى‌الله‌عليه‌وآله‌وسلم أجاب عنها القرآن يَسْئَلُونَكَ ما ذا يُنْفِقُونَ قُلْ ما أَنْفَقْتُمْ مِنْ خَيْرٍ فَلِلْوالِدَيْنِ وَالْأَقْرَبِينَ وَالْيَتامى وَالْمَساكِينِ وَابْنِ السَّبِيلِ وَما تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللهَ بِهِ عَلِيمٌ (215) كُتِبَ عَلَيْكُمُ الْقِتالُ وَهُوَ كُرْهٌ لَكُمْ وَعَسى الكريم يجمعها الإقلاع عن الملذات والصبر على الطاعة وبهذا يرتبط السياق بما قبله حيث كان الكلام في معرض التضحية في سبيل العقيدة والإيمان وما يأتي نوع من التضحية ( يَسْئَلُونَكَ ) يا رسول الله ( ما ذا يُنْفِقُونَ ) في سبيل الله من أقسام الأموال ( قُلْ ) ليس لهم الإنفاق فإنه أي شيء كان يقبل إذا كان المنفق عليه أهلا كما أنه لا يقبل إذا كان المنفق عليه غير أهل فمعيار الإنفاق ليس ماهية المنفق وإنما شخص المنفق عليه ف ( ما أَنْفَقْتُمْ مِنْ خَيْرٍ ) فاللازم أن يكون للوالدين ( وَالْأَقْرَبِينَ ) أقربائكم ( وَالْيَتامى وَالْمَساكِينِ وَابْنِ السَّبِيلِ ) وأشباه ذلك مما يقصد به وجه الله سبحانه ( وَما تَفْعَلُوا مِنْ خَيْرٍ ) إنفاق أو غيره ( فَإِنَّ اللهَ بِهِ عَلِيمٌ ) فيجازيكم بالخير خيرا. و روي أنها نزلت في عمرو ابن الجموح ، وكان شيخا كبيرا كثير المال فقال يا رسول الله بما ذا أتصدق ؟ وعلى من أتصدق فأنزل الله هذه الآية (1) . [217] ثم رجع السياق إلى الآية السابقة التي فيها ذكر التضحية والزلزال ( كُتِبَ عَلَيْكُمُ الْقِتالُ ) مع من تعدى عليكم أو على العقيدة الصحيحة أو على الناس ( وَهُوَ كُرْهٌ لَكُمْ ) تكرهونه ( وَعَسى ) ( 1) فقه القرآن : ج 1 ص 239. أَنْ تَكْرَهُوا شَيْئاً وَهُوَ خَيْرٌ لَكُمْ وَعَسى أَنْ تُحِبُّوا شَيْئاً وَهُوَ شَرٌّ لَكُمْ وَاللهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ (216) يَسْئَلُونَكَ عَنِ الشَّهْرِ الْحَرامِ قِتالٍ فِيهِ قُلْ قِتالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَنْ سَبِيلِ اللهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرامِ وَإِخْراجُ أَهْلِهِ مِنْهُ أَكْبَرُ بمعنى « قد » وما بعده فاعله ( أَنْ تَكْرَهُوا شَيْئاً وَهُوَ خَيْرٌ لَكُمْ ) والقتال من ذلك فإنه يوجب سيادتكم وسعادتكم ( وَعَسى أَنْ تُحِبُّوا شَيْئاً وَهُوَ شَرٌّ لَكُمْ ) وترك القتال كذلك لما فيه من راحة الجسم وعدم اضطراب القلب لكنه شر لما فيه من زوال السيادة والعزة وتسلط الكفار والأجانب ( وَاللهُ يَعْلَمُ ) ما فيه خيركم وشركم ( وَأَنْتُمْ لا تَعْلَمُونَ ) . [218] بعث رسول الله بسرية فاتفق أن قاتلت في شهر رجب وهي تترد في أن اليوم الذي حاربت فيه من جمادى أو رجب ، وشهر رجب من الأشهر الحرم ، ولذا كثر صخب المشركين وإنه كيف يقاتل الرسول في شهر حرام وأتى وفدهم إلى المدينة يسألون الرسول صلى‌الله‌عليه‌وآله‌وسلم عن ذلك فنزلت هذه الآية ( يَسْئَلُونَكَ عَنِ الشَّهْرِ الْحَرامِ قِتالٍ فِيهِ ) بدل شهر أي يسألونك يا رسول الله عن القتال في الشهر الحرام ( قُلْ قِتالٌ فِيهِ ) أي في الشهر الحرام ( كَبِيرٌ ) في نفسه لا يجوز ( وَ ) لكن ليس كبر ذنبه مثل عظم ذنب ما تفعلونه أنتم أيها المشركون ف ( صَدٌّ عَنْ سَبِيلِ اللهِ ) أي المنع عنه بأن لا يسلم أحد ( وَكُفْرٌ بِهِ ) أي بالله سبحانه ( وَ ) صد عن ( الْمَسْجِدِ الْحَرامِ ) لئلا يحج المسلمون ( وَإِخْراجُ أَهْلِهِ ) أي أهل المسجد الحرام ( مِنْهُ ) كما فعل المشركون بالنبي والمسلمين ( أَكْبَرُ عِنْدَ اللهِ وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ وَلا يَزالُونَ يُقاتِلُونَكُمْ حَتَّى يَرُدُّوكُمْ عَنْ دِينِكُمْ إِنِ اسْتَطاعُوا وَمَنْ يَرْتَدِدْ مِنْكُمْ عَنْ دِينِهِ فَيَمُتْ وَهُوَ كافِرٌ فَأُولئِكَ حَبِطَتْ أَعْمالُهُمْ فِي الدُّنْيا وَالْآخِرَةِ وَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (217) إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هاجَرُوا عِنْدَ اللهِ ) فكيف تؤاخذون المسلمين بذنب مهما عظم وتنسون ذنوبكم التي هي أعظم منه ( وَالْفِتْنَةُ ) التي أنتم تقيمون عليها من تفتين المسلمين عن دينهم وإغرائهم بالكفر بعد الإسلام ( أَكْبَرُ مِنَ الْقَتْلِ ) الذي صدر من المسلمين ، فالقتل يفسد دنيا المقتول والفتنة تفسد دين المفتتن وأخراه ( وَلا يَزالُونَ ) أي لا يزال الكفار ( يُقاتِلُونَكُمْ ) أيها المسلمون ( حَتَّى يَرُدُّوكُمْ عَنْ دِينِكُمْ ) إلى الكفر ( إِنِ اسْتَطاعُوا ) أن يردوكم ( وَمَنْ يَرْتَدِدْ مِنْكُمْ ) أيها المسلمون ( عَنْ دِينِهِ ) إلى الكفر ( فَيَمُتْ وَهُوَ كافِرٌ ) في مقابل من ارتد ورجع حتى مات مؤمنا ( فَأُولئِكَ حَبِطَتْ أَعْمالُهُمْ ) والحبط هو الإبطال والإفناء فلا حسنة لهم ولم ينتفعوا بإيمانهم السابق على الكفر ( فِي الدُّنْيا ) فليس لهم احترام المسلم وحقوقه ( وَالْآخِرَةِ ) فلا يجزى بالجنة والثواب ( وَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) إلى الأبد. [219] وهناك ظن أناس أن القاتل في رجب إن سلم من الإثم لم يكن له أجر لأنه انتهك حرمة الشهر الحرام فأنزل الله ( إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هاجَرُوا ) بأن قطعوا ديارهم وأهليهم وخلفوا أموالهم لأجل أن يكونوا وَجاهَدُوا فِي سَبِيلِ اللهِ أُولئِكَ يَرْجُونَ رَحْمَتَ اللهِ وَاللهُ غَفُورٌ رَحِيمٌ (218) يَسْئَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ قُلْ فِيهِما إِثْمٌ كَبِيرٌ وَمَنافِعُ لِلنَّاسِ وَإِثْمُهُما أَكْبَرُ مِنْ نَفْعِهِما وَيَسْئَلُونَكَ ما ذا يُنْفِقُونَ قُلِ الْعَفْوَ مع الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَجاهَدُوا ) أي أوقعوا أنفسهم بالجهد والتعب ، وأوضح أفراده المقاتلة ( فِي سَبِيلِ اللهِ ) لكسب مراضيه ( أُولئِكَ يَرْجُونَ رَحْمَتَ اللهِ ) يأملونها في الدنيا والآخرة ( وَاللهُ غَفُورٌ ) يغفر لمن زل و ( رَحِيمٌ ) بعباده المؤمنين فلا ينقص أجورهم وإنما قال : « يرجون » لأن الإنسان لا يدري ما حاله في المستقبل وإنه هل يبقى على الإيمان والصلاح حتى يثاب أم يفتن في دينه حتى يحبط عمله.` },
            { text: "كَانَ ٱلنَّاسُ أُمَّةً وَٰحِدَةً فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلْكِتَٰبَ بِٱلْحَقِّ لِيَحْكُمَ بَيْنَ ٱلنَّاسِ فِيمَا ٱخْتَلَفُوا۟ فِيهِ وَمَا ٱخْتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ بَغْيًۢا بَيْنَهُمْ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ لِمَا ٱخْتَلَفُوا۟ فِيهِ مِنَ ٱلْحَقِّ بِإِذْنِهِۦ وَٱللَّهُ يَهْدِى مَن يَشَآءُ إِلَىٰ صِرَٰطٍ مُّسْتَقِيمٍ", tafsir: `` },
            { text: "أَمْ حَسِبْتُمْ أَن تَدْخُلُوا۟ ٱلْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ ٱلَّذِينَ خَلَوْا۟ مِن قَبْلِكُم مَّسَّتْهُمُ ٱلْبَأْسَآءُ وَٱلضَّرَّآءُ وَزُلْزِلُوا۟ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ مَتَىٰ نَصْرُ ٱللَّهِ أَلَآ إِنَّ نَصْرَ ٱللَّهِ قَرِيبٌ", tafsir: `` },
            { text: "يَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلْ مَآ أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَٰلِدَيْنِ وَٱلْأَقْرَبِينَ وَٱلْيَتَٰمَىٰ وَٱلْمَسَٰكِينِ وَٱبْنِ ٱلسَّبِيلِ وَمَا تَفْعَلُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ", tafsir: `` },
            { text: "كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ وَعَسَىٰٓ أَن تَكْرَهُوا۟ شَيْـًٔا وَهُوَ خَيْرٌ لَّكُمْ وَعَسَىٰٓ أَن تُحِبُّوا۟ شَيْـًٔا وَهُوَ شَرٌّ لَّكُمْ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ", tafsir: `` },
            { text: "يَسْـَٔلُونَكَ عَنِ ٱلشَّهْرِ ٱلْحَرَامِ قِتَالٍ فِيهِ قُلْ قِتَالٌ فِيهِ كَبِيرٌ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفْرٌۢ بِهِۦ وَٱلْمَسْجِدِ ٱلْحَرَامِ وَإِخْرَاجُ أَهْلِهِۦ مِنْهُ أَكْبَرُ عِندَ ٱللَّهِ وَٱلْفِتْنَةُ أَكْبَرُ مِنَ ٱلْقَتْلِ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ ٱسْتَطَٰعُوا۟ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِۦ فَيَمُتْ وَهُوَ كَافِرٌ فَأُو۟لَٰٓئِكَ حَبِطَتْ أَعْمَٰلُهُمْ فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَٱلَّذِينَ هَاجَرُوا۟ وَجَٰهَدُوا۟ فِى سَبِيلِ ٱللَّهِ أُو۟لَٰٓئِكَ يَرْجُونَ رَحْمَتَ ٱللَّهِ وَٱللَّهُ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ قُلْ فِيهِمَآ إِثْمٌ كَبِيرٌ وَمَنَٰفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا وَيَسْـَٔلُونَكَ مَاذَا يُنفِقُونَ قُلِ ٱلْعَفْوَ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ", tafsir: `يا رسول الله ( عَنِ الْخَمْرِ ) وهي كل مسكر وأظهر أفراده المسكر المتخذ من العنب ( وَالْمَيْسِرِ ) وهو القمار بجميع أصنافه والسؤال كان عن حكمهما ( قُلْ ) يا محمد ( فِيهِما إِثْمٌ كَبِيرٌ ) أي وزر عظيم لما فيهما من الفساد الكبير ( وَمَنافِعُ لِلنَّاسِ ) فإن الخمر تفيد اللذة والطرب وفي الاتجار بها ثمن وربح والقمار فيه لذة للاعب وربح للفائز ( وَإِثْمُهُما أَكْبَرُ مِنْ نَفْعِهِما ) إذ الفساد الذي يسببانه في البدن والعقل والمال أكبر من اللذة والربح الذي يحصل بسببهما بالإضافة إلى العقوبة الأخروية التي تصيب الإنسان من جرائها. ( وَيَسْئَلُونَكَ ) يا رسول الله ( ما ذا يُنْفِقُونَ ) وهنا جاء الجواب طبق السؤال وإنه « ماذا » لا إنه « لمن » فقال ( قُلْ ) يا محمد ( الْعَفْوَ ) أي الزائد من المال على النفقة فإن ما بقدر نفقة النفس والأهل لا ينفق تقديما كَذلِكَ يُبَيِّنُ اللهُ لَكُمُ الْآياتِ لَعَلَّكُمْ تَتَفَكَّرُونَ (219) فِي الدُّنْيا وَالْآخِرَةِ وَيَسْئَلُونَكَ عَنِ الْيَتامى قُلْ إِصْلاحٌ لَهُمْ خَيْرٌ وَإِنْ تُخالِطُوهُمْ لواجبي النفقة على غيره وهذا الإنفاق مستحب لما دل على حصر الحقوق الواجبة في أمور معدودة ( كَذلِكَ ) أي هكذا يا رسول الله فإن كذا تشبيه وإشارة والكاف الملحق بها اللام للخطاب ( يُبَيِّنُ اللهُ لَكُمُ الْآياتِ ) الأدلة المرتبطة بالتشريعات ( لَعَلَّكُمْ تَتَفَكَّرُونَ ) أي لكي تتفكروا.` },
            { text: "فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَيَسْـَٔلُونَكَ عَنِ ٱلْيَتَٰمَىٰ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ وَإِن تُخَالِطُوهُمْ فَإِخْوَٰنُكُمْ وَٱللَّهُ يَعْلَمُ ٱلْمُفْسِدَ مِنَ ٱلْمُصْلِحِ وَلَوْ شَآءَ ٱللَّهُ لَأَعْنَتَكُمْ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ", tafsir: `أمر ( الدُّنْيا وَ ) أمر ( الْآخِرَةِ ) فتجمعوهما في التفكير ثم ترون جمال الأحكام إذ التفكير في الدنيا فقط يوجب شلل قسم من الأحكام فلما ذا ينفق الإنسان ـ مثلا ـ وهو بحاجة إلى المال ، كما إن التفكير في الآخرة فقط يوجب شلل قسم آخر من الأحكام فلما ذا لا ينفق الإنسان جميع أمواله لتحصيل أجر الآخرة وهكذا سائر الأحكام فلا يعرف جمالها إلا إذا افتكر الإنسان في كلتا الحياتين وعرف المصلحتين ( وَيَسْئَلُونَكَ عَنِ الْيَتامى ) كيف يعاشروهم فقد ورد أنه لما نزل ( وَلا تَقْرَبُوا مالَ الْيَتِيمِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ ) (1) ذهب كل من عنده يتيم ليعزل اليتيم في مأكله ومشربه عن نفسه لئلا يبتلي بماله واشتد ذلك عليهم فسألوا النبي صلى‌الله‌عليه‌وآله‌وسلم فنزلت ( قُلْ ) يا رسول الله ( إِصْلاحٌ لَهُمْ خَيْرٌ ) بأن يصلح الإنسان أموال اليتيم ويعاشره معاشرة المصلحين بدون أجرة وعوض خير من عزلهم وطردهم ( وَإِنْ تُخالِطُوهُمْ ) بأن تخلطوا أموالهم ( 1) الأنعام : 153. فَإِخْوانُكُمْ وَاللهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ وَلَوْ شاءَ اللهُ لَأَعْنَتَكُمْ إِنَّ اللهَ عَزِيزٌ حَكِيمٌ (220) وَلا تَنْكِحُوا الْمُشْرِكاتِ حَتَّى يُؤْمِنَّ وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ بأموالكم وتشاركون معهم بالنسبة وحفظ المقدار فهم إخوانكم في الإيمان والأخ يعاشر الأخ بالإصلاح والغبطة ( وَاللهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ ) فهو عارف بنية المخالطين للأيتام وإنهم يريدون بالمخالطة الإفساد وأكل مال اليتيم أو الإصلاح والتحفظ على اليتيم حتى يبلغ ويرشد ( وَلَوْ شاءَ اللهُ لَأَعْنَتَكُمْ ) أي أوقعكم في العنت والمشقة بالنسبة إلى اليتيم بأن يوجب الاجتناب عن أموالهم واعتزال أموالكم عن أموالهم فحيث أنه لم يفعل ذلك رحمة بكم فلا تأكلوا أموالهم فسادا وطمعا ( إِنَّ اللهَ عَزِيزٌ ) فهو يقدر ـ بعزته ـ من إعناتكم ( حَكِيمٌ ) لا يفعل إلا الصلاح وما تقتضيه الحكمة. [222] ثم انتقل السياق إلى فئة من أحكام الأسرة في النكاح والطلاق وشؤونها ولعل الارتباط العام بين هذه الآيات والآيات السابقة أنها انتهت إلى حكم اليتيم ، فاللازم بيان العش الذي يتربى فيه فراخ الإنسان ، وإنه كيف يلزم أن يكون لينشأ الأولاد صالحين أصحاء جسما وعقلا وعاطفة ( وَلا تَنْكِحُوا ) أيها الرجال المسلمون النساء ( الْمُشْرِكاتِ ) سواء كن أهل كتاب أم لا فأهل الكتاب أيضا مشركون كما قال سبحانه ( فَتَعالَى اللهُ عَمَّا يُشْرِكُونَ ) (1) ( حَتَّى يُؤْمِنَ ) ويدخلن في الإسلام ( وَلَأَمَةٌ مُؤْمِنَةٌ خَيْرٌ مِنْ مُشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ ) تلك ( 1) النمل : 64. وَلا تُنْكِحُوا الْمُشْرِكِينَ حَتَّى يُؤْمِنُوا وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُولئِكَ يَدْعُونَ إِلَى النَّارِ وَاللهُ يَدْعُوا إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ بِإِذْنِهِ وَيُبَيِّنُ آياتِهِ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ (221) وَيَسْئَلُونَكَ عَنِ الْمَحِيضِ قُلْ هُوَ أَذىً فَاعْتَزِلُوا النِّساءَ فِي الْمَحِيضِ وَلا تَقْرَبُوهُنَّ حَتَّى يَطْهُرْنَ فَإِذا تَطَهَّرْنَ فَأْتُوهُنَّ المشركة لجمالها أو مالها أو حسبها أو نسبها ( وَلا تُنْكِحُوا الْمُشْرِكِينَ ) بناتكم أيها المسلمون ( حَتَّى يُؤْمِنُوا وَلَعَبْدٌ مُؤْمِنٌ ) تزوجوه بنتكم ( خَيْرٌ مِنْ مُشْرِكٍ وَلَوْ أَعْجَبَكُمْ ) ذلك المشرك ( أُولئِكَ ) المشركات والمشركون ( يَدْعُونَ إِلَى النَّارِ ) إما بالتبليغ إلى الشرك وإما بحكم دينهم فإن جليس الإنسان إذا كان غير متدين لا بد وأن يسري إلى جليسه ( وَاللهُ يَدْعُوا إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ ) أي غفران الذنوب ( بِإِذْنِهِ ) فالمسلمات والمسلمون حين أخذوا مبادئهم عن الله سبحانه لا بد وأن يدعون بلسانهم أو بحكم دينهم إلى الجنة ( وَيُبَيِّنُ آياتِهِ ) أحكامه ودلائله ( لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ ) أي لكي يتذكروا ويتعظوا ويرشدوا.` },
            { text: "وَلَا تَنكِحُوا۟ ٱلْمُشْرِكَٰتِ حَتَّىٰ يُؤْمِنَّ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ وَلَا تُنكِحُوا۟ ٱلْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا۟ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ أُو۟لَٰٓئِكَ يَدْعُونَ إِلَى ٱلنَّارِ وَٱللَّهُ يَدْعُوٓا۟ إِلَى ٱلْجَنَّةِ وَٱلْمَغْفِرَةِ بِإِذْنِهِۦ وَيُبَيِّنُ ءَايَٰتِهِۦ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ", tafsir: `` },
            { text: "وَيَسْـَٔلُونَكَ عَنِ ٱلْمَحِيضِ قُلْ هُوَ أَذًى فَٱعْتَزِلُوا۟ ٱلنِّسَآءَ فِى ٱلْمَحِيضِ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ ٱللَّهُ إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّٰبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ", tafsir: `يا رسول الله ( عَنِ الْمَحِيضِ ) الحيض والمحيض بمعنى واحد وأنه هل يجوز مقاربة النساء في حالة الحيض أم لا ( قُلْ ) يا محمد صلى‌الله‌عليه‌وآله‌وسلم ( هُوَ ) أي المحيض ( أَذىً ) قذر نجس أو مشقة ( فَاعْتَزِلُوا النِّساءَ فِي الْمَحِيضِ ) والاعتزال هو الابتعاد عنهن ( وَلا تَقْرَبُوهُنَ ) بالجماع ( حَتَّى يَطْهُرْنَ ) وينظفن عن الدم ( فَإِذا تَطَهَّرْنَ ) عن الدم ( فَأْتُوهُنَ ) جامعوهن مِنْ حَيْثُ أَمَرَكُمُ اللهُ إِنَّ اللهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ (222) نِساؤُكُمْ حَرْثٌ لَكُمْ فَأْتُوا حَرْثَكُمْ أَنَّى شِئْتُمْ وَقَدِّمُوا لِأَنْفُسِكُمْ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّكُمْ مُلاقُوهُ وَبَشِّرِ الْمُؤْمِنِينَ (223) ( مِنْ حَيْثُ أَمَرَكُمُ اللهُ ) بمقاربتهن من الفرج الذي هو محل الدم ( إِنَّ اللهَ يُحِبُّ التَّوَّابِينَ ) الذين يرجعون كثيرا عن ذنوبهم إلى الندم والاستغفار بمعنى أنهم كلما أذنبوا تابوا ورجعوا واستغفروا ولعل ذكر التواب بمناسبة أن من زل فقارب في المحيض يقبل الله توبته وإن تكرر منه إذا ندم ندما حقيقيا وتاب توبة نصوحا ( وَيُحِبُّ الْمُتَطَهِّرِينَ ) بالماء عن الأقذار الباطنية والظاهرية أو بالاستغفار عن الذنوب.` },
            { text: "نِسَآؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا۟ حَرْثَكُمْ أَنَّىٰ شِئْتُمْ وَقَدِّمُوا۟ لِأَنفُسِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّكُم مُّلَٰقُوهُ وَبَشِّرِ ٱلْمُؤْمِنِينَ", tafsir: `أي مزرعة ومحترث فكما يحرث الحارث البذر في الأرض كذلك يحرث الرجل في زوجته ( فَأْتُوا حَرْثَكُمْ ) وزرعكم ( أَنَّى شِئْتُمْ ) « أنى » إما زمانية بمعنى أي وقت شئتم ، باستثناء أيام الحيض التي سبق أنها لا يجوز وسائر ما استثنى من حال الصوم والإحرام وشبههما ، وإما مكانية أي إتيانها في قبلها من خلفها أو قدامها أو جانبيها ، أو بمعنى الكيفية باركة ونائمة وقائمة ، أما أن يراد سياق السبيلان فبعيد عن سياق الآية ( وَقَدِّمُوا لِأَنْفُسِكُمْ ) بالولد فإنه يبقى ذخرا لكم ، أو قدموا لأنفسكم بالطاعة حيث ذكرت أوامر ونواهي ( وَاتَّقُوا اللهَ ) في أوامره ونواهيه ( وَاعْلَمُوا أَنَّكُمْ مُلاقُوهُ ) والملاقاة هنا بمعنى أنه عليكم حساب الملاقي لملاقيه ( وَبَشِّرِ الْمُؤْمِنِينَ ) بأنهم وَلا تَجْعَلُوا اللهَ عُرْضَةً لِأَيْمانِكُمْ أَنْ تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ وَاللهُ سَمِيعٌ عَلِيمٌ (224) لا يُؤاخِذُكُمُ اللهُ بِاللَّغْوِ فِي أَيْمانِكُمْ وَلكِنْ يُؤاخِذُكُمْ بِما كَسَبَتْ قُلُوبُكُمْ وَاللهُ غَفُورٌ حَلِيمٌ (225) يفوزون بكل كرامة. [225] وناسب قصة النساء حلف بن رواحة حين حلف أن لا يدخل على ختنه ولا يكلمه ولا يصلح بينه وبين امرأته فكان يقول : إني حلفت بهذا فلا يحل لي أن أفعله ، فنزلت الآية مما ناسب قصة العائلة والنساء التي سبقت ، وتأتي ، فقال سبحانه : ( وَلا تَجْعَلُوا اللهَ عُرْضَةً ) أي معرضا ( لِأَيْمانِكُمْ ) بأن تحلفوا به ( أَنْ تَبَرُّوا ) أي لئلا تبروا ، أي تريدون بالحلف عدم البر ( وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ ) أي وعدم التقوى وعدم الإصلاح ، فإن هذه اليمين فاسدة لا تنعقد ( وَاللهُ سَمِيعٌ ) لأيمانكم وأقوالكم ( عَلِيمٌ ) بأحوالكم ونياتكم.` },
            { text: "وَلَا تَجْعَلُوا۟ ٱللَّهَ عُرْضَةً لِّأَيْمَٰنِكُمْ أَن تَبَرُّوا۟ وَتَتَّقُوا۟ وَتُصْلِحُوا۟ بَيْنَ ٱلنَّاسِ وَٱللَّهُ سَمِيعٌ عَلِيمٌ", tafsir: `` },
            { text: "لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغْوِ فِىٓ أَيْمَٰنِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ وَٱللَّهُ غَفُورٌ حَلِيمٌ", tafsir: `ولا يعاقبكم ( بِاللَّغْوِ فِي أَيْمانِكُمْ ) جمع يمين ، ويمين اللغو هو ما يجري على عادة الناس من قول : لا والله وبلى والله من غير عقد على يمين يقتطع بها مال ولا يظلم بها أحد ( وَلكِنْ يُؤاخِذُكُمْ بِما كَسَبَتْ قُلُوبُكُمْ ) أي بحنث يمين نويتم اليمين الحقيقية حين إجرائها ( وَاللهُ غَفُورٌ ) يغفر الذنب ( حَلِيمٌ ) يحلم عن العصاة لعلهم يتوبوا ، وتكرار كلمة غفور في كثير من الآيات لفتح باب التوبة أمام العصاة الذين هم كثيرا ما يعصون عن شهوة ونزوات وهوى ، فإن لِلَّذِينَ يُؤْلُونَ مِنْ نِسائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِنْ فاؤُ فَإِنَّ اللهَ غَفُورٌ رَحِيمٌ (226) وَإِنْ عَزَمُوا الطَّلاقَ فَإِنَّ اللهَ سَمِيعٌ عَلِيمٌ (227) وَالْمُطَلَّقاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلاثَةَ قُرُوءٍ وَلا يَحِلُّ لَهُنَّ أَنْ الله سبحانه لا يسد عليهم باب التوبة وإن تكررت منهم المعاصي والذنوب. [227] ثم يرجع السياق إلى أحكام الأسرة مع مناسبة للحكم مع الحلف فيقول سبحانه : ( لِلَّذِينَ يُؤْلُونَ مِنْ نِسائِهِمْ ) والإيلاء هو الحلف على ترك وطي المرأة على وجه الإضرار بهن ( تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ) مبتدأ لقوله « للذين » أي توقف أربعة أشهر جائز للذين يؤلون من نسائهم وذلك لأن للرجل أن لا يطأ زوجته أربعة أشهر وبعد ما تم أربعة أشهر خيره الحاكم بين الوطي والكفارة وبين الطلاق وإن امتنع عن الأمرين حبسه ( فَإِنْ فاؤُ ) ورجعوا إلى زوجاتهم بالوطي بعد الأشهر الأربعة ( فَإِنَّ اللهَ غَفُورٌ ) يغفر لهم بهذا الحلف ( رَحِيمٌ ) بهم.` },
            { text: "لِّلَّذِينَ يُؤْلُونَ مِن نِّسَآئِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ فَإِن فَآءُو فَإِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ", tafsir: `` },
            { text: "وَإِنْ عَزَمُوا۟ ٱلطَّلَٰقَ فَإِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ", tafsir: `فطلقوا ( فَإِنَّ اللهَ سَمِيعٌ ) للطلاق ( عَلِيمٌ ) بالضمائر والنيات.` },
            { text: "وَٱلْمُطَلَّقَٰتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَٰثَةَ قُرُوٓءٍ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ ٱللَّهُ فِىٓ أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِى ذَٰلِكَ إِنْ أَرَادُوٓا۟ إِصْلَٰحًا وَلَهُنَّ مِثْلُ ٱلَّذِى عَلَيْهِنَّ بِٱلْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَٱللَّهُ عَزِيزٌ حَكِيمٌ", tafsir: `أي يصبرن ( بِأَنْفُسِهِنَ ) أي يحفظنها عن الزواج ونحوه ( ثَلاثَةَ قُرُوءٍ ) جمع قرء وهو من ألفاظ الضد يطلق على الحيض وعلى الطهر والمراد هنا الطهر فإذا طلقت المرأة في طهر لم يواقعها فيه الرجل كان هذا الطهر وطهران آخران بينهما حيض موجبا لانتظار العدة فإذا رأت الدم الثالث انقضت عدتها ( وَلا يَحِلُّ لَهُنَّ أَنْ يَكْتُمْنَ مَا خَلَقَ اللّهُ فِي أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِاللّهِ وَالْيَوْمِ الآخِرِ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَلِكَ إِنْ أَرَادُواْ إِصْلاَحًا وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ وَاللّهُ عَزِيزٌ حَكُيمٌ (228) يَكْتُمْنَ ) أي يخفين ( ما خَلَقَ اللهُ فِي أَرْحامِهِنَ ) من الولد ودم الحيض حتى يبطلن حق الرجعة في الطلاق الرجعي أو يستعجلن العدة ( إِنْ كُنَّ يُؤْمِنَّ بِاللهِ وَالْيَوْمِ الْآخِرِ ) يوم القيامة ، فمن آمن بهما لا بد وأن تستقيم حركاته وسكناته وأقواله وأفعاله ، لأنه يعلم أن الله مطلع عليه وأنه سوف يحاسبه ( وَبُعُولَتُهُنَ ) أي أزواج المطلقات الرجعيات ( أَحَقُّ بِرَدِّهِنَ ) إلى أنفسهم ( فِي ذلِكَ ) أي زمان التربص ( إِنْ أَرادُوا ) أي البعولة بردهن ( إِصْلاحاً ) لا إضرارا ، وذلك أن الرجل كان إذا أراد الإضرار بامرأته طلقها واحدة وتركها ، حتى إذا قرب انقضاء عدتها راجعها وتركها مدة ثم طلقها أخرى وتركها مدة كما فعل في الأولى ثم راجعها وتركها مدة ثم طلقها أخرى ، وهذا العمل حرام وإن كان يثبت حكم الرجعة به ( وَلَهُنَ ) أي حق النساء على أزواجهن ( مِثْلُ الَّذِي ) للأزواج ( عَلَيْهِنَ ) فلكل على الآخر حقوق تتكافأ ( بِالْمَعْرُوفِ ) من العشرة وسائر الأمور ( وَلِلرِّجالِ عَلَيْهِنَ ) زيادة ( دَرَجَةٌ ) فإن بيده الطلاق وله عليها الطاعة ( وَاللهُ عَزِيزٌ ) ينفذ أوامره ( حَكِيمٌ ) جعل أحكامه على طبق المصلحة والصلاح ، ومن المحتمل أن يكون قوله تعالى : ( وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَ ) بيان حال العدة أي أن لكل من الزوج والزوجة حقا على الآخر في حال العدة مع أن الرجل له فضيلة على المرأة بأن الاختيار إلى الزوج فقط. الطَّلاقُ مَرَّتانِ فَإِمْساكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسانٍ وَلا يَحِلُّ لَكُمْ أَنْ تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئاً إِلاَّ أَنْ يَخافا أَلاَّ يُقِيما حُدُودَ اللهِ فَإِنْ خِفْتُمْ أَلاَّ يُقِيما حُدُودَ اللهِ فَلا جُناحَ عَلَيْهِما فِيمَا افْتَدَتْ بِهِ تِلْكَ حُدُودُ اللهِ فَلا تَعْتَدُوها وَمَنْ يَتَعَدَّ حُدُودَ اللهِ فَأُولئِكَ هُمُ الظَّالِمُونَ (229)` },
            { text: "ٱلطَّلَٰقُ مَرَّتَانِ فَإِمْسَاكٌۢ بِمَعْرُوفٍ أَوْ تَسْرِيحٌۢ بِإِحْسَٰنٍ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا۟ مِمَّآ ءَاتَيْتُمُوهُنَّ شَيْـًٔا إِلَّآ أَن يَخَافَآ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ ٱللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا ٱفْتَدَتْ بِهِۦ تِلْكَ حُدُودُ ٱللَّهِ فَلَا تَعْتَدُوهَا وَمَن يَتَعَدَّ حُدُودَ ٱللَّهِ فَأُو۟لَٰٓئِكَ هُمُ ٱلظَّٰلِمُونَ", tafsir: `فإن للرجل أن يطلق زوجته تطليقتين فالواجب إذا راجعها بعد التطليقتين إمساك وحفظ لها في حبالته ( بِمَعْرُوفٍ ) بالعشرة الحسنة ( أَوْ تَسْرِيحٌ ) وطلاق ثالث ( بِإِحْسانٍ ) بإعطائها حقوقها وعدم التعدي ، وفوق ذلك إنه يحسن إليها جبرا لخاطرها المكسور. ( وَلا يَحِلُّ لَكُمْ ) أيها الأزواج ( أَنْ تَأْخُذُوا ) في حال الطلاق والاستبدال ( مِمَّا ) أي من الذي ( آتَيْتُمُوهُنَ ) وأعطيتموهن من المهور ( شَيْئاً إِلَّا أَنْ يَخافا ) أي الزوجان ( أَلَّا يُقِيما حُدُودَ اللهِ ) من حقوق الزوجية ( فَإِنْ خِفْتُمْ ) أيها الحكام ( أَلَّا يُقِيما حُدُودَ اللهِ ) من حقوق الزوجية ( فَلا جُناحَ ) ولا حرج ( عَلَيْهِما ) أي على الزوجة في البذل وعلى الزوج في قبول البذل ( فِيمَا ) أي في الذي ( افْتَدَتْ ) الزوجة ( بِهِ ) من المال ( تِلْكَ ) الأحكام المذكورة هي ( حُدُودَ اللهِ ) وأوامره ونواهيه ( فَلا تَعْتَدُوها ) ولا تجاوزوها بالمخالفة ( وَمَنْ يَتَعَدَّ ) منكم ويتجاوز ( حُدُودَ اللهِ ) ويخالف أوامره ونواهيه ( فَأُولئِكَ هُمُ الظَّالِمُونَ ) فَإِنْ طَلَّقَها فَلا تَحِلُّ لَهُ مِنْ بَعْدُ حَتَّى تَنْكِحَ زَوْجاً غَيْرَهُ فَإِنْ طَلَّقَها فَلا جُناحَ عَلَيْهِما أَنْ يَتَراجَعا إِنْ ظَنَّا أَنْ يُقِيما حُدُودَ اللهِ وَتِلْكَ حُدُودُ اللهِ يُبَيِّنُها لِقَوْمٍ يَعْلَمُونَ (230) وَإِذا طَلَّقْتُمُ النِّساءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ` },
            { text: "فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُۥ مِنۢ بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُۥ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَآ أَن يَتَرَاجَعَآ إِن ظَنَّآ أَن يُقِيمَا حُدُودَ ٱللَّهِ وَتِلْكَ حُدُودُ ٱللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ", tafsir: `طلاقا ثلاثا ( فَلا تَحِلُّ لَهُ مِنْ بَعْدُ ) الطلاق الثالث فإنها تحرم عليه ( حَتَّى تَنْكِحَ ) المرأة المطلقة ثلاثا ( زَوْجاً غَيْرَهُ ) ويسمى هذا الزوج محللا ( فَإِنْ طَلَّقَها ) أي طلق المرأة الزوج الثاني وانقضت عدتها ( فَلا جُناحَ عَلَيْهِما ) أي على الزوجة والزوج الأول الذي طلقها ثلاث طلقات ( أَنْ يَتَراجَعا إِنْ ظَنَّا ) أي الزوجان ( أَنْ يُقِيما حُدُودَ اللهِ ) في حسن الصحبة والمعاشرة وإن لم يظنا صح الرجوع لكنه سبب للمعصية ، والحاصل أن الحكم الوضعي الصحة وإن كان الحكم التكليفي الحرمة كمن يغسل يده النجسة بالماء المغصوب الذي يوجب طهارة يده لكنه فعل حراما ( وَتِلْكَ ) المذكورات في باب الطلاق والنكاح ( حُدُودَ اللهِ ) أوامره ونواهيه ( يُبَيِّنُها لِقَوْمٍ يَعْلَمُونَ ) الأمور فإنهم هم الذين ينتفعون بهذه الأحكام.` },
            { text: "وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا۟ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُۥ وَلَا تَتَّخِذُوٓا۟ ءَايَٰتِ ٱللَّهِ هُزُوًا وَٱذْكُرُوا۟ نِعْمَتَ ٱللَّهِ عَلَيْكُمْ وَمَآ أَنزَلَ عَلَيْكُم مِّنَ ٱلْكِتَٰبِ وَٱلْحِكْمَةِ يَعِظُكُم بِهِۦ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `أي قاربن تمام العدة وإنما عبر بهذا التعبير لأن انقضاء العدة يعبر عنه بانقضاء الأجل فما يقابله بلوغ الأجل إذا قاربه ، إذ البلوغ الدقي خارج عن محاورة العرف ( فَأَمْسِكُوهُنَ ) أي احفظوهن في حبالتكم بالرجوع إليهن في عدة الرجعة ( بِمَعْرُوفٍ ) الذي يعرفه العقلاء والمشرعون من القيام بحقوق أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ وَلا تُمْسِكُوهُنَّ ضِراراً لِتَعْتَدُوا وَمَنْ يَفْعَلْ ذلِكَ فَقَدْ ظَلَمَ نَفْسَهُ وَلا تَتَّخِذُوا آياتِ اللهِ هُزُواً وَاذْكُرُوا نِعْمَتَ اللهِ عَلَيْكُمْ وَما أَنْزَلَ عَلَيْكُمْ مِنَ الْكِتابِ وَالْحِكْمَةِ يَعِظُكُمْ بِهِ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ (231) وَإِذا طَلَّقْتُمُ النِّساءَ فَبَلَغْنَ أَجَلَهُنَّ الزوجة ( أَوْ سَرِّحُوهُنَ ) أي اتركوهن حتى تنقضي عدتهن ( بِمَعْرُوفٍ ) بإعطاء حقوقهن كاملة من غير إيذاء لهن ( وَلا تُمْسِكُوهُنَ ) بأن ترجعوا إليهن ( ضِراراً ) بقصد الإضرار بهن لتطويل العدة أو التضييق في النفقة ـ كما تقدم ـ ( لِتَعْتَدُوا ) عليهن وتظلموهن ( وَمَنْ يَفْعَلْ ذلِكَ ) الإمساك بقصد الإضرار ( فَقَدْ ظَلَمَ نَفْسَهُ ) لأنه أساء بسمعته عند الناس وعرض نفسه لعذاب الله وسخطه ( وَلا تَتَّخِذُوا آياتِ اللهِ ) أحكامه وأوامره ونواهيه ( هُزُواً ) سخرية بأن تستخفوا بها ( وَاذْكُرُوا نِعْمَةَ اللهِ عَلَيْكُمْ ) حيث أنعم عليكم بكل نعمه ، التي منها نعمة الزوجة التي تسكنون إليها وتقضون مآربكم بسببها ( وَ ) اذكروا ( ما أَنْزَلَ عَلَيْكُمْ مِنَ الْكِتابِ وَالْحِكْمَةِ ) فشرفكم بتعلمكم الأحكام وإرشادكم إلى ما يصلحكم ويهيئ لكم حياة سعيدة ( يَعِظُكُمْ بِهِ ) أي بذلك الكتاب ، وهذا إما صفة للكتاب أو جملة مستأنفة ( وَاتَّقُوا اللهَ ) في أوامره ونواهيه ( وَاعْلَمُوا أَنَّ اللهَ بِكُلِّ شَيْءٍ عَلِيمٌ ) فلا يفوته عملكم ونيتكم فلا تتعرضوا لسخطه وغضبه.` },
            { text: "وَإِذَا طَلَّقْتُمُ ٱلنِّسَآءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَٰجَهُنَّ إِذَا تَرَٰضَوْا۟ بَيْنَهُم بِٱلْمَعْرُوفِ ذَٰلِكَ يُوعَظُ بِهِۦ مَن كَانَ مِنكُمْ يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ وَٱللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ", tafsir: `أي انقضت عدتهن ـ وذلك فَلا تَعْضُلُوهُنَّ أَنْ يَنْكِحْنَ أَزْواجَهُنَّ إِذا تَراضَوْا بَيْنَهُمْ بِالْمَعْرُوفِ ذلِكَ يُوعَظُ بِهِ مَنْ كانَ مِنْكُمْ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ذلِكُمْ أَزْكى لَكُمْ وَأَطْهَرُ وَاللهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ (232) وَالْوالِداتُ يُرْضِعْنَ أَوْلادَهُنَّ حَوْلَيْنِ كامِلَيْنِ لِمَنْ أَرادَ أَنْ يُتِمَّ الرَّضاعَةَ بقرينة : أن ينكحن ـ ( فَلا تَعْضُلُوهُنَ ) أي لا تمنعوهن ظلما ( أَنْ يَنْكِحْنَ أَزْواجَهُنَ ) إلى الزوج السابق أو من تريد الزواج به فعلا وسمى زوجا للأول وربما قيل في وجه النزول أن معقل بن يسار عضل أخته جملاء أن ترجع إلى الزوج الأول وهو عاصم بن عدي حين طلقها وخرجت من العدة ثم أراد أن يجتمعا بنكاح جديد فمنعهما من ذلك ، ولو كان كذلك كان المراد بأزواجهن بالمعنى الأول فإنه لا يحق لأحد أن يمنع المرأة الثيبة في الرجوع إلى زوجها بنكاح جديد ( إِذا تَراضَوْا بَيْنَهُمْ بِالْمَعْرُوفِ ) مما أباحه شرع الإسلام من شروط النكاح وآداب العشرة ( ذلِكَ ) المذكور من تحريم العضل ( يُوعَظُ بِهِ مَنْ كانَ مِنْكُمْ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ) فإن المؤمن يجتنب سخط الله ويبتغي رضاه ( ذلِكُمْ ) الذي ذكرنا في باب الزواج ( أَزْكى لَكُمْ ) أنمى لكم ( وَأَطْهَرُ ) لنفوسكم فإن في الزواج النسل والتحصن وسير الحياة إلى الأمام ( وَاللهُ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ ) فاتبعوا أوامره وانتهوا عن زواجره.` },
            { text: "وَٱلْوَٰلِدَٰتُ يُرْضِعْنَ أَوْلَٰدَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَن يُتِمَّ ٱلرَّضَاعَةَ وَعَلَى ٱلْمَوْلُودِ لَهُۥ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِٱلْمَعْرُوفِ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا لَا تُضَآرَّ وَٰلِدَةٌۢ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُۥ بِوَلَدِهِۦ وَعَلَى ٱلْوَارِثِ مِثْلُ ذَٰلِكَ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوٓا۟ أَوْلَٰدَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّآ ءَاتَيْتُم بِٱلْمَعْرُوفِ وَٱتَّقُوا۟ ٱللَّهَ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `فإن الأم ترضع ولدها سنتين تامتين أربعة وعشرين شهرا ( لِمَنْ أَرادَ أَنْ يُتِمَّ الرَّضاعَةَ ) التي وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ لا تُكَلَّفُ نَفْسٌ إِلاَّ وُسْعَها لا تُضَارَّ والِدَةٌ بِوَلَدِها وَلا مَوْلُودٌ لَهُ بِوَلَدِهِ وَعَلَى الْوارِثِ مِثْلُ ذلِكَ ندب إليها الإسلام ومن العلماء من أوجب ذلك ( وَعَلَى الْمَوْلُودِ لَهُ ) أي الأب ، وإنما عبر بهذا التعبير إثارة للعاطفة ، له فإن الأب قد ولد له الولد فاللازم أن يحنو عليه ( رِزْقُهُنَ ) الإدام والطعام ( وَكِسْوَتُهُنَ ) اللباس ( بِالْمَعْرُوفِ ) لدى الشرع والعرف من اللائق بحالها فإن على الأب أن يقوم بهذه الشؤون ما دامت الأم في الرضاع ، وقد استفاد أكثر المفسرين من هذه الجملة كون الكلام حول الأم المطلقة وإلا فالرزق والكسوة على الزوج لأجل النكاح لا لأجل الرضاع ( لا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَها ) فكل من الأب والأم يؤدي واجبه في حدود طاقته فلا تتحمل الأم الرضاع بلا بدل ولا ينتفع الأب بولده في المستقبل مجانا فسعة هذه أن ترضع ببدل ، وسعة ذاك أن يدفع الأجر لما يعود نفعه إليه ( لا تُضَارَّ والِدَةٌ بِوَلَدِها ) بأن ترضع مجانا وبلا عوض باستغلال الأب عاطفة الأم للولد فلا ينفق عليها ، أو بمعنى أن الوالدة لا يؤخذ منها الولد ليعطي للأجنبية غيظا من الأب عليها فتضر بفراق ولدها ( وَلا ) يضار ( مَوْلُودٌ لَهُ ) أي الأب ( بِوَلَدِهِ ) بأن تستغل الأم عاطفة الأب نحو الولد فتكلفه أكثر من الكسوة والرزق قبال رضاعها ، أو لا يضر الأب بولده بأن يأخذه من الأم ويعطيه للأجنبية ، فإن لبن الأم أوفق بالولد ، والأول أقرب إلى السياق ( وَعَلَى الْوارِثِ ) للأب إذا مات الأب ( مِثْلُ ذلِكَ ) الرزق والكسوة للأم في حال رضاعها للولد ، فَإِنْ أَرادا فِصالاً عَنْ تَراضٍ مِنْهُما وَتَشاوُرٍ فَلا جُناحَ عَلَيْهِما وَإِنْ أَرَدْتُمْ أَنْ تَسْتَرْضِعُوا أَوْلادَكُمْ فَلا جُناحَ عَلَيْكُمْ إِذا سَلَّمْتُمْ ما آتَيْتُمْ بِالْمَعْرُوفِ وَاتَّقُوا اللهَ وَاعْلَمُوا أَنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ (233) وَالَّذِينَ يُت َوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ ولا يخفى أن أجر رضاع الصبي مما يرثه الصبي من أبيه لدى موت الأب ( فَإِنْ أَرادا ) أي الأب والأم ( فِصالاً ) للولد عن الرضاع بأن يفطماه قبل الحولين ( عَنْ تَراضٍ مِنْهُما وَتَشاوُرٍ ) بأن تشاور الأبوان وتراضيا في فطام الولد قبل العامين وذلك لئلا يتضرر الصبي إذا استقل أحدهما بالفطام فإن الرضا المتعقب للمشورة لا يكون إلا إذا كان الانفصال صلاحا ( فَلا جُناحَ عَلَيْهِما ) أي على الأبوين في هذا الفطام ( وَإِنْ أَرَدْتُمْ ) أيها الآباء ( أَنْ تَسْتَرْضِعُوا أَوْلادَكُمْ ) بأن تستأجروا لهم مرضعات غير أمهاتهم ( فَلا جُناحَ ) ولا حرج ( عَلَيْكُمْ ) في ذلك ( إِذا سَلَّمْتُمْ ) إلى المرضعات ( ما آتَيْتُمْ ) ووعدتم لهن من الأجر ( بِالْمَعْرُوفِ ) أي تسليما بالمعروف بدون نقصان ومطل ومن ، وهذا شرط تكليفي لا وضعي ، كما هو كثير في القرآن الحكيم ، لغاية الإلفات إلى لزوم كون الأعمال عن صدق وإخلاص وتقوى ( وَاتَّقُوا اللهَ ) في أعمالكم التي منها الأحكام السالفة حول الرضاع ( وَاعْلَمُوا أَنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ ) فلا يغيب شيء عنه ولا تخفى عليه خافية ، فلتكن أعمالكم حسب مراضيه وأوامره.` },
            { text: "وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ بِٱلْمَعْرُوفِ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", tafsir: `أي الرجال الذين يموتون ( وَيَذَرُونَ أَزْواجاً يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْراً فَإِذا بَلَغْنَ أَجَلَهُنَّ فَلا جُناحَ عَلَيْكُمْ فِيما فَعَلْنَ فِي أَنْفُسِهِنَّ بِالْمَعْرُوفِ وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (234) وَلا جُناحَ عَلَيْكُمْ فِيما عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّساءِ أَوْ أَكْنَنْتُمْ فِي أَنْفُسِكُمْ أَزْواجاً ) أي يخلفون زوجاتهم ( يَتَرَبَّصْنَ بِأَنْفُسِهِنَ ) أي يحفظن أنفسهن عن الزواج ولعل في قوله إشارة إلى أن النفس ولو كانت تطمح نحو الزواج لكن الواجب اصطبارها والتحفظ عليها ( أَرْبَعَةَ أَشْهُرٍ وَعَشْراً ) ففي هذه المدة يجب عليها الحداد بترك الزينة والخطبة ( فَإِذا بَلَغْنَ أَجَلَهُنَ ) وانقضت المدة ( فَلا جُناحَ عَلَيْكُمْ ) أيها المسلمون ( فِيما فَعَلْنَ فِي أَنْفُسِهِنَ ) من الزينة أو الخطبة أو النكاح فإنها ترجع إلى نفسها والناس مسلطون على أنفسهم ( بِالْمَعْرُوفِ ) بأن لا تعمل منكرا ينافي الإسلام ( وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ ) فيطلع على أعمالهم ، ولا يفوته شيء من إطاعتكم ومخالفتكم.` },
            { text: "وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُوا۟ قَوْلًا مَّعْرُوفًا وَلَا تَعْزِمُوا۟ عُقْدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبْلُغَ ٱلْكِتَٰبُ أَجَلَهُۥ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ يَعْلَمُ مَا فِىٓ أَنفُسِكُمْ فَٱحْذَرُوهُ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٌ", tafsir: `إذا كانت المرأة في العدة ف ( لا جُناحَ عَلَيْكُمْ ) أيها الراغبون في الزواج منهن ( فِيما عَرَّضْتُمْ بِهِ مِنْ خِطْبَةِ النِّساءِ ) بأن تلمحوا إلى رغبتكم في الزواج منهن وتعرضوا على ذلك تعريضا وإشارة من طرف خفي ، لا تصريحا فإن ذلك خلاف الجو الذي يحيط بالمرأة المعتدة من الربط الباقي بينها وبين زوجها الأول ( أَوْ أَكْنَنْتُمْ فِي أَنْفُسِكُمْ ) بأن أضمرتم إرادة زواجهن بدون أن تصرحوا أو تلمحوا بذلك فإن الكناية عَلِمَ اللهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ وَلكِنْ لا تُواعِدُوهُنَّ سِرًّا إِلاَّ أَنْ تَقُولُوا قَوْلاً مَعْرُوفاً وَلا تَعْزِمُوا عُقْدَةَ النِّكاحِ حَتَّى يَبْلُغَ الْكِتابُ أَجَلَهُ وَاعْلَمُوا أَنَّ اللهَ يَعْلَمُ ما فِي أَنْفُسِكُمْ فَاحْذَرُوهُ وَاعْلَمُوا أَنَّ اللهَ غَفُورٌ حَلِيمٌ (235) اللفظية والإضمار القلبي لا جناح فيهما ( عَلِمَ اللهُ أَنَّكُمْ ) أيها الرجال ( سَتَذْكُرُونَهُنَ ) وهن في العدة إرادة للزواج بهن ( وَلكِنْ ) لا تصرحوا بالخطبة و ( لا تُواعِدُوهُنَّ سِرًّا ) في الخلوة فتبدوا رغبتكم في الزواج بهن في منأى من الناس ( إِلَّا أَنْ تَقُولُوا قَوْلاً مَعْرُوفاً ) بالكناية والتلميح لا بالتصريح وذكر ما يقبح ذكره كما كانت عادة بعض الناس. ( وَلا تَعْزِمُوا ) أي لا تقصدوا ( عُقْدَةَ النِّكاحِ ) أي إجراء الصيغة التي هي كعقدة تعقد النكاح بين الجانبين ، وقد نهى عن العزم على ذلك مبالغة ، كقوله : ( وَلا تَقْرَبُوا مالَ الْيَتِيمِ ) (1) ( حَتَّى يَبْلُغَ الْكِتابُ ) الذي كتبناه في باب العدة من أربعة أشهر وعشرا (2) ( أَجَلَهُ ) أي أمده ، بأن تنقضي العدة ( وَاعْلَمُوا أَنَّ اللهَ يَعْلَمُ ما فِي أَنْفُسِكُمْ ) من عزم النكاح فكيف بما تسرون به من نكاح المعتدة سرا ( فَاحْذَرُوهُ ) أن تخالفوه ( وَاعْلَمُوا أَنَّ اللهَ غَفُورٌ ) يستر عاجلا فلا يغرنكم ستره ( حَلِيمٌ ) عليم فلا يعجل بالعقوبة فلا يسبب ذلك جرأتكم على انتهاك حرماته. ( 1) الأنعام : 153. ( 2) راجع موسوعة الفقه : ج 70. لا جُناحَ عَلَيْكُمْ إِنْ طَلَّقْتُمُ النِّساءَ ما لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتاعاً بِالْمَعْرُوفِ حَقًّا عَلَى الْمُحْسِنِينَ (236) وَإِنْ طَلَّقْتُمُوهُنَّ مِنْ قَبْلِ أَنْ تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ ف َرِيضَةً فَنِصْفُ ما فَرَضْتُمْ [237] وبعد بيان حكم موت الزوج ، يأتي حكم الطلاق ، والطلاق إن كان قبل الدخول ولم يذكر في العقد مهر فللمرأة المتعة ، وإن كان قبل الدخول وذكر المهر فللمرأة نصف المهر ( لا جُناحَ عَلَيْكُمْ ) أيها الأزواج ( إِنْ طَلَّقْتُمُ النِّساءَ ما لَمْ تَمَسُّوهُنَ ) بالدخول ( أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً ) « أو » بمعنى الواو ، أي لم يكن شيء من الأمرين لا المس ولا المهر ، ويسمى المهر فريضة لأنه يجب إذا سمي ، والمعنى أنه يباح الطلاق قبل المس والفرض ، فلا يتوهم أحد أن النكاح لأجل الوطي فكيف يصح الطلاق قبله ( وَمَتِّعُوهُنَ ) أي أعطوهن المتعة وهي ما تتمتع به المرأة ويوجب تعويضا يجبر خاطرها الكسير ( عَلَى الْمُوسِعِ ) أي الغني يقال أوسع الرجل إذا كثر ماله ( قَدَرُهُ ) من دار أو خادم أو نحوهما ( وَعَلَى الْمُقْتِرِ ) أي الفقير يقال أقتر الرجل إذا افتقر ( قَدَرُهُ ) كخاتم أو درهم أو نحوهما ( مَتاعاً بِالْمَعْرُوفِ ) ليس فيه إسراف ولا تقصير ( حَقًّا عَلَى الْمُحْسِنِينَ ) الذين يحسنون طاعة الأوامر والانتهاء عن الزواجر.` },
            { text: "لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ ٱلنِّسَآءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا۟ لَهُنَّ فَرِيضَةً وَمَتِّعُوهُنَّ عَلَى ٱلْمُوسِعِ قَدَرُهُۥ وَعَلَى ٱلْمُقْتِرِ قَدَرُهُۥ مَتَٰعًۢا بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّآ أَن يَعْفُونَ أَوْ يَعْفُوَا۟ ٱلَّذِى بِيَدِهِۦ عُقْدَةُ ٱلنِّكَاحِ وَأَن تَعْفُوٓا۟ أَقْرَبُ لِلتَّقْوَىٰ وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ إِنَّ ٱللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `طلاقا قبل الدخول ( وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً ) بأن عينتم في النكاح المهر فعليكم أن تدفعوا إلى المرأة نصف ( ما فَرَضْتُمْ ) نصف المهر ، هذا هو الحكم إِلاَّ أَنْ يَعْفُونَ أَوْ يَعْفُوَا الَّذِي بِيَدِهِ عُقْدَةُ النِّكاحِ وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوى وَلا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ (237) الواجب ( إِلَّا أَنْ يَعْفُونَ ) أي تعفي المرأة عن نصفها فلا تأخذ شيئا وتهب مالها إلى الزوج ( أَوْ يَعْفُوَا الَّذِي بِيَدِهِ عُقْدَةُ النِّكاحِ ) يمكن أن يراد به الزوج بأن يعفو عن نصفه فيعطي للمرأة جميع مهر المرأة ، وروي أن المراد عفو ولي الزوجة ، فيما إذا كان لها ولي مفروض كالصغيرة ، أو موكل من قبلها في الكبيرة ( وَأَنْ تَعْفُوا أَقْرَبُ لِلتَّقْوى ) فإن من يترك حق نفسه تبرعا أقرب إلى التقوى بأن تبقى معصية الله فلا يطلب ما ليس له ( وَلا تَنْسَوُا الْفَضْلَ بَيْنَكُمْ ) بأن يتفضل بعضكم على بعض فيتنازل عن حقوقه لأجل صاحبه ولعل الفرق بين العفو والفضل أن العفو هبة جميع حقوقه والفضل هبة بعضها ( إِنَّ اللهَ بِما تَعْمَلُونَ بَصِيرٌ ) فيجازيكم على أعمالكم إن حسنا وإن سيئا. [239] إن القرآن الحكيم دائما يلطف أجواء الأحكام بتلميح إلى قدرة إله الكون وعظمته ورحمته وغفرانه ونحوها ليسمو بالنفس ويربط الحكم بالخالق حتى يكون أقرب إلى التنفيذ ، ولما طالت آيات الأحكام وبالأخص ما له جو كابت حزين من طلاق وموت ونحوهما أتت آيات الصلاة متداخلة بينها لتشع في النفس الطمأنينة والهدوء ( أَلا بِذِكْرِ اللهِ تَطْمَئِنُّ الْقُلُوبُ ) (1) مع مناسبة لهذه الآيات مع الجو العام لما قبلها ( 1) الرعد : 29. حَافِظُواْ عَلَى الصَّلَوَاتِ والصَّلاَةِ الْوُسْطَى وَقُومُواْ لِلّهِ قَانِتِينَ (238) فَإِنْ خِفْتُمْ فَرِجالاً أَوْ رُكْباناً فَإِذا أَمِنْتُمْ فَاذْكُرُوا اللهَ كَما عَلَّمَكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ (239) وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْواجاً وبعدها حيث تعرضت لصلاة الخوف والمطاردة ، هذا ما أحتمله أن يكون سببا لذكر هذه الآيات هنا متوسطة أحكام الموت والطلاق ( حافِظُوا عَلَى الصَّلَواتِ ) كلها ( وَالصَّلاةِ الْوُسْطى ) خاصة وهي صلاة الظهر لأنها تتوسط بين النهار فإن الرسول صلى‌الله‌عليه‌وآله‌وسلم كان يصليها بالهاجرة في مسجد مكشوف فكانت أثقل صلاة عليهم ولذا لم يكن يحضرها إلا الصف والصفان فقط ، كما ورد عن بعض الصحابة ( وَقُومُوا ) أيها المسلمون ( لِلَّهِ قانِتِينَ ) أي داعين فإن القنوت هو الدعاء ، ومنه القنوت في الصلاة والمراد إما القنوت في الصلاة أو مطلقا.` },
            { text: "حَٰفِظُوا۟ عَلَى ٱلصَّلَوَٰتِ وَٱلصَّلَوٰةِ ٱلْوُسْطَىٰ وَقُومُوا۟ لِلَّهِ قَٰنِتِينَ", tafsir: `` },
            { text: "فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا فَإِذَآ أَمِنتُمْ فَٱذْكُرُوا۟ ٱللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا۟ تَعْلَمُونَ", tafsir: `فلم تتمكنوا من المحافظة على الصلاة بشرائطها وآدابها ، حيث ابتليتم بالعدو الذي لا يسمح لكم بالصلاة الكاملة فصلوا رجالا جمع راجل أي مشاة ( أَوْ رُكْباناً ) جمع راكب أي على ظهور دوابكم ( فَإِذا أَمِنْتُمْ ) من الخوف ( فَاذْكُرُوا اللهَ ) صلاة كاملة ( كَما عَلَّمَكُمْ ما لَمْ تَكُونُوا تَعْلَمُونَ ) من أمور دينكم ودنياكم. [241] ثم رجع السياق إلى تتمة الأحكام السابقة ، بعد ما أشعّت في النفس الاطمئنان وندى الجو بذكر الصلاة ( وَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْواجاً ) « يتوفون » مجازا بالمشارفة ، فإنه كثيرا ما يعبر عمن شارف وَصِيَّةً لِأَزْواجِهِمْ مَتاعاً إِلَى الْحَوْلِ غَيْرَ إِخْراجٍ فَإِنْ خَرَجْنَ فَلا جُناحَ عَلَيْكُمْ فِي ما فَعَلْنَ فِي أَنْفُسِهِنَّ مِنْ مَعْرُوفٍ وَاللهُ عَزِيزٌ حَكِيمٌ (240) وَلِلْمُطَلَّقاتِ مَتاعٌ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ (241) أمرا بالداخل فيه ، كما يعكس كثيرا فيعبر عن الداخل بالمشارف ، نحو ( لا تَقْرَبُوا مالَ الْيَتِيمِ ) و ( لا تَعْزِمُوا عُقْدَةَ النِّكاحِ ) فالمراد الذين يقاربون الوفاة ، ولهم زوجات فمن الأفضل أن يوصوا ( وَصِيَّةً لِأَزْواجِهِمْ ) بأن يمتعهن الوصي ( مَتاعاً إِلَى الْحَوْلِ ) فيعطي النفقة والكسوة إليهن إلى سنة كاملة ( غَيْرَ إِخْراجٍ ) أي في حال كونهن غير مخرجات إخراجا عن بيوت أزواجهن ( فَإِنْ خَرَجْنَ ) عن رغبتهن ( فَلا جُناحَ عَلَيْكُمْ ) أيها الأولياء ( فِي ما فَعَلْنَ فِي أَنْفُسِهِنَّ مِنْ مَعْرُوفٍ ) بالزواج والزينة بعد انقضاء عدة الوفاة ـ وهي أربعة أشهر وعشرا ـ فإن قبل ذلك لا يكون معروفا ، بل منكرا ( وَاللهُ عَزِيزٌ ) فيحكم بمقتضى عزته وسلطته ( حَكِيمٌ ) لا يحكم اعتباطا بل عن مصالح وعلل ، وهذه الآية حسب ما ذكرنا لها من المعنى لا تكون منسوخة بآية ( أَرْبَعَةَ أَشْهُرٍ وَعَشْراً ) .` },
            { text: "وَٱلَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَٰجًا وَصِيَّةً لِّأَزْوَٰجِهِم مَّتَٰعًا إِلَى ٱلْحَوْلِ غَيْرَ إِخْرَاجٍ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِى مَا فَعَلْنَ فِىٓ أَنفُسِهِنَّ مِن مَّعْرُوفٍ وَٱللَّهُ عَزِيزٌ حَكِيمٌ", tafsir: `` },
            { text: "وَلِلْمُطَلَّقَٰتِ مَتَٰعٌۢ بِٱلْمَعْرُوفِ حَقًّا عَلَى ٱلْمُتَّقِينَ", tafsir: `يمتعهن الأزواج بشيء سواء كن واجبة النفقة أم لا ( بِالْمَعْرُوفِ ) فإن ذلك يسبب رفع الغضاضة ( حَقًّا عَلَى الْمُتَّقِينَ ) الذين يتقون مخالفة أوامر الله سبحانه إيجابا كانت أو ندبا. كَذلِكَ يُبَيِّنُ اللهُ لَكُمْ آياتِهِ لَعَلَّكُمْ تَعْقِلُونَ (242) أَ لَمْ تَرَ إِلَى الَّذِينَ خَرَجُوا مِنْ دِيارِهِمْ وَهُمْ أُلُوفٌ حَذَرَ الْمَوْتِ فَقالَ لَهُمُ اللهُ مُوتُوا ثُمَّ أَحْياهُمْ إِنَّ اللهَ لَذُو` },
            { text: "كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمْ ءَايَٰتِهِۦ لَعَلَّكُمْ تَعْقِلُونَ", tafsir: `الذي بين الله لكم الأحكام ( يُبَيِّنُ اللهُ لَكُمْ آياتِهِ لَعَلَّكُمْ تَعْقِلُونَ ) أي لكي تعقلوا آياته وأحكامه. [244] ومن جو الأسرة وامتدادها وانقطاعها ينتقل السياق إلى قصة الحياة والموت التي تشبه قصة الأسرة في كونها امتدادا للحياة العائلية وانقطاعا لها في قصة عجيبة هي : أن أهل مدينة من مدائن الشام كانوا سبعين ألف بيت هربوا من الطاعون فمروا بمدينة خربة قد جلا أهلها عنها وأفناهم الطاعون فنزلوا بها فأماتهم الله من ساعتهم جميعا وصاروا رميما يلوح ، فمر بهم نبي من أنبياء بني إسرائيل يقال له « حزقيل » فبكى واستعبر وقال : يا رب لو شئت لأحييتهم الساعة كما أمتهم ، فعمروا بلادك وولدوا عبادك وعبدوك مع من يعبدك ، فأوحى الله إليه أن يقول الاسم الأعظم فقاله عليهم فعادوا أحياء ينظر بعضهم إلى بعض يسبحون الله ويكبرونه ويهللونه ( أَ لَمْ تَرَ ) استفهام تقريري أي ألم تعلم فإن الرؤية تأتي بمعنى العلم كقول الشاعر : « رأيت الله أكبر كل شيء » وقد يستفهم بمثل هذا الاستفهام لإيجاد العلم ( إِلَى الَّذِينَ خَرَجُوا مِنْ دِيارِهِمْ وَهُمْ أُلُوفٌ ) سبعون ألفا كما تقدم ( حَذَرَ الْمَوْتِ ) وفرارا من الطاعون ( فَقالَ لَهُمُ اللهُ مُوتُوا ) فأماتهم حيث ظنوا الهرب ( ثُمَّ أَحْياهُمْ ) بدعاء النبي حزقيل عليه‌السلام ( إِنَّ اللهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ (243) وَقاتِلُوا فِي سَبِيلِ اللهِ وَاعْلَمُوا أَنَّ اللهَ سَمِيعٌ عَلِيمٌ (244) مَنْ ذَا الَّذِي يُقْرِضُ اللهَ قَرْضاً حَسَناً فَيُضاعِفَهُ لَهُ أَضْعافاً كَثِيرَةً وَاللهُ يَقْبِضُ وَيَبْصُطُ وَإِلَيْهِ تُرْجَعُونَ (245) فَضْلٍ عَلَى النَّاسِ ) كلهم بخلقهم ورزقهم وتدبير أمورهم ( وَلكِنَّ أَكْثَرَ النَّاسِ لا يَشْكُرُونَ ) نعمه وفضله عليهم بل يقللون فضله بالعصيان.` },
            { text: "أَلَمْ تَرَ إِلَى ٱلَّذِينَ خَرَجُوا۟ مِن دِيَٰرِهِمْ وَهُمْ أُلُوفٌ حَذَرَ ٱلْمَوْتِ فَقَالَ لَهُمُ ٱللَّهُ مُوتُوا۟ ثُمَّ أَحْيَٰهُمْ إِنَّ ٱللَّهَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَشْكُرُونَ", tafsir: `` },
            { text: "وَقَٰتِلُوا۟ فِى سَبِيلِ ٱللَّهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ سَمِيعٌ عَلِيمٌ", tafsir: `إذ علمتم أن الهروب من الموت لا ينفع ف ( قاتِلُوا فِي سَبِيلِ اللهِ ) ولا تهربوا خوف الموت ( وَاعْلَمُوا أَنَّ اللهَ سَمِيعٌ ) لأقوالكم ( عَلِيمٌ ) بنياتكم وأعمالكم. [246] إن القتال بإعطاء المال والنفس في سبيل الله ليس هدرا وإنما المقاتل والعامل للبر ، يقرض الله بما يذهب منه ثم يرجعه سبحانه إليه ف ( مَنْ ذَا الَّذِي يُقْرِضُ اللهَ قَرْضاً حَسَناً ) أي أيّ شخص ذاك الذي يقرض الله وينفق نفسه وماله في سبيله قرضا حسنا لا لرياء وسمعة ولا بمنّ وإكراه وسائر ما يشين القرض ( فَيُضاعِفَهُ لَهُ أَضْعافاً كَثِيرَةً ) ربما بلغت الملايين وعما ذا تخافون في قرض أموالكم هل من الفقر ؟ ( وَاللهُ يَقْبِضُ ) فيفقر ( وَيَبْصُطُ ) فيغني فلا ينفعكم البخل ولا يضركم القرض والسخاء ، أم تخافون في قرض أنفسكم لله من الموت ؟ ( وَإِلَيْهِ تُرْجَعُونَ ) فيعطيكم أفضل مما أخذ منكم ، قال الإمام أمير أَ لَمْ تَرَ إِلَى الْمَلَإِ مِنْ بَنِي إِسْرائِيلَ مِنْ بَعْدِ مُوسى إِذْ قالُوا لِنَبِيٍّ لَهُمُ ابْعَثْ لَنا مَلِكاً نُقاتِلْ فِي سَبِيلِ اللهِ قالَ هَلْ عَسَيْتُمْ إِنْ كُتِبَ عَلَيْكُمُ الْقِتالُ أَلاَّ تُقاتِلُوا قالُوا وَما لَنا أَلاَّ نُقاتِلَ فِي سَبِيلِ اللهِ وَقَدْ أُخْرِجْنا مِنْ دِيارِنا وَأَبْنائِنا المؤمنين عليه‌السلام لأحد أولاده « أعر الله جمجمتك » (1) . [247] وهنا قصة حياة أو موت أخرى تناسب القصة السابقة ( أَ لَمْ تَرَ ) أي ألم تعلم ـ كما تقدم ـ ( إِلَى الْمَلَإِ ) أي الجماعة ( مِنْ بَنِي إِسْرائِيلَ مِنْ بَعْدِ مُوسى ) النبي ( إِذْ قالُوا لِنَبِيٍّ لَهُمُ ) هو أشموئيل وبالعربية إسماعيل ( ابْعَثْ لَنا مَلِكاً ) أي سلطانا ( نُقاتِلْ فِي سَبِيلِ اللهِ ) تحت لوائه حيث أذلهم الجبابرة وأخرجتهم من بلادهم وقتلتهم وسبيت ذراريهم ونسائهم وكان النبي في ذلك الزمان ينظم أمور الدين والملك وينظم أمور الجيش والسلطة ( قالَ ) النبي ( هَلْ عَسَيْتُمْ ) أي لعلكم ( إِنْ كُتِبَ عَلَيْكُمُ الْقِتالُ أَلَّا تُقاتِلُوا ) أراد بذلك أخذ العهد عليهم في المقاتلة إن عيّن ملك لهم ( قالُوا ) أي قال الملأ في جواب النبي عليه‌السلام ( وَما لَنا أَلَّا نُقاتِلَ فِي سَبِيلِ اللهِ ) أي ليس بإمكاننا أن نترك القتال ( وَقَدْ أُخْرِجْنا مِنْ دِيارِنا ) أخرجنا الأعداء من بلادنا ( وَأَبْنائِنا ) أي إخراجنا من أبنائنا حيث قتل بعضهم وسبي البعض ، ( 1) نهج البلاغة : ص 64. فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتالُ تَوَلَّوْا إِلاَّ قَلِيلاً مِنْهُمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ (246) وَقالَ لَهُمْ نَبِيُّهُمْ إِنَّ اللهَ قَدْ بَعَثَ لَكُمْ طالُوتَ مَلِكاً قالُوا أَنَّى يَكُونُ لَهُ الْمُلْكُ عَلَيْنا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِنَ الْمالِ قالَ إِنَّ اللهَ اصْطَفاهُ عَلَيْكُمْ وَزادَهُ بَسْطَةً فِي الْعِلْمِ فسأل النبي عليه‌السلام من الله ذلك ، فاستجاب الله دعاءه وعين لهم ملكا وكتب عليهم القتال ( فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتالُ تَوَلَّوْا ) أدبروا وكرهوا القتال ( إِلَّا قَلِيلاً مِنْهُمْ وَاللهُ عَلِيمٌ بِالظَّالِمِينَ ) الذين فروا من الجهاد بعد طلب منهم وإلحاح.` },
            { text: "مَّن ذَا ٱلَّذِى يُقْرِضُ ٱللَّهَ قَرْضًا حَسَنًا فَيُضَٰعِفَهُۥ لَهُۥٓ أَضْعَافًا كَثِيرَةً وَٱللَّهُ يَقْبِضُ وَيَبْصُۜطُ وَإِلَيْهِ تُرْجَعُونَ", tafsir: `` },
            { text: "أَلَمْ تَرَ إِلَى ٱلْمَلَإِ مِنۢ بَنِىٓ إِسْرَٰٓءِيلَ مِنۢ بَعْدِ مُوسَىٰٓ إِذْ قَالُوا۟ لِنَبِىٍّ لَّهُمُ ٱبْعَثْ لَنَا مَلِكًا نُّقَٰتِلْ فِى سَبِيلِ ٱللَّهِ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ ٱلْقِتَالُ أَلَّا تُقَٰتِلُوا۟ قَالُوا۟ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِى سَبِيلِ ٱللَّهِ وَقَدْ أُخْرِجْنَا مِن دِيَٰرِنَا وَأَبْنَآئِنَا فَلَمَّا كُتِبَ عَلَيْهِمُ ٱلْقِتَالُ تَوَلَّوْا۟ إِلَّا قَلِيلًا مِّنْهُمْ وَٱللَّهُ عَلِيمٌۢ بِٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ٱللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا قَالُوٓا۟ أَنَّىٰ يَكُونُ لَهُ ٱلْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِٱلْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ ٱلْمَالِ قَالَ إِنَّ ٱللَّهَ ٱصْطَفَىٰهُ عَلَيْكُمْ وَزَادَهُۥ بَسْطَةً فِى ٱلْعِلْمِ وَٱلْجِسْمِ وَٱللَّهُ يُؤْتِى مُلْكَهُۥ مَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ", tafsir: `أشموئيل ( إِنَّ اللهَ قَدْ بَعَثَ لَكُمْ ) وعين عليكم ( طالُوتَ مَلِكاً ) وكان من أبناء « بن يامين » أخي يوسف عليه‌السلام ولم يكن من سبط النبوة ولا من سبط المملكة ، فإن النبوة كانت في أولاد « لاوي » ابن يعقوب عليه‌السلام ، والمملكة كانت في أولاد « يهوذا » ابن يعقوب عليه‌السلام ( قالُوا أَنَّى ) أي كيف ( يَكُونُ لَهُ الْمُلْكُ عَلَيْنا ) ويجعل سلطانا وملكا لنا ( وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ ) لأنا من أسباط النبوة والمملكة ( وَلَمْ يُؤْتَ سَعَةً مِنَ الْمالِ ) فهو فقير لا مال له والملك يحتاج إلى المال ليدير شؤون السلطة ( قالَ ) النبي عليه‌السلام في جوابهم ( إِنَّ اللهَ اصْطَفاهُ عَلَيْكُمْ ) والله لا يصطفي إلا من هو الأصلح بحال عباده ( وَزادَهُ بَسْطَةً ) أي سعة وزيادة ( فِي الْعِلْمِ ) والمملكة تحتاج وَالْجِسْمِ وَاللهُ يُؤْتِي مُلْكَهُ مَنْ يَشاءُ وَاللهُ واسِعٌ عَلِيمٌ (247) وَقالَ لَهُمْ نَبِيُّهُمْ إِنَّ آيَةَ مُلْكِهِ أَنْ يَأْتِيَكُمُ التَّابُوتُ فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ إلى علم الملك ليتمكن به من إدارتها ( وَالْجِسْمِ ) فهو رجل سمين يهابه الناس ، شجاع يخافه الأعداء وهذه الأمور هي مقومات الملك لا المال فإن العلم والشجاعة والهيبة تأتي بالمال ، وليس بالعكس ( وَ ) ليس كونه من « بن يامين » نقصا فكما جعل الله الملك في بيت « يهوذا » سابقا يجعله في « طالوت » حالا فإن ( اللهُ يُؤْتِي مُلْكَهُ مَنْ يَشاءُ ) وليس احتكارا على أحد ( وَاللهُ واسِعٌ ) قدرة وعطاء فيهب الملك لمن يشاء ( عَلِيمٌ ) بمصالح العباد فلا يجعل شيئا إلا إذا كان صالحا.` },
            { text: "وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ ءَايَةَ مُلْكِهِۦٓ أَن يَأْتِيَكُمُ ٱلتَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ ءَالُ مُوسَىٰ وَءَالُ هَٰرُونَ تَحْمِلُهُ ٱلْمَلَٰٓئِكَةُ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `أشموئيل زيادة في الدلالة على جعل الله « طالوت » ملكا عليهم ( إِنَّ آيَةَ مُلْكِهِ ) وأن الله تعالى جعله ملكا ( أَنْ يَأْتِيَكُمُ التَّابُوتُ ) وهو تابوت أنزله الله على أم موسى فوضعت موسى فيه حين ألقته في البحر وكان بنوا إسرائيل يتبركون به فلما حضر موسى الموت وضع فيه الألواح ودرعه وما كان عنده من آيات النبوة وأودعه يوشع وصيه فلم يزل التابوت بينهم حتى استخفوا به وكان الصبيان يلعبون به في الطرقات فلم يزل بنوا إسرائيل في عز وشرف ما دام التابوت بينهم فلما عملوا بالمعاصي واستخفوا بالتابوت رفعه الله عنهم ثم جعل رد التابوت عليهم دليلا على أنه جعل الله طالوت ملكا ( فِيهِ سَكِينَةٌ مِنْ رَبِّكُمْ ) تسكنون وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسى وَآلُ هارُونَ تَحْمِلُهُ الْمَلائِكَةُ إِنَّ فِي ذلِكَ لَآيَةً لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ (248) فَلَمَّا فَصَلَ طالُوتُ بِالْجُنُودِ قالَ إِنَّ اللهَ مُبْتَلِيكُمْ بِنَهَرٍ فَمَنْ شَرِبَ مِنْهُ فَلَيْسَ مِنِّي إليه وتعلمون أنكم منصورون بسببه ويكون دليلا على ملك طالوت ( وَبَقِيَّةٌ مِمَّا تَرَكَ آلُ مُوسى وَآلُ هارُونَ ) عصا موسى عليه‌السلام والألواح وطست خاص بالأنبياء عليهم‌السلام وأشياء أخر ، فإنها وصلت بالإرث إلى آل هذين النبيين المعظمين وهم جعلوها في التابوت ( تَحْمِلُهُ الْمَلائِكَةُ ) حملا واقعيا أو حملا ظاهرا بأن رأى بنوا إسرائيل الملائكة بين السماء والأرض أتت بالتابوت ( إِنَّ فِي ذلِكَ ) التابوت الذي رجع إليكم بعد فقده ( لَآيَةً لَكُمْ ) على كون طالوت ملكا ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) مصدقين ، أي إن كنتم مؤمنين قلبا ، تصدقون ذلك.` },
            { text: "فَلَمَّا فَصَلَ طَالُوتُ بِٱلْجُنُودِ قَالَ إِنَّ ٱللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّى وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُۥ مِنِّىٓ إِلَّا مَنِ ٱغْتَرَفَ غُرْفَةًۢ بِيَدِهِۦ فَشَرِبُوا۟ مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ فَلَمَّا جَاوَزَهُۥ هُوَ وَٱلَّذِينَ ءَامَنُوا۟ مَعَهُۥ قَالُوا۟ لَا طَاقَةَ لَنَا ٱلْيَوْمَ بِجَالُوتَ وَجُنُودِهِۦ قَالَ ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُوا۟ ٱللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةًۢ بِإِذْنِ ٱللَّهِ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ", tafsir: `رأى بنوا إسرائيل التابوت صدقوا وانضووا تحت لواء طالوت ، وتحركوا نحو الجهاد مع أعدائهم ولما ( فَصَلَ ) خرج وانفصل عن المدينة ( طالُوتُ بِالْجُنُودِ ) الذين كانوا معه ( قالَ ) طالوت ممتحنا للجنود حتى يتبين مقدار صبرهم وثباتهم على المكاره وأنهم إن جازوا من نهر الماء عطاشا يوثق بهم في الحرب وإن لم يسمعوا ولم يتمكنوا من الصبر على عطش قليل فهم أحرى بأن لا يصبروا أمام السيوف والرماح ( إِنَّ اللهَ مُبْتَلِيكُمْ ) ممتحنكم ( بِنَهَرٍ ) من ماء في طريقكم ( فَمَنْ شَرِبَ مِنْهُ فَلَيْسَ مِنِّي ) ممن يتبعني وَمَنْ لَمْ يَطْعَمْهُ فَإِنَّهُ مِنِّي إِلاَّ مَنِ اغْتَرَفَ غُرْفَةً بِيَدِهِ فَشَرِبُوا مِنْهُ إِلاَّ قَلِيلاً مِنْهُمْ فَلَمَّا جاوَزَهُ هُوَ وَالَّذِينَ آمَنُوا مَعَهُ قالُوا لا طاقَةَ لَنَا الْيَوْمَ بِجالُوتَ وَجُنُودِهِ قالَ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا اللهِ كَمْ مِنْ فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللهِ وَاللهُ مَعَ الصَّابِرِينَ (249) ولينصرف ( وَمَنْ لَمْ يَطْعَمْهُ ) أي لم يذق طعم ذلك الماء ( فَإِنَّهُ مِنِّي ) ويتبعني ( إِلَّا مَنِ اغْتَرَفَ غُرْفَةً ) واحدة ( بِيَدِهِ ) فشربها فقط لا أكثر من ذلك ( فَشَرِبُوا مِنْهُ ) من النهر ( إِلَّا قَلِيلاً مِنْهُمْ ) الذين أطاعوا أمر طالوت فلم يشربوا إلا غرفة واحدة و هؤلاء الذين أطاعوا هم الذين اتبعوا طالوت إلى الحرب أما من عصاه فلم يتبعه ( فَلَمَّا جاوَزَهُ هُوَ ) أي جاوز طالوت النهر ( وَالَّذِينَ آمَنُوا مَعَهُ ) ممن تبعه ولم يشرب الماء إلا غرفة ( قالُوا لا طاقَةَ لَنَا الْيَوْمَ بِجالُوتَ ) وهو رئيس الكفار ( وَجُنُودِهِ ) لما رأوا من كثرتهم ( قالَ الَّذِينَ يَظُنُّونَ أَنَّهُمْ مُلاقُوا اللهِ ) من أصحاب طالوت ، وفي قوله « يظنون » إشارة إلى أن الظن بالمعاد كاف في تحفيز الإنسان نحو الجهاد والأعمال الصالحة ، وملاقاة الله كناية عن القيامة لأنهم يلاقون جزاء الله ( كَمْ مِنْ فِئَةٍ ) أي جماعة ( قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللهِ ) أي بنصره ( وَاللهُ مَعَ الصَّابِرِينَ ) الذين يصبرون على المكاره ويثبتون عند ملاقاة الكفار ، وبهذا الكلام شجعوا أنفسهم وأصحابهم لمقابلة جالوت وجنوده. وَلَمَّا بَرَزُوا لِجالُوتَ وَجُنُودِهِ قالُوا رَبَّنا أَفْرِغْ عَلَيْنا صَبْراً وَثَبِّتْ أَقْدامَنا وَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ (250) فَهَزَمُوهُمْ بِإِذْنِ اللهِ وَقَتَلَ داوُدُ جالُوتَ وَآتاهُ اللهُ الْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُ مِمَّا يَشاءُ وَلَوْ لا دَفْعُ اللهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ لَفَسَدَتِ الْأَرْضُ وَلكِنَّ اللهَ ذُو` },
            { text: "وَلَمَّا بَرَزُوا۟ لِجَالُوتَ وَجُنُودِهِۦ قَالُوا۟ رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ", tafsir: `أي ظهروا في محل الحرب ( لِجالُوتَ وَجُنُودِهِ ) الكثيرة ( قالُوا ) أي قال طالوت والمؤمنون ( رَبَّنا أَفْرِغْ ) أي أصبب ( عَلَيْنا صَبْراً ) لنكون صابرين في الحرب ( وَثَبِّتْ أَقْدامَنا ) حتى لا نفر ( وَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ ) فاستجاب الله سبحانه دعاءهم.` },
            { text: "فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ", tafsir: `أي هزم طالوت والمؤمنون ، جالوت والكفار ( بِإِذْنِ اللهِ ) ونصره ( وَقَتَلَ داوُدُ ) النبي عليه‌السلام وهو أبو سليمان عليه‌السلام ( جالُوتَ ) رئيس الكفار فإن داود أخذ حصاة ورماها بالمقلاع نحو جالوت فأصابت جبهته وكانت فيها ياقوتة فانتشرت ووصلت إلى دماغه وخر ميتا وهزم الكفار ( وَآتاهُ ) أي أعطى ( اللهِ ) داود عليه‌السلام ( الْمُلْكَ وَالْحِكْمَةَ ) فصار نبيا وملكا ( وَعَلَّمَهُ مِمَّا يَشاءُ ) من العلوم الدنيوية والأخروية ( وَلَوْ لا دَفْعُ اللهِ النَّاسَ بَعْضَهُمْ بِبَعْضٍ ) بأن يدفع الكافرين المفسدين بسبب المؤمنين المصلحين ( لَفَسَدَتِ الْأَرْضُ ) لما يوجدون فيها من القتل والحرق والسبي والإفساد ( وَلكِنَّ اللهَ ذُو فَضْلٍ عَلَى الْعالَمِينَ (251) تِلْكَ آياتُ اللهِ نَتْلُوها عَلَيْكَ بِالْحَقِّ وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ (252) فَضْلٍ عَلَى الْعالَمِينَ ) فيدفع الفاسد بالصالح لتبقى الأرض عامرة وينمو الزرع والضرع.` },
            { text: "تِلْكَ ءَايَٰتُ ٱللَّهِ نَتْلُوهَا عَلَيْكَ بِٱلْحَقِّ وَإِنَّكَ لَمِنَ ٱلْمُرْسَلِينَ", tafsir: `أي تلك التي ذكرت من إماتة الأحياء دفعة وإحياء الموتى دفعة وتمليك طالوت ونصرة المؤمنين على أعدائهم دلالات الله على وجوده وقدرته وعلمه وسائر صفاته ( نَتْلُوها ) نقرؤها ( عَلَيْكَ ) يا رسول الله ( بِالْحَقِ ) أي بالصدق فلا كذب فيها وأنزلت لأجل الصدق لا لأجل الباطل والكذب والغش ( وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ ) حيث تخبر بهذه الأخبار عن غيب بدلالة الله لك ووحيه إياها إليك. تقريب القران الى الأذهان من آية ( 254) سورة البقرة إلى ( 93) سورة آل عمران بسم الله الرّحمن الرّحيم الحمد لله ربّ العالمين ، والصلاة والسّلام على أشرف الأنبياء والمرسلين محمّد المصطفى وعترته الطّاهرين. تِلْكَ الرُّسُلُ فَضَّلْنا بَعْضَهُمْ عَلى بَعْضٍ مِنْهُمْ مَنْ كَلَّمَ اللهُ وَرَفَعَ بَعْضَهُمْ دَرَجاتٍ وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ وَأَيَّدْناهُ بِرُوحِ الْقُدُسِ وَلَوْ شاءَ اللهُ مَا اقْتَتَلَ الَّذِينَ مِنْ بَعْدِهِمْ` },
            { text: "تِلْكَ ٱلرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ مِّنْهُم مَّن كَلَّمَ ٱللَّهُ وَرَفَعَ بَعْضَهُمْ دَرَجَٰتٍ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَٰتِ وَأَيَّدْنَٰهُ بِرُوحِ ٱلْقُدُسِ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلَ ٱلَّذِينَ مِنۢ بَعْدِهِم مِّنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَٰتُ وَلَٰكِنِ ٱخْتَلَفُوا۟ فَمِنْهُم مَّنْ ءَامَنَ وَمِنْهُم مَّن كَفَرَ وَلَوْ شَآءَ ٱللَّهُ مَا ٱقْتَتَلُوا۟ وَلَٰكِنَّ ٱللَّهَ يَفْعَلُ مَا يُرِيدُ", tafsir: `الذين أشير إليهم في قوله ( إِنَّكَ لَمِنَ الْمُرْسَلِينَ ) ( فَضَّلْنا بَعْضَهُمْ عَلى بَعْضٍ ) فهم وإن اشتركوا في أصل الرسالة إلا أنهم مختلفين في الفضيلة ( مِنْهُمْ مَنْ كَلَّمَ اللهُ ) إياه وهو موسى عليه‌السلام وحيث أن هناك محل سؤال : هل يمكن للإنسان أن يرتقي هذا المرتقى العظيم حتى يكلمه الله سبحانه ؟ ألمحت الآية إلى ذلك قائلة : ( وَرَفَعَ بَعْضَهُمْ دَرَجاتٍ ) لا درجة واحدة ، حتى سببت تلك الرفعة أن يتمكن من مكالمة الله مباشرة ( وَآتَيْنا عِيسَى ابْنَ مَرْيَمَ الْبَيِّناتِ ) وأنه لمن تفنن القرآن الحكيم في التعبير حيث لم يصرح باسم موسى وصرح باسم عيسى عليه‌السلام والبينات هي الدلالات الواضحات على نبوته من إحياء الموتى وإبراء الأكمه والأبرص ( وَأَيَّدْناهُ ) أي قويناه فإن التأييد بمعنى التقوية ( بِرُوحِ الْقُدُسِ ) أي روح مقدسة ، كما مر سابقا فلم يكن إنسانا عاديا ولا خالقا وربا وإنما نبي مؤيد من عند الله سبحانه ، وحيث كان هنا مجال سؤال هو أن الأنبياء عليهم‌السلام حيث أتوا بالدلالات لم يكن مجال لتشكيك الناس فيهم فكيف تقع الحروب بين الناس حول الأنبياء إثباتا أو نفيا أو إثباتا لنبي دون نبي ؟ أتى السياق مشيرا إلى جواب ذلك ( وَلَوْ شاءَ اللهُ ) بأن ألجأ الناس واضطرهم على الانقياد والاهتداء ( مَا اقْتَتَلَ الَّذِينَ مِنْ بَعْدِهِمْ ) أي من بعد الرسل أي بعد مجيء كل واحد منهم مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّناتُ وَلكِنِ اخْتَلَفُوا فَمِنْهُمْ مَنْ آمَنَ وَمِنْهُمْ مَنْ كَفَرَ وَلَوْ شاءَ اللهُ مَا اقْتَتَلُوا وَلكِنَّ اللهَ يَفْعَلُ ما يُرِيدُ (253) يا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِمَّا رَزَقْناكُمْ مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لا بَيْعٌ فِيهِ وَلا خُلَّةٌ وَلا شَفاعَةٌ ( مِنْ بَعْدِ ما جاءَتْهُمُ الْبَيِّناتُ ) أي جاءت الناس الأدلة الواضحة ( وَلكِنِ اخْتَلَفُوا ) أي الناس ( فَمِنْهُمْ مَنْ آمَنَ وَمِنْهُمْ مَنْ كَفَرَ ) بالرسول ( وَلَوْ شاءَ اللهُ مَا اقْتَتَلُوا ) تكريرا للتأكيد وأن المشيئة الإلجائية لم تتعلق حول التشريع وإن تعلقت حول التكوين ( وَلكِنَّ اللهَ يَفْعَلُ ما يُرِيدُ ) من إعطاء الاختيار بيد الإنسان ليؤمن من آمن عن اختيار ويكفر من كفر عن اختيار ليثبت الجزاء والحساب ولم يذكر الرسول صلى‌الله‌عليه‌وآله‌وسلم لأن الخطاب موجه إليه ( وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ ) . [255] وحيث أن القتال يحتاج إلى الإنفاق يزاوج القرآن الحكيم في آياته بين الأمرين كثيرا ( يا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِمَّا رَزَقْناكُمْ ) من مختلف أنواع الرزق ، ولعل عمومه يشمل مثل التعليم والشفاعة ونحوها فإن العلم والوجاهة من رزق الله سبحانه ( مِنْ قَبْلِ أَنْ يَأْتِيَ يَوْمٌ لا بَيْعٌ فِيهِ ) حتى يشتري الإنسان نفسه بشيء فينجيها من عذاب الله سبحانه ( وَلا خُلَّةٌ ) أي صداقة فيراعى الصديق المذنب لأجل صديقه ، أو صداقة بين الله وبين أحد حتى يراعيه ويغفر ذنبه لصداقته ( وَلا شَفاعَةٌ ) كشفاعات الدنيا حيث أن الشفيع ينبعث من نفسه فيشفع للمذنب ، فإن هناك لا يشفعون إلا لمن ارتضى وَالْكافِرُونَ هُمُ الظَّالِمُونَ (254) اللهُ لا إِلهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلاَّ بِإِذْنِهِ يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ وَما خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلاَّ بِما شاءَ ( وَالْكافِرُونَ هُمُ الظَّالِمُونَ ) فليس حرمان الكافر في ذلك اليوم لأجل الظلم من قبل الله سبحانه بل الكافر هو الظالم الذي استحق العقاب بكفره وظلمه نفسه حيث حرمها من نيل المثوبة.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَٰكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَٰعَةٌ وَٱلْكَٰفِرُونَ هُمُ ٱلظَّٰلِمُونَ", tafsir: `` },
            { text: "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ لَّهُۥ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ مَن ذَا ٱلَّذِى يَشْفَعُ عِندَهُۥٓ إِلَّا بِإِذْنِهِۦ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ وَسِعَ كُرْسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا وَهُوَ ٱلْعَلِىُّ ٱلْعَظِيمُ", tafsir: `فالأمور في يوم القيامة كلها بيده لا يشارك فيما يفعل ولعل هذا هو وجه الارتباط بين هذه الآية والآية السالفة ( الْحَيُ ) الذي لا يموت فلا يمكن التخلص منه ( الْقَيُّومُ ) القائم على الأمور يعلمها جميعا فلا يمكن الاختفاء منه. ( لا تَأْخُذُهُ سِنَةٌ ) وهي النوم الخفيف المسمى بالنعاس ( وَلا نَوْمٌ ) وقدم الأول لتقدمه في الخارج ( لَهُ ما فِي السَّماواتِ وَما فِي الْأَرْضِ ) فهو الخالق والمالك الوحيد الذي لا يشاركه أحد ، والظرف هنا يتبع المظروف فليست السماوات والأرض خارجتين عن الملكية ( مَنْ ذَا ) أي أي شخص ( الَّذِي يَشْفَعُ عِنْدَهُ ) يوم القيامة ( إِلَّا بِإِذْنِهِ ) استفهام إنكاري فإنهم لا يشفعون إلا لمن ارتضى ( يَعْلَمُ ما بَيْنَ أَيْدِيهِمْ وَما خَلْفَهُمْ ) أي ما يقدمون من أعمال خير وشر وما يخلفون من بعدهم كبناء مدرسة أو مخمر يبقيان بعده ( وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ ) أي بما يعلمه من الماضي والحاضر والآتي ( إِلَّا بِما شاءَ ) أي وَسِعَ كُرْسِيُّهُ السَّماواتِ وَالْأَرْضَ وَلا يَؤُدُهُ حِفْظُهُما وَهُوَ الْعَلِيُّ الْعَظِيمُ (255) لا إِكْراهَ فِي الدِّينِ قَدْ تَبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ فَمَنْ يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِنْ بِاللهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقى بما أراد من اطلاع الناس عليه فإن علم الشخص حتى بالضروريات مما تتعلق به مشيئة الله سبحانه فإنه هو الذي جعل الإنسان بحيث يعلم الأمور في الجملة ( وَسِعَ كُرْسِيُّهُ السَّماواتِ وَالْأَرْضَ ) الكرسي كناية عن السلطة والملكية يقال : كرسي فلان يسع العراق إذا كان ملكا عليها ، أي أن سلطة الله سبحانه تشمل جميع الكون ، فإنه لا يخلو من سماء وأرض ( وَلا يَؤُدُهُ ) أي لا يشق عليه تعالى ، من آده يأده ، إذا أثقله وجهده ( حِفْظُهُما ) أي حفظ السماوات والأرض بالتربية والتنمية والإصلاح ( وَهُوَ الْعَلِيُ ) أي الرفيع مقاما ( الْعَظِيمُ ) الشأن.` },
            { text: "لَآ إِكْرَاهَ فِى ٱلدِّينِ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ فَمَن يَكْفُرْ بِٱلطَّٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا وَٱللَّهُ سَمِيعٌ عَلِيمٌ", tafsir: `فإن الله لم يلجأ الخلق إلى اعتناق الدين بل جعل فيهم الاختيار والإرادة فإن شاءوا دانوا وإن لم يشاءوا لم يدينوا ( قَدْ تَبَيَّنَ ) أي وضح ( الرُّشْدُ مِنَ الْغَيِ ) أي الهداية من الضلالة والإيمان من الكفر والحق من الباطل ( فَمَنْ يَكْفُرْ بِالطَّاغُوتِ ) وهو كل ما يعبد من دون الله ( وَيُؤْمِنْ بِاللهِ ) وحده ، وقدم نفي الكفر لأن النفي مقدم على الإثبات كما قدم في كلمة « لا إله إلا الله » ( فَقَدِ اسْتَمْسَكَ ) أي تمسك واعتصم وأخذ ( بِالْعُرْوَةِ ) وهي « المسكة » لمثل الكوز ( الْوُثْقى ) أي الوثيقة التي لا تنفصل فقد شبه الخير بإناء للسقي لا انْفِصامَ لَها وَاللهُ سَمِيعٌ عَلِيمٌ (256) اللهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُمْ مِنَ الظُّلُماتِ إِلَى النُّورِ وَالَّذِينَ كَفَرُوا أَوْلِياؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُمْ مِنَ النُّورِ إِلَى الظُّلُماتِ أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (257) أو الطعام له عروة فالإيمان بالله عروة وثقى للخير لأنه ( لَا انْفِصامَ لَها ) ولا انقطاع بل تدوم الاستفادة من الخير بسبب الإيمان في الدنيا والآخرة بينما الإيمان بالطاغوت عروة واهية تنفصم إذا فارق الإنسان الحياة الدنيا ينقطع الخير الذي يناله الإنسان ـ فرضا ـ بسبب الكفر ( وَاللهُ سَمِيعٌ ) لأقوالكم ( عَلِيمٌ ) بنياتكم وأعمالكم.` },
            { text: "ٱللَّهُ وَلِىُّ ٱلَّذِينَ ءَامَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `يلي أمورهم وينصرهم ويعينهم ( يُخْرِجُهُمْ مِنَ الظُّلُماتِ ) ظلمات الحياة ومشاكلها ، من ظلمة العقيدة ، وظلمة القول وظلمة الدنيا كلها ( إِلَى النُّورِ ) نور الهداية ، ونور الآخرة ( وَالَّذِينَ كَفَرُوا أَوْلِياؤُهُمُ الطَّاغُوتُ ) أي أن جنس الطاغوت يكون أولياء لهم ، فإن الطواغيت من الجن والإنس يتولون أمورهم وضلالهم وحيث أن الطاغوت أريد به الجنس جاز الإتيان بصيغة الجمع في « أوليائهم » صفة له ( يُخْرِجُونَهُمْ مِنَ النُّورِ ) الكامن في فطرتهم ، ومن نور الدنيا ( إِلَى الظُّلُماتِ ) ظلمات الكفر والظلال في الدنيا وعذاب الله في الآخرة ( أُولئِكَ ) الذين كفروا ( أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) إلى الأبد فلا منجي لهم ولا مخلص [259] سبق الحديث عن الإيمان والكفر ، فلتناسب المقام قصة حوار أَ لَمْ تَرَ إِلَى الَّذِي حَاجَّ إِبْراهِيمَ فِي رَبِّهِ أَنْ آتاهُ اللهُ الْمُلْكَ إِذْ قالَ إِبْراهِيمُ رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ قالَ أَنَا أُحْيِي وَأُمِيتُ قالَ إِبْراهِيمُ فَإِنَّ اللهَ يَأْتِي بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِها مِنَ الْمَغْرِبِ فَبُهِتَ الَّذِي كَفَرَ حول هذا الموضوع بين إبراهيم عليه‌السلام ونمرود ( أَ لَمْ تَرَ ) أي ألم تعلم ، وقد تقدم أن هذه العبارة تذكر لإفادة العلم ( إِلَى الَّذِي حَاجَ ) من المحاجة بمعنى المجادلة والمخاصمة ( إِبْراهِيمَ فِي رَبِّهِ ) أي في باب رب إبراهيم عليه‌السلام الذي كان يعبده ، أو رب الذي حاج وإن كان الأول أقرب ( أَنْ آتاهُ اللهُ الْمُلْكَ ) أي حيث أن الله أعطى نمرود الملك والسلطة بطر فأنكر وجود الخالق وجعل يجادل نبيه إبراهيم عليه‌السلام حول وجود الله سبحانه فقد قابل الإحسان بالإساءة ( إِذْ قالَ إِبْراهِيمُ رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ ) في جواب نمرود حيث قال له : من ربك ؟ والمراد بالإحياء إحياء الجماد فإن كل حي أصله التراب والماء إذ التراب بسبب الماء ينقلب عشبا والعشب ينقلب نطفة إنسانا أو حيوانا ( قالَ ) نمرود ( أَنَا أُحْيِي وَأُمِيتُ ) فأخرج نفرين من حبسه وضرب عنق أحدهما وأطلق الآخر وكان هذا مغالطة من نمرود إلا أن إبراهيم عليه‌السلام أراد أن يلزمه بحجة لا يتمكن حتى من المغالطة فيها ف ( قالَ إِبْراهِيمُ فَإِنَّ اللهَ يَأْتِي بِالشَّمْسِ مِنَ الْمَشْرِقِ ) هكذا يظهر للأبصار سواء دارت هي أو دارت الأرض كما يقوله بعض علماء الفلك ( فَأْتِ بِها مِنَ الْمَغْرِبِ ) إن كنت إلها خالقا ( فَبُهِتَ الَّذِي كَفَرَ ) أي تحير وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ (258) أَوْ كَالَّذِي مَرَّ عَلى قَرْيَةٍ وَهِيَ خاوِيَةٌ عَلى عُرُوشِها قالَ أَنَّى يُحْيِي هذِهِ اللهُ بَعْدَ مَوْتِها فَأَماتَهُ اللهُ مِائَةَ عامٍ ثُمَّ بَعَثَهُ قالَ كَمْ لَبِثْتَ قالَ لَبِثْتُ يَوْماً أَوْ بَعْضَ يَوْمٍ قالَ بَلْ لَبِثْتَ مِائَةَ عامٍ نمرود ولم يحر جوابا ( وَاللهُ لا يَهْدِي الْقَوْمَ الظَّالِمِينَ ) الذين ظلموا أنفسهم بتعاميهم عن الحق فإنه سبحانه لا يلطف لطفه الخاص بمثل هؤلاء وإن أتم عليهم الحجة وأراهم الطريق.` },
            { text: "أَلَمْ تَرَ إِلَى ٱلَّذِى حَآجَّ إِبْرَٰهِـۧمَ فِى رَبِّهِۦٓ أَنْ ءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ إِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّىَ ٱلَّذِى يُحْىِۦ وَيُمِيتُ قَالَ أَنَا۠ أُحْىِۦ وَأُمِيتُ قَالَ إِبْرَٰهِـۧمُ فَإِنَّ ٱللَّهَ يَأْتِى بِٱلشَّمْسِ مِنَ ٱلْمَشْرِقِ فَأْتِ بِهَا مِنَ ٱلْمَغْرِبِ فَبُهِتَ ٱلَّذِى كَفَرَ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "أَوْ كَٱلَّذِى مَرَّ عَلَىٰ قَرْيَةٍ وَهِىَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْىِۦ هَٰذِهِ ٱللَّهُ بَعْدَ مَوْتِهَا فَأَمَاتَهُ ٱللَّهُ مِا۟ئَةَ عَامٍ ثُمَّ بَعَثَهُۥ قَالَ كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ بَل لَّبِثْتَ مِا۟ئَةَ عَامٍ فَٱنظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمْ يَتَسَنَّهْ وَٱنظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ ءَايَةً لِّلنَّاسِ وَٱنظُرْ إِلَى ٱلْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `أي ألم تر إلى الذي مر على قرية ، والمعنى إن شئت فانظر إلى الذي حاج وإن شئت فانظر إلى الذي مر على قرية وهو عزيز النبي عليه‌السلام أو أرميا ( وَهِيَ خاوِيَةٌ عَلى عُرُوشِها ) أي ساقطة حيطانها على سقوفها وأهلها موتى والسباع تأكل الجيف ففكر في نفسه ساعة ( قالَ أَنَّى ) أي كيف ( يُحْيِي هذِهِ ) الأموات ( اللهُ بَعْدَ مَوْتِها ) وكان ذلك منه تعجبا لا إنكارا ( فَأَماتَهُ اللهُ مِائَةَ عامٍ ) حتى بلي ونخرت عظامه ( ثُمَّ بَعَثَهُ ) أحياه كما كان ( قالَ ) الله سبحانه له بإيجاد صوت في الجو ( كَمْ لَبِثْتَ ) في مبيتك ومنامك ( قالَ ) النبي ( لَبِثْتُ يَوْماً ) ثم نظر فإذا هو نام صباحا والآن قبل غروب الشمس فأضرب قائلا ( أَوْ بَعْضَ يَوْمٍ قالَ ) الله سبحانه ( بَلْ لَبِثْتَ مِائَةَ عامٍ ) وقد كان معه طعام وشراب وحمار ، فكان الطعام والشراب باقيين كما هما وكان الحمار قد مات وتفرقت عظامه ونخرت دلالة على كمال قدرة الله فَانْظُرْ إِلى طَعامِكَ وَشَرابِكَ لَمْ يَتَسَنَّهْ وَانْظُرْ إِلى حِمارِكَ وَلِنَجْعَلَكَ آيَةً لِلنَّاسِ وَانْظُرْ إِلَى الْعِظامِ كَيْفَ نُنْشِزُها ثُمَّ نَكْسُوها لَحْماً فَلَمَّا تَبَيَّنَ لَهُ قالَ أَعْلَمُ أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ (259) وَإِذْ قالَ إِبْراهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِ الْمَوْتى سبحانه ( فَانْظُرْ إِلى طَعامِكَ وَشَرابِكَ لَمْ يَتَسَنَّهْ ) لم تغيره السنون ، والإتيان بلفظ المفرد باعتبار كل واحد منهما ( وَانْظُرْ إِلى حِمارِكَ ) كيف مات ونخرت عظامه ( وَلِنَجْعَلَكَ ) أيها الرسول ( آيَةً لِلنَّاسِ ) أي حجة حيث أحييناك بعد مائة عام حتى يعرف الناس أن الله قادر على بعث الأموات ( وَانْظُرْ إِلَى الْعِظامِ ) لحمارك المتفتتة ( كَيْفَ نُنْشِزُها ) أي كيف نرفع بعضها إلى بعض لنركب منها الهيكل العظمي للحمار ( ثُمَّ نَكْسُوها ) أي نلبس العظام ( لَحْماً ) حتى يستوي حمارا حيا ( فَلَمَّا تَبَيَّنَ لَهُ ) أي وضح له إحياء الأموات عيانا ( قالَ ) النبي عليه‌السلام ( أَعْلَمُ أَنَّ اللهَ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) أي علما عيانا وإلا فقد كان يعلم ذلك قبل السؤال.` },
            { text: "وَإِذْ قَالَ إِبْرَٰهِـۧمُ رَبِّ أَرِنِى كَيْفَ تُحْىِ ٱلْمَوْتَىٰ قَالَ أَوَلَمْ تُؤْمِن قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِى قَالَ فَخُذْ أَرْبَعَةً مِّنَ ٱلطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ ٱجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ٱدْعُهُنَّ يَأْتِينَكَ سَعْيًا وَٱعْلَمْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ", tafsir: `اذكر يا رسول الله ( إِذْ قالَ إِبْراهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِ الْمَوْتى ) فإنه عليه‌السلام رأى جيفة تمزقها السباع فيأكل منها سباع البر وسباع الهواء ودواب البحر فسأل الله إبراهيم عليه‌السلام فقال : يا رب قد علمت أنك تجمعها من بطون السباع والطير ودواب البر فأرني كيف قالَ أَ وَلَمْ تُؤْمِنْ قالَ بَلى وَلكِنْ لِيَطْمَئِنَّ قَلْبِي قالَ فَخُذْ أَرْبَعَةً مِنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ اجْعَلْ عَلى كُلِّ جَبَلٍ مِنْهُنَّ جُزْءاً ثُمَّ ادْعُهُنَّ يَأْتِينَكَ سَعْياً وَاعْلَمْ أَنَّ اللهَ عَزِيزٌ حَكِيمٌ (260) تحييها لأعاين ذلك ( قالَ ) الله سبحانه ( أَ وَلَمْ تُؤْمِنْ ) على نحو استفهام التقرير ، ليقول آمنت ، كقولهم : « ألستم خير من ركب المطايا » ( قالَ ) إبراهيم عليه‌السلام ( بَلى ) أنا مؤمن ( وَلكِنْ ) أسأل ذلك ( لِيَطْمَئِنَّ قَلْبِي ) ويكون يقيني عين اليقين فإن الإنسان الذي يعلم أن النار ـ مثلا ـ حارة ، يسمى ذلك علم اليقين ، فإذا رآها سمي حق اليقين ، فإذا أدخل يده فيها فاحترقت سمي عين اليقين ، وورد أنه عليه‌السلام علم أن الله يتخذ عبدا له خليلا إذا سأله إحياء الموتى أحياها فأراد أن يطمئن أنه هو ( قالَ ) الله سبحانه ( فَخُذْ أَرْبَعَةً مِنَ الطَّيْرِ ) الطاووس والحمام والغراب والديك فاذبحهن وقطعهن واخلطهن بعضا ببعض ( فَصُرْهُنَّ إِلَيْكَ ) من صرته بمعنى قطعته و « إليك » إنما هو من مستلزمات القطع ، فإن الإنسان إذا أراد أن يقطع شيئا قطعا جيدا ويخلطه لا بد وأن يجذبه إليه ولعله كناية عن القطع الجيد والتخليط البالغ ( ثُمَّ اجْعَلْ عَلى كُلِّ جَبَلٍ ) من عشرة جبال ( مِنْهُنَّ جُزْءاً ) وإنما ذلك يدل على أن الأجزاء الميتة تجتمع من محلات متباعدة وقت الحشر ( ثُمَّ ادْعُهُنَ ) بأن تأخذ بمنقار كل واحد من الطيور الأربعة في يدك وتدعوه باسمه ( يَأْتِينَكَ ) تجتمع الأجزاء من الجبال ( سَعْياً ) مسرعات ( وَاعْلَمْ أَنَّ اللهَ عَزِيزٌ ) لا يمتنع عليه شيء ( حَكِيمٌ ) فيما يفعل فلا يفعل شيئا اعتباطا وعبثا ، ففعل إبراهيم عليه‌السلام ذلك فتطايرت مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ وَاللهُ يُضاعِفُ لِمَنْ يَشاءُ وَاللهُ واسِعٌ عَلِيمٌ (261) الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ ثُمَّ لا يُتْبِعُونَ ما أَنْفَقُوا مَنًّا الأجزاء بعضها إلى بعض حتى استوت الأبدان وجاء كل بدن حتى نظم إلى رقبته ورأسه فأطلقها إبراهيم عليه‌السلام فطرن فالتقطن الحب وشربن الماء ثم دعون لإبراهيم عليه‌السلام . [262] تقدم الكلام في الآيات السابقة عن من يقرض الله قرضا حسنا ، ثم تخلل الكلام دليل التوحيد والرسالة والمعاد والآن يرجع السياق إلى الإنفاق ( مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ ) لا رياء أو سمعة وشهرة ونحوها ( كَمَثَلِ حَبَّةٍ ) من الحنطة أو الشعير أو نحوهما ( أَنْبَتَتْ ) أي أخرجت ( سَبْعَ سَنابِلَ ) جمع سنبلة وهي مجمع الحبات ( فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ ) فتكون النفقة في سبيل الله بسبعمائة ضعف ( وَاللهُ يُضاعِفُ ) أي يزيد كل سبعمائة ( لِمَنْ يَشاءُ ) من عباده من المنفقين ( وَاللهُ واسِعٌ عَلِيمٌ ) يسع علمه وقدرته فيعلم المنفق والإنفاق ، وقد مثل الإنفاق بهذا ليكون أوقع في النفس وأكثر في التأثير والتشويق. [263] ثم ذكر شرطا آخر للإنفاق المثمر الموجب للأجر بقوله تعالى : ( الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ فِي سَبِيلِ اللهِ ثُمَّ لا يُتْبِعُونَ ) أي لا يعقبون ( ما أَنْفَقُوا مَنًّا ) على المعطى له بأن يمن عليه في إنفاقه كأن يقول له : إني وَلا أَذىً لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (262) قَوْلٌ مَعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِنْ صَدَقَةٍ يَتْبَعُها أَذىً وَاللهُ غَنِيٌّ حَلِيمٌ (263) يا أَيُّهَا الَّذِينَ آمَنُوا لا تُبْطِلُوا صَدَقاتِكُمْ بِالْمَنِّ وَالْأَذى كَالَّذِي يُنْفِقُ مالَهُ رِئاءَ النَّاسِ أعطيتك فكن شاكرا ( وَلا أَذىً ) بأن يؤذى المعطى له ، كأن يقول : ابتليت بفلان الفقير ( لَهُمْ أَجْرُهُمْ ) وجزاء إنفاقهم ( عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ ) من العذاب لأن من ينفق هكذا يكون مخلصا في جميع أعماله ، أو لا خوف عليهم من فوت الأجر ( وَلا هُمْ يَحْزَنُونَ ) وهو يحتمل الأمرين مثل ـ لا خوف ـ.` },
            { text: "مَّثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ كَمَثَلِ حَبَّةٍ أَنۢبَتَتْ سَبْعَ سَنَابِلَ فِى كُلِّ سُنۢبُلَةٍ مِّا۟ئَةُ حَبَّةٍ وَٱللَّهُ يُضَٰعِفُ لِمَن يَشَآءُ وَٱللَّهُ وَٰسِعٌ عَلِيمٌ", tafsir: `` },
            { text: "ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمْ فِى سَبِيلِ ٱللَّهِ ثُمَّ لَا يُتْبِعُونَ مَآ أَنفَقُوا۟ مَنًّا وَلَآ أَذًى لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `` },
            { text: "قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَآ أَذًى وَٱللَّهُ غَنِىٌّ حَلِيمٌ", tafsir: `بأن يرد به السائل ، نحو الله يعطيك ( وَمَغْفِرَةٌ ) أي تجاوز عن السائل فيما إذا أساء ( خَيْرٌ مِنْ صَدَقَةٍ يَتْبَعُها أَذىً ) لأن الصدقة كذلك تجرح قلب السائل دونهما ، ولأنها تتبع العقاب ، لأن هكذا صدقة محرمة ، بخلافهما ( وَاللهُ غَنِيٌ ) فلا يحتاج إلى صدقاتكم أيها المعطون ، وإنما أنتم تحتاجون إليها ، فحث الله بالإنفاق لكم ، لا له ( حَلِيمٌ ) حليم عن عقابكم بسبب صدقاتكم التي يتبعها الأذى.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لَا تُبْطِلُوا۟ صَدَقَٰتِكُم بِٱلْمَنِّ وَٱلْأَذَىٰ كَٱلَّذِى يُنفِقُ مَالَهُۥ رِئَآءَ ٱلنَّاسِ وَلَا يُؤْمِنُ بِٱللَّهِ وَٱلْيَوْمِ ٱلْـَٔاخِرِ فَمَثَلُهُۥ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُۥ وَابِلٌ فَتَرَكَهُۥ صَلْدًا لَّا يَقْدِرُونَ عَلَىٰ شَىْءٍ مِّمَّا كَسَبُوا۟ وَٱللَّهُ لَا يَهْدِى ٱلْقَوْمَ ٱلْكَٰفِرِينَ", tafsir: `على السائل ( وَالْأَذى ) له فإن فيها إبطالا للصدقة من حيث الثواب فلا ثواب لها عند العرف لأن مثل هذه الصدقة لا تحسب جميلا وإنما قبيحا بشعا ، فإن من يبطل صدقته بالمن والأذى فهو ( كَالَّذِي يُنْفِقُ مالَهُ رِئاءَ النَّاسِ ) لأجل وَلا يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَمَثَلُهُ كَمَثَلِ صَفْوانٍ عَلَيْهِ تُرابٌ فَأَصابَهُ وابِلٌ فَتَرَكَهُ صَلْداً لا يَقْدِرُونَ عَلى شَيْءٍ مِمَّا كَسَبُوا وَاللهُ لا يَهْدِي الْقَوْمَ الْكافِرِينَ (264) أن يراه الناس فيمدحوه ( وَلا يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ ) بأن يكون الداعي له إلى التصدق أمر الله سبحانه أو ثواب الآخرة ( فَمَثَلُهُ كَمَثَلِ صَفْوانٍ عَلَيْهِ تُرابٌ فَأَصابَهُ وابِلٌ فَتَرَكَهُ صَلْداً ) الصفوان : الحجر الأملس ، والوابل : المطر الشديد الوقع ، والصلد من الأرض ما لا ينبت شيئا لصلابته ، فإن الإنسان الكافر كالحجر الصلب الذي لا يرجى منه خير ، وما يتحفظ به ظواهره بمنزلة تراب على الحجر يظن الناس أنه محل قابل للنبت ، والصدقة التي يرائي بها كالمطر الشديد ، فإنه إذا نزل بأرض صالحة كان مبعث الخير والنبات لكنه إذا نزل على الحجر المغطى بالتراب أزال ترابه وأظهر صلادته وعدم قبوله لأي إنبات أو عشب ، وكذلك الكافر الذي يظن به الناس بعض الخير إذا أنفق رياء ظهر على الناس حقيقته المنحرفة فتكون الصدقة ـ التي هي بذاتها سبب الخير والرحمة ـ معرية لحقيقة الكافر البشعة ، ومن ناحية أخرى أنها توجب سخط الله عليه أكثر من ذي قبل فتكون مذهبة لما يظن أنها حسنة له من بعض أعماله الخيرية السابقة ( لا يَقْدِرُونَ عَلى شَيْءٍ مِمَّا كَسَبُوا ) من مكاسبهم السابقة لأن الصدقة برياء ذهاب بها كما أن المطر يذهب بالتراب فلا يمكن إرجاعه وجمعه ( وَاللهُ لا يَهْدِي الْقَوْمَ الْكافِرِينَ ) فلا يلطف بهم اللطف الخاص لأنهم أسقطوا أنفسهم عن القابلية لجحودهم بعد أن عرفوا الحق. وَمَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوالَهُمُ ابْتِغاءَ مَرْضاتِ اللهِ وَتَثْبِيتاً مِنْ أَنْفُسِهِمْ كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ أَصابَها وابِلٌ فَآتَتْ أُكُلَها ضِعْفَيْنِ فَإِنْ لَمْ يُصِبْها وابِلٌ فَطَلٌّ وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ (265) أَ يَوَدُّ أَحَدُكُمْ أَنْ` },
            { text: "وَمَثَلُ ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُمُ ٱبْتِغَآءَ مَرْضَاتِ ٱللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍۭ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَـَٔاتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", tafsir: `أي لأجل طلب رضى الله سبحانه ( وَتَثْبِيتاً مِنْ أَنْفُسِهِمْ ) أي لأجل تثبيت أعمالهم الحسنة وتركيزها ، تثبيتا ناشئا من أنفسهم فأنفسهم هي التي توصي بذلك ، لا كالمرائي الذي يحمله على الصدقة رؤية الناس ، فهذه الجملة « من أنفسهم » مقابل جملة « رئاء الناس » في الآية السابقة ( كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ ) أي بستان مرتفع ( أَصابَها وابِلٌ ) مطر غزير ( فَآتَتْ ) أي أعطت ( أُكُلَها ) وثمرها ( ضِعْفَيْنِ ) فإن الإنسان المؤمن كالبستان الواقع في مرتفع يزهو للناس ويكون أقرب إلى الاستفادة من الهواء والشمس والمطر ، فإن المؤمن أقرب إلى الخير فإذا تصدق تكون صدقته كالمطر الذي إذا نزل بالبستان يوجب نمو ثمارها وازدهار أشجارها ( فَإِنْ لَمْ يُصِبْها وابِلٌ ) مطر غزير فيكفي لإثمارها وإنضارها طل رذاذ من مطر قليل ( وَاللهُ بِما تَعْمَلُونَ بَصِيرٌ ) فيجازيكم على أعمالكم إن رياء وإن قربة. [267] ولما مثل سبحانه لصدقة كل من المؤمن والكافر ، مثل لصدقة المؤمن الذي يمن بصدقته فيبطلها ( أَ يَوَدُّ ) أي هل يحب ( أَحَدُكُمْ أَنْ تَكُونَ لَهُ جَنَّةٌ مِنْ نَخِيلٍ وَأَعْنابٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ لَهُ فِيها مِنْ كُلِّ الثَّمَراتِ وَأَصابَهُ الْكِبَرُ وَلَهُ ذُرِّيَّةٌ ضُعَفاءُ فَأَصابَها إِعْصارٌ فِيهِ نارٌ فَاحْتَرَقَتْ كَذلِكَ يُبَيِّنُ اللهُ لَكُمُ الْآياتِ لَعَلَّكُمْ تَتَفَكَّرُونَ (266) يا أَيُّهَا الَّذِينَ آمَنُوا أَنْفِقُوا مِنْ طَيِّباتِ ما كَسَبْتُمْ وَمِمَّا أَخْرَجْنا لَكُمْ مِنَ الْأَرْضِ تَكُونَ لَهُ جَنَّةٌ مِنْ نَخِيلٍ وَأَعْنابٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهارُ ) أي تحت أشجارها ( لَهُ فِيها ) أي في تلك الجنة ( مِنْ كُلِّ الثَّمَراتِ وَأَصابَهُ الْكِبَرُ ) أي الشيخوخة ( وَلَهُ ذُرِّيَّةٌ ضُعَفاءُ ) عاجزون عن كسب المأكل والملبس ( فَأَصابَها ) أي أصاب الجنة ( إِعْصارٌ فِيهِ نارٌ فَاحْتَرَقَتْ ) كلا لا يحب أحد ذلك إنه في أشد أوقات حاجته ، فهل يرضى إصابة النار بأثمن ما يملك ؟ إن مثل من ينفق عن إيمان واعتقاد مثل تلك الجنة ، فإذا امتن بعد ذلك أو آذى السائل ، يكون ذلك نارا تحرق جنته في أشد أوقات حاجته ، فالإنسان في أشد الحاجة إلى خيره في الآخرة ، فإذا امتن بقي صفر اليدين هناك ( كَذلِكَ ) أي كهذا البيان الذي بين أمر الصدقة وغيرها ( يُبَيِّنُ اللهُ لَكُمُ الْآياتِ ) بضرب الأمثال والمشوقات ( لَعَلَّكُمْ تَتَفَكَّرُونَ ) فتستقيموا على الصراط المستقيم.` },
            { text: "أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُۥ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَٰرُ لَهُۥ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَأَصَابَهُ ٱلْكِبَرُ وَلَهُۥ ذُرِّيَّةٌ ضُعَفَآءُ فَأَصَابَهَآ إِعْصَارٌ فِيهِ نَارٌ فَٱحْتَرَقَتْ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلْـَٔايَٰتِ لَعَلَّكُمْ تَتَفَكَّرُونَ", tafsir: `` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ أَنفِقُوا۟ مِن طَيِّبَٰتِ مَا كَسَبْتُمْ وَمِمَّآ أَخْرَجْنَا لَكُم مِّنَ ٱلْأَرْضِ وَلَا تَيَمَّمُوا۟ ٱلْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِـَٔاخِذِيهِ إِلَّآ أَن تُغْمِضُوا۟ فِيهِ وَٱعْلَمُوٓا۟ أَنَّ ٱللَّهَ غَنِىٌّ حَمِيدٌ", tafsir: `طيبا واقعيا بكونه حلالا وظاهريا بكونه جيدا و ( مِنْ ) طيبات ما ( أَخْرَجْنا لَكُمْ مِنَ الْأَرْضِ ) أي وَلا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنْفِقُونَ وَلَسْتُمْ بِآخِذِيهِ إِلاَّ أَنْ تُغْمِضُوا فِيهِ وَاعْلَمُوا أَنَّ اللهَ غَنِيٌّ حَمِيدٌ (267) الشَّيْطانُ يَعِدُكُمُ الْفَقْرَ وَيَأْمُرُكُمْ بِالْفَحْشاءِ وَاللهُ يَعِدُكُمْ مَغْفِرَةً مِنْهُ وَفَضْلاً وَاللهُ واسِعٌ عَلِيمٌ (268) طيب مكسبكم وطيب ثماركم ، فلا تنفقوا من الربا ولا من الماء الآجن ولا من حشف التمر ـ مثلا ـ ( وَلا تَيَمَّمُوا ) أي لا تقصدوا ( الْخَبِيثَ ) الحرام الرديء ( مِنْهُ تُنْفِقُونَ ) للناس ( وَ ) الحال أنكم ( لَسْتُمْ بِآخِذِيهِ ) فإن أراد أحد إعطائكم من ذلك ما كنتم تأخذونه ( إِلَّا أَنْ تُغْمِضُوا فِيهِ ) أي تغمضوا عيونكم كراهة له ، فالإنسان إذا استبشع شيئا غمض عينه حتى لا يراه ، فكيف تنفقون مثل هذا الشيء الذي إذا أردتم أخذه غمضتم عينكم استبشاعا له ( وَاعْلَمُوا أَنَّ اللهَ غَنِيٌ ) عن صدقاتكم فلا يأخذ إلا الطيب ولا يقبل إلا الحسن ( حَمِيدٌ ) أي مستحق للحمد على نعمه ، ومن حمده أن يعطي الإنسان الشيء الطيب في سبيله ، فالإنسان إذا أراد تقدير شخص دفع إليه أحسن ما يتمكن ، لا أنه يدفع الرديء الخبيث.` },
            { text: "ٱلشَّيْطَٰنُ يَعِدُكُمُ ٱلْفَقْرَ وَيَأْمُرُكُم بِٱلْفَحْشَآءِ وَٱللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا وَٱللَّهُ وَٰسِعٌ عَلِيمٌ", tafsir: `إذا أردتم الإنفاق في سبيل الله ( وَيَأْمُرُكُمْ بِالْفَحْشاءِ ) إذا أردتم الإنفاق يقول لكم : أنفقوا من الرديء الخبيث ، وهو قسم من الفحشاء ، أو المراد به الأعمال القبيحة مطلقا ، ( وَاللهُ يَعِدُكُمْ مَغْفِرَةً مِنْهُ ) فإنه يغفر ذنوبكم بسبب الصدقة وسائر المبرات ( وَفَضْلاً ) فيخلف ما أنفقتموه ( وَاللهُ واسِعٌ ) ليس ضيق المقدرة حتى لا يتمكن من التعويض ( عَلِيمٌ ) بما تعطون فيجازيكم بالحسن يُؤْتِي الْحِكْمَةَ مَنْ يَشاءُ وَمَنْ يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْراً كَثِيراً وَما يَذَّكَّرُ إِلاَّ أُولُوا الْأَلْبابِ (269) وَما أَنْفَقْتُمْ مِنْ نَفَقَةٍ أَوْ نَذَرْتُمْ مِنْ نَذْرٍ فَإِنَّ اللهَ يَعْلَمُهُ وَما لِلظَّالِمِينَ مِنْ أَنْصارٍ (270) إِنْ تُبْدُوا الصَّدَقاتِ حسنا وبالسيئ سيئا. [270] إنّ الإنفاق في سبيل الله من الطيب بلا رياء ولا منّ ولا أذى من الحكمة التي هي وضع الأشياء موضعها اللائق والله سبحانه ( يُؤْتِي الْحِكْمَةَ مَنْ يَشاءُ ) ممن له قابلية بما سبق أن أخذ بالشريعة ( وَمَنْ يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْراً كَثِيراً ) وأي خير أعظم من أن يعمر الإنسان دنياه وعقباه بأخذه بأوامر الله سبحانه وانتهاجه المنهج المستقيم الموجب لسعادة النشأتين ( وَما يَذَّكَّرُ ) أي ما يتذكر ولا يفهم ذلك ( إِلَّا أُولُوا الْأَلْبابِ ) أصحاب العقول فصاحب العقل هو الذي يتبع ما ينفعه ويذر ما يضره.` },
            { text: "يُؤْتِى ٱلْحِكْمَةَ مَن يَشَآءُ وَمَن يُؤْتَ ٱلْحِكْمَةَ فَقَدْ أُوتِىَ خَيْرًا كَثِيرًا وَمَا يَذَّكَّرُ إِلَّآ أُو۟لُوا۟ ٱلْأَلْبَٰبِ", tafsir: `` },
            { text: "وَمَآ أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ ٱللَّهَ يَعْلَمُهُۥ وَمَا لِلظَّٰلِمِينَ مِنْ أَنصَارٍ", tafsir: `قليلة أو كثيرة أي أية صدقة تصدقتم بها ( أَوْ نَذَرْتُمْ مِنْ نَذْرٍ ) أي ما أوجبتموه على أنفسكم لله بسب النذر ( فَإِنَّ اللهَ يَعْلَمُهُ ) فيجازيكم عليه ويكون ذلك سببا للإحسان إلى النفس ( وَما لِلظَّالِمِينَ ) الذين يظلمون أنفسهم بالشح ومنع الصدقات الواجبة وحنث النذر والمن والأذى والرياء في الصدقة ( مِنْ أَنْصارٍ ) ينصرونهم ويخلصونهم من عقاب الله سبحانه.` },
            { text: "إِن تُبْدُوا۟ ٱلصَّدَقَٰتِ فَنِعِمَّا هِىَ وَإِن تُخْفُوهَا وَتُؤْتُوهَا ٱلْفُقَرَآءَ فَهُوَ خَيْرٌ لَّكُمْ وَيُكَفِّرُ عَنكُم مِّن سَيِّـَٔاتِكُمْ وَٱللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", tafsir: `أي تظهروا ( الصَّدَقاتِ ) حين إعطائها ، بأن تعطوها فَنِعِمَّا هِيَ وَإِنْ تُخْفُوها وَتُؤْتُوهَا الْفُقَراءَ فَهُوَ خَيْرٌ لَكُمْ وَيُكَفِّرُ عَنْكُمْ مِنْ سَيِّئاتِكُمْ وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ (271) لَيْسَ عَلَيْكَ هُداهُمْ وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ وَما تُنْفِقُوا مِنْ جهرا ، بقصد القربة لا بقصد الرياء ( فَنِعِمَّا هِيَ ) أي فنعم الشيء الصدقة الظاهرة فإنها توجب دفع التهمة واقتداء الناس ( وَإِنْ تُخْفُوها ) أي الصدقات ( وَتُؤْتُوهَا ) أي تعطوها سرا ( الْفُقَراءَ فَهُوَ خَيْرٌ لَكُمْ ) لأنه أقرب إلى القربة وأبعد عن الرياء وأحفظ لصون ماء وجه الآخذ ( وَيُكَفِّرُ ) أي يغفر ( عَنْكُمْ مِنْ سَيِّئاتِكُمْ ) أي بعض ذنوبكم بواسطة إعطاء الصدقة فإن صدقة السر تطفي غضب الرب ( وَاللهُ بِما تَعْمَلُونَ خَبِيرٌ ) فيجازيكم على أعمالكم ، فليس التصدق سرا غائبا عن الله سبحانه بل هو بكل شيء عليم. [273] امتنع بعض المسلمين عن التصدق إلى غير المسلم فنزلت ( لَيْسَ عَلَيْكَ هُداهُمْ ) فإنك لست مجبورا بأن تهديدهم وإنما عليك الإرشاد والبلاغ ( وَلكِنَّ اللهَ يَهْدِي مَنْ يَشاءُ ) إلى الصراط المستقيم ، بإراءته الطريق ، أو بإيصاله المطلوب ( وَما تُنْفِقُوا مِنْ خَيْرٍ فَلِأَنْفُسِكُمْ ) فإن نفعه الدنيوي والأخروي يعود إليكم ( وَما تُنْفِقُونَ ) أي ليس إنفاقكم ( إِلَّا ابْتِغاءَ وَجْهِ اللهِ ) أي لأجله سبحانه ، وأي شيء أحسن من أن ينفق الإنسان في سبيل خالقه ومنعمه والمتفضل عليه ( وَما تُنْفِقُوا مِنْ خَيْرٍ فَلِأَنْفُسِكُمْ وَما تُنْفِقُونَ إِلاَّ ابْتِغاءَ وَجْهِ اللهِ وَما تُنْفِقُوا مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنْتُمْ لا تُظْلَمُونَ (272) لِلْفُقَراءِ الَّذِينَ أُحْصِرُوا فِي سَبِيلِ اللهِ لا يَسْتَطِيعُونَ ضَرْباً فِي الْأَرْضِ يَحْسَبُهُمُ الْجاهِلُ أَغْنِياءَ مِنَ التَّعَفُّفِ تَعْرِفُهُمْ بِسِيماهُمْ لا يَسْئَلُونَ النَّاسَ إِلْحافاً خَيْرٍ يُوَفَّ إِلَيْكُمْ ) أي يوفر عليكم جزاءه وثوابه ( وَأَنْتُمْ لا تُظْلَمُونَ ) فتعطون جزاء إنفاقكم كاملا غير منقوص ، فالإنفاق لأنفسكم ، وثوابه يعود عليكم ، وهو في سبيل الله وما أجمل أن يعطي الإنسان شيئا يعود نفعه إليه ثم يثاب به في الآخرة ، ويرضى الله سبحانه عنه بذلك. [274] ولما بين الله سبحانه فضل الصدقة عقبه بأحسن مصارفها بقوله سبحانه : ( لِلْفُقَراءِ ) أي أن النفقة لهؤلاء ( الَّذِينَ أُحْصِرُوا فِي سَبِيلِ اللهِ ) أي منعوا والذي منعهم هو أنفسهم ، لأجل سبيل الله وإطاعته ، فقد نزلت الآية في أصحاب الصفة الذين تركوا كل شيء لأجل الإسلام وأحصروا أنفسهم للعبادة والجهاد بين يدي رسول الله صلى‌الله‌عليه‌وآله‌وسلم ( لا يَسْتَطِيعُونَ ضَرْباً فِي الْأَرْضِ ) أي ذهابا فيها وعدم الاستطاعة اختيارية لا اضطرارية ( يَحْسَبُهُمُ الْجاهِلُ ) أي يظنهم الذي يجهل حالهم وباطن أمرهم ( أَغْنِياءَ مِنَ التَّعَفُّفِ ) الامتناع من السؤال فإن الناس إذا رأوا تعففهم ظنوهم أغنياء لما عهدوا من سؤال الفقراء ( تَعْرِفُهُمْ ) أي تعرف إنهم فقراء ( بِسِيماهُمْ ) أي من وجوههم وأحوالهم يكون الفقر عليها باد ( لا يَسْئَلُونَ النَّاسَ إِلْحافاً ) أي كما هو شأن كثير من الفقراء ، بمعنى أنه ليس منهم سؤال فيكون إلحافا ، وَما تُنْفِقُوا مِنْ خَيْرٍ فَإِنَّ اللهَ بِهِ عَلِيمٌ (273) الَّذِينَ يُنْفِقُونَ أَمْوالَهُمْ بِاللَّيْلِ وَالنَّهارِ سِرًّا وَعَلانِيَةً فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (274) الَّذِينَ يَأْكُلُونَ الرِّبا لا يَقُومُونَ إِلاَّ كَما يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطانُ مِنَ الْمَسِّ لا إنهم يسألون من غير إلحاف ( وَما تُنْفِقُوا مِنْ خَيْرٍ ) كل شيء يطلق عليه الخير من دار أو عقار أو درهم أو دينار أو غيرها ( فَإِنَّ اللهَ بِهِ عَلِيمٌ ) لا يفوته شيء فيجازيكم جزاء حسنا.` },
            { text: "لَّيْسَ عَلَيْكَ هُدَىٰهُمْ وَلَٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَلِأَنفُسِكُمْ وَمَا تُنفِقُونَ إِلَّا ٱبْتِغَآءَ وَجْهِ ٱللَّهِ وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ", tafsir: `` },
            { text: "لِلْفُقَرَآءِ ٱلَّذِينَ أُحْصِرُوا۟ فِى سَبِيلِ ٱللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِى ٱلْأَرْضِ يَحْسَبُهُمُ ٱلْجَاهِلُ أَغْنِيَآءَ مِنَ ٱلتَّعَفُّفِ تَعْرِفُهُم بِسِيمَٰهُمْ لَا يَسْـَٔلُونَ ٱلنَّاسَ إِلْحَافًا وَمَا تُنفِقُوا۟ مِنْ خَيْرٍ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٌ", tafsir: `` },
            { text: "ٱلَّذِينَ يُنفِقُونَ أَمْوَٰلَهُم بِٱلَّيْلِ وَٱلنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `بالليل سرا وعلانية وبالنهار سرا وعلانية ( فَلَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) إن الآية وإن كانت عامة إلا إنها نزلت في علي عليه‌السلام حيث كانت له أربعة دراهم فتصدق باثنين منها نهارا سرا وعلانية وباثنين ليلا سرا وعلانية (1) ، وقد تقدم معنى ( لا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) . [276] وحيث كانت الآيات حول الإنفاق ، ناسب السياق ذكر الربا ، فإنه عكس الإنفاق إذ هو استيلاء على أموال الناس من غير مبرر ، بخلاف الإنفاق الذي هو إعطاء ماله للناس من غير مكسب وتجارة ( الَّذِينَ يَأْكُلُونَ الرِّبا ) وأكله كناية عن أخذه وإن لم يتصرف فيه ( لا يَقُومُونَ إِلَّا كَما يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطانُ مِنَ الْمَسِ ) الرجل الذي مسه ( 1) من لا يحضره الفقيه : ج 2 ص 288. ذلِكَ بِأَنَّهُمْ قالُوا إِنَّمَا الْبَيْعُ مِثْلُ الرِّبا وَأَحَلَّ اللهُ الْبَيْعَ وَحَرَّمَ الرِّبا الشيطان فصرع وتغير حاله ودارت عينه وزال توازن جسده وزبد فمه إذا أراد أن يقوم لبقية ما فيه من الشعور يقوم بعض القيام بكل انحراف وتأرجح ثم يسقط على الأرض ، وهكذا الإنسان الذي يأكل الربا حتى اعتاد ذلك يكون أشبه شيء في عملية انتهاب أموال الناس بمن تخبطه الشيطان الذي يريد أن يقوم فإن تفكيره تفكير منحرف كتفكير المطروح وعينه تنظر بزيغ إلى أموال الناس كعين المصروع وفيه يلهج حول المال بانحراف كفم المصروع وإذا أراد أن يقوم من كبوته ويترك الربا ويأخذ بالجادة المستقيمة حول المال لا يلبث أن يسقط في الربا كما اعتاد من أكله وصار الابتزاز لمال الناس ملكته ، وهذا تشبيه رائع مفزع وهكذا يكونون هؤلاء يوم القيامة. فقد روى الإمام الصادق عليه‌السلام عن الرسول صلى‌الله‌عليه‌وآله‌وسلم أنه قال : لما أسري بي إلى السماء رأيت أقواما يريد أحدهم أن يقوم ولا يقدر عليه من عظم بطنه فقلت من هؤلاء يا جبريل فقال : هؤلاء الذين يأكلون الربا لا يقومون إلا كما يقوم الذي يتخبطه الشيطان من المس (1) ، وقد ثبت في العلم أن الأرواح الشريرة قد تدخل في الإنسان فتسبب له صرعا ( ذلِكَ ) الأكل للربا الذي اعتادوه بسبب أنهم ( قالُوا ) ليس في أكل الربا بأس ف ( إِنَّمَا الْبَيْعُ مِثْلُ الرِّبا ) كلاهما تعامل برضى الطرفين ( وَ ) ليس كذلك فمنطقهم غلط فقد ( أَحَلَّ اللهُ الْبَيْعَ ) لما فيه من الفوائد ( وَحَرَّمَ الرِّبا ) لما فيه من ( 1) بحار الأنوار : ج 100 ص 116. فَمَنْ جاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ فَانْتَهى فَلَهُ ما سَلَفَ وَأَمْرُهُ إِلَى اللهِ وَمَنْ عادَ فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (275) المضار ، ويكفي أن نلمح إلى ضرر واحد هو أن معطي الربا إما ساقته الضرورة إلى الاقتراض كمرض أو نحوه مما ألجأ للاقتراض برباء فما أقبح أن يستغل الإنسان أخيه في مثل هذا الموقع مما يجدر به أن يساعده ويسعفه ، وإما اقترض للتجارة وهذا لا يخلو من أحد أحوال ثلاثة : الأول أن يخسر والثاني أن لا يربح ولا يخسر وما أقبح في هاتين الصورتين أن يأخذ صاحب المال زيادة بينما خسر العامل في الأول ولم يربح في الثاني والثالث أن يربح ، وقد قرر الإسلام المضاربة والاشتراك في المربح فيما يجبر المقترض أن يدفع بمقدار خاص إلى المقرض بينما قد ربح بمقداره وقد ربح أقل وقد ربح أكثر. ( فَمَنْ جاءَهُ مَوْعِظَةٌ مِنْ رَبِّهِ ) في تركه أخذ الربا ( فَانْتَهى ) وتاب ( فَلَهُ ما سَلَفَ ) فكل ربا أكله الناس بجهالة وعدم علم بحرمته أو قبل الإسلام لا يسترد منهم ( وَأَمْرُهُ إِلَى اللهِ ) سبحانه لا إلى الناس حتى يقول من أعطاه الربا : ردّ عليّ ما أخذت مني ، أو أمره في قبول الله توبته إليه سبحانه ( وَمَنْ عادَ ) إلى الربا بعد النهي والإسلام ( فَأُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ ) أبد الآبدين إلا أن يدركهم الله برحمته كما قال سبحانه : ( إِنَّ اللهَ لا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ ما دُونَ ذلِكَ لِمَنْ يَشاءُ ) (1) . ( 1) النساء : 117. يَمْحَقُ اللهُ الرِّبا وَيُرْبِي الصَّدَقاتِ وَاللهُ لا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ (276) إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ وَأَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (277) يا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللهَ وَذَرُوا ما بَقِيَ مِنَ الرِّبا` },
            { text: "ٱلَّذِينَ يَأْكُلُونَ ٱلرِّبَوٰا۟ لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ ٱلَّذِى يَتَخَبَّطُهُ ٱلشَّيْطَٰنُ مِنَ ٱلْمَسِّ ذَٰلِكَ بِأَنَّهُمْ قَالُوٓا۟ إِنَّمَا ٱلْبَيْعُ مِثْلُ ٱلرِّبَوٰا۟ وَأَحَلَّ ٱللَّهُ ٱلْبَيْعَ وَحَرَّمَ ٱلرِّبَوٰا۟ فَمَن جَآءَهُۥ مَوْعِظَةٌ مِّن رَّبِّهِۦ فَٱنتَهَىٰ فَلَهُۥ مَا سَلَفَ وَأَمْرُهُۥٓ إِلَى ٱللَّهِ وَمَنْ عَادَ فَأُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `` },
            { text: "يَمْحَقُ ٱللَّهُ ٱلرِّبَوٰا۟ وَيُرْبِى ٱلصَّدَقَٰتِ وَٱللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ", tafsir: `أي ينقصه ويتلفه ويهلكه فما ظن المرابي أنه سبب زيادة أمواله يكون سببا لهلاكه ونقصانه فإن الربا يسبب غضب الناس وسخطهم على المرابي مما يثير حربا أو نهبا من الناس أو الحكومات لأمواله فيذهب الأصل والفرع ( وَيُرْبِي ) أي يزيد وينمي ( الصَّدَقاتِ ) فإنه وإن ذهب جزء من المال بالصدقة لكنها تسبب حب الناس والتفافهم وتعاونهم مع المتصدق مما ينجر إلى زيادة أمواله ، وهذا مع الغض عن المحق والنماء الخارجين عن الطبيعة مما يشأهما الله سبحانه بلا واسطة عادية ( وَاللهُ لا يُحِبُّ كُلَّ كَفَّارٍ ) كثير الكفر ( أَثِيمٍ ) أي مذنب وفي هذا دلالة على أن آكل الربا كفار أثيم.` },
            { text: "إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `بالأصول الاعتقادية ( وَعَمِلُوا الصَّالِحاتِ ) بأن أتوا بالواجبات وتركوا المحرمات ( وَأَقامُوا الصَّلاةَ وَآتَوُا الزَّكاةَ ) تخصيص بعد التعميم لأهميتهما ( لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ ) وقد مر تفسير عدم الخوف وعدم الحزن.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَذَرُوا۟ مَا بَقِىَ مِنَ ٱلرِّبَوٰٓا۟ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `خافوا من عقابه ( وَذَرُوا ما بَقِيَ مِنَ الرِّبا ) إِنْ كُنْتُمْ مُؤْمِنِينَ (278) فَإِنْ لَمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِنَ اللهِ وَرَسُولِهِ وَإِنْ تُبْتُمْ فَلَكُمْ رُؤُسُ أَمْوالِكُمْ لا تَظْلِمُونَ وَلا تُظْلَمُونَ (279) مما كنتم تطلبونه قبل الإسلام وقد روي عن الإمام الباقر عليه‌السلام أنه قال : إن الوليد بن المغيرة كان يربي في الجاهلية وقد بقي له بقايا على ثقيف فأراد خالد بن الوليد المطالبة بها بعد أن أسلم فنزلت الآية ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) بالإسلام حقا فإن المؤمن هو الذي يأتمر بالأوامر وينزجر بالزواجر.` },
            { text: "فَإِن لَّمْ تَفْعَلُوا۟ فَأْذَنُوا۟ بِحَرْبٍ مِّنَ ٱللَّهِ وَرَسُولِهِۦ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَٰلِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ", tafsir: `ولم تنقادوا إلى هذا النهي بل أكلتم الربا بعد النهي ( فَأْذَنُوا بِحَرْبٍ مِنَ اللهِ وَرَسُولِهِ ) أي اعملوا القتال مع الله ورسوله صلى‌الله‌عليه‌وآله‌وسلم ، فأكل الربا يكون كمن أعلن الحرب مع الإله والرسول صلى‌الله‌عليه‌وآله‌وسلم ، وذلك من أفظع الجرائم ، وعاقبته خسران الدين والدنيا ، و حكم آكل الربا إنه يؤدب مرتين ثم يقتل في الثالثة كما روي عن الإمام الصادق عليه‌السلام (1) ( وَإِنْ تُبْتُمْ ) ولم تأخذوا الربا ( فَلَكُمْ رُؤُسُ أَمْوالِكُمْ ) دون الزيادة التي حصلتموها بالربا ولا مفهوم للآية بأنهم إن لم يتوبوا فليس لهم رأس المال ، بل المراد أن لكم رأس المال فما تبغون بالزيادة ( لا تَظْلِمُونَ ) الناس بأخذ الزيادة منهم ( وَلا تُظْلَمُونَ ) بالنقصان من رأس المال. ( 1) من لا يحضره الفقيه : ج 4 ص 70. وَإِنْ كانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلى مَيْسَرَةٍ وَأَنْ تَصَدَّقُوا خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ (280) وَاتَّقُوا يَوْماً تُرْجَعُونَ فِيهِ إِلَى اللهِ ثُمَّ تُوَفَّى كُلُّ نَفْسٍ ما كَسَبَتْ وَهُمْ لا يُظْلَمُونَ (281) يا أَيُّهَا الَّذِينَ آمَنُوا إِذا تَدايَنْتُمْ` },
            { text: "وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا۟ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ", tafsir: `فيمن تطلبون منه ـ ممن ذكر أنه يرجع رأس المال ـ ( ذُو عُسْرَةٍ ) بأن كان رأس مالكم الذي تطلبونه عند ذي عسرة لا يتمكن من أدائه لعسره وضيقه فاللازم نظرة إلى انتظار وتأخير ( إِلى مَيْسَرَةٍ ) أي إلى حال يسار المديون والجملة خبرية معناها الأمر ، أي فأنظروه إلى وقت يساره ( وَأَنْ تَصَدَّقُوا ) على المعسر بما عليه من الدين بأن تجعلوا طلبكم صدقة له ( خَيْرٌ لَكُمْ ) في الدنيا يجلب المحبة والبركة من الله سبحانه وفي الآخرة بالثواب الجزيل ( إِنْ كُنْتُمْ تَعْلَمُونَ ) أي إن كنتم تعلمون الخير من الشر وتميزون ما ينفعكم مما يضركم لعلمتم أن هبة الدين للمعسر خير لكم.` },
            { text: "وَٱتَّقُوا۟ يَوْمًا تُرْجَعُونَ فِيهِ إِلَى ٱللَّهِ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ", tafsir: `فلا تأكلوا الربا ولا تؤاخذوا المعسرين بل تصدقوا عليهم ، فإن إتيان الحرام موجب للعقاب والتصدق موجب للثواب ( ثُمَّ تُوَفَّى ) أي تعطى وافيا ( كُلُّ نَفْسٍ ما كَسَبَتْ ) من خير أو شر ( وَهُمْ لا يُظْلَمُونَ ) شيئا فلا ينقص من أجورهم شيء كما لا يزاد في عذابهم أكثر من استحقاقهم ، ومعنى الرجوع إلى الله الرجوع إلى حكمه وأمره وقضائه وجزائه.` },
            { text: "يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰٓ أَجَلٍ مُّسَمًّى فَٱكْتُبُوهُ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌۢ بِٱلْعَدْلِ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ ٱللَّهُ فَلْيَكْتُبْ وَلْيُمْلِلِ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا يَبْخَسْ مِنْهُ شَيْـًٔا فَإِن كَانَ ٱلَّذِى عَلَيْهِ ٱلْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُۥ بِٱلْعَدْلِ وَٱسْتَشْهِدُوا۟ شَهِيدَيْنِ مِن رِّجَالِكُمْ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَٱمْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ ٱلشُّهَدَآءِ أَن تَضِلَّ إِحْدَىٰهُمَا فَتُذَكِّرَ إِحْدَىٰهُمَا ٱلْأُخْرَىٰ وَلَا يَأْبَ ٱلشُّهَدَآءُ إِذَا مَا دُعُوا۟ وَلَا تَسْـَٔمُوٓا۟ أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰٓ أَجَلِهِۦ ذَٰلِكُمْ أَقْسَطُ عِندَ ٱللَّهِ وَأَقْوَمُ لِلشَّهَٰدَةِ وَأَدْنَىٰٓ أَلَّا تَرْتَابُوٓا۟ إِلَّآ أَن تَكُونَ تِجَٰرَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا وَأَشْهِدُوٓا۟ إِذَا تَبَايَعْتُمْ وَلَا يُضَآرَّ كَاتِبٌ وَلَا شَهِيدٌ وَإِن تَفْعَلُوا۟ فَإِنَّهُۥ فُسُوقٌۢ بِكُمْ وَٱتَّقُوا۟ ٱللَّهَ وَيُعَلِّمُكُمُ ٱللَّهُ وَٱللَّهُ بِكُلِّ شَىْءٍ عَلِيمٌ", tafsir: `أي تعاملتم بالدين ودان بعضكم بِدَيْنٍ إِلى أَجَلٍ مُسَمًّى فَاكْتُبُوهُ وَلْيَكْتُبْ بَيْنَكُمْ كاتِبٌ بِالْعَدْلِ وَلا يَأْبَ كاتِبٌ أَنْ يَكْتُبَ كَما عَلَّمَهُ اللهُ فَلْيَكْتُبْ وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ وَلْيَتَّقِ اللهَ رَبَّهُ وَلا يَبْخَسْ مِنْهُ شَيْئاً بعضا في بيع أو غيره ( بِدَيْنٍ ) إما تأكيد وإما لدفع توهم أن يكون المراد من المداينة المجازاة كما قال الشاعر « ولا أنت دياني فتجزيني » ( إِلى أَجَلٍ مُسَمًّى ) أي مدة قد سميت في العقد كما لو دائنه إلى سنة أو باعه نسيئة إلى ستة أشهر مثلا ( فَاكْتُبُوهُ ) أي اكتبوا ذلك الدين في صك وأنه إلى أية مدة لئلا يقع فيه نسيان أو جحود أو خلاف ( وَلْيَكْتُبْ بَيْنَكُمْ ) كتاب الدين ( كاتِبٌ بِالْعَدْلِ ) بالحق لا يزيد في المقدار والأجل والوصف ولا ينقص منها ( وَلا يَأْبَ ) أي لا يمتنع ( كاتِبٌ ) أي شخص كان من المتعاملين أو غيرهما ( أَنْ يَكْتُبَ ) الصك ( كَما عَلَّمَهُ اللهُ ) بأن يبخل فلا يكتب ، فالتكليف من الله سبحانه وهو في مقابل أن علمه تعالى الكتابة والعلم فلا يثقل أو يبطئ أو يبخل ( فَلْيَكْتُبْ ) الكاتب ( وَلْيُمْلِلِ ) بمعنى ليملأ فإن الإملال والإملاء بمعنى واحد يلقي صيغة الكتابة على الكاتب ( الَّذِي عَلَيْهِ الْحَقُ ) أي المديون حتى يقر على نفسه أولا ، حتى لا يقول زائدا على الحق ثانيا ، فالذي له الحق لو أملى كان معرضا لأن يقول الزيادة ( وَلْيَتَّقِ اللهَ ) الكاتب أو المديون ( رَبَّهُ ) فإنه رب له فكيف يخالف أمره ( وَلا يَبْخَسْ ) أي لا ينقص الكاتب أو المديون ( مِنْهُ ) أي من الحق ( شَيْئاً ) أما نقص الكاتب فواضح وأما نقص المديون كأن يجعل فَإِنْ كانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهاً أَوْ ضَعِيفاً أَوْ لا يَسْتَطِيعُ أَنْ يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُ بِالْعَدْلِ وَاسْتَشْهِدُوا شَهِيدَيْنِ مِنْ رِجالِكُمْ فَإِنْ لَمْ يَكُونا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتانِ مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَداءِ أَنْ تَضِلَّ إِحْداهُما فَتُذَكِّرَ إِحْداهُمَا الْأُخْرى الدينار والذي هو مقابل ثوب في مقابل ثوبين ( فَإِنْ كانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهاً ) بحيث لم يتمكن من الإملاء ( أَوْ ضَعِيفاً ) لجنون أو كبر أو صغر أو نحوها ( أَوْ لا يَسْتَطِيعُ أَنْ يُمِلَّ هُوَ ) لخرس أو عذر آخر مع عدم السفاهة والضعف ( فَلْيُمْلِلْ وَلِيُّهُ ) أي ولي من عليه الحق ( بِالْعَدْلِ ) بلا إفراط أو تفريط ( وَاسْتَشْهِدُوا ) أي اطلبوا شهادة ( شَهِيدَيْنِ مِنْ رِجالِكُمْ ) على المكتوب لينفع ذلك عند الترافع والمخاصمة لدى التخالف ، ولعل قيد من رجالكم لإخراج الكفار ( فَإِنْ لَمْ يَكُونا ) أي لم يكن الشاهدين ( رَجُلَيْنِ ) لعدم حضورهما أو عدم إرادة المستشهد ( فَرَجُلٌ وَامْرَأَتانِ ) يشهدون على الكتابة ، أو فليشهد رجل وامرأتان ( مِمَّنْ تَرْضَوْنَ مِنَ الشُّهَداءِ ) لوثاقتهم أو عدالتهم إذ لا تقبل شهادة من عداهم لدى المخالفة والتراخ ، وإنما جعلت المرأتان مكان رجل واحد لأن المرأة لضعف ذاكرتها كما ثبت في العلم الحديث يتطرق إليها من النسيان ما لا يتطرق إلى الرجل ، ولذا قال سبحانه : ( أَنْ تَضِلَّ إِحْداهُما ) من الضلال أي تخطأ وتشتبه وتنسى ( فَتُذَكِّرَ إِحْداهُمَا ) التي لم تضل ( الْأُخْرى ) التي نسيت وضلت ، و « أن » إما بمعنى « لئلا » وتكون جملة « فتذكر » منقطعة ، أي إن ضلّت تذكر الثانية الأولى ، وأما أصلها « إن » بالكسر ، صفة وَلا يَأْبَ الشُّهَداءُ إِذا ما دُعُوا وَلا تَسْئَمُوا أَنْ تَكْتُبُوهُ صَغِيراً أَوْ كَبِيراً إِلى أَجَلِهِ ذلِكُمْ أَقْسَطُ عِنْدَ اللهِ وَأَقْوَمُ لِلشَّهادَةِ وَأَدْنى أَلاَّ تَرْتابُوا إِلاَّ أَنْ تَكُونَ تِجارَةً حاضِرَةً لامرأتان ، والأول أقرب ( وَلا يَأْبَ ) أي لا يمتنع ( الشُّهَداءِ ) الذين يراد إشهادهم للدين ـ وسموا شهداء بمجاز المشارفة ـ ( إِذا ما دُعُوا ) لتحمل الشهادة وهذا أمر إيجابي أو استحبابي ، أو المراد الأعم من التحمل والأداء. ( وَلا تَسْئَمُوا ) أي لا تضجروا أيها المتداينون ( أَنْ تَكْتُبُوهُ ) أي تكتبوا الدين أو تكتبوا الحق ( صَغِيراً ) كان الحق والدين ( أَوْ كَبِيراً ) وهذا تأديب لمن يترك كتابة الصغير لعدم الاهتمام به ، فكثيرا ما يقع التنازع في الصغير ( إِلى أَجَلِهِ ) أي إلى أجل الدين ومدته ، وفيه تنبيه إلى أن الكتابة تبقى إلى الأجل فتنفع هناك ، أو المعنى كتابة تتضمن إلى الأجل ، فيعين في المكتوب أجل الدين. ( ذلِكُمْ ) ذا إشارة إلى الكتاب الذي يكتب في المداينة « وكم » خطاب إلى الذين آمنوا ( أَقْسَطُ عِنْدَ اللهِ ) أي أعدل ، بمعنى أقرب إلى العدل وإلا فليس في العدل مفاضلة حقيقية ( وَأَقْوَمُ لِلشَّهادَةِ ) فيه تقوم الشهادة التي تؤمن عن الزيادة والنقصان ( وَأَدْنى أَلَّا تَرْتابُوا ) أي أقرب إلى عدم الريب في المبلغ والأجل فالله يريده وأنتم لا تشكون ، والشهادة تستقيم ، بسبب الكتابة والصك وما ذكر من الكتابة عامة لكل مكان ( إِلَّا أَنْ تَكُونَ ) المعاملة ـ المفهوم من الكلام ـ ( تِجارَةً حاضِرَةً ) معجلة غير تُدِيرُونَها بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُناحٌ أَلاَّ تَكْتُبُوها وَأَشْهِدُوا إِذا تَبايَعْتُمْ وَلا يُضَارَّ كاتِبٌ وَلا شَهِيدٌ وَإِنْ تَفْعَلُوا فَإِنَّهُ فُسُوقٌ بِكُمْ وَاتَّقُوا اللهَ وَيُعَلِّمُكُمُ اللهُ وَاللهُ بِكُلِّ شَيْءٍ عَلِيمٌ (282) مؤجلة كغالب التجارات النقدية التي تجري في الأسواق ( تُدِيرُونَها بَيْنَكُمْ ) إدارة يد بيد ، ومعنى الإدارة المناقلة ، فينقل هذا ماله إلى ذاك وينقل ذاك عنه إلى هذا ( فَلَيْسَ عَلَيْكُمْ جُناحٌ ) وحرج ( أَلَّا تَكْتُبُوها ) فلا مانع من عدم كتابة التجارة النقدية إذ الكتابة للوثيقة وهنا لا يحتاج إلى الوثيقة ( وَأَشْهِدُوا إِذا تَبايَعْتُمْ ) فإنه يستحب للإنسان الذي يريد المبايعة أن يأخذ الشاهد ، ففي المعاملة كثيرا ما يقع من نزاع وخصام فإذا كان هناك شهادة يقل وطئ النزاع ، والآية وإن كانت عامة لفظا لكن لا يعد أن لا يراد بها الإطلاق من المعاملات الجزئية اليومية لعدم تعارف الأشهاد منذ زمان الرسول صلى‌الله‌عليه‌وآله‌وسلم ( وَلا يُضَارَّ كاتِبٌ وَلا شَهِيدٌ ) بأن يكلف الكاتب الكتابة ويكلف الشاهد الشهادة في حال يكون حرجا عليهما وضررا ، كما تعارف الآن عند الحكومات المنحرفة فإنه يحضر الشاهد ويعنت ويضار فإن في مضارتها زهادة للناس عن الكتابة والشهادة ( وَإِنْ تَفْعَلُوا ) المضارة بها ( فَإِنَّهُ فُسُوقٌ بِكُمْ ) أي خروج عن أمر الله سبحانه لسببكم أيها المضارون ( وَاتَّقُوا اللهَ ) فيما أمركم ونهاكم ( وَيُعَلِّمُكُمُ اللهُ ) مصالحكم فاتبعوه ( وَاللهُ بِكُلِّ شَيْءٍ عَلِيمٌ ) وأنتم لا تعلون وما أجدر بالجاهل أن يتبع العالم ، عن علي بن إبراهيم أن في وَإِنْ كُنْتُمْ عَلى سَفَرٍ وَلَمْ تَجِدُوا كاتِباً فَرِهانٌ مَقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُمْ بَعْضاً فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ أَمانَتَهُ وَلْيَتَّقِ اللهَ رَبَّهُ وَلا تَكْتُمُوا الشَّهادَةَ وَمَنْ يَكْتُمْها فَإِنَّهُ آثِمٌ قَلْبُهُ` },
            { text: "وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا۟ كَاتِبًا فَرِهَٰنٌ مَّقْبُوضَةٌ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَٰنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ وَلَا تَكْتُمُوا۟ ٱلشَّهَٰدَةَ وَمَن يَكْتُمْهَا فَإِنَّهُۥٓ ءَاثِمٌ قَلْبُهُۥ وَٱللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ", tafsir: `أيها المتداينون المتبايعون ( عَلى سَفَرٍ ) أي مسافرين والتعبير بلفظ « على » لركوب المسافر غالبا ( وَلَمْ تَجِدُوا كاتِباً ) يكتب الدين والمعاملة ( فَرِهانٌ مَقْبُوضَةٌ ) تقوم مقام الصك ورهان جمع رهن ، وهو اسم للوثيقة ولذا جاءت الصفة بالتأنيث والقبض شرط في صحة الرهن ، ولذا وصفه بالقبض ( فَإِنْ أَمِنَ بَعْضُكُمْ ) وهو صاحب الحق ( بَعْضاً ) وهو من عليه الحق بأن وثق به وأنه يؤدي الدين بدون صك ولا رهن ، فأعطاه الدين مجردا عن الأمرين ( فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ ) أي المديون ( أَمانَتَهُ ) فلا ينكر ولا يمطل ، كفاء لما رآه أهلا ( وَلْيَتَّقِ اللهَ رَبَّهُ ) فإن الله شهيد ويجازي فإن أنكر أو مطل أو بخس كان معرضا نفسه لعقوبة الله سبحانه ( وَلا تَكْتُمُوا ) أيها الشهود ( الشَّهادَةَ ) التي تحملتموها ( وَمَنْ يَكْتُمْها ) أي يخفي الشهادة فلا يحضر لأدائها أو يؤديها على خلاف الواقع ( فَإِنَّهُ آثِمٌ قَلْبُهُ ) فقد عزم القلب على الكتمان وأطاعته الجوارح واللسان ولأن الكتمان أنسب إلى القلب لكونه في محل وَاللهُ بِما تَعْمَلُونَ عَلِيمٌ (283) لِلَّهِ ما فِي السَّماواتِ وَما فِي الْأَرْضِ وَإِنْ تُبْدُوا ما فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحاسِبْكُمْ بِهِ اللهُ فَيَغْفِرُ لِمَنْ يَشاءُ وَيُعَذِّبُ مَنْ يَشاءُ وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ (284) مكتوم ( وَاللهُ بِما تَعْمَلُونَ ) من إخفاء الشهادة وإبدائها ( عَلِيمٌ ) فلا تفعلوا ما يوجب عقابه وسخطه.` },
            { text: "لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ", tafsir: `فما تعاطونه من الأملاك ليست لكم إلا مجازا وإنما هي ملك له سبحانه فاعملوا فيها حسب ما أمركم ولا تخالفوا أمر المالك الحقيقي ( وَإِنْ تُبْدُوا ) أي تظهروا ( ما فِي أَنْفُسِكُمْ ) بما تعلمونه ويخفى على غيركم ( أَوْ تُخْفُوهُ ) فتكتموه ( يُحاسِبْكُمْ بِهِ اللهُ ) فإن جميع الأعمال والأقوال والأفكار تحت المحاسبة ، أو أن الإبداء والإخفاء لما في النفس محسوب عليهما ، وهذا العموم للتناسق مع إبداء الشهادة وكتمانها ( فَيَغْفِرُ لِمَنْ يَشاءُ وَيُعَذِّبُ مَنْ يَشاءُ ) حسب ما تقتضيه الحكمة البالغة فالغفران والشفاعة ليسا اعتباطا وإنما ينصبان على المحل القابل ( وَاللهُ عَلى كُلِّ شَيْءٍ قَدِيرٌ ) من المغفرة والعقاب ولا يخفى أن العذاب على ما في النفس لا ينافي ما دل على عدم العقاب ، على العزم على المعصية لاختلاف المعاصي ، واختلاف أنواع العقاب فلا شبهة في أن من يعزم على المعاصي وإن لم يفعلها أبعد عن قرب الحلال ممن لا يعزم إطلاقا ، وهذا البعد هو نوع من العذاب أو يجمع بنحو ذلك. آمَنَ الرَّسُولُ بِما أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقالُوا سَمِعْنا وَأَطَعْنا غُفْرانَكَ رَبَّنا وَإِلَيْكَ الْمَصِيرُ (285) [286] وهنا يرجع السياق إلى ذكر التوحيد والنبوة والشرائع جملة في لباس أنها لا تكلف الناس فوق الطاقة وسؤال المغفرة والعفو لتكون فذلكة للسورة ( آمَنَ الرَّسُولُ ) محمد صلى‌الله‌عليه‌وآله‌وسلم ( بِما أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ ) فهو أول مؤمن بما أنزل إليه وليس كرؤساء الأديان المفتعلة والملوك والحكام الذين لا يشملهم القانون ( وَالْمُؤْمِنُونَ كُلٌ ) أي كل واحد منهم ( آمَنَ بِاللهِ وَمَلائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ ) فليس المؤمن أن يقتنع بجانب واحد من جوانب الإسلام كما هو كثير في تابعي الأحزاب والمبادئ حيث أن ذا النشاط المتفايض منهم يقتنع منه بجانب واحد وإن ترك سائر الجوانب فإن لسان حال المؤمنين ( لا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ ) فلسنا كاليهود الذين لا يعترفون بالمسيح عليه‌السلام ونبي الإسلام صلى‌الله‌عليه‌وآله‌وسلم ولا كالنصارى الذين لا يعترفون بنبي الإسلام ، فلا تكون كمن يؤمن ببعض ويكفر ببعض ( وَقالُوا سَمِعْنا ) آيات الله وأحكامه ( وَأَطَعْنا ) أوامره ونواهيه لا كاليهود الذين قالوا سمعنا وعصينا ، يقولون ( غُفْرانَكَ ) أي نطلب مغفرتك ( رَبَّنا ) نعلم أن ( إِلَيْكَ الْمَصِيرُ ) فاغفر لنا حتى نكون في ذلك اليوم سعداء. [287] إن الأحكام التي سلفت في السورة وفي غيرها ليست مما لا يطاق لاَ يُكَلِّفُ اللّهُ نَفْسًا إِلاَّ وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لاَ تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلاَ تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا فإنه ( لا يُكَلِّفُ اللهُ نَفْساً إِلَّا وُسْعَها ) فإن أوامره ونواهيه مستطاعة للمكلف وليس في الدين من حرج ، فلا يظن أحد أن الإيمان السابق ذكره في ( وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ ) يوجب مشقة وعنتا وإرهاقا ( لَها ) أي للنفس ( ما كَسَبَتْ ) من الحسنات فالجزاء الحسن يجزى به من أحسن ( وَعَلَيْها ) أي على النفس ضرر ( مَا اكْتَسَبَتْ ) من الآثام والسيئات ولعل في مجيء الكسب من بابين « كسب » و « أكتسب » إفادة أن الطاعة طبيعية والمعصية تؤتي بالتكلف إذ للفظة الاكتساب ظلالا يفيد التعب والغضب بخلاف الكسب وتؤيده قاعدة « زيادة المبنى تدل على زيادة المعنى » وهناك يتوجه المؤمنون إلى الله داعين سائلين ( رَبَّنا لا تُؤاخِذْنا إِنْ نَسِينا أَوْ أَخْطَأْنا ) بلا نسيان وإنما تصح المؤاخذة فيهما لغلبة كون مقدماتهما اختيارية وما ينتهي إلى الاختيار يكون بالاختيار ( رَبَّنا وَلا تَحْمِلْ عَلَيْنا إِصْراً ) أي ثقلا فإن بعض التكاليف قد توجب ظروفها ثقلا وعنتا ، فالمؤمن يسأل أن يجنبه الله سبحانه مثل هذا الثقل ( كَما حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنا ) فإنهم بلجاجتهم استحقوا تحميل الثقل كما تقدم في قصة بقرة بني إسرائيل وكما قال سبحانه : ( فَبِظُلْمٍ مِنَ الَّذِينَ هادُوا حَرَّمْنا عَلَيْهِمْ طَيِّباتٍ أُحِلَّتْ لَهُمْ ) (1) ( 1) النساء : 161. رَبَّنَا وَلاَ تُحَمِّلْنَا مَا لاَ طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَآ أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ (286) ( رَبَّنا وَلا تُحَمِّلْنا ما لا طاقَةَ لَنا بِهِ ) وإن كان مقدورا لنا فإن عدم الطاقة ليس بمعنى عدم القدرة حتى يقال : إن الله لا يكلف غير المقدور فما وجه هذا الدعاء ؟ ( وَاعْفُ عَنَّا ) ذنوبنا ( وَاغْفِرْ لَنا ) خطايانا أي استرها ولا تبدها ( وَارْحَمْنا أَنْتَ مَوْلانا ) سيدنا والأولى بالتصرف فينا ( فَانْصُرْنا عَلَى الْقَوْمِ الْكافِرِينَ ) حتى نغلب عليهم في الحكم كما نغلب عليهم في الحجة. (3)` },
            { text: "ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ", tafsir: `` },
            { text: "لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَآ إِصْرًا كَمَا حَمَلْتَهُۥ عَلَى ٱلَّذِينَ مِن قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِۦ وَٱعْفُ عَنَّا وَٱغْفِرْ لَنَا وَٱرْحَمْنَآ أَنتَ مَوْلَىٰنَا فَٱنصُرْنَا عَلَى ٱلْقَوْمِ ٱلْكَٰفِرِينَ", tafsir: `` }
        ]
    }
});
